WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[63912] = { title = "Celestial Shadowlands Chart", description = "<You recognize this relic from the Archivists' Codex.\n\nThe mawsworn discarded it, believing it to be useless.\n\nAnd the chart is useless, without the accompanying data to plot the relative locations of Shadowlands afterlives. If the research were retrieved from deceased scholars, the chart could be returned to the Archivist, fully functional.>", objectives = "Collect 6 Afterlife Navigation Research scrolls, then bring them to Archivist Roh-Suir in the Reliquary of Remembrance.", progress = "Is that the missing chart?", completion = "Aha! You have recovered the Celestial Shadowlands Chart.\n\nWith the chart and the data you collected, it can be restored to its fully functional form. It will take some time to analyze and interpret the results, which I can get started on now that the relic has been returned to the Archive.\n\nAllow me a moment to find a good spot for it..." }
WordHunterWoW_QuestEN[63913] = { title = "Unstable Explosive Orb", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this device in the Reliquary of Remembrance.>", objectives = "Bring the Unstable Explosive Orb to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", completion = "I appreciate you handling this relic carefully. It is nothing short of a miracle that it did not detonate when Korthia was invaded." }
WordHunterWoW_QuestEN[63914] = { title = "Cipher of Understanding", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for the cipher in the Reliquary of Remembrance.>", objectives = "Bring the Cipher of Understanding to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", completion = "My stars! To comprehend any of these languages would allow one the insight to translate all of them. We must look into this further." }
WordHunterWoW_QuestEN[63915] = { title = "Drum of the Death Loa", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this drum in the Reliquary of Remembrance.>", objectives = "Bring the Drum of the Death Loa to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", completion = "I could hear you approaching with this drum before I saw you. And strangely, I though someone else might be with you." }
WordHunterWoW_QuestEN[63916] = { title = "Sack of Strange Soil", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this soil in the Reliquary of Remembrance.>", objectives = "Bring the Sack of Strange Soil to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", completion = "This soil can grow any type of plant, anywhere.\n\nNot the most dangerous relic missing from the archive, and yet it could be the most useful. With enough time, one could restore the verdant beauty of Korthia." }
WordHunterWoW_QuestEN[63917] = { title = "Everliving Statuette", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this statuette in the Reliquary of Remembrance.>", objectives = "Bring the Everliving Statuette to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", completion = "I trust you did not listen to anything that this little monster told you.\n\nIt is absolutely incapable of uttering the truth." }
WordHunterWoW_QuestEN[63918] = { title = "Obelisk of Dark Tidings", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this obelisk in the Reliquary of Remembrance.>", objectives = "Bring the Obelisk of Dark Tidings to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", completion = "We must be cautious around this obelisk.\n\nMore than one attendant was driven mad while researching the relic." }
WordHunterWoW_QuestEN[63919] = { title = "Book of Binding: The Tormented Sorcerer", description = "<You hear a muffled voice speaking from within this book, interspersed with crackling static. Though the utterances are mostly unintelligible, you can make out the repeated request to recover azure pages.\n\nFlipping through the volume, you note that many of its pages are missing.\n\nIf the pages were retrieved, the book could be returned to the Archivist and reassembled.>", objectives = "Collect 10 azure pages, then bring them to Archivist Roh-Suir in the Reliquary of Remembrance.", progress = "I find these strange speaking tomes... discomfiting.", completion = "This appears to be a companion tome to the crimson book that was under the care of scholars in the Seeker's Quorum.\n\nKnowing that this book binding was separated from its pages intentionally, I will stitch all but one azure page back into it before returning it to the archive." }
WordHunterWoW_QuestEN[63920] = { title = "Enigmatic Decrypting Device", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this device in the Reliquary of Remembrance.>", objectives = "Bring the Enigmatic Decrypting Device to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", completion = "Though I have only a passing understanding of its operation, this relic can strip the complexity of communication into a form that is free from subtlety, guile, or metaphor. Pure logic." }
WordHunterWoW_QuestEN[63921] = { title = "Ring of Self-Reflection", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this ring in the Reliquary of Remembrance.>", objectives = "Bring the Ring of Self-Reflection to Archivist Roh-Suir in the Reliquary of Remembrance.", completion = "I am curious to learn how this strange ring functions." }
WordHunterWoW_QuestEN[63922] = { title = "Shadow Slicing Shortsword", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this shortsword in the Reliquary of Remembrance.>", objectives = "Bring the Shadow Slicing Shortsword to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", completion = "Though the blade's shadow severing properties may appear to be no more than a parlor trick, I believe this is one of the most dangerous relics in our care." }
WordHunterWoW_QuestEN[63923] = { title = "Lang Family Wood-Carving", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this wood-carving in the Reliquary of Remembrance.>", objectives = "Bring the Lang Family Wood-Carving to Archivist Roh-Suir in the Reliquary of Remembrance.\n\nProvided item:", completion = "I believe this relic can teach us something about the history as well as the future." }
WordHunterWoW_QuestEN[63924] = { title = "Gorak Claw Fetish", description = "<Your familiarity with the Archivists' Codex makes it clear that this is one of the missing relics.\n\nArchivist Roh-Suir has a spot for this fetish in the Reliquary of Remembrance.>", objectives = "Bring the Gorak Claw Fetish to Archivist Roh-Suir in the Reliquary of Remembrance.", completion = "Some mote of Gorak Tul yet lives within this fetish. His corruption is barely contained." }
WordHunterWoW_QuestEN[63934] = { title = "Assail Mail", description = "Greetings, mortal!\n\nI am on a mission to deliver messages to our allies here in exciting Korthia. However, I was unable to complete my task.\n\nThe messages I was programmed to transport were stolen by Mawsworn, and then incorrectly stored all over the ground.\n\nWould you collect the messages and return them to me? I will then see them delivered to their intended recipients.\n\nThank you!", objectives = "Retrieve 6 Stolen Messages from the Scholar's Den.", progress = "I must see my task completed.", completion = "These are the messages that were stolen! I commend you on recovering them.\n\nOh, there appears to be at least one extra..." }
WordHunterWoW_QuestEN[63935] = { title = "Precious Roots", description = "Korthia. A sister forest, stricken.\n\nBut in the throes of destruction, there is still hope. \n\nGather the anima, and build anew.", objectives = "Collect 8 Residual Anima from around the Vault in Korthia.", progress = "Sow growth.", completion = "Precious anima that will be shared. A sacrifice, honored." }
WordHunterWoW_QuestEN[63936] = { title = "Devoured Anima", description = "Sika has idea!\n\nDevourers... devour. They eat anything! So they eat anima, too.\n\nIf we take anima from devourers, then that anima is ours!", objectives = "Reclaim 12 Devoured Anima from devourers in the Estuary of Awakening.", progress = "Sika wonders what anima tastes like.", completion = "Thank you! Wow... you can't tell this was inside devourer!\n\nSika will get anima to those most in need." }
WordHunterWoW_QuestEN[63937] = { title = "Nasty, Big, Pointy Teeth", description = "There's tons of interesting things to kill out here! Bears, birds, mawsworn, and gromits!\n\nLet's start with the gromits shall we? Go slaughter the fierce gromits in the Mauler's Outlook and bring me their FANGS! I can always use more teeth.", objectives = "Collect 6 Fierce Gromit Fangs.", progress = "I like the long teeth. Razor sharp fangs. The short ones are nice too.", completion = "EEEEEE! These are so good! Look how long and sharp they are! I am going to put these where they go right now! Thank you!" }
WordHunterWoW_QuestEN[63944] = { title = "Korthia Awaits", description = "Ready yourself, {name}. Our allies await your arrival in Korthia.", objectives = "Report to Tal-Galan at Keeper's Respite in Korthia.", completion = "Ah, yes. Your anima is rather familiar.\n\nWe were wondering when you would arrive." }
WordHunterWoW_QuestEN[63945] = { title = "The Soul Blade", description = "The runeblade of a Necrolord can be a potent weapon in this realm. An abundance of souls are willing to contribute their anima to end their own suffering and bring defeat to the Jailer.\n\nTake one of my runeblades and charge it with the anima of the willing souls you find here.\n\nOnce charged, use it lay waste to their forces here.", objectives = "Charge Heirmir's Runeblade with Willing Souls and use it to slay the Eye of Gorgoa.", progress = "Has my blade tasted victory?", completion = "<Bonesmith Heirmir takes her runeblade back from you and examines it carefully.>\n\nNot bad, <name>. Always room for improvement... but not bad." }
WordHunterWoW_QuestEN[63946] = { title = "Rescue the Archivist [PH]", description = "What... happened?\n\nWe... barely escaped Roh-Domum when the invaders arrived... but my fellow researchers were badly injured. \n\nPlease... you must help them!", objectives = "" }
WordHunterWoW_QuestEN[63947] = { title = "Raiders in the Ruins [PH]", description = "While I abhor violence and prefer a reasoned response to conflict, there's no alternative here.\n\nIn order for us to escape safely, we must disrupt the attackers. Deliver a decisive strike to the mawsworn that have invaded Roh-Domum.\n\nTake out their forces.", objectives = "Defeat 15 mawsworn invaders." }
WordHunterWoW_QuestEN[63948] = { title = "Seeking the Seeker's Staff [PH]", description = "We were researching the properties of an artifact that we dubbed the Sundered Staff.\n\nThe staff was split into three segments, as it was far too unstable to handle while assembled.\n\nI do not think the invaders were looking for it, or aware of its properties, but they have found the pieces. Each segment is held by a different member of the mawsworn.\n\nWe must recover these pieces, quickly.\n\nIt is only a matter of time before they discover they are parts of a more-dangerous whole.", objectives = "Recover the three segments of the Sundered Staff." }
WordHunterWoW_QuestEN[63949] = { title = "Shaping Fate", description = "The Jailer's power and malevolence continue to grow. So must our resilience.\n\nStand amongst your allies, {name}. Push back against the darkness that would consume us all.\n\nTogether, we will yet prevail.\n\nMay the Purpose guide your hand.", objectives = "Thwart the Jailer's efforts throughout Korthia and the Maw by completing Covenant Assaults, Daily Quests, looting treasures, slaying rare creatures, and defeating Tormentors of Torghast.", progress = "One cannot run from history, but one's actions may shape the outcome.", completion = "The threads of fate weave through you, Maw Walker.\n\nJust as the prophecies foretold." }
WordHunterWoW_QuestEN[63950] = { title = "Razorwing Talons", description = "These lands are not well known yet by my hunters, but we have discovered formidable beasts that reside here.\n\nAmong these are the Razorwing: vicious predators with terrible talons... and the temper of a vorkai.\n\n<Herne grins fiercely.>\n\nBring me some of their talons to help teach our newest hunters about the kinds of beasts they will face.", objectives = "Collect 10 Razorwing Talons.", progress = "Do you have those Razorwing Talons?", completion = "These talons are in excellent shape. And they look like they could take out an eye! <Herne chuckles ironically.>\n\nI expect they will get a lot of attention from our Wild Hunt recruits.\n\nThank you, Maw Walker." }
WordHunterWoW_QuestEN[63951] = { title = "A Shady Place", description = "Existence is not a simple thing, {name}. It is layers upon layers of realities.\n\nThe Jailer's traps are pulling our troops into one such rift, hidden from normal sight.\n\nI have obtained an Unbalanced Riftstone. It will give you the ability to enter the rift and destroy the traps keeping our troops trapped inside, before they are lost forever.\n\nAfter you've destroyed the Rift-Veiled Traps, exit the rift and pull the trapped soldiers back into our reality.", objectives = "Use the Unbalanced Riftstone to enter the rift and break Rift-Veiled Traps to free $1a Riftbound Vorkai.", progress = "There is much we cannot see.", completion = "Excellent work Maw Walker." }
WordHunterWoW_QuestEN[63952] = { title = "Heavy-Handed Tactics", description = "We need more constructs on the front lines, but we have no bodies, heads, or legs! \n\nRathan's making the best constructs possible with what we DO have... a lot of hands.\n\nDon't ask questions!\n\nThere are enemies in Calcis that we need dead. Take the hands and kill things!", objectives = "Slay 8 Mawsworn Soulbreakers, 4 Crystalline Guardians, Lady Nalis, and Glassmaker.", progress = "Rathan is nothing if not resourceful.", completion = "<Margrave Sin'dane looks impressed... or annoyed... or disgusted... or concerned?>\n\nHm. I suppose with enough hands, anything IS possible..." }
WordHunterWoW_QuestEN[63953] = { title = "Korrak's Revenge", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[63954] = { title = "Sealed Secrets", description = "Ah, Korthia. What secrets will be revealed?\n\nMy associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you.\n\nThey have secured those items in designated drop boxes, and those now await pickup in Seeker's Quorum. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer.\n\nBring those sealed containers to me, and I will reward you handsomely.", objectives = "Retrieve 5 Sealed Containers from the Seeker's Quorum.", progress = "Do you have the sealed containers?", completion = "Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised." }
WordHunterWoW_QuestEN[63955] = { title = "Sealed Secrets", description = "Ah, Korthia. What secrets will be revealed?\n\nMy associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you.\n\nThey have secured those items in designated drop boxes, and those now await pickup outside of the Vault. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer.\n\nBring those sealed containers to me, and I will reward you handsomely.", objectives = "Retrieve 5 Sealed Containers from the Vault in Korthia.", progress = "Do you have the sealed containers?", completion = "Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised." }
WordHunterWoW_QuestEN[63956] = { title = "Sealed Secrets", description = "Ah, Korthia. What secrets will be revealed?\n\nMy associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you.\n\nThey have secured those items in designated drop boxes, and those now await pickup in the Windswept Aerie. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer.\n\nBring those sealed containers to me, and I will reward you handsomely.", objectives = "Retrieve 5 Sealed Containers from the Windswept Aerie in Korthia.", progress = "Do you have the sealed containers?", completion = "Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised." }
WordHunterWoW_QuestEN[63957] = { title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe Seeker's Quorum records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nBring those data to me, and I will reward you handsomely.", objectives = "Collect 5 Observational Records from Seeker's Quorum in Korthia.", progress = "Have you retrieved the observational records from Seeker's Quorum?", completion = "The name \"Seeker's Quorum\" has puzzled me greatly since I learned of it. What are they seeking? What constitutes a Quorum? What did they do there?\n\nThese mysteries may be beyond us, or they may yet be revealed. And here is your reward, as promised." }
WordHunterWoW_QuestEN[63958] = { title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe records from outside the Vault should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nBring that data to me, and I will reward you handsomely.", objectives = "Collect 5 Observational Records from outside the Vault in Korthia.", progress = "Have you retrieved the observational records from the Vault?", completion = "The Vault is reason why the Jailer targeted Korthia with his chains. Many secrets of the Shadowlands are archived there.\n\nIf we can just get a glimpse of how it works and what it holds, that information would be most valuable indeed.\n\nAnd here is your reward, as promised." }
WordHunterWoW_QuestEN[63959] = { title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe Sanctuary of Guidance records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nBring those data to me, and I will reward you handsomely.", objectives = "Collect 5 Observational Records from the Sanctuary of Guidance in Korthia.", progress = "Have you retrieved the observational records from the Sanctuary of Guidance?", completion = "The devourers have destroyed much of what might have been useful at the Sanctuary of Guidance. But this information will still prove valuable.\n\nAnd here is your reward, as promised." }
WordHunterWoW_QuestEN[63960] = { title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe records from the Windswept Aerie and Estuary of Awakening should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nAnd don't forget to look below ground!\n\nBring those data to me, and I will reward you handsomely.", objectives = "Collect 5 Observational Records from the Windswept Aerie and Estuary of Awakening in Korthia.", progress = "Have you retrieved the observational records from the Windswept Aerie and Estuary of Awakening?", completion = "Places like the Aerie and Estuary must have been desolate even before all the destruction. What interesting creatures congregate there.\n\nWill they all survive these changes? Will some adapt, and become even more fearsome?\n\nHere is your reward, as promised." }
WordHunterWoW_QuestEN[63961] = { title = "Sealed Secrets", description = "Ah, Korthia. What secrets will be revealed?\n\nMy associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you.\n\nThey have secured those items in designated drop boxes, and those now await pickup in Mauler's Outlook. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer.\n\nBring those sealed containers to me, and I will reward you handsomely.", objectives = "Retrieve 5 Sealed Containers from Mauler's Outlook in Korthia.", progress = "Do you have the sealed containers?", completion = "Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised." }
WordHunterWoW_QuestEN[63962] = { title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe records at Mauler's Outlook should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nBring those data to me, and I will reward you handsomely.", objectives = "Collect 5 Observational Records from Mauler's Outlook in Korthia.", progress = "Have you retrieved the observational records from Mauler's Outlook?", completion = "Excellent, this data will serve us well. We can begin to answer some of our questions about Korthia, and the Mauler's Outlook. Was it always home to such terrible creatures, or did was it something more?\n\nAnd here is your reward, as promised" }
WordHunterWoW_QuestEN[63963] = { title = "Broker's Bounty: Ripmaul", description = "New lands bring new opportunity. To any interested party, we will provide a quantity of valuables in return for a piece of heavily spiked hide from the beast known as Ripmaul.\n\nFaint-hearted collectors need not bother.\n\nPlease bring this sample to Ta'nasi in Keeper's Respite.", objectives = "Retrieve a Heavy Spiked Hide from Ripmaul.", progress = "Have something to trade?", completion = "<Ta'nasi tugs at the spiked hide to test its strength.>\n\nAn excellent specimen. This will do nicely.\n\nAnd as promised, here is your reward in trade." }
WordHunterWoW_QuestEN[63964] = { title = "Broker's Bounty: Grimtalon", description = "New lands bring new opportunity. To any interested party, we will provide a quantity of valuables in return for an intact boney beak from the beast known as Grimtalon.\n\nFaint-hearted collectors need not bother.\n\nPlease bring this sample to Ta'nasi in Keeper's Respite.", objectives = "Retrieve a Mature Ossified Beak from Grimtalon.", progress = "Have something to trade?", completion = "<Ta'nasi knocks the sturdy beak against her palm, listening to the sound.>\n\nAn excellent specimen. This will do nicely.\n\nAnd as promised, here is your reward in trade." }
WordHunterWoW_QuestEN[63965] = { title = "Razorwing Egg Rescue", description = "I'm amazed by the wildlife here in Korthia! So many interesting creatures...\n\nSay, you know those flying beasts with the claws, the Razorwing? They sometimes knock their eggs out of their nests, and then they completely ignore them! If you find any abandoned eggs, could you bring them to me?\n\nGently, of course. I wonder if they can be raised to be friendly?\n\nIf not, well, it wouldn't be the first time I've had my antennae chewed on.", objectives = "Collect 5 Razorwing Eggs.", completion = "Look at these wonderful eggs! I can hear their heartbeats.\n\nThis is the start of something beautiful, I just know it." }
WordHunterWoW_QuestEN[63968] = { title = "Clean Out the Crucible", description = "The Winter Queen has called a hunt. We will ensure that the Crucible of the Damned is rid of the Jailer's forces today.\n\nDo your part and hunt down any enemies you find.", objectives = "Kill 30 enemies in the Crucible of the Damned and Calcis.", completion = "The hunt is not yet complete, but you have earned your place in the records of its victory." }
WordHunterWoW_QuestEN[63969] = { title = "Looming Darkness", description = "The Winter Queen called for a hunt in this location due to reports of a massive, unnatural darkness swelling in its upper regions.\n\nThe Wild Hunt is brave, but not foolish. We must learn what we can about this darkness before we charge into it.\n\nSearch the bodies of our enemies nearby for clues.", objectives = "Collect 1 Mawsworn Ritual Book, 10 Mawsworn Missive Scraps, and 15 Dark Marrow.", progress = "Have you learned anything regarding the darkness yet?", completion = "We will discover the source of this darkness, and end it." }
WordHunterWoW_QuestEN[63970] = { title = "No Soul Left Behind", description = "Do you hear the cries of tormented souls trapped in Gorgoa?\n\nThe twisted river of souls flows before us, swelling with cruelty and the torment of undeserving victims.\n\nOur brave regiment of druid spirits led the charge into the river to seek out those lost souls, but I fear many have instead joined in their suffering.\n\nSummon your courage and take my cradle with you into the river. Load the lost souls you find onto the cradle, then order the cradle to come back to me.", objectives = "Use Thiernax's Rescue Cradle to rescue 12 Lost Druids in Gorgoa and send them back to Thiernax.", progress = "I admire Thiernax's dedication to even the least among us.", completion = "Thank you, <name>. We must not forget to help one another as we stride deeper into the darkness." }
WordHunterWoW_QuestEN[63971] = { title = "Snail Stomping", description = "Careful where you step. You wouldn't want to accidentally squish a Mawsworn, would you?\n\nOf course you would! It's so fun!\n\n<Lady Moonberry giggles and points at the snails around her.>\n\nIt's so much easier to squish Mawsworn after you've transformed them into stinky little snails.\n\nHere, take my wand and try it out on whatever you like.\n\nYou may need to weaken them a bit first, but it'll work on almost anything!", objectives = "Use Lady Moonberry's Wand to transform 15 weakened enemies into snails, and then squish them!", progress = "Lady Moonberry never ceases to surprise me.", completion = "<Lord Herne grins.> My record was squishing four in a single jump.\n\nOne of the many benefits of being a quadruped." }
WordHunterWoW_QuestEN[63972] = { title = "Just Don't Ask Me to Spell It", description = "It's getting dangerous out there for druid spirits!\n\nThankfully, we always have room for another friend in our group, and this fine tirnenn has offered to help me and the gang get around the battlefield safely.\n\n<The tirnenn behind Choofa begins speaking slowly, but Choofa just talks louder.>\n\nGood ol' Kirriprkar- I mean, Karripkraker- I mean, Krackerkrisp...\n\n<Choofa laughs.>\n\nLet's just call her \"Big K\"!\n\nHop on, everybody!", objectives = "Help Krrprripripkraak and her friends sow chaos in the Crucible of the Damned.", progress = "Krrprripripkraak and Choofa are teaming up? This, I must see.", completion = "I have received many reports from hunters who were aided by Krrprripripkraak and her friends. Thank you for helping them." }
WordHunterWoW_QuestEN[63973] = { title = "Double Dromans", description = "Relax, {name}. Breathe.\n\n<Dreamweaver inhales and exhales slowly.>\n\nThings are getting tense around here, but that doesn't mean YOU need to be tense.\n\nEverything is going to be okay. If you don't believe me, let the mighty deeds of Droman Aliothe and Droman Tashmur reassure you.\n\nThey headed up the hill together to clear a path for the rest of us. They'll have everything taken care of in no time.", objectives = "Help Droman Aliothe defeat enemies along her path and kill Lord Dretnal.", progress = "You can find the droman up the hill from here.", completion = "No matter how strong we become, we are stronger when we hunt together." }
WordHunterWoW_QuestEN[63974] = { title = "That's Going to Sting", description = "<Niya speaks loudly to be heard over the buzzing coming from the collection of needler nests behind her.>\n\nI've caught Moonberry trying to steal these nests for her pranks over ten times already!\n\nThe other faeries said I was crazy to bring the needlers out here. Too wild! Too unpredictable!\n\nBut that's exactly why we need them.\n\nLord Herne's scouts report powerful Heralds among our enemy's forces.\n\nTake one of these nests, and use it to surprise the Heralds!", objectives = "Use an Angry Needler Nest to weaken and kill Herald Gkeca, Herald Throgtu, and Herald Duarri.", progress = "Niya is proving to be quite the clever tactician...", completion = "I wish I could've been there to see it myself!\n\nA fitting end for the Heralds..." }
WordHunterWoW_QuestEN[63976] = { title = "The Al'ley Cat of Oribos", description = "Ah, Maw Walker. I have a message.\n\nAn individual has a proposition for you, specifically. I know nothing of the details, only that they asked you meet them towards the back of the Idyllia.", objectives = "Meet with the mysterious contact in Oribos.", completion = "It is a pleasure to meet you." }
WordHunterWoW_QuestEN[63977] = { title = "Insider Trading", description = "I am the foremost expert on broker culture. However, relationships between cartels are complicated and unstable.\n\nCartel So holds a small presence here in Oribos, which means the other cartels may have knowledge that I do not. Ask around--with your renown, surely they'll have whatever information that we are missing.", objectives = "Speak with various broker cartels around Oribos.", progress = "Have you had a chance to speak with the other cartels?", completion = "How rude! They should be aware of who they are talking to.\n\nI apologize for my kin, Maw Walker." }
WordHunterWoW_QuestEN[63979] = { title = "Things Best Kept Dark", description = "The leader of Cartel So represents a grave danger to the Shadowlands, Maw Walker.\n\nHer name is So'leah. She seeks to assemble an artifact of the First Ones and use its power for selfish ends.\n\nPieces of the relic are said to be hidden on your homeworld. Brokers have never before found our way there. But if So'leah does, then Azeroth too is imperiled.\n\nWe must intercept her.\n\nThere is cargo nearby marked for Cartel So. Perhaps the manifest will give us clues as to their leader's whereabouts.", objectives = "Find a shipping manifest belonging to Cartel So.", progress = "Have you found anything?", completion = "Tazavesh, the Veiled Market...\n\nAn interesting choice of locations." }
WordHunterWoW_QuestEN[63980] = { title = "Seeking Smugglers", description = "We brokers have found that it is in our best interests to remain mobile. And discreet.\n\nA number of our cities and outposts are tucked away in the In-Between, capable of moving from place to place.\n\nMuch to my chagrin, it seems I have lost track of Tazavesh.\n\nI believe our best course of action is to ask Cartel Ta for access. They pride themselves on keeping track of such things.\n\nLet's try our luck with those at the Night Market in Revendreth. They may be more forthcoming than their Oribos kin.", objectives = "Speak with Ta'nla the Identifier at the Night Market.", completion = "You seek information?\n\nThat requires a transaction." }
WordHunterWoW_QuestEN[63982] = { title = "Above My Station", description = "While I indeed know the location of the Veiled Market, I fear I can do little in terms of providing you with transportation to it.\n\nIn return for your assistance with a task, I can send you to someone who can assist us both. There is a bounty hunter at Transfer Station Ta--a broker enclave in Bastion. He is better suited to help you... and he owes me a shipment.\n\nMeet with Ta'oku and tell him that Ta'nla sent you.\n\nFor your convenience, I can offer use of a portal. After all, we are partners, yes?", objectives = "Take the portal at the Night Market and speak with Ta'oku.", completion = "Need something hunted down?" }
WordHunterWoW_QuestEN[63983] = { title = "Dead Drop", description = "Ta'nla requested something very... specific... on behalf of a client.\n\nThe kyrian have been working on a new type of centurion they call an aquilon. I sent some of our trade specialists to retrieve the prototype in question, but they have yet to return. \n\nUntil I have the item, there is obviously no way I can ship it to Ta'nla. Perhaps we can help one another.\n\nIf you can locate the aquilon and bring it here, I will help you reach Tazavesh.", objectives = "Retrieve the Prototype Aquilon.", progress = "Have you acquired the... item?", completion = "Perfect! This will put us back on schedule." }
WordHunterWoW_QuestEN[63984] = { title = "Coins for the Ferryman", description = "Your side of the deal is done, Maw Walker. Now for your payment.\n\nMy cartel runs a ferry that travels between Oribos and Tazavesh. Its purpose is to transport cargo, but as in all things, there are... exceptions.\n\nTake this coin to Ta'meri and you will be provided safe passage to the market.\n\nWhat happens after that is up to you.\n\n<Ta'oku bows, uttering a sound that seems almost like a chuckle.>", objectives = "Speak with Ta'meri in Oribos.\n\nProvided item:", completion = "Maw Walker! What can humble Ta'meri do for you?" }
WordHunterWoW_QuestEN[63985] = { title = "The Veiled Market", description = "Let me guess... Ta'oku sent you my way, yes? \n\n<Ta'meri looks at the coin you offer.>\n\nSo, you seek travel to Tazavesh. Not something we'd typically offer an outsider, but since payment has been accounted for, it would be my pleasure to assist you.\n\nStep aboard, and do remember to keep any appendages inside the craft at all times. The currents of the In-Between can be fickle.", objectives = "Ride the barge to Tazavesh.", completion = "No worries! I have another plan." }
WordHunterWoW_QuestEN[63986] = { title = "Tazavesh: Raiders of the Lost Artifact", description = "It looks like you may need to show a bit of force once more, my dear friend. Tazavesh security will not let us simply walk in.\n\nBut So'leah needs to be stopped. If that requires a bit of physical... persuasion... then it is a necessary evil. \n\nBring some friends. I have a feeling the security here has tricks up their sleeves.", objectives = "Enter Tazavesh and defeat So'leah." }
WordHunterWoW_QuestEN[63987] = { title = "Ve'lor's Lost Parcel", description = "", objectives = "" }
WordHunterWoW_QuestEN[63989] = { title = "Oozing with Character", description = "Apprentice! I've been looking for you.\n\nKevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well!\n\nCan you take Plaguey with you and test their ability to infect organic life forms?", objectives = "Help Plaguey test their infection ability in the Mauler's Outlook.", progress = "They're good oozes, <name>.", completion = "How did Plaguey do? Is he as viral as we'd hoped?" }
WordHunterWoW_QuestEN[63990] = { title = "The Blade in the Night", description = "Though my hunt has been arduous, I have two promising leads on additional Night Warriors. The first is here in Maldraxxus.\n\nThis tower contains records of those who arrived in Maldraxxus, including someone referred to as \"The Blade in the Night.\" I believe this to be our next Night Warrior.\n\nI encountered many traps on the way here. Doubtless we will find more within the tower. Someone is trying to stop us.\n\nWe will not let them succeed.", objectives = "Search the Sepulcher of Knowledge for clues.", progress = "Hmm.", completion = "I am not opposed to helping you, but... There are matters I must attend to first." }
WordHunterWoW_QuestEN[63994] = { title = "Who is the Maw Walker?", description = "Korthian prophecies foretell the arrival of a Maw Walker who can save us from disaster. \n\nPerhaps this is that day. But perhaps not. I must test your anima to verify your claim.\n\nIf you speak the truth, then I have a solemn duty to empower your anima before we proceed.", objectives = "Participate in Tal-Galan's Maw Walker trial.", progress = "Let us proceed, Maw Walker.", completion = "Maw Walker. We must summon the others." }
WordHunterWoW_QuestEN[64006] = { title = "Nav Test: Zereth Mortis", description = "This quest will take you through a likely flow for the 9.2 Main Line questing. We don't have a finalized pitch for the 9.2 Main Line yet, so this is just a rough idea of how the POIs might be used.\n\nThis test is built to be Beastmaster and Godmode friendly, so feel free to use cheats.\n\nUseful cheats:\n92BrokerTown - Return to hub\n92NavTest - Restart the Nav Test (Must abandon first)", objectives = "This quest will take you through a likely flow for the 9.2 Main Line questing. We don't have a finalized pitch for the 9.2 Main Line yet, so this is just a rough idea of how the POIs might be used.\n\nThis test is built to be Beastmaster and Godmode friendly, so feel free to use cheats.\n\nUseful cheats:\n92BrokerTown - Return to hub\n92NavTest - Restart the Nav Test (Must abandon first)" }
WordHunterWoW_QuestEN[64007] = { title = "Charge of the Covenants", description = "Thanks to the efforts of you and other heroes of Azeroth, the covenants have grown strong. But we can no longer afford to wait for the Jailer to make his next move.\n\nThe way to the Maw is open. Our forces stand ready.\n\nThe covenants await your signal, {name}.", objectives = "Rally the covenant forces to go into the Maw.", completion = "The Maw...\n\nNow our true work begins." }
WordHunterWoW_QuestEN[64012] = { title = "Supplies from Death's Advance", description = "Your work toward stopping the Jailer's advances has not gone unnoticed. If it is power you seek to continue your efforts I believe I can be of some assistance.", objectives = "Speak with Duchess Mynx at Keeper's Respite in Korthia.", completion = "Your work toward stopping the Jailer's advances has not gone unnoticed. If it is power you seek to continue your efforts I believe I can be of some assistance." }
WordHunterWoW_QuestEN[64014] = { title = "Mawsplaining", description = "There remains one task now before the glorious battle can begin. The horn must be anchored to the Maw so that its voice may pierce the barrier that surrounds that foul realm. \n\nHow this can be done, I do not know. Seek out one that understands the mysteries of that place. Surely they can guide your hand.\n\nDanica and her sisters will listen for Ilskahorn's call. They will answer when you need them, {name}.", objectives = "Ask Ve'nari's help to bind the Ilskahorn to the Maw.", progress = "Have you bound the horn to the Maw?", completion = "That's quite an instrument you have there.\n\nIt seems the golden feathers were worth following, Maw Walker. You owe me yet again." }
WordHunterWoW_QuestEN[64015] = { title = "Into the Meat Grinder", description = "All these mawsworn have got me excited for some slaughter!\n\nI've got a plan that probably won't end in you dying.\n\nAre you in?", objectives = "Lay a trap for the Mawsworn.", completion = "Bwahahaha!\n\nSo much slaughter, so many parts! You've been a real strong arm today, <name>." }
WordHunterWoW_QuestEN[64016] = { title = "Oozing with Character", description = "Apprentice! I've been looking for you.\n\nKevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well!\n\nFor Ooz, I'd like to know if they are able to consume organic material and increase in size.", objectives = "Help Ooz test their growth ability on Shardhide in the Mauler's Outlook.", progress = "They're good oozes, <name>.", completion = "How did the tests go? OH! Ooz! You're huge! You're even more beautiful than normal!" }
WordHunterWoW_QuestEN[64017] = { title = "Oozing with Character", description = "Apprentice! I've been looking for you.\n\nKevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well!\n\nFor Bloop, I'd like to know if their ooze is capable of propagation. Take them with you, and find those bears. Give them the command to inject the life form with their ooze and see what happens.", objectives = "Help Bloop test their propagation ability in the Mauler's Outlook.", progress = "They're good oozes, <name>.", completion = "How did the tests go? OH! Look at all of them! They're so cute!" }
WordHunterWoW_QuestEN[64018] = { title = "The Weight of Stone", description = "The campaign continues, {name}. The Stone Legion is here to turn the tide of battle.\n\nFirst, we must deliver supplies to our allies. The broken land of Korthia means we are the only ones who can keep our troops supplied.\n\nSecond, we must deal with the mawsworn and the devourers. I have a very simple strategy. We are going to drop anima onto the mawsworn. That will attract the devourers to attack. Either they kill the mawsworn, or the mawsworn kills them. Regardless, we win.", objectives = "Assist the Stone Legion in delivering supplies and anima.", completion = "You did it!" }
WordHunterWoW_QuestEN[64040] = { title = "Once More, with Healing", description = "The mawsworn continue to engage our forces at the Vault. There are heavy casualties on both sides. We must help!\n\nTake this and restore any wounded covenant allies you find. Mikanikos helped me create it. It runs on anima and should help patch up anyone. Even the Stoneborn or Maldraxxi.", objectives = "Restore 10 Wounded Covenant Allies.", progress = "I wish we could do more. But we're stretched so thin.", completion = "How wonderful! I am relieved to know our allies are no longer wounded." }
WordHunterWoW_QuestEN[64042] = { title = "Rituals of Night", description = "Tyrande's time grows short, so we must act quickly. \n\n<Ysera frowns in concern.>\n\nWe had hoped to gather more Night Warriors, but we will have to proceed with who we have and hope it is enough.\n\n<Ysera shakes her head, then looks more resolute.>\n\nBefore we can begin, we must finish preparations for the ritual. Please bring these last few items with you and meet us at the grove.", objectives = "Assist with the preparations and ritual.", progress = "Good, we may begin.", completion = "With everything in place we can begin. I only hope we are not too late for Tyrande." }
WordHunterWoW_QuestEN[64043] = { title = "We Need a Healer - You!", description = "There are too many wounded on the battlefield! \n\nNot everyone can 'bash it and make better.' We need more healers.\n\nYou: take my device and get our wounded back on their feet!", objectives = "Restore 10 Wounded Covenant Allies in Seeker's Quorum.", completion = "That got them back on their feet!\n\nAny little bit helps to keep us in the fight." }
WordHunterWoW_QuestEN[64065] = { title = "Local Reagents", description = "Korthia is an odd place. The wildlife here is different, likely due to years of exposure to the Vault and everything it contains.\n\nAre you ready to try some experiments? We'll need a good stock of reagents first.\n\nNear the Seeker's Quorum, you should be able to find shardhides, gromits, and razorwings. Watch out for their needles!", objectives = "Collect 8 Shardhide Talons, 6 Gromit Feet, and 1 Razorwing Spines for Plague Deviser Marileth in Korthia.", progress = "Feel like taste testing my newest experiment? It probably won't kill you.", completion = "This needle is so long and perfect! Well done apprentice. I can't wait to get started on our new tests!" }
WordHunterWoW_QuestEN[64070] = { title = "Staying Scrappy", description = "Our army always need more weapons, armor, and troops. Always.\n\nWe're getting reinforcements, but I can't keep everyone properly armed at this rate. Especially without a full forge and assistants.\n\nWe'll have to make do with the next best thing. I need you to go get me any kind of scrap metal from the Mawsworn you can find. I'll figure out how to turn it into usable weapons.", objectives = "Collect 12 Mawsworn scrap metal.", progress = "One day, I'll fight a campaign where we are properly supplied and equipped. It'll be the easiest war I'll ever fight.", completion = "Well, it's not the finest materials, but it will do." }
WordHunterWoW_QuestEN[64080] = { title = "Down to Earth", description = "I can hear the wings of the Mawsworn in the sky up above, taunting us. \n\nBut a bird in the hand can be crushed. \n\nTake my spear and prove your aim. Pull a few down and smite them. \n\nBe sure to use the spear. Do not traipse among them so that they will chase you back down to the ground. That's not the point.\n\nI want to see you drag them out of the sky.", objectives = "Use Korayn's Javelin to spear 4 Mawsworn Harbingers.", completion = "It is so satisfying to see those flying Mawsworn get their wings clipped.\n\nWell done, my friend." }
WordHunterWoW_QuestEN[64083] = { title = "Sinfall Tactician", description = "Sinfall is gaining more respect than Denathrius could have ever hoped to earn! It is all thanks to your efforts, {name}.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance." }
WordHunterWoW_QuestEN[64084] = { title = "Necrolord Tactician", description = "You have brought great honor to the Necrolords. Such honor attracts the attention of others yet again.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance." }
WordHunterWoW_QuestEN[64085] = { title = "Night Fae Tactician", description = "Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance." }
WordHunterWoW_QuestEN[64086] = { title = "Kyrian Tactician", description = "Look around you, {name}. Elysian Hold stands as a testament to the progress we have made thanks to you.\n\nZo'sorg has once again requested your presence in Oribos. Go at once.\n\nThe favor of Cartel Zo is not something we want to squander. A broker clan's trust is not one effortlessly gained.\n\nPerhaps they have more rewards to bestow upon you.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", completion = "I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance." }
WordHunterWoW_QuestEN[64089] = { title = "Teas and Tinctures", description = "How delightful! What a lovely little spot of nature.\n\nHave you tried the local brews? Perhaps a nice herbal tea? No? Well, let's try it together! Search about this place and bring back any herbs that look... interesting.\n\nA good spot of tea, and then we shall get to work. I'll wait here.", objectives = "Collect 12 potential tea materials.", progress = "Tubbins! Grubbins! What are the two of you up to? Not bothering the Night Fae again are you?", completion = "Oh my! I've never even seen most of these herbs. Hum, this black one looks a bit dangerous. This green one seems promising. Well done <name>!" }
WordHunterWoW_QuestEN[64090] = { title = "The Big Squeeze", description = "So our missin' blue got 'imself dragged off to the big squeeze. Fortunately I am wise to the prise.\n\nWe'll soft foot it in like we work there, find your moose, avoid eye contact with the fangs, and chisel out of 'ere like we're masons. Follow?", objectives = "Head to where Cudgelface thinks Huln was taken, and blend in.", progress = "Well, this is exciting!", completion = "It sounds like Huln might not have much time left!" }
WordHunterWoW_QuestEN[64091] = { title = "Mal'appropriated", description = "<The dreadlord catches your eye, wishing to speak. You glance at your companions. Moonberry urges you forward with a mischievous grin. You step as close as you dare.>\n\nFree me from this prison, mortal, and you will have my favor. I am aligned with powers greater than these pathetic puppets or their masters. They have no concept of the true forces at work. \n\nAll I need are the sigils of binding which hold me. The rest I can... take care of.\n\nFree me, and you will be granted untold power.", objectives = "Collect the Sigils of Binding", progress = "Hmmm.", completion = "If he got nicked, I know where they took 'im." }
WordHunterWoW_QuestEN[64092] = { title = "Hunting Huln", description = "Huln is somewhere in the area, but the Stonewright isn't letting anyone in to her territory because of the recent, ah, troubles with Dreadlords. The guards won't let anyone in, and they're kicking out anyone who doesn't look like they belong.\n\nLuckily for Huln, Cudgelface and I came up with a foolproof plan!\n\nWe just need to look like we belong and then we can ask around and find Huln. Easy!", objectives = "Don a disguise then search Dominance Keep for Huln Highmountain while avoiding the guards.", completion = "I'm busy with this piece of dreadlord filth. Find something useful to do before the Stonewright gets angry. You don't want to see her angry." }
WordHunterWoW_QuestEN[64101] = { title = "The Proper Procedures", description = "I came here to observe the actions of those from Revendreth. However I have been met with news that concerns me.\n\n{name}, the attendants tell me that they stored anima in canisters and that anima is being looted, by our own people. That's not how this should be done.\n\nCan I entrust you to retrieve the anima, so I might see it returned to its proper place?", objectives = "Collect 5 Lost Anima Vessels.", completion = "There's so much anima here. This will be very useful in helping the attendants rebuild. Thank you." }
WordHunterWoW_QuestEN[64103] = { title = "Old Tricks Work Best", description = "{name}. Here we are again, fighting alongside each other to protect the Shadowlands.\n\nWe're waging a losing war, but we might be able to turn the tide. I need you to seek out some very specific commanders of the Mawsworn forces. In every army, there's good commanders and bad ones. By taking out the good ones, only the bad ones advance, weakening the force as a whole.\n\nOur Eyes have brought us the names. Now I just need you to kill them.", objectives = "Kill Moros, Oizys, and Apate, commanders of the Mawsworn.", completion = "A power vacuum can cause more damage to an army than any bomb or battle." }
WordHunterWoW_QuestEN[64104] = { title = "Think of the Critters", description = "The wildlife of Korthia have been through so much. Some of them can't seem to find enough to eat.\n\nI've saved some extra food that we can share with them. \n\nBut I'm worried that they might be too shy to trust us, and I don't blame them! \n\nHere. Take these treats and see if you can get close enough to them to feed them properly. Even small creatures are so important.", objectives = "Approach and feed Hungry Gromits in Korthia.", completion = "You were able to feed some of them? Wonderful!\n\nI'll start saving up more food for next time. I hope that one day we can help this place heal, too." }
WordHunterWoW_QuestEN[64106] = { title = "A Unified Effort", description = "You have made strong allies within your covenant as well as the others within the Shadowlands. This bond is why they have decided to loan aid to our cause.\n\nThey are ready to fight alongside us as we begin our advance into the Maw.\n\nEach covenant will strike at the Jailer from a different area. Help them scour this treacherous land for any who serve Zovaal so that we may put an end to his growing influence.", objectives = "Aid the covenants in assaulting the Jailer's forces in the Maw.", completion = "Do not relent, <name>. This is only the first of many battles to come." }
WordHunterWoW_QuestEN[64129] = { title = "Charge of the Wild Hunt", description = "Ever since I joined the Wild Hunt I've learned so much about how to fight and how to defend the realms. \n\nI admit I'm still learning. But I am so glad to be learning alongside you, and my runestag friend, Aldermeigh.\n\nAldermeigh is being trained to charge into battle with the bravery of a vorkai, but he needs practice. Will you take him out for a ride, and mow down all the Mawsworn you can?", objectives = "Mount Aldermeigh and slay Mawsworn in Korthia.", completion = "You and Aldermeigh make a great team! Thank you for taking him out and dispatching so many Mawsworn.\n\nOne day, I too will ride with the Wild Hunt, and we will right many wrongs." }
WordHunterWoW_QuestEN[64131] = { title = "Tracking Quest", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[64138] = { title = "Tracking Quest", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[64159] = { title = "Repatriate Rare Supplies", description = "The rebels have stolen supplies from surrounding camps.\n\nYou have proven yourself adept at correcting such situations. I trust you can aid us in resolving this situation.", objectives = "Recover supplies from the makeshift camps across the river." }
WordHunterWoW_QuestEN[64162] = { title = "Ritual Rival", description = "Yet another rival Kahn has risen out of the rebel tribes.\n\nI'd take care of then myself, but I'm busy overseeing things here. \n\nI trust you can teach them the error of their ways?", objectives = "Find and defeat the Rebel Kahn in the makeshift camps across the river." }
WordHunterWoW_QuestEN[64163] = { title = "Revenge Against Renegades", description = "Rebel clans have laid claims to some of our camps across the river.\n\nSuch rebellious rabble need dealing with.\n\nI trust that you are capable of teaching these rebels a lesson on my behalf?\n\nThe camps are an untidy mess as well, so just ignore the chaos for now. We can resolve that later once order is restored.", objectives = "Find and defeat Rebel Centaur Warriors in the makeshift camps across the river." }
WordHunterWoW_QuestEN[64166] = { title = "Random Memory Access", description = "When the Jailer snared Korthia and dragged it toward the Maw, he destroyed so much in this place. Not only mountains and buildings, but the people, too.\n\nThose people had lives, hopes, memories.\n\nI have to think that they can't all be gone, and we might be able to save something of them that lingers.\n\nHere, take some of my power. See if you can collect those memories. Bring them to me, and I'll keep them safe. \n\nNo one should be forgotten.", objectives = "Collect Korthian Memories using the Ephemeral Wings.", completion = "Thank you, <name>. I'll make sure these memories are taken care of. \n\nI wonder what it would have been like, being here as one of them..." }
WordHunterWoW_QuestEN[64167] = { title = "Pets Detective", description = "I'm so glad you're here, {name}!\n\nI've been expecting a delivery of pet supplies and some new pets.  But my distribution manager, Zantini has not reported in. I suspect foul play.\n\nThere's been some shady people eyeballing my store for a while now. But I haven't been able to leave the store and track them down. You can.\n\nTake my pet cat, Fiona, and find these well hidden spies.", objectives = "Investigate the city of Dalaran with Breanni's special spy catching cat, Fiona.", progress = "What have you learned, <name>?", completion = "So there is a group of violet, pet fanatics in the Eye of Azshara?" }
WordHunterWoW_QuestEN[64168] = { title = "Champion: Spore of Marasmius", description = "", objectives = "Take us home?" }
WordHunterWoW_QuestEN[64169] = { title = "Champion: Ella", description = "", objectives = "Ella has been reunited with her grub. You should probably give them a good home." }
WordHunterWoW_QuestEN[64170] = { title = "Champion: ELGU - 007", description = "", objectives = "Power restored. Awaiting Input." }
WordHunterWoW_QuestEN[64171] = { title = "Champion: Kiaranyka", description = "", objectives = "Thank you Maw Walker. I know my Aspirant will be grateful. I would like to aid you in your task, if you would allow me." }
WordHunterWoW_QuestEN[64172] = { title = "Champion: Ryuja Shockfist", description = "", objectives = "That was quite the workout. Let's do it again sometime." }
WordHunterWoW_QuestEN[64173] = { title = "Champion: Kinessa the Absorbent", description = "", objectives = "I think we should leave now. We shall speak of this to no-one." }
WordHunterWoW_QuestEN[64174] = { title = "Champion: Steadyhands", description = "", objectives = "Well now I need to put this platter to use. 'Ow about I serves you?" }
WordHunterWoW_QuestEN[64175] = { title = "Champion: Lassik Spinebender", description = "", objectives = "Do your colleagues require aid? I am sure I can be of some use." }
WordHunterWoW_QuestEN[64184] = { title = "Missing Friend", description = "", objectives = "" }
WordHunterWoW_QuestEN[64185] = { title = "Assist Ella With ?", description = "", objectives = "" }
WordHunterWoW_QuestEN[64186] = { title = "ELGU - 007's Missing Power Core", description = "", objectives = "" }
WordHunterWoW_QuestEN[64187] = { title = "Kiaranyka's Search", description = "", objectives = "" }
WordHunterWoW_QuestEN[64188] = { title = "Ryuja's Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[64189] = { title = "Kinessa's Support", description = "", objectives = "" }
WordHunterWoW_QuestEN[64190] = { title = "Steadyhands' Platter", description = "", objectives = "" }
WordHunterWoW_QuestEN[64191] = { title = "Lassik's Gear", description = "", objectives = "" }
WordHunterWoW_QuestEN[64194] = { title = "War Prototype", description = "As Forgelite Prime, I always work to make something better!\n\nBut largest centurions, they are much too large to bring to Korthia. This, I fix. Here is Atleos, field colossus prototype. Vanguard of the Kyrian! \n\nIt needs testing. More testing. Must be perfect against a powerful opponent.\n\nGo, take Atleos and defeat a great Maw beast! Press all the buttons!", objectives = "Use the Atleos prototype in the Windswept Aerie to defeat Kraxis.", progress = "You have work still, yes?", completion = "Ha! Perfect victory. Atleos returns, and you do too." }
WordHunterWoW_QuestEN[64196] = { title = "Pet Up", description = "It sounds like some group of pet poachers are up to no good in the Eye of Azshara. My supply manager's flight path takes him right over that area!\n\nZantini and his pets, Strigfellow and Speedy IV, were bringing back a rare murloc pet, along with some other pets and supplies.\n\n{name}, please find Zantini and his pets. Help them out. Then we can try to recover the pets and the supplies.", objectives = "Find and help Zantini and his pets along the coast of the Eye of Azshara.", completion = "Thanks for the rescue, pal. Stringfellowe, Speedy IV and me appreciate it." }
WordHunterWoW_QuestEN[64202] = { title = "Gotta Hand It To Ya", description = "Your power Maw Walker... it rivals even mine before Zovaal separated my body.\n\nThis is but a small part of my whole, but more than enough...\n\nAllow me to aid you in your efforts against Zovaal.  In doing so my vengeance will be fulfilled.", objectives = "Accept Nilganihmaht's help.", completion = "<The five rings glow and morph their power coalescing into a small ring that would perfectly fit your finger.>\n\n<Nilganihmaht's voice booms in your head> \n\nLet us embark from this place and bring down Zovaal together." }
WordHunterWoW_QuestEN[64203] = { title = "The Coast is Clear", description = "I was on the last leg of a supply run when we were shot down! They took the pets, but the supplies are scattered over this stretch of beach.\n\nI don't know what they're planning, but I know we gotta get our supplies. You an' me, we ain't subtle.... But Speedy IV... He won't cause all them pirates to go into hiding. He can get the supplies while Stringfellowe surveils the area from the air.\n\nSpeedy's fond of you, so chat him up and let's try to recover the smoldering supplies before they all burn up.", objectives = "Gather pet supplies along the shores of Eye of Azshara with Speedy IV.", progress = "Supplies are always in need.", completion = "We got our pet supplies back. Now we gotta get our pets." }
WordHunterWoW_QuestEN[64210] = { title = "The Box of Many Things", description = "Ah, Maw Walker, of course. Soon I shall be undone, claimed by this place forever. But you continue to walk its halls, unbroken!\n\nIt was my great aspiration to prevail with the help of this box. Sadly, I overestimated my own capabilities.\n\nI trust I am not overestimating yours. Take the box. Prove yourself worthy of it.", objectives = "Bring the Box of Many Things to the Runecarver.", progress = "Ah, you return.", completion = "Ah... a curious device. Anchoring it in this place will prove useful." }
WordHunterWoW_QuestEN[64211] = { title = "Doorway in the Dark", description = "I fear our efforts to stop Zovaal have been thwarted, mortal.\n\nA doorway has been opened to a forbidden realm... and the Banished One has reclaimed a power taken from him long ago.\n\nI sense your allies returning from the Sanctum of Domination. I must know every detail of what transpired.", objectives = "Speak to Jaina and witness the end of the battle in Torghast.", completion = "<Jaina appears sad, but resolute.>\n\nWe still have hope." }
WordHunterWoW_QuestEN[64212] = { title = "Doorway in the Dark", description = "I fear our efforts to stop Zovaal have been thwarted, mortal.\n\nA doorway has been opened to a forbidden realm... and the Banished One has reclaimed a power taken from him long ago.\n\nI sense your allies returning from the Sanctum of Domination. I must know every detail of what transpired.", objectives = "Speak to Thrall and witness the end of the battle in Torghast.", completion = "<Thrall's brow is furrowed.>\n\nWe can't let the Jailer win." }
WordHunterWoW_QuestEN[64213] = { title = "A Symbol of Hope", description = "Before Anduin followed the Jailer through the gateway, he dropped something.\n\nI don't think this was part of the Jailer's plan. It must be a sign that Anduin's soul is still his own!\n\n<Jaina opens her hand to show you a golden compass.>\n\nThis was very personal to Anduin. I feel his presence upon it.\n\nWe need to know why he left it for us.", objectives = "Assist Jaina in examining Anduin's compass.", progress = "If Anduin was able to leave this for us to find, then some part of him must still be free from the Jailer's domination...", completion = "<Tears fall from Jaina's eyes.>\n\nWe cannot lose him, <name>. No matter what it takes." }
WordHunterWoW_QuestEN[64214] = { title = "A Symbol of Hope", description = "Before Anduin followed the Jailer through the gateway, he dropped something.\n\nI'm not sure what it was, but Jaina picked it up. Perhaps this is a sign that Anduin is still fighting back against the Jailer!\n\nWe need to find out what this object was, and why the young king left it for us.", objectives = "Assist in examining Anduin's compass.", progress = "Why did Anduin leave this for us to find?", completion = "Anduin Wrynn does not deserve such a fate.\n\nWe must fight to save him, <name>!" }
WordHunterWoW_QuestEN[64215] = { title = "Paw Patrol", description = "While Speedy IV was collecting supplies, Stringfellowe was scouting the rest of the Eye of Azshara.\n\nTurns out there is a whole mess of pirates to the west.  That must be where the pets are at.\n\nHead over there and rescue the pets.", objectives = "Obtain keys from the Violetsail pirates along the west coast of the Eye of Azshara. Then set the captured pets free.", progress = "Have you found them, <name>?", completion = "Nice work freeing the pets, <name>. \n\nBut still no sign of Gurgl." }
WordHunterWoW_QuestEN[64216] = { title = "Tower Knowledge", description = "The woven power of this box can only be unlocked by feeding it pride and memory. In its weave are incantations I have seen used in the other realms to siphon or condition a soul. This... abomination... has used these tools of redemption and honor to create a lock.\n\nAs you challenge the floors of Torghast, your skill, speed, and efficiency will all contribute to Tower Knowledge which this box can feed upon. \n\nFeed it to retrieve the powers within.", objectives = "Place the Box of Many Things in Torghast.", progress = "<The Box of Many Things thrums with power.>", completion = "<The box hungers, reaching into your memories of Torghast for past deeds to feed upon.>" }
WordHunterWoW_QuestEN[64218] = { title = "Danger Near and Far", description = "We have done all we can about the Jailer for now, my friend. \n\nOther matters require our attention. Like the devourer rifts I recently saw opening to the east! \n\nIf we do not stop them, those beasts will wreak havoc on this place.\n\nWill you help me take care of them, {name}?", objectives = "Investigate the Genesis Fields.", completion = "Someone inside needs our help!" }
WordHunterWoW_QuestEN[64219] = { title = "A Mysterious Voice", description = "So much destruction. The devourers are insatiable. \n\nI hope the creature we heard is not badly hurt.\n\nThis door is not going to open normally. Perhaps we can force our way through together!\n\nWhatever is on the other side needs our help.", objectives = "Enter the Cradle of Nascence.", progress = "We must help whoever is trapped inside!", completion = "We were too late... but we must not give up hope." }
WordHunterWoW_QuestEN[64223] = { title = "Core of the Matter", description = "She has fallen, but appears to still be alive. There must be something we can do to help her.\n\nLet us see if the Enlightened know anything. I will find some way to transport her and meet you back in Haven.", objectives = "Speak with Elder Kreth in Haven.", progress = "Let us hope we are not too late.", completion = "That was unhelpful..." }
WordHunterWoW_QuestEN[64224] = { title = "Seeking the Unknown", description = "If the Elders will not assist us, we must find someone who will. \n\nThat other Enlightened, Firim... he was much more interested in the automa. \n\nHe said he was estranged from his kin. Someone in Haven must know something about him. \n\nLook around the camp for clues about Firim's whereabouts. I will try again to convince the Elders to talk.", objectives = "Search Haven for information about Firim.", progress = "Have you found anything?", completion = "The elders refuse to say anything about Firim.\n\nI hope you were able to learn something." }
WordHunterWoW_QuestEN[64225] = { title = "Finding Firim", description = "You found something? What luck! May I see the letter?\n\nSo, an Enlightened named Xevveth heard that Firim was last seen west of the Forge of the Afterlives, and went to go seek him out. \n\nWe should begin our search there.", objectives = "Find Firim.", completion = "Those assassins are after more than just my life. They wish to steal my research! I cannot let them have it." }
WordHunterWoW_QuestEN[64226] = { title = "Security Measures", description = "It seems the hidden traps I placed around the grotto are not as effective as I would like, considering your presence in my home. \n\nHowever, they are still useful in preventing the majority of unwanted attention. \n\nSince you so kindly brought assassins to me, I cannot reset the traps myself. \n\nSo you will need to do it for me. I will stay here to guard both myself and my precious research. Use this Sensory Synchronizer I placed nearby to show you which traps need to be reset.", objectives = "Use the Sensory Synchronizer, then reset 10 Triggered Traps near Exile's Hollow.", completion = "Good. That should shield us from notice for a while." }
WordHunterWoW_QuestEN[64227] = { title = "Unseen Agents", description = "Ever since you opened the way from Oribos, certain cartels have taken the opportunity to come after me and my work in a rather... lethal fashion. They know how important my research is to everything. \n\nMore assassins are sure to follow, what with you blazing a clear path right to me! \n\nI cannot get them all. You need to fix this and help protect my secrets. \n\nTake care of them for me.", objectives = "Kill assassins near Exile's Hollow.", completion = "I suppose you have proven to be useful. Thank you." }
WordHunterWoW_QuestEN[64228] = { title = "Now You May Speak", description = "You truly brought me an oracle! Intact even!\n\nI have never known these divine beings to speak to anyone but automa. There is so much we could learn from her about Zereth Mortis.\n\nYou must tell me everything!", objectives = "Talk to Firim about the oracle.", progress = "Let me hear what happened...", completion = "Astounding!" }
WordHunterWoW_QuestEN[64230] = { title = "Cyphers of the First Ones", description = "The way is not quite clear, but the first steps have been made.\n\nIt seems the divine construct has taken more of a liking to you than to me. \n\nNow that it has given you the beginnings of understanding, see what else it wishes to show you.\n\nThe results should be enlightening.", objectives = "Investigate the Cypher Console.", progress = "You have been blessed.", completion = "Can't you feel the knowledge you've gained coursing through you?!\n\nTo think it is you who will unlock the secrets of Zereth Mortis...\n\nI will be watching you very closely." }
WordHunterWoW_QuestEN[64231] = { title = "[DNT] Training Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[64237] = { title = "Gurgl and the Bandit", description = "We've got all the pets back except Gurgl. {name}, we need to get that pet back for Breanni.\n\nStringfellowe saw a nook where we think the leader of these pet poachers is hiding out. \n\nLet's get 'em!", objectives = "Find and battle the leader of the pet poachers.", completion = "You're back, <name>! And you've brought back our supplies, pets and Gurgl!!\n\nGurgl doesn't seem to want to leave your side.\n\nHe's been through enough hard times and I am not going to break this one's little heart.\n\nTake care of my friend, <name>.\n\nTake care of my friend, Gurgl." }
WordHunterWoW_QuestEN[64240] = { title = "Flight of the Kyrian", description = "We've engaged in a heavy battle at the entrance to the Vault of Secrets! Our forces could use some reinforcement.\n\nPlease, guide my fellow Ascended to give support to our fighters there. \n\nThe fighters on the ground can handle the clean-up, but they need shields and healing.\n\nGood luck!", objectives = "Assist covenant forces from the air at the Vault of Secrets.", progress = "Have you helped our forces at the Vault of Secrets?", completion = "You don't always need to strike with force from the skies! Sometimes just a little extra help from healing is the best tactic.\n\nThank you, my friend." }
WordHunterWoW_QuestEN[64255] = { title = "Party Time", description = "Oh neat that looks like Temel's hat!", objectives = "Oh neat that looks like Temel's hat!", progress = "Oh neat that looks like Temel's hat!", completion = "<Your butler has a cheshire grin as he takes the party hat.>" }
WordHunterWoW_QuestEN[64266] = { title = "Supplies from The Archivists' Codex", description = "I have no words to express the warmth that fills me knowing your dedication has ensured Korthia's history remain intact.\n\nPlease. Allow me to share my gratitude.", objectives = "Speak with Archivist Roh-Suir in the Reliquary of Remembrance in Korthia.", completion = "I have no words to express the warmth that fills me knowing your dedication has ensured Korthia's history remain intact.\n\nPlease. Allow me to share my gratitude." }
WordHunterWoW_QuestEN[64267] = { title = "Mysterious Gifts from Ve'nari", description = "I'm impressed by your sheer tenacity to survive while remaining somewhat useful, Maw Walker. You remind me of myself when I was much younger and naive. \n\nTake this and continue your work... somewhere less conspicuous.", objectives = "Speak with Ve'nari at Ve'nari's Refuge in the Maw.", completion = "I'm impressed by your sheer tenacity to survive while remaining somewhat useful, Maw Walker. You remind me of myself when I was much younger and naive. \n\nTake this and continue your work... somewhere less conspicuous." }
WordHunterWoW_QuestEN[64271] = { title = "A More Civilized Way", description = "Ah, {name}.\n\nI have a matter to discuss with you. But not here.\n\n<Nadjia eyes the other denizens of Keeper's Respite suspiciously.>\n\nMeet me where the road enters Korthia from the Maw and I will explain.", objectives = "Meet Nadjia near the road leading into Korthia.", completion = "Your form still needs work. Thank you, for taking time out of our unending campaign to duel. We must remember, even in times of great struggle, to do things that bring us joy." }
WordHunterWoW_QuestEN[64273] = { title = "Containing the Helsworn", description = "", objectives = "" }
WordHunterWoW_QuestEN[64274] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[64282] = { title = "Full of Surprises", description = "You continue to surprise me Maw Walker, your presence here is most unexpected!\n\nSince we are both here, I believe we should work together.\n\nThe Jailer has a vault full of valuables, somewhere in this rift.  Locate it for me, or bring it here to be opened and we'll share the wealth together!", objectives = "Locate Zovaal's Vault.", progress = "Have you found the vault?", completion = "This is quite a profitable partnership. I am certain Cartel Ve will be most unhappy with our success." }
WordHunterWoW_QuestEN[64286] = { title = "Paragon of Death's Advance", description = "The call to action has been answered, yet again. Your efforts shall not go unnoticed.\n\nLet us see if we cannot find a fitting reward for your efforts.", objectives = "Speak with Duchess Mynx at Keeper's Respite in Korthia.", completion = "The first of many interactions, I hope.\n\nPlease. Accept this as a token of our appreciation." }
WordHunterWoW_QuestEN[64287] = { title = "Paragon of The Archivists' Codex", description = "You have gone to great lengths to restore that which we cherish most dearly, Maw Walker.\n\nMeet me in my chamber when you are ready. We have one final matter to discuss.", objectives = "Speak with Archivist Roh-Suir at the Reliquary of Remembrance in Korthia.", completion = "The value of that which we hold in our possession endures while they remain in our presence, but knowledge and memories exist in a space that cannot be misplaced or stolen, only forgotten.\nMay the journey and memories of our time together remain with you always." }
WordHunterWoW_QuestEN[64288] = { title = "Paragon of Ve'nari", description = "Come, Maw Walker. Meet me at my refuge.\n\nWe have one final matter to discuss.\n\n...and do make sure you are not followed.", objectives = "Speak with Ve'nari at Ve'nari's Refuge in The Maw.", completion = "Our arrangement has benefited me quite nicely.\n\n<Ve'nari looks around, admiring how her hard work has paid off.>\n\nNow, before I plunge this sack of discarded waste into the darkness, perhaps there is something here you may find of use.\n\nAnd do not let this go to your head, Maw Walker. Think of this as an investment in your future dedication to my cause." }
WordHunterWoW_QuestEN[64289] = { title = "Picking Up the Pieces", description = "Much was lost when Korthia was pulled into the Maw.\n\nPriceless relics were torn asunder. I have seen creatures carrying the remnants of these items. \n\nThey must be recovered.\n\nConfront the Jailer's forces and search what remains of Korthia for these fragments of our once glorious vault.", objectives = "Recover 50 Relic Fragments from rare creatures and treasures throughout Korthia.", completion = "These will do nicely. There is much I can do to improve them." }
WordHunterWoW_QuestEN[64290] = { title = "Collecting Research", description = "You have done well to collect these fragments. They will go a long way to restoring our archives. \n\nI can use what you have found to gather more research about what was lost within Korthia. \n\nAfterwards, it will be up to you to find more fragments and relics within Korthia to boost our archives.", objectives = "Speak with Archivist Roh-Suir to turn in any Korthian Relics for Cataloged Research.", progress = "We thank you for your aid so far, Maw Walker.", completion = "This should do nicely. The reliquary will improve with more research." }
WordHunterWoW_QuestEN[64292] = { title = "Maelie, The Wanderer", description = "I can't thank you enough for finding Maelie! You know, I think she's just a little bit more than I can handle.\n\nWould you mind watching over her? I think she's really taken a liking to you!", objectives = "Accept responsibility for Maelie.", completion = "Take care of Maelie, Maw Walker." }
WordHunterWoW_QuestEN[64304] = { title = "New Opportunities Await", description = "Going somewhere in a hurry? Ah, yes. You, Maw Walker--you would not happen to be venturing to explore the new, mysterious mass within the Maw, would you?\n\nI do wonder what secrets it holds.\n\nPerhaps there is something we can do to help one another.\n\nIf this is of interest to you then let us continue our discussion. If not, move along. I will find someone else to do the job.", objectives = "Slay 20 players in Korthia.", completion = "Excellent work, indeed.\n\nA reward for your efforts, and to our continued shared interests." }
WordHunterWoW_QuestEN[64306] = { title = "Quest Completion Criteria", description = "", objectives = "" }
WordHunterWoW_QuestEN[64314] = { title = "Covenants Renewed", description = "Our efforts were focused on preventing the Jailer from shattering the barrier around the Maw and invading the rest of the Shadowlands.\n\nInstead, he expanded the Maw itself to envelop Oribos and claim the Aribiter's sigil.\n\nI do not fully understand what we witnessed atop Torghast. But the Primus certainly does.\n\nIt is time to enact his contingency plan. The covenants will arrive with their sigils shortly. \n\nInform the Primus that we are ready to begin.", objectives = "Speak to the Primus, then claim the Sigils from each covenant.", completion = "Excellent, mortal. You have done your part.\n\nNow my work begins." }
WordHunterWoW_QuestEN[64322] = { title = "Night Fae Veteran", description = "Ardenweald is safer than it has been in quite some time, thanks to you.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Ardenweald.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", completion = "Ah, <name>. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons." }
WordHunterWoW_QuestEN[64323] = { title = "Kyrian Veteran", description = "Bastion is healing thanks to you, {name}. The path is clear.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Bastion.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", completion = "Ah, <name>. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons." }
WordHunterWoW_QuestEN[64324] = { title = "Necrolord Veteran", description = "The might of the Necrolords grows thanks to you, {name}.\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Maldraxxus.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", completion = "Ah, <name>. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons." }
WordHunterWoW_QuestEN[64325] = { title = "Sinfall Veteran", description = "Sinfall's influence grows thanks to your triumphs, {name}!\n\nYour accomplishments have not gone unnoticed, even beyond the borders of Revendreth.\n\nTales of your victories have echoed through the halls of Oribos. Zo'sorg, the Master of Conflict, has requested a meeting with you in the Enclave.\n\nThey have a keen interest in the art of war. I suggest you don't keep them waiting.", objectives = "Meet with Zo'sorg in the Enclave in Oribos.", completion = "Ah, <name>. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo'dash is authorized to further upgrade your armor and weapons." }
WordHunterWoW_QuestEN[64340] = { title = "Bewitching", description = "Does everyone on your world wear these pointy hats?!", objectives = "Does everyone on your world wear these pointy hats?!", progress = "Does everyone on your world wear these pointy hats?!", completion = "<Your butler tries out a terribly awkward cackle as he takes the hat, then coughs remembering his decorum.>" }
WordHunterWoW_QuestEN[64368] = { title = "Relic Efficiency", description = "", objectives = "Your work in restoring the reliquary has been invaluable.\n\nI've uncovered new methods to find relics. Hopefully they will help you." }
WordHunterWoW_QuestEN[64376] = { title = "Hidden Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[64430] = { title = "Spill the Tea", description = "It seems Tubbins and Gubbins have gone off somewhere.\n\nI do worry about the two of them. Be a dear and check on them. One never knows what shenanigans they might be up to.\n\nI last saw them speaking with one of the faeries from Ardenweald. They were discussing the fine art of tea making.", objectives = "Find Tubbins and Gubbins.", completion = "Ah, you've all returned safely. Wonderful!" }
WordHunterWoW_QuestEN[64432] = { title = "Strength to Weakness", description = "{name}, the scrap metal we've been recovering has some interesting properties. I have come to believe the mawsworn are imbuing their armor and increasing its durability.\n\nTake this lightning rod. First, you will need to get struck by lightning. Don't make that face. You'll be fine. But, you need to also be grounded on mawsworn metal. The large chains embedded in Korthia, near the Windswept Aerie should work.\n\nOnce you are... ah... energized, I will send a tauralus, Borrhas, to carry you into battle.", objectives = "Empower the lightning rod, then kill mawsworn.", completion = "I told you it would be fine. How did the test go? I wish I could have seen the looks on their faces when their fancy armor was suddenly the reason they were being destroyed." }
WordHunterWoW_QuestEN[64437] = { title = "Inform the Primus", description = "{name}, return to Korthia and tell the Primus that the Winter Queen's sigil has been restored.", objectives = "Return to the Primus in Korthia.", completion = "Ah, good. With the Queen's Sigil restored, we're that much closer to being able to stop Zovaal. Thank you for this information." }
WordHunterWoW_QuestEN[64438] = { title = "Empowering Equipment", description = "The research you find can unlock many possibilities.\n\nOne such avenue is improving some equipment that you may find within Korthia.\n\nSpeak with my assistant nearby. He can use our research to restore this equipment to its former power.", objectives = "Speak with Assistant Scholar Kah-Vez to upgrade one piece of equipment from Korthia.", progress = "I will do what I can to aid you, Maw Walker.", completion = "This is the least we can do to help you in your efforts, Maw Walker." }
WordHunterWoW_QuestEN[64441] = { title = "A Loose Thread", description = "<A book appears to have been recently knocked off the table from the nearby Venthyr encampment.\n\nThe Venthyr would likely appreciate you returning it to them before one of the gromits uses it for nesting material.>", objectives = "Pick up the book to return it.", completion = "<It appears you and Mal'ganis are not done with one another. When you finally confront the Jailer, you are certain the dreadlord will be there as well.>" }
WordHunterWoW_QuestEN[64458] = { title = "Adventurer: Sulanoom", description = "", objectives = "Your devotion to Ardenweald is unquestionable, <name>.\n\nSulanoom was especially impressed by your unshakable spirit, so much so that they wish to join our fight here.\n\nLet's make good use of their services!" }
WordHunterWoW_QuestEN[64459] = { title = "Adventurer: Elwyn", description = "", objectives = "The forest blesses us, <name>. Your interest in the wellbeing of Ardenweald has not gone unnoticed.\n\nThe venerable Elwyn has agreed to join our fight.\n\nTogether we shall protect the realm." }
WordHunterWoW_QuestEN[64460] = { title = "Adventurer: Yanlar", description = "", objectives = "<name>, you have fought many valiant battles for Ardenweald.\n\nYanlar has joined you for many fights across the Shadowlands and has been continually impressed with your valor. \n\nI am delighted to say that they have asked to permanently fight with you." }
WordHunterWoW_QuestEN[64461] = { title = "Adventurer: Hermestes", description = "", objectives = "Your faith in Bastion is inspiring, <name>.\n\nHermestes has seen your unflagging dedication to our cause.\n\nIt has inspired them to join us in a different capacity at the Hold, so that they may contribute further to the greater needs of the Shadowlands." }
WordHunterWoW_QuestEN[64462] = { title = "Adventurer: Cromas the Mystic", description = "", objectives = "Greetings, my mortal friend! I have good tidings.\n\nCromas the Mystic has watched your progress with Kyrian with great interest for quite some time.\n\nNow he wishes to join you and lend his courage and skills to our cause." }
WordHunterWoW_QuestEN[64463] = { title = "Adventurer: Auric Spiritguide", description = "", objectives = "It seems we have another recruit, <name>.\n\nI am honored to say that the Auric Spiritguide has decided to lend their wisdom and skills to our cause.\n\nShe will make a wonderful ally!" }
WordHunterWoW_QuestEN[64464] = { title = "Adventurer: Lyra Hailstorm", description = "", objectives = "We've got an exciting development today, <name>!\n\nLyra Hailstorm wants join our ranks here at the Seat! Her expertise will be a welcome addition.\n\nNow go fight together for the good of Maldraxxus!" }
WordHunterWoW_QuestEN[64465] = { title = "Adventurer: Enceladus", description = "", objectives = "Your dedication is inspiring, <name>.\n\nYou have made quite an impression on Enceladus. Fixing your weapons has shown him that you are a true warrior.\n\nThe purpose is clear, fight for Maldraxxus!" }
WordHunterWoW_QuestEN[64466] = { title = "Adventurer: Deathfang", description = "", objectives = "We've got exciting news today, <name>.\n\nBaroness Draka has given us the distinct honor of conscripting Deathfang into our service.\n\nMaldraxxus shall be victorious with help from this ferocious beast!" }
WordHunterWoW_QuestEN[64467] = { title = "Adventurer: Chachi the Artiste", description = "", objectives = "Exquisite news, <name>.\n\nChachi the Artiste has decided to lend his exquisite taste in service to Revendreth.\n\nBe sure to make good use of his skills." }
WordHunterWoW_QuestEN[64468] = { title = "Adventurer: Madame Iza", description = "", objectives = "Madame Iza has decided to enter the fray in service of Revendreth.\n\nIsn't that exciting, <name>?\n\nHer remarks aren't the only thing that is cutting, so do not underestimate her in a fight." }
WordHunterWoW_QuestEN[64469] = { title = "Adventurer: Lucia", description = "", objectives = "Lucia wishes to bring her wealth of skills to our cause <name>.\n\nShe's been restless to punish those who have turned on Revendreth.\n\nUse her well." }
WordHunterWoW_QuestEN[64506] = { title = "What Must Be Found", description = "There is much detailed in the codex. Items that are forever lost, and some that still exist.\n\nSome powerful relics may remain, hidden somewhere within Korthia. \n\nBrowse the reliquary. You will find echoes of artifacts that are still whole here in Korthia.\n\nCommit them to memory. You must find them and return them to me.", objectives = "Examine what relics are missing within the Reliquary of Remembrance.", progress = "Have you seen the missing relics?", completion = "These are just some of the relics that are missing.\n\nYou have the power to recover them, wherever they are within Korthia." }
WordHunterWoW_QuestEN[64509] = { title = "Stylish Cover", description = "Is that ta' same type of head topper Hips from the Sinstone Swingers wears?", objectives = "Is that ta' same type of head topper Hips from the Sinstone Swingers wears?", progress = "Is that ta' same type of head topper Hips from the Sinstone Swingers wears?", completion = "Is that actually his spare hat? I can't believe it, I think I see some sweat on the band... thank you!" }
WordHunterWoW_QuestEN[64511] = { title = "Missing Relics", description = "Thanks to your aid, I have been able to recover more research regarding the lost relics from the vault.\n\nI have gone over the codex and believe there are more relics within Korthia that can still be recovered.\n\nThese were sealed within chests that I believe have been scattered in Korthia during the initial attack.\n\nI have set up the missing relics in here. Commit them to memory. They must be recovered.", objectives = "Examine the missing relics within the Reliquary of Remembrance.", progress = "Have you seen the missing relics?", completion = "Please, do what you can to find these relics. We must not let this knowledge fall to ruin." }
WordHunterWoW_QuestEN[64513] = { title = "Ve'rayn's Head", description = "<Ve'rayn has been hunting Ve'nari for some time. Ve'nari would be very interested in seeing proof that she has been dealt with permanently.>", objectives = "Deliver Ve'rayn's Head to Ve'nari in Ve'nari's Refuge.\n\nProvided item:", completion = "Is that what I think it is...?" }
WordHunterWoW_QuestEN[64517] = { title = "Byron Test - Item Gained", description = "", objectives = "" }
WordHunterWoW_QuestEN[64518] = { title = "Byron Test - Obtain Any Item", description = "", objectives = "" }
WordHunterWoW_QuestEN[64519] = { title = "Lost Vaults", description = "I have finished my research on more relics that may still exist in Korthia. I believe they are still within our smaller vaults.\n\nWith your help, I can recreate devices that are capable of repairing the entrances to these vaults.\n\nTake note of the echoes of relics that are still missing. Please review them so you know what to look for.", objectives = "Examine the missing relics within the Reliquary of Remembrance.", progress = "Have you seen the missing relics?", completion = "Thank you for your continued aid. The reliquary will be restored, thanks to your diligent work." }
WordHunterWoW_QuestEN[64521] = { title = "Helsworn Battle Plans", description = "<These battle plans detail possible movements into Korthia, and include detailed reports of the defensive capabilities of the Death's Advance in the region.\n\nDuchess Mynx in Keeper's Respite would be able to spread this information rapidly to those who need it.>", objectives = "Deliver Helsworn Battle Plans to Duchess Mynx in Keeper's Respite.\n\nProvided item:", completion = "<Duchess Mynx's eyes widen as she browses the documents you brought her.>\n\nI will disseminate these immediately. Thank you!" }
WordHunterWoW_QuestEN[64522] = { title = "Stolen Korthian Supplies", description = "<These supplies are marked with the seal of the Death's Advance, stolen from the Rift without being noticed.\n\nDuchess Mynx in Keeper's Respite would be very grateful to have this returned.>", objectives = "Deliver Stolen Korthian Supplies to Duchess Mynx in Keeper's Respite.\n\nProvided item:", completion = "<Duchess Mynx looks at you incredulously.>\n\nYou found these WHERE?!\n\nWell, how am I supposed to stop thieves I cannot even see? Cowardly shades!" }
WordHunterWoW_QuestEN[64526] = { title = "Mysterious Rifts", description = "Thank you so much for your aid, {name}. I have uncovered more relics from the codex that remain intact.\n\nThe key to finding these relics rests within the strange rifts within Korthia.\n\nI can now craft a way for you to enter these rifts, in order to gain access to these missing relics.\n\nAs before, take note of the echoes to understand what these relics look like. Please be sure to examine them before you depart.", objectives = "Examine the missing relics within the Reliquary of Remembrance and purchase a Repaired Riftkey from Roh-Suir.", progress = "Have you seen the missing relics?", completion = "Thank you for your continued aid. The reliquary will be restored, thanks to your diligent work." }
WordHunterWoW_QuestEN[64527] = { title = "Observing the Chase", description = "In our observations of your kind's conflict, we have noticed a high rate of escape among the prey.\n\nThis is unadvantageous to our observation efforts.\n\nThe Observer has acquired a tool we believe will improve your ability to force conflict.\n\nBefore I give it to you, we ask that you prove your willingness to participate in such conflicts, so that we know we will receive a worthy return on this investment.", objectives = "Enable War Mode and slay 1 player within the world.", progress = "Your hesitation to set out and hunt your prey is not promising, <name>...", completion = "Excellent. We will be watching your future endeavors with great interest." }
WordHunterWoW_QuestEN[64528] = { title = "Wilderling Saddle", description = "<As you slipped off of the escaped wilderling's back, it shook its saddle off at your feet. It reluctantly left your side as the night fae led it back to Keeper's Respite.\n\nReldorn in Keeper's Respite might know what to make of this gesture.>", objectives = "Deliver Wilderling Saddle to Reldorn in Keeper's Respite.\n\nProvided item:", completion = "<Reldorn laughs when he sees the saddle you're carrying.>\n\nI had wondered where that one's saddle had ended up. He has resisted every rider that has attempted companionship with it, but it appears he has finally found one he considers worthy.\n\nYou have made a very stubborn, loyal companion this day, <name>." }
WordHunterWoW_QuestEN[64529] = { title = "Intact Aquilon Core", description = "<The massive devourer was clutching this aquilon power core in its fist when it died, no doubt ripped from one of the destroyed aquilon around it. The power core appears to be almost entirely intact.\n\nDeos in Keeper's Respite would be able to help you locate an aquilon that you could power with it.>", objectives = "Deliver Intact Aquilon Core to Deos in Keeper's Respite.\n\nProvided item:", completion = "<Deos's eyes light up when he sees the intact power core you're holding.>\n\nThank the Archon! I recovered a few broken aquilon from the fight earlier, and one is missing its power core. I will restore it so that you may take it with you." }
WordHunterWoW_QuestEN[64530] = { title = "Gravewing Crystal", description = "<This large crystal fragment shattered off of the massive construct's body. Flashes of energy crackle inside of it.\n\nThe Stonewright in Keeper's Respite would be able to use this crystal to empower a gravewing for you.>", objectives = "Deliver Gravewing Crystal to the Stonewright in Keeper's Respite.\n\nProvided item:", completion = "<The Stonewright raises one eyebrow as you hand her the powerful crystal.>\n\nThis is truly a unique crystal... Luckily, I know just the stonechild worthy of it. I trust you will take good care of her." }
WordHunterWoW_QuestEN[64531] = { title = "Mor'geth", description = "", objectives = "" }
WordHunterWoW_QuestEN[64532] = { title = "The Final Relics", description = "I have excellent news, {name}. I have uncovered the last set of our missing relics! \n\nIt may be difficult for you to locate them, but I have developed the proper research to aid you.\n\nPlease, review the last of our missing relics. We are so close to finding them all!", objectives = "Examine the missing relics within the Reliquary of Remembrance and purchase Research Report: Ancient Shrines.", progress = "Have you seen the missing relics?", completion = "Thank you for your continued aid. The reliquary will be restored, thanks to your diligent work." }
WordHunterWoW_QuestEN[64541] = { title = "The Cost of Death", description = "Here to trade, Maw Walker?", objectives = "Here to trade, Maw Walker?", progress = "Here to trade, Maw Walker?", completion = "With so many more interlopers in the Maw I need to secure my Stygia supply. Your efforts to keep me supplied will not go unnoticed and you always know where to find me." }
WordHunterWoW_QuestEN[64546] = { title = "Visions of Sire Denathrius", description = "", objectives = "It appears I am at your mercy of your whims, <name>.\n\nAs a creation of Theotar, I am obliged to attend your court whenever you wish.\n\nI suppose I shall be seeing you soon..." }
WordHunterWoW_QuestEN[64549] = { title = "Legend of the Animaswell", description = "<This appears to be an incomplete set of notes detailing one archivist's search for a mythical font of anima hidden somewhere deep in Korthia.\n\nWatcher Vesperbloom in the Heart of the Forest would be able to help you put together a team to search for it.>", objectives = "Deliver Legend of the Animaswell to Watcher Vesperbloom in the Heart of the Forest.\n\nProvided item:", completion = "<Watcher Vesperbloom carefully studies the documents you brought her.>\n\nThe documentation is incomplete. It is unclear if the archivist even survived...\n\nBut the tales of the anima are incredible, and there are enough details here to launch an expedition.\n\nIt will not be easy. The archivist warns of many dangers protecting the anima source..." }
WordHunterWoW_QuestEN[64551] = { title = "Legend of the Animaswell", description = "<This appears to be an incomplete set of notes detailing one archivist's search for a mythical font of anima hidden somewhere deep in Korthia.\n\nMerick Feldscar in the Seat of the Primus would be able to help you put together a team to search for it.>", objectives = "Deliver Legend of the Animaswell to Merick Feldscar in the Seat of the Primus.\n\nProvided item:", completion = "<Merick Feldscar carefully studies the documents you brought him.>\n\nThe documentation is incomplete. It is unclear if the archivist even survived...\n\nBut the tales of the anima are impressive, and there are enough details here to launch an expedition.\n\nIt will not be easy. The archivist warns of many dangers protecting the anima source..." }
WordHunterWoW_QuestEN[64552] = { title = "Legend of the Animaswell", description = "<This appears to be an incomplete set of notes detailing one archivist's search for a mythical font of anima hidden somewhere deep in Korthia.\n\nKoros in Elysian Hold would be able to help you put together a team to search for it.>", objectives = "Deliver Legend of the Animaswell to Koros in Elysian Hold.\n\nProvided item:", completion = "<Koros carefully studies the documents you brought him.>\n\nThe documentation is incomplete. It is unclear if the archivist even survived...\n\nBut the tales of the anima are coherent, and there are enough details here to launch an expedition.\n\nIt will not be easy. The archivist warns of many dangers protecting the anima source..." }
WordHunterWoW_QuestEN[64553] = { title = "Legend of the Animaswell", description = "<This appears to be an incomplete set of notes detailing one archivist's search for a mythical font of anima hidden somewhere deep in Korthia.\n\nTactician Sakaa in Sinfall would be able to help you put together a team to search for it.>", objectives = "Deliver Legend of the Animaswell to Tactician Sakaa in Sinfall.\n\nProvided item:", completion = "<Tactician Sakaa carefully studies the documents you brought her.>\n\nThe documentation is incomplete. It is unclear if the archivist even survived...\n\nBut the tales of the anima are incredible, and there are enough details here to launch an expedition.\n\nIt will not be easy. The archivist warns of many dangers protecting the anima source..." }
WordHunterWoW_QuestEN[64554] = { title = "Venthyr Assault", description = "The Jailer's forces  have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination!\n\nYour help is needed Maw Walker. Assist our forces on the battlefield!You will receive:", objectives = "Complete 1 quests in Perdition Hold and the Face of Oblivion." }
WordHunterWoW_QuestEN[64555] = { title = "Surveying Secrets", description = "Each of the covenants have provided their own specialists in their areas of expertise. A few of them have taken to the field to scout this unknown land.\n\nSpeak with them. They should all be keeping a report of their survey. Return them to me.", objectives = "Speak with the forward scouts in Korthia.", progress = "Have you found all of the scouts?", completion = "Most of this information is useful. My thanks, Maw Walker." }
WordHunterWoW_QuestEN[64556] = { title = "In Need of Assistance", description = "The inhabitants of Korthia have been through much. Were it not for our arrival, the Jailer's forces would have rampaged through the remainder of the City of Secrets, leaving destruction in their wake.\n\nTo continue our efforts, we must assist those in need.\n\nHeed the call of our allies, Maw Walker. See to it no stone is left unturned and no ally of the Jailer left alive.", objectives = "Complete 3 Daily Quests from Mikanikos, Ta'nasi, and Kael'thas throughout Korthia.", completion = "This work brings us one step closer to ending Zovaal's reign over this forsaken land." }
WordHunterWoW_QuestEN[64557] = { title = "In Darkness, Found", description = "Cartel Ve has a reputation for creeping around dangerous places in search of treasure. If they had any sense, they would leave the acquisition and sale of goods to the Xy. Alas.\n\nOne Ve member disappeared into Torghast with a plundered box of powerful items that he assumed would help him explore in safety. Madness!", objectives = "Find Ve'nish in Torghast, Tower of the Damned.", completion = "Step no closer! Reveal yourself!" }
WordHunterWoW_QuestEN[64560] = { title = "Anima Reclamation", description = "Our efforts here need a constant supply of troops, supplies, and anima. The last one is the hardest, for obvious reasons. But I've learned to be resourceful. \n\nNearby there is a plentiful source of anima: the devourers that currently swarm the Sanctuary of Guidance. It's not as easy as beating it out of a soul, but it's just as effective, if you're strong enough. Are you?", objectives = "Reclaim 8 Devoured Anima from devourers at the Sanctuary of Guidance.", progress = "Every drop of anima we reclaim is a potential weapon against the Jailer.", completion = "You can trust me with this anima. I will see it is turned against the Jailer and his forces." }
WordHunterWoW_QuestEN[64561] = { title = "Observational Records", description = "Greetings, Maw Walker, a moment of your time?\n\nAs you no doubt know, my cartel has quietly spread observational devices all across Korthia. But that data is no good to us if it is not retrieved. Which is where you come in.\n\nThe records from the Windswept Aerie and Estuary of Awakening should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb.\n\nAnd don't forget to look below ground!\n\nBring those data to me, and I will reward you handsomely.", objectives = "Collect 5 Observational Records from the Windswept Aerie and Estuary of Awakening in Korthia.", progress = "Have you retrieved the observational records from the Windswept Aerie and Estuary of Awakening?", completion = "Places like the Aerie and Estuary must have been desolate, even before all the destruction. What interesting creatures congregate there.\n\nWill they all survive these changes, or will some adapt, and become even more fearsome?\n\nAnd here is your reward, as promised." }
WordHunterWoW_QuestEN[64562] = { title = "We Need a Healer - You!", description = "There are too many wounded on the battlefield! \n\nNot everyone can 'bash it and make better.' We need more healers.\n\nYou, take my device and get our wounded back on their feet!", objectives = "Restore 10 Wounded Covenant Allies in Seeker's Quorum.", completion = "That got them back on their feet!\n\nAny little bit helps to keep us in the fight." }
WordHunterWoW_QuestEN[64567] = { title = "The Missing Scholar", description = "Ah, Maw Walker. Your return blesses us with great optimism, and much needed assistance.\n\nSeveral scholars remain unaccounted for. We believe they were last seen studying in the great court. We fear they may be lost, or worse, taken by those who seek to disrupt our way of life.\n\nReturn to me when you have answers.\n\nMay the path guide you.", objectives = "Locate Scholar Roh-Suir in Korthia.", completion = "How... how did you find me?" }
WordHunterWoW_QuestEN[64571] = { title = "Tazavesh: Seek and Do Not Destroy", description = "", objectives = "" }
WordHunterWoW_QuestEN[64579] = { title = "Hollow Efforts", description = "The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process. \n\nThese empty metal husks still contain residual materials of creation that may be useful to us.\n\nUse my Forge-Tap near these metal spheres to harvest any Remnant Neomotes. You may also find other useful proto-materials!", objectives = "Collect 40 Remnant Neomotes from Progenitor Forges using Firim's Forge-Tap.", progress = "Have you gathered the materials already?", completion = "Excellent work, <name>. These resources will bolster our efforts here." }
WordHunterWoW_QuestEN[64581] = { title = "A Gently Shaken Gift", description = "", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special <race> <class>." }
WordHunterWoW_QuestEN[64582] = { title = "Yuni-Test", description = "", objectives = "" }
WordHunterWoW_QuestEN[64592] = { title = "Historic Protection", description = "The outsiders have disrupted the sands. We cannot reach the terraforming records we need in order to collect necessary historical information.\n\nWill you assist us?\n\nHelp Mai Obet collect historical records in the Endless Sands.", objectives = "Help Mai Obet examine 6 Terraforming Records in the Endless Sands.", completion = "We have archived the necessary records. Thank you for your assistance." }
WordHunterWoW_QuestEN[64597] = { title = "Sanctum of Domination - Damned If You Don't", description = "I feel Kel'Thuzad's presence in these halls. Claim shards from his phylactery and I'll be able to open a new pathway into his chambers.\n\nFour shards should be enough. We wouldn't want him coming back again would we?", objectives = "Collect 4 Phylactery Shards from Kel'Thuzad within the Sanctum of Domination on Normal Difficulty.", progress = "Four shards should allow us to access his chamber.", completion = "This should help us gain access to his chamber more readily." }
WordHunterWoW_QuestEN[64598] = { title = "Sanctum of Domination - Damned If You Don't", description = "I feel Kel'Thuzad's presence in these halls. Claim shards from his phylactery and I'll be able to open a new pathway into his chambers.\n\nFour shards should be enough. We wouldn't want him coming back again would we?", objectives = "Collect 4 Phylactery Shards from Kel'Thuzad within the Sanctum of Domination on Heroic Difficulty.", progress = "Four shards should allow us to access his chamber.", completion = "This should help us gain access to his chamber more readily." }
WordHunterWoW_QuestEN[64599] = { title = "Sanctum of Domination - Damned If You Don't", description = "I feel Kel'Thuzad's presence in these halls. Claim shards from his phylactery and I'll be able to open a new pathway into his chambers.\n\nFour shards should be enough. We wouldn't want him coming back again would we?", objectives = "Collect 4 Phylactery Shards from Kel'Thuzad within the Sanctum of Domination on Mythic Difficulty.", progress = "Four shards should allow us to access his chamber.", completion = "This should help us gain access to his chamber more readily." }
WordHunterWoW_QuestEN[64607] = { title = "Tazavesh: A Hard Bargain", description = "Ah, my work looks marvelous on you. You are the very image of legitimacy!\n\nAnd now that I've provided you with my talents, you shall provide me with yours. Seek out my business associate, Fe'tajid, at the Gilded Landing and offer him your assistance.\n\nI look forward to hearing of your success.", objectives = "Seek out Au'manal's business associate and offer your assistance.", progress = "Have you spoken with my associate?", completion = "It seems our efforts to deceive the Zo were unsuccessful. But their efforts to kill you failed as well, so no harm done, yes?\n\nPerhaps a more generous reward is in order. Please accept this, along with my sincerest gratitude." }
WordHunterWoW_QuestEN[64639] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[64640] = { title = "AubriesTestQuestForJeff", description = "", objectives = "" }
WordHunterWoW_QuestEN[64641] = { title = "Mysterious Greenery", description = "There's a bright power emanating from the place above. I'm drawn towards it, like a moth to a light!\n\nI want to check it out, whatever it is. Won't you join me, please? It'll be so fun!", objectives = "Visit the Untamed Verdure with Glimmercane.", completion = "We are Circle Koh of the jiro.\n\nWe are here to fix this land." }
WordHunterWoW_QuestEN[64642] = { title = "Clearing the Ruins", description = "This place was abandoned for too long. The vegetation has overtaken the land.\n\nWe must enter the Blooming Foundry to fix it.\n\nUntil then: clear the area. Remove the deviants who have grown twisted over time.", objectives = "Kill 15 creatures within the Untamed Verdure.", completion = "This is a good start." }
WordHunterWoW_QuestEN[64643] = { title = "Scavenging a Solution", description = "The Blooming Foundry created this area. It maintains the automa, the creatures, and the plants.\n\nThe overgrowth is its fault.\n\nWe need to enter the Foundry to fix this land. This constructor can break through when it is working.\n\nMany automa in this area stopped moving long ago. Find usable pieces inside them.", objectives = "Find 8 Automa Internals from Abandoned Automa in the Untamed Verdure.", progress = "With your help, we will restore this place to its glory.", completion = "This will work." }
WordHunterWoW_QuestEN[64644] = { title = "A Splash of the Eternal", description = "I don't really know much about this place or its inhabitants, but what I do know is magic! I can sense ancient power from the waters near us.\n\nMaybe that can help?\n\nLet's check out that pond!", objectives = "Help Glimmercane extract water from the pool in the Untamed Verdure.", progress = "<The automa lies inert.>", completion = "<A small opening in the creature looks like the perfect size for a little pour of mystical water.>" }
WordHunterWoW_QuestEN[64645] = { title = "Moment of Truth", description = "Our constructor is ready.\n\nWe shall start the process to open the Blooming Foundry and reset this land.\n\nWe can start over.", objectives = "Follow the Koh jiro in the Untamed Verdure.", completion = "On to the Foundry." }
WordHunterWoW_QuestEN[64646] = { title = "Ramping Up", description = "We must restore the Foundry's power to use it. Conductors will channel power so we can use it.\n\nWe know how to use the conductors. Clear the way, and we shall start over.", objectives = "Activate 4 conductors within the Blooming Foundry.", completion = "These automa should not act like this.\n\nThey are beautiful. Strange. New.\n\nWe must deliberate before continuing." }
WordHunterWoW_QuestEN[64647] = { title = "Strange Gears", description = "<Oddly, the seed within the automa's innards is still very much alive.\n\nAre they all like this?>", objectives = "Collect 3 Winding Seeds from the automa in the Blooming Foundry.", progress = "These are very unusual.", completion = "<Koh Shira examines the piece of the automa--entwined with living vines.>\n\nThis cannot be.\n\nAutoma do not have vines within them. But these automa do.\n\nThis... is beautiful." }
WordHunterWoW_QuestEN[64648] = { title = "Reap What We Have Sown", description = "We told the constructor that we will use the Foundry to reset this land.\n\nWe must stop it and protect the new automa.", objectives = "Defeat the Charged Constructor.", completion = "Learning about new creatures that are infused with living growth--well, that sounds right up my alley! \n\nI think I'll stay with them and see how I can help... and maybe pick up their language as well. \n\nThanks for coming on this adventure with me, friend!" }
WordHunterWoW_QuestEN[64650] = { title = "Hyena Soul", description = "<The Hyena Soul is fiery and spry. The shape of the hyena will be yours to call upon.>", objectives = "Bring the Hyena Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the hyena. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[64651] = { title = "Cobra Soul", description = "<The Cobra Soul is covetous and protective. The shape of the cobra will be yours to call upon.>", objectives = "Bring the Cobra Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the cobra. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[64654] = { title = "Champion: Ben Howell", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[64706] = { title = "A Matter Of Motivation", description = "Giants litter these sands, mortal. But I believe we can revitalize them. \n\nThe smaller automa that are hiding in the desert can be utilized here. Use my Motivator to rally them to our cause. If we can gather enough, their energy can replenish these defeated behemoths to bolster our forces.\n\nReturn as many as you can to me, and we will put them to work!", objectives = "Return 6 Motivated Automa to Firim.", progress = "Have they been suitably motivated?", completion = "Well done, mortal! Soon we shall see the results of your efforts." }
WordHunterWoW_QuestEN[64709] = { title = "A Fel Path Through Time", description = "A corrupting star shines upon the land, threatening all with burning oblivion. The star betrays those who seek the light, its red glow obscuring rather than revealing.\n\nWhile its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[64710] = { title = "Whispering Felflame Crystal", description = "The crystal pulses with an eerie, felfire green glow. Holding it, you hear faint echoes of guttural demonic voices. Although the words are jumbled, one is both decipherable and repeated often: Dalaran. \n\nPerhaps someone in the city floating over the Broken Isles can tell you more about this crystal and its purpose.", objectives = "Bring the Whispering Felflame Crystal to Aridormi in Dalaran, floating above the Broken Isles.", completion = "I will just put this back when it belongs. Thank you for bringing it to me, <name>." }
WordHunterWoW_QuestEN[64713] = { title = "Picking Up the Pieces... Literally", description = "Orbs help us develop terrain for the Forge. Magic within the orbs draws the devourers. They tear apart the metal to reach it. We must collect the remains.\n\nLook for the fragments around the orbs. Bring them to us.", objectives = "Collect 30 Orb Fragments.", progress = "Did you find the fragments? We need many pieces.", completion = "Enough to fix a small orb. This will do." }
WordHunterWoW_QuestEN[64717] = { title = "Materials of Creation", description = "The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process.\n\nThe spheres near the Forge of Afterlives contain trace amounts of materials unique to that location.\n\nI have modified my Forge-Tap to harvest those materials.  Use it near the forges I have identified. The rare Eidolic Fragments have the greatest chance to be found on the largest of Progenitor Forges.", objectives = "Collect 10 Eidolic Fragments and 300 Minor Enigmet.", progress = "Have you collected what we need?", completion = "I shall make use of these immediately. These will help Saezurah and the automa resist the effects of the domination magic." }
WordHunterWoW_QuestEN[64718] = { title = "Keys To Victory", description = "The song... incomplete. Harmony is needed. Seek those who scry. Send them to serve the cycle.\n\nMawsworn hold the keys that bind. Take the keys, set them free.", objectives = "Free 6 Automa Scryers from their cells.", completion = "The chorus gathers. Soon, our voices will merge." }
WordHunterWoW_QuestEN[64720] = { title = "Cleaving A Path", description = "Maw Walker! My scouts report that the Mawsworn have dominated two automa Oracles to aid them in battle. These Oracles will most certainly predict our strategy and our ultimate goal, if given the chance.  \n\nWe need to eliminate both Oracles before we enter the Crypts. With them out of the way, the Mawsworn troops won't know what we're doing until we're finished with it.\n\nTake Emeni with you. She's eager for battle.", objectives = "Slay Oracle Zoketh and Oracle Voraxxi.", completion = "Perfectly executed, <name>. The loss of those Oracles should keep the Mawsworn in the dark." }
WordHunterWoW_QuestEN[64722] = { title = "Knocking On Death's Door", description = "This is it, mortal. The forces you have assembled should be enough to break through the Mawsworn and reach the Crypts. Getting inside, however, will require more effort. The Mawsworn have barricaded the entrance.\n\nKbato will carry you into battle. Eliminate the Mawsworn, and destroy the devices that power the barrier.", objectives = "Riding Kbato, defeat the Mawsworn forces in the Endless Sands and open the way to the Crypts of the Eternal.", completion = "By the First Ones... I never dreamed I would see this place with my own eyes." }
WordHunterWoW_QuestEN[64723] = { title = "Restoration Project", description = "Without an Arbiter, the very purpose of the Shadowlands has been compromised. Souls flood the Maw with no direction.\n\nAs Saezurah noted, Zereth Mortis would ordinarily craft a new being to take the Arbiter's place. I suspect the Jailer's forces have disrupted the land to the point where this is no longer possible.\n\nIt is time to take action ourselves, and bring stability again to the Shadowlands! Speak to Saezurah, and see where we must begin.", objectives = "Speak with Saezurah.", progress = "Have you spoken with them?", completion = "The covenants are certain to send aid if we ask." }
WordHunterWoW_QuestEN[64725] = { title = "Unforgivable Intrusion", description = "Darkness spreads dissonance throughout these halls. Mawsworn drain life from the air, and give only suffering in return. This must not be.\n\nIf the song is to be restored, silence is needed. The Mawsworn must be destroyed.", objectives = "Eliminate 6 Dominated Automa and 3 Darkseer Corrupters.", progress = "When the halls are silent, we may proceed.", completion = "The golden hour of silence. A space for creation to begin." }
WordHunterWoW_QuestEN[64726] = { title = "The Order Of Things", description = "Essences of ancient souls, tampered with--they bleed from each room. The halls must be restored, the flow of souls redirected.\n\nThe spheres hold the key. Seal the breaches, restore the flow, then the vessel may be filled.", objectives = "Use $13oa Containment Spheres to seal the breaches.", progress = "Seal the breach, restore the flow.", completion = "A breath held--anticipation. Soon, the soul will merge, and the song of creation will begin." }
WordHunterWoW_QuestEN[64727] = { title = "The Infinite Circle", description = "Creation calls--can you hear it? Yet darkness lingers below, taints the ancient melody.\n\nTo forge anew, peace must be restored. The Walker must walk, and protect.\n\nThere is much to be done. Lead the way.", objectives = "Escort Saezurah to the center of the Crypts of the Eternal.", completion = "Our voices are muffled in the lingering dark." }
WordHunterWoW_QuestEN[64728] = { title = "Acquaintances Forgotten", description = "It is time. The song shall bring life anew. Tell me when you are ready to begin.", objectives = "Complete the Ritual.", progress = "The ritual must be completed.", completion = "Dissonance lingers. A pure tone is needed. Reset the cycle anew." }
WordHunterWoW_QuestEN[64729] = { title = "Lifetimes To Consider", description = "This song has been completed, and harmony has been restored. Yet Zereth Mortis remains haunted by discord.\n\nDissonance lingers still, outside these walls. We must leave before it finds us.\n\nSpeak with the one you call Firim--he will open the way.", objectives = "Return to Exile's Hollow.", completion = "I can hardly believe all we've accomplished... truly, this is a day worth remembering. We could not have achieved this without you, my friend." }
WordHunterWoW_QuestEN[64730] = { title = "The Turning Point", description = "A pause, devoid of breath. A melody lingers on. The cycle awaits a voice.\n\n<You are unsure of what Saezurah means. Perhaps you should try to set up the ritual again, starting with the Vessel and the scryers.>", objectives = "Examine the Vessel and the Automa Scryers.", progress = "Have you tried everything?", completion = "I do not wish to say it but... it seems we have failed, my friend." }
WordHunterWoW_QuestEN[64731] = { title = "For Every Soul", description = "Without the Arbiter to stem the flow of souls to the Maw, the Shadowlands will never be fully repaired.\n\nThis cannot be the end. Surely you can think of something?", objectives = "Find a way to create a new Arbiter.", progress = "This moment is of great importance.", completion = "A new voice added to the chorus -- the cycle continues ever onward." }
WordHunterWoW_QuestEN[64733] = { title = "Help From Beyond", description = "If we stand any chance of breaking through the Mawsworn forces, we will need the help of all of the covenants.\n\nI will speak with the Kyrian. You and Pelagos can speak with the others. But before you go, ask Firim if there is any way we can gain the support of the Enlightened as well.", objectives = "Speak with representatives from the Enlightened, Venthyr, Necrolord, and Night Fae.", completion = "Between the strength of the covenant forces and the help of the automa, we should be able to reach the Crypts!" }
WordHunterWoW_QuestEN[64739] = { title = "Zovaal's Grasp", description = "I remember this metal. I saw it when I was touched by Maw magic. When I was severed...\n\nI will show you where this happened. Follow me. I will tell you my story.", objectives = "Follow Hanoa the Exile and listen to her story.", completion = "It is worse than I thought. Much worse." }
WordHunterWoW_QuestEN[64741] = { title = "Security Check", description = "I do not understand--these are my brethren! How can they be so careless, so unconcerned with both greedy cartels and the Mawsworn at their doorstep?\n\nTheir protective technology is antiquated. It will not keep danger out. If I cannot persuade them to leave, I can at least ensure they are safe where they insist on staying.\n\nI do not want to lose my friends again.\n\nThere should be four hidden conduits around the edge of the shield. Take this kit. It will allow you to inspect and repair them, if needed.", objectives = "Investigate the Shield Conduits around Haven.", progress = "Should those conduits fall, we will need to construct additional ones. Nobody wants that.", completion = "I knew it! Haven's defenses were deliberately tampered with -- by Cartel Xy!" }
WordHunterWoW_QuestEN[64742] = { title = "Traces of Tampering", description = "So the shield has been sabotaged. Of course the ruthless Cartel Xy are the first to attempt to profit off this land. \n\nTheir greed has put us all in even more danger. We must stop them. Let us search together for signs of their passage.", objectives = "Find clues of Cartel Xy's presence.", completion = "Cartel Xy is nearby." }
WordHunterWoW_QuestEN[64743] = { title = "Xy Are You Doing This?", description = "We cannot see them, but I am certain this is where Cartel Xy has established their base.\n\nSomething must have drawn Xy to this area of Zereth Mortis specifically, and we must discover what it is if we are to protect our friends here. \n\nTheir cloaks do not cover their supplies very well. See what information you can gather from their belongings.", objectives = "Gather 10 Suspicious Papers.", progress = "We must discover Cartel Xy's intentions here.", completion = "Oh, they thought they could hide their plans with a code? Hold on, my friend, this should take just a moment..." }
WordHunterWoW_QuestEN[64744] = { title = "Broker Decloaker", description = "Do you sense a shift in the air? They may be hidden, but Cartel Xy is near.\n\nFortunately, the devices they use to cloak themselves are familiar to me. Here; take this. Place it on the ground and it will reveal nearby agents... for a time. \n\nStop them, even if you must take their lives.", objectives = "Kill 12 Cartel Xy agents just outside of Haven.", completion = "Their deaths are a shame, but we must protect Haven." }
WordHunterWoW_QuestEN[64745] = { title = "Selfless Preservation", description = "The automa were once abundant here, singing, constructing various things, carrying out the purpose of the First Ones. Then, invaders from the Maw slaughtered them all.\n\nThe last automa to fall were protecting something important in a nearby structure. \n\nI witnessed one of the cursed Mawsworn steal a device by the door. The Elders say we should not meddle with artifacts, but would it be a transgression to recover what was stolen?", objectives = "Recover the Stolen Artifact in the Arrangement Index and restore it to its rightful place.", completion = "This automa still lives! But it is so weak." }
WordHunterWoW_QuestEN[64758] = { title = "Following the Leader", description = "We sealed the door to the Slumbering Vault when we first arrived. It is a sanctum, a cradle of all that is precious here. The power that sleeps within should not be touched by us. \n\nIf the Xy leader made it past the shields while we were distracted by the beauty of this place, I shudder to think of what they have already disturbed.\n\nHurry! We must go to the Slumbering Vault and ensure its safety.", objectives = "Investigate the Slumbering Vault.", progress = "Cartel Xy must be stopped!", completion = "No! What has that fool done to the console?!" }
WordHunterWoW_QuestEN[64759] = { title = "Junk's Not Dead", description = "This automa has been hiding here! I suspect it will not be receptive to our help.\n\nI am hesitant to suggest this, but if the servitor were to associate you with this facility, it might be more amenable. \n\nIf you have the means, copy the glyphs inscribed on similar automa outside. Those that the Maw have touched will be tainted, but I saw from my vantage point a few fallen automa in the sands with untarnished glyphs.", objectives = "Obtain glyphs from 6 Depleted Servitors around the Arrangement Index.", completion = "I hope this will encourage our friend here to view us as an ally. First Ones forgive us." }
WordHunterWoW_QuestEN[64760] = { title = "Technical Difficulties", description = "The console is going haywire! We have to fix it!\n\nMaybe these buttons do something?", objectives = "Press buttons on the console in the Slumbering Vault.", progress = "We have to fix the console somehow!", completion = "Thank you for your assistance, Maw Walker.\n\nI must return to Oribos. I will tell Cartel Al that our friends are not lost, but Enlightened." }
WordHunterWoW_QuestEN[64761] = { title = "Core Competency", description = "The poor thing.\n\nThe sacred should not be disturbed, but... will the elders judge us if we help it survive? This is preservation, not interference.\n\n...I hope. \n\nWe can power it back up. Use this depleted core as a conduit. Perhaps the larger wild animates in the nearby sands have enough energy to charge it.", objectives = "Charge a Depleted Automa Core by draining slain wild creatures in the Arrangement Index.", completion = "This lonely one will be strong again." }
WordHunterWoW_QuestEN[64762] = { title = "Revival of the Fittest", description = "This core is brimming with energy!\n\nUse the charged core to revive the automa. Hopefully, it will no longer see us as a threat.\n\nDo be careful. The power of the First Ones is not meant for us to control.", objectives = "Revive the Hidden Servitor in the Arrangement Index.", completion = "Support has arrived. The restoration may commence." }
WordHunterWoW_QuestEN[64763] = { title = "Maintenance Mode", description = "The architect set forth these tasks: \n\nStay safe. \n\nRestore the Protoform Repository when danger passes.\n\nThe mortal knows the cyphers. The mortal will help with the tasks.\n\nAttuning of the energy terminals is required. Each terminal requires a codex. Invaders pilfered the necessary codices. \n\nGo.", objectives = "Attune 4 Energy Terminals in the Arrangement Index.", completion = "The tasks are in motion." }
WordHunterWoW_QuestEN[64766] = { title = "Access Request", description = "The architect alone possesses the Restoration Matrix required for the restoration. The architect will restore the Protoform Repository.\n\nThe mortal will gain access to the Chamber of Shaping and inform the architect of recent progress. The architect will restore the repository.\n\nFulfillment of the task is imminent.", objectives = "Find the Proto Architect in the Chamber of Shaping and retrieve a Restoration Matrix.", progress = "The architect will assist us.", completion = "The Restoration Matrix is acquired. The architect is not present. The architect is therefore lost. \n\nRestoration of the repository is mandatory, even so." }
WordHunterWoW_QuestEN[64767] = { title = "The Final Song", description = "Servitors do not possess the strength to restore the repositories. Nevertheless, the task must be completed.\n\nThe mortal must stay close to protect the restoration process.\n\nCome.", objectives = "Stay near Kodah while keeping enemies away to capture the Protoform Repository.", completion = "I should have obeyed the elders! This is all my fault!" }
WordHunterWoW_QuestEN[64768] = { title = "Lightsprocket's Artifact Hunt", description = "", objectives = "" }
WordHunterWoW_QuestEN[64771] = { title = "Enlightened Exodus", description = "Hello, my friend!\n\nAn expedition of Cartel Al was sent in search of this place long ago, and was believed lost. I entered Zereth Mortis in hopes of saving my splintered cartel from the dangers of the Maw that have preceded me.\n\nAt last, I have found my old friend! And yet, she refuses to return to safety.\n\nPerhaps others can be convinced. Will you try?", objectives = "Talk to the Enlightened around Haven.", progress = "Have any others chosen to leave?", completion = "If they cannot be persuaded, they must be protected." }
WordHunterWoW_QuestEN[64772] = { title = "Broken Circle", description = "The jiro of Circle Olea work here. We make...\n\n<The jiro pauses for a moment.>\n\nThey... make new lands and creatures for the Forge.\n\nDevourers attacked, but some jiro still survive. You must find them. Tell them to gather outside the cave to the north. I will clear the way.\n\nDo not tell them I sent you. They will not want to see me.", objectives = "Find any surviving jiro and convince them to meet outside the cave.", completion = "Thank you for finding the survivors!" }
WordHunterWoW_QuestEN[64773] = { title = "A Jiro Guide to Not Being Eaten", description = "Devourers attacked. They overran the guardians. They still search for food.\n\nWe are not safe. Reduce the devourers' numbers.\n\nThis is how not to be eaten.", objectives = "Reduce the devourer presence at the Terrace of Formation.", progress = "Is it safe? There are so many devourers...", completion = "Fewer devourers, less likely we will be eaten." }
WordHunterWoW_QuestEN[64775] = { title = "Mawdified Behavior", description = "There is a devourer in the cave. It creates a rift. This should not be possible in Zereth Mortis.\n\nEnter the cave and destroy the devourer. Search for clues. See how it can open a rift.\n\nBe careful. This one is different from others. It has absorbed the magic of the First Ones. This has never happened before. Be ready for anything.\n\nI will stay here and protect the jiro.", objectives = "Kill the Unraveller and search it for clues.", progress = "Is the devourer destroyed? Did you find any clues?", completion = "A new type of devourer. Troubling. Hopefully these are the only ones.\n\nAs for this mysterious metal... I have seen it before." }
WordHunterWoW_QuestEN[64778] = { title = "Rift Recon", description = "Devourers are a problem. Rifts are a bigger problem. \n\nThey will keep bringing devourers. We must close them. To do this, we need information. \n\nTake the crescendal. Use it to analyze the rifts. Bring the information back to us.", objectives = "Analyze 6 Warped Rifts.", progress = "Do not break the crescendal. It can be... difficult to use.", completion = "This information will help us. Tell us how to close the rifts. Fewer rifts means fewer devourers." }
WordHunterWoW_QuestEN[64779] = { title = "Pound of Flesh", description = "Automa remove threats to us. But there are no more automa. We must help ourselves. We need magic.\n\nDevourers ate the orb magic. Now they are warped and twisted. But also full of magic.\n\nBring us devourer flesh. We will extract the magic. We will need it to defeat the devourers.", objectives = "Collect 30 Warped Flesh from devourers at Zovaal's Grasp.", progress = "Devourers were not meant to eat this magic.", completion = "This is the flesh <name> gathered? \n\n\n\nIt will have to do." }
WordHunterWoW_QuestEN[64780] = { title = "Mawsteel, Maw Problems", description = "Zereth Mortis is sacred. Rifts should not form here. Something creates them. \n\nThe metal you found has Maw magic. Devourers use it to make rifts. This is how they skirt our protections.\n\nMawsteel shards are strewn across the area. Take these shards. Throw them off our cliffs. Make sure devourers do not use them to create rifts.", objectives = "Lift 4 Mawsteel Shards and throw them off the cliffs.", completion = "Removing mawsteel prevents rifts. It is not much but it will help." }
WordHunterWoW_QuestEN[64783] = { title = "Dance Dance Darkmoon", description = "Simon says, \"Are you ready to dance?\" Step on in and show off your sweet moves, {class}.\n\nThe rules are simple. Your opponent will perform a series of stylish moves, then you gotta match 'em.\n\nEarn enough accolades and then come back to ol' Simon. Just know that the more challenging the opponent, the more accolades you can earn.\n\nSimon says, \"Are you up for the challenge?\"", objectives = "Earn accolades by competing in the dance competition.", progress = "Simon says, \"Show me what you got.\"", completion = "Simon says, \"Those were some sweet moves, <name>.\" \n\nSimon is impressed!" }
WordHunterWoW_QuestEN[64784] = { title = "9.0 Rated PvP Incentive - Shadowlands Season 2 Exclusive Mount", description = "", objectives = "" }
WordHunterWoW_QuestEN[64785] = { title = "Overgrown Story", description = "Since our arrival here the Untamed Verdure has been a mystery waiting to be solved. The lush foliage of the area grows on everything as the creatures run amok without purpose.\n\nThere could be valuable research data to be obtained from these creatures.\n\nUse a Containment Trap to subdue the elemental creatures. Once subdued, examine them for research data.", objectives = "Gaiagantic and 12 Geomentals examined for research data.", completion = "This information will help, but I'm afraid those ruins still remain a mystery!" }
WordHunterWoW_QuestEN[64794] = { title = "Knowing is Half the Battle", description = "{name}, you should join Shandris and infiltrate the Mawsworn forces from the east. Whatever information you two uncover will inform us of your next course of action.\n\nTake care. We have no information on what you may find.", objectives = "Meet Shandris near the Provis Strata.", completion = "You've arrived.\n\nTheir movements here are strange. It almost seems as if the bulk of their forces are elsewhere." }
WordHunterWoW_QuestEN[64796] = { title = "Scour the Sands", description = "The little I have seen so far has given me almost no information about our enemies. We will have to take a closer look.\n\nI can hide the both of us from sight on your command. But stay away from the dreadlords--their eyes are sharp enough to spy even a hidden huntress.", objectives = "Scout Provis Strata with Shandris Feathermoon.", progress = "The less attention we draw, the better.", completion = "We have discovered their immediate goal. We should return to our allies, quickly." }
WordHunterWoW_QuestEN[64797] = { title = "Harmony and Discord", description = "These obelisks must be key to Zovaal's plans. Even without full knowledge of their purpose, we should stop the Mawsworn from meddling with them.\n\nI will bring this information to Highlord Bolvar. Head to Darion Mograine and do the same. He will need to plan his defenses around this.", objectives = "Speak with Darion Mograine at Provis Terra.", completion = "The enemy has not yet been able to break through our defending line, but I fear we will lose the battle without your assistance." }
WordHunterWoW_QuestEN[64798] = { title = "What We Overcome", description = "I understand now. All of us that were touched by Domination were able to tap into something. Whether nobility or vengeance, it gave the strength to resist.\n\nWith all that I have faced, I have to remember that I am still here.\n\nAnd if there are those willing to stand with Sylvanas, I have to believe they will stand with me as well.\n\nI'm ready to try again. This time, I will overcome whatever I face.", objectives = "Defeat the Mawbound Monstrosity and infuse the final shard.", progress = "We will not fail. There is no other choice but oblivion.", completion = "All the shards are now infused with the resistance we gained from our experiences with Domination.\n\nIt was not easy, for any of us. But I am proud of what we were able to accomplish, together.\n\nAs for the rest, our future is in the hands of the Primus." }
WordHunterWoW_QuestEN[64799] = { title = "The Broken Crown", description = "Our friends have returned from the Sepulcher of the First Ones with a familiar face.\n\nAnduin... What terrible things he has endured. \n\nBut as difficult and painful as it is, we must uncover what he knows. The Jailer has blocked our way within the Sepulcher, and we risk falling victim to Domination ourselves if we blindly follow.\n\nHe is our best hope.", objectives = "Speak to Anduin Wrynn in the Geometric Cavern.", progress = "We must defeat Zovaal, or all is lost.", completion = "The suffering he endured... \n\nThis will be difficult to overcome." }
WordHunterWoW_QuestEN[64800] = { title = "Our Last Option", description = "Zovaal has blocked our pursuit. If we are to defeat him, we must find a way to withstand Domination.\n\nBut to overcome it, we need to understand how it works. \n\nThe Primus of Maldraxxus created Domination, he will be able to tell us more.\n\nI asked Taelia to bring a piece of the Helm of Domination to Zereth Mortis. I dread to think of what might happen were I to try to carry it again... \n\nLet us discuss the way forward.", objectives = "Listen to the plan.", progress = "We can never turn things back to the time that was. We can only live with the choices made, and move forward.", completion = "I don't like this as an option any more than Taelia does, but we need to wield Domination safely if we are to find a way to overcome it.\n\nOur first step is to ensure that the helm still works. On us." }
WordHunterWoW_QuestEN[64801] = { title = "Elder Eru", description = "Since we have earned the trust of the Enlightened, I have learned more about their explorations into Zereth Mortis.\n\nThey know more than they are willing to tell, but often do not act on that knowledge. Perhaps where they observe, we can be a catalyst for action.\n\nIn a secluded corner called the Lexical Glade, there is an elder named Eru. She may be able to give us insight on how we might use the language of the First Ones.\n\nSeek her out, and see if she will help us.", objectives = "Find Elder Eru outside the Lexical Glade.", completion = "What is this? You wish to know if there is anything here that can help you resist Mawsworn magic?\n\nYou are in luck, stranger. I happen to know that this place is a library. And libraries are wonderful places to find what you are looking for." }
WordHunterWoW_QuestEN[64802] = { title = "Hello, Darkness", description = "I created Domination as a tool to punish Zovaal.\n\nMy anger informed that creation, and now we pay the price for my hubris. Even Eternal Ones err on occasion.\n\nBut we are not without hope.\n\nTake the half of the broken Helm of Domination, and test it upon one of your own. If it retains enough power, it can then be used to test it elsewhere in Zereth Mortis.", objectives = "Test the broken Helm of Domination on Darion Mograine.", progress = "We will not give up until we have stopped Zovaal.", completion = "Even those who overcame Domination are not entirely immune to it now.\n\nBut there may be something buried in that history that can aid us. \n\nI will think on this.\n\nFor now, focus your efforts on the creatures of Zereth Mortis. See what makes them more resistant." }
WordHunterWoW_QuestEN[64803] = { title = "Testing One Two", description = "The creatures of Zereth Mortis have existed here since well before I created Domination.\n\nWe have seen the effects that Zovaal's forces have had on them, but I believe there is more to be learned.\n\nUse the helm on the denizens of Zereth Mortis and see what you can uncover about a natural resistance.", objectives = "Test the Broken Helm on creatures in Zereth Mortis.", progress = "You have an object that wields Domination, yet you are not overcome? Interesting.", completion = "The more advanced creatures resist Domination for longer? \n\nWell of course, I could have told you that. It's all about the language!" }
WordHunterWoW_QuestEN[64804] = { title = "Cryptic Catalogue", description = "This area is a repository of various texts. Hmmm? What do they say? I have no idea!\n\nI have dedicated myself to their catalogue and organization. This is more important than ever, with invaders destroying the balance in Zereth Mortis! We must preserve what we have found so far.\n\nYou can help. Go into the glade and memorize the phrases there, then meet me down in the grotto. There is something in it that might help you test that helm of yours further.", objectives = "Memorize Phrases in the Lexical Glade.", progress = "Think how much we could learn if we understood the intentions of the First Ones.", completion = "This place is wondrous.\n\nI could spend all of my existence here." }
WordHunterWoW_QuestEN[64805] = { title = "The Not-Scientific Method", description = "The language of the First Ones is not static like most others. It evolves.\n\nCreatures like the sentries are more advanced than your average poultrid, obviously. Their more complex thought processes give them an innate resistance to the invaders' overriding magic. \n\nBut you should not take my word for it. We can actually test this! \n\nIn the grotto there is a librarian. Take those phrases you memorized and infuse them into it. Then try out your helm.", objectives = "Test the Broken Helm on an activated Lexicon Librarian and observe the results.", completion = "You see! It took far longer for Domination to overtake the librarian's native purposing.\n\nOf course it did fail in the end, but I would call that a success for your particular interest.\n\nDo not worry, another automa will take that one's place. There must always be a librarian." }
WordHunterWoW_QuestEN[64806] = { title = "Where the Memory Resides", description = "I think I know what will be asked of us in Bastion. It will not be easy.\n\nWith this half of the Helm, we have collected the first part of what is needed to resist Domination. But there are those of us who have also suffered from it. Lived through it. \n\nIn a way, it has marked us. All of us.\n\nThere must be something in those experiences that will help us break free from Zovaal's influence.\n\nLet us go to the Chamber of First Reflection in Bastion.", objectives = "Meet Highlord Bolvar inside the Chamber of First Reflection in Bastion.", completion = "Good, you've arrived.\n\nWe have assembled those who have suffered from Domination in the past. Some more recently than others. \n\nAll have come through it, not always intact, but we are still standing. That is what we must capture." }
WordHunterWoW_QuestEN[64807] = { title = "What We Wish to Forget", description = "While the language of the Progenitors will aid us, there is another trait that will help break Domination's hold on us.\n\nAn indomitable will. \n\nThose of us who have endured before, and survived, have that inherent resistance, which we will offer up to be infused into each of the shards.\n\nThe Primus has assured me that this will work. With no other options, this is the only way. \n\nI trust that it will be worth the suffering.", objectives = "Assist with the ritual and infuse the Shards of Domination.", progress = "We will do whatever it takes.", completion = "I feel... lighter. But I cannot forget what has brought me to here, and what must still be done.\n\nI hope that Taelia will remember what she saw... the man I am now. Not some lone figure locked away, but someone who does what is necessary for the good of all." }
WordHunterWoW_QuestEN[64808] = { title = "What Makes Us Strong", description = "I wish that I knew of this place sooner. Where terrible darkness could be purged from oneself, memories examined and expunged...\n\nI am willing to do whatever it takes to help defeat Zovaal, no matter the cost.\n\nThis is the only way.", objectives = "Assist with the ritual and infuse the Shards of Domination.", progress = "It takes more than raw strength to do what must be done.", completion = "I think I understand.\n\n<Anduin steels himself.>\n\nI am ready to try again." }
WordHunterWoW_QuestEN[64809] = { title = "One Half of the Equation", description = "The Primus's theory about the language of the First Ones has borne out. \n\nStill, it may not be enough. \n\nWhile the Primus finalizes his plans, let us go deep into the Endless Sands to find pieces of this power to infuse the helm. \n\nDarion, Taelia, and I will meet you there to help with the Mawsworn.", objectives = "Travel to the Deserted Overlook.", completion = "The enemy is formidable, but with the strength of our arms and the power of the Broken Helm, we may be able to even the odds.\n\nThough I admit, I have an extra sense of caution with my daughter in the field." }
WordHunterWoW_QuestEN[64810] = { title = "Oppress and Destroy", description = "What we seek is in the vaults of the Endless Sands. To reach them will require strength and numbers.\n\nTogether we will destroy the Mawsworn. \n\nI look forward to taking the fight directly to them.\n\nRemember, they will be vulnerable to the broken shard from the Helm of Domination.", objectives = "Slay Mawsworn in the Endless Sands.", progress = "Such magnificent desolation.", completion = "Well done. \n\nLet us hope that this is last time we see the helm used as a weapon." }
WordHunterWoW_QuestEN[64811] = { title = "Aggressive Excavation", description = "Elder Eru said that we could find the most complex examples of the First Ones' language out here. \n\nWe'll need to fight our way to the vaults, and then infuse the helm once we find those phrases.\n\nOn a personal note, I never thought I'd have the chance to fight alongside my father. Though with the stakes this high, it somehow feels like exactly the place I'm supposed to be.\n\nI am ready when you are.", objectives = "Collect the Inscrutible Phrases.", completion = "We've done it. The broken half of the helm is infused with the most advanced pieces of the First Ones' power that we could readily find.\n\nWe are so close to success." }
WordHunterWoW_QuestEN[64812] = { title = "Forge of Domination", description = "We have all of the pieces we need. The broken half of the helm has been augmented with the complexity of the language of the First Ones, and the shards bear our memories. \n\nOur will to resist Domination.\n\nAll that remains is for the Primus to reforge the Helm, then we will be able to draw upon that combined power for ourselves.\n\nI know that it is dangerous, but it is our only hope.", objectives = "Travel to The Runecarver's Oubliette in Torghast.", completion = "How appropriate that the place I was imprisoned in will be the setting for how we free ourselves." }
WordHunterWoW_QuestEN[64813] = { title = "The Crown of Wills", description = "When I created Domination, I did not foresee how much pain it would cause the realms. Not only the Shadowlands, but yours as well.\n\nIt is time we take this helm, this symbol of that magic, and reforge it anew. But, not for the same purpose it once had.\n\nLet it represent the strength of will that you and your kind possess, so that it may help us overcome and defeat Zovaal at last.", objectives = "Reforge the Helm of Domination.", progress = "There is no going back.", completion = "This is a power unlike any I have felt before. We have made something new.\n\nIt will be our key to defeating Zovaal." }
WordHunterWoW_QuestEN[64814] = { title = "Battle for the Forge", description = "Our forces have been holding out so far, but we have not secured the area. We could use some assistance cutting down the enemy's numbers.\n\nThis should be a simple task for you, Maw Walker.", objectives = "Kill 8 Mawsworn forces.", progress = "Is it done?", completion = "We must remain vigilant. No one may pass our defenses." }
WordHunterWoW_QuestEN[64815] = { title = "Together, We Ride", description = "The four covenants are working together here along with the automa. \n\nUnfortunately, some of our soldiers have been separated or wounded and are unable to return back here.\n\nIf you could aid them, that would help tremendously.", objectives = "Aid 5 covenant forces.", completion = "The fewer losses we suffer here, the longer we can hold the line." }
WordHunterWoW_QuestEN[64816] = { title = "Reality's Doorstep", description = "The time has come to follow Zovaal into the very heart of the Shadowlands.\n\nWe must return to Zereth Mortis and finish this.", objectives = "Return to Zereth Mortis.", completion = "There is more work yet to do here in Zereth Mortis before Zovaal's influence will be expunged from the Shadowlands." }
WordHunterWoW_QuestEN[64817] = { title = "In Plain Sight", description = "That sound! It came from the direction of the obelisk at Provis Flora.\n\nImpossible. We've let no one through. Hurry, {name}. Follow me!", objectives = "Defend the obelisk at Provis Flora.", progress = "We must hurry!", completion = "They managed to hide themselves. This bodes poorly for us." }
WordHunterWoW_QuestEN[64818] = { title = "Reinforcements May Be Necessary", description = "The dreadlords infiltrated deep into our ranks. Bolvar must know what has happened.\n\nI cannot leave my position here. Quickly, give him the news. Perhaps the Enlightened council will have advice as well.", objectives = "Speak with Bolvar Fordragon at Haven.", completion = "Mograine will have the forces he needs." }
WordHunterWoW_QuestEN[64820] = { title = "This is Your Fault, Fix It", description = "Provis Fauna is normally regulated by autonomous constructs, but there have been reports that they are no longer working.\n\nAccording to the reports, you are the one responsible for the tampering of these nodes. Which means it is on you to fix them. Take this tuner, it should help--and once they are repaired, do not meddle with them again.", objectives = "Fix 5 defense nodes.", completion = "With the defenses working again, hopefully the Mawsworn presence diminishes." }
WordHunterWoW_QuestEN[64821] = { title = "Nothing is True", description = "If we are dealing with dreadlords, they could be disguised as anything... including the denizens of Zereth Mortis. Fortunately we have just the thing for dispelling their illusions. \n\nSearch the fields and test the automa. If you find any dreadlords, take care of them.", objectives = "Find and kill 4 Dreadlord Saboteurs.", completion = "That should slow down their plans. Good work, Maw Walker." }
WordHunterWoW_QuestEN[64822] = { title = "A Break in Communication", description = "Mograine's request for reinforcements is unusual. We were already planning on reinforcing the area, and sent three different outfits his way.\n\nFrom the sound of it, none of them have arrived. See if you can find their commanders and make sure they make it to Mograine.", objectives = "Reassign orders to three covenant commanders.", progress = "Have you found them?", completion = "They claimed you gave them their previous orders? Strange." }
WordHunterWoW_QuestEN[64823] = { title = "Doppelganger Duel", description = "Something about this doesn't sit right with me. From what you reported, this seems like intentional sabotage from within our ranks... or the work of more dreadlords. \n\nIf dreadlords are involved, then the obelisk may be at risk! Get to it--if we linger on this it may be too late!", objectives = "Find the Mawsworn presence at the Circle of Thought.", progress = "Time is of the essence here.", completion = "Mal'ganis...\n\nWe are losing this race." }
WordHunterWoW_QuestEN[64824] = { title = "Fighting for the Forge", description = "We made our way here as soon as we could. Anduin has been sighted near the structure in the middle of this land, referred to as the Forge of Afterlives.\n\nNo doubt the Jailer will join him soon. We need to leave immediately.", objectives = "Head to the Forge of Afterlives with Jaina.", completion = "Anduin...\n\nWe'll save you somehow." }
WordHunterWoW_QuestEN[64825] = { title = "Seeking Haven", description = "I am at a loss.\n\nWe have no way to follow Zovaal and Anduin. I'll open a portal back to Haven. We will discuss our next steps there.", objectives = "Return to Haven with Jaina and Baine.", completion = "We will look into how to follow them into the Sepulcher. Until then, you should focus your efforts on more immediate issues." }
WordHunterWoW_QuestEN[64829] = { title = "Finding Tahli", description = "After eons of tranquility, the Maw's influence has brought sorrow to Zereth Mortis. One of our acolytes, Tahli, has found it particularly difficult to process recent events. She left some time ago and has not returned. \n\nWill you check on her? She was last seen heading toward the ruins that are buried under the sands.", objectives = "Find Tahli near the Arrangement Index.", completion = "Even now, this place is beautiful." }
WordHunterWoW_QuestEN[64830] = { title = "Enlisting the Enlightened", description = "The fate of Sylvanas is not my immediate priority.\n\nThe Jailer has destroyed the Harmonic Channels, ensuring that we cannot follow him. \n\nPerhaps the studious Enlightened Brokers know something about these channels that will help us--but broker cooperation comes often with strings attached. \n\nDo whatever they demand. We must learn more.", objectives = "Persuade the Elders of Haven to offer their assistance.", completion = "Zereth Mortis has the answers you seek.\n\nIf you know where to look." }
WordHunterWoW_QuestEN[64831] = { title = "Remnants of the First Ones", description = "Some evidence of the Mawsworn's destruction may remain in Provis Esper. Recovering that evidence will provide some clue as to how to follow this Jailer.\n\nLet us hunt together. I will know the sign of the First Ones's magic when we are in its vicinity.", objectives = "Collect 3 Conduction Remnants.", progress = "Have we found all of the remnants?", completion = "Only inert remnants, unfortunately.\n\nBut do not lose hope, my friend!" }
WordHunterWoW_QuestEN[64832] = { title = "Reclaiming Provis Esper", description = "Provis Esper is overrun with devourers, buzzing around like hungry vespoids.\n\nThey are destroying the local automa, which is not at all what the First Ones intended. A cleansing is in order.\n\nFor our safety and to restore the natural order, clear some of them out.", objectives = "Kill 20 Insatiable Mites, 5 Soul-Parched Gorgers, and 2 Reality Breachers.", progress = "Have you cleansed Provis Esper?", completion = "More devourers will come, but you have lessened their impact for now." }
WordHunterWoW_QuestEN[64833] = { title = "Forging Unity from Diversity", description = "The other Elders follow a strict interpretation of how best to honor the works of the First Ones.\n\nI am not so inflexible. Our end goal is the same. \n\nLet us return to the area where you last saw the Jailer.", objectives = "Meet Elder Ara above Provis Esper.", completion = "The site below is crawling with devourers. But you can manage, yes?" }
WordHunterWoW_QuestEN[64834] = { title = "Glow and Behold", description = "Look, {name}. The remnants are faintly glowing!\n\nThey must be reacting to something in Pilgrim's Grace.\n\nFind out what is causing this reaction!", objectives = "Locate what is causing the Conduction Remnants to react.", progress = "The remnants reacted to this translocator? Incredible!", completion = "So the remnants have something to do with the translocator. But what?\n\nWhatever their prior function, they have no power now." }
WordHunterWoW_QuestEN[64835] = { title = "Pluck from the Vines", description = "I ran, scrambling through the thorny foliage, the lashers snapping at my heels.\n\nMy fellow pilgrims were not so lucky. I could hear their screams of pain and horror as I fled.\n\nYou must find a way inside. Rescue them, {name}!", objectives = "Rescue 5 missing pilgrims.", progress = "Have you rescued the missing pilgrims?", completion = "I cannot thank you enough for rescuing the pilgrims who could be saved." }
WordHunterWoW_QuestEN[64836] = { title = "Nip It in the Bud", description = "The Catalyst Wards used to be peaceful. Pilgrims have been coming here for ages to observe the wonders of the First Ones. But this place is no longer safe. The Cultivator showed no mercy and no reason as it slew several of our brethren.\n\nYou must destroy it.\n\nOther Elders would disagree with me. The other Elders are wrong.", objectives = "Kill the Cultivator.", progress = "What could have caused the Cultivator to behave so irrationally... so violently?", completion = "Putting the Cultivator down was the right call." }
WordHunterWoW_QuestEN[64837] = { title = "The Pilgrim's Journey", description = "Pilgrim's Grace is a sacred site for the Enlightened. The Elders there have an intimate understanding of the creations of the First Ones.\n\nWe will find answers there about these strange remnants we have found.\n\nMeet me at Pilgrim's Grace. It is not far.", objectives = "Meet Elder Ara at Pilgrim's Grace.", completion = "Welcome to Pilgrim's Grace." }
WordHunterWoW_QuestEN[64838] = { title = "Where There's a Pilgrim, There's a Way", description = "If the remnants can be restored, someone in Pilgrim's Grace may know how.\n\nBegin with Elder Nirav. I hope he is willing to help. He seems anxious and distracted today.\n\nFind me in town when you are done.", objectives = "Speak to the inhabitants of Pilgrim's Grace.", progress = "Have you spoken to the Enlightened in Pilgrim's Grace?", completion = "Feroz is our best bet? And he has gone missing along with several other pilgrims?\n\nWe should hurry." }
WordHunterWoW_QuestEN[64839] = { title = "Root of the Problem", description = "I suspect we can harness the growth energy present in these plants for our own purposes, but I will need fresh samples.\n\nYou can harvest energized plant matter from any of the lashers or vine-choked automa nearby, or those inside the Catalyst Wards.", objectives = "Collect energized plant matter.", progress = "Have you recovered the energized plant matter?", completion = "These roots are overflowing with growth energy." }
WordHunterWoW_QuestEN[64840] = { title = "Unchecked Growth", description = "This growth energy is highly unusual. I would like to know more about how it affects the local automa.\n\nHarvest replicating essence from deceased automa in the Catalyst Gardens.\n\nBring it back to me for study.", objectives = "Collect 12 Replicating Essence.", progress = "Do you have the replicating essence?", completion = "Hmm... it replicates rapidly until it kills the host. \n\nThis is more of a curse than a gift!" }
WordHunterWoW_QuestEN[64841] = { title = "Take Charge", description = "That floating structure looming overhead is the Creation Catalyst.\n\nI cannot get close to it. The tower is overloaded with an excess of Progenitor energy. To travel there now would be suicide.\n\nThere are consoles in the gardens that can be used to discharge that energy. Do so.", objectives = "Discharge the excess energy of the Creation Catalyst.", progress = "Is it safe to fly up to the Creation Catalyst?", completion = "Well done, Maw Walker!" }
WordHunterWoW_QuestEN[64842] = { title = "Flora Frenzy", description = "Those guardian automa will shoot down anything that attempts to reach the Creation Catalyst.\n\nMay I suggest fighting fire with fire? Or rather, fighting the creations of the First Ones with the creation energy of the First Ones?\n\nI have had little time to adequately test my theory, but this potion should provide the boost you need to destroy them... ideally without dying from exposure to the creation energy in the process.", objectives = "Drink Feroz's solution and destroy the automa of the Catalyst Gardens.", progress = "Your safety is probable, but not guaranteed.", completion = "It was quite poetic, I think, using their own growth energy against them." }
WordHunterWoW_QuestEN[64843] = { title = "Key Crafting", description = "With those agitated automa quelled, there is but one task ahead.\n\nWe shall ferry you and your Enlightened companion up to the Creation Catalyst.\n\nThe rest is up to you.", objectives = "Restore the Translocator Key at the Creation Catalyst.", progress = "It is incredible to see the Creation Catalyst up close.", completion = "We have done it!" }
WordHunterWoW_QuestEN[64844] = { title = "The Pilgrimage Ends", description = "You have rescued many pilgrims, and I have restored your entrance to the Sepulcher. With that, our bargain is concluded--and so, too, is my pilgrimage.\n\nBut your journey continues.\n\nReturn to the overlook behind Pilgrim's Grace and open the translocator.\n\nMy thanks, {name}. This adventure has been... enlightening.", objectives = "Return to the overlook behind Pilgrim's Grace.", progress = "Let us listen to what they have to say.", completion = "The next step is a large one. Are you ready, <name>?" }
WordHunterWoW_QuestEN[64846] = { title = "Torghast", description = "Countless souls are tortured in the halls of Torghast. They need your help!", objectives = "Speak with Tal-Inara.", completion = "Too many have been lost to Torghast. The way in is difficult... but not impossible." }
WordHunterWoW_QuestEN[64849] = { title = "Tower of the Damned", description = "We know little of Torghast. However, Fatescribe Roh-Tahl claims there is work that must be done there.\n\nHe believes there is a path for you to reach this place... and that someone there requires your aid.\n\nDo what you must to reach Torghast and aid anyone who is within.", objectives = "Travel to Torghast by jumping into the Ring of Transference, then find any entity there that needs your aid.", completion = "Stay back! \n\nWait... you're not one of the Jailer's forces.\n\nBox! We have a visitor, play the nice music would you?" }
WordHunterWoW_QuestEN[64850] = { title = "Traversing Torghast", description = "I've heard of you, the Maw Walker! You must know of me, the legendary Ve'nish.\n\nI am here to find great treasures within Torghast with the aid of my box. I can see you admiring it.\n\nPerhaps we can work together. Why don't you go into Torghast ahead of me to scout ahead?\n\nI shall even reward you for anything you discover within.", objectives = "Aid Ve'nish's exploration of Torghast by completing a wing within Torghast. Use the wayfinder within Torghast to access different wings.", progress = "How goes exploring the darkness of Torghast?", completion = "Ah, the place is filled to the brink with all sorts of terrible creatures... and also plenty of powers!\n\nPerfect! Did you hear that, box? We'll find plenty in this place... perhaps even more than that coward Ve'nari out in the Maw.\n\nAhem, thank you, Maw Walker. You've done your part well. I shall have more questions later." }
WordHunterWoW_QuestEN[64852] = { title = "Aeon Matrix", description = "<Firim could make use of this item>", objectives = "Deliver the item to Firim.\n\nProvided item:", completion = "This is just what I needed! Take this in appreciation for your efforts!" }
WordHunterWoW_QuestEN[64853] = { title = "Two Paths to Tread", description = "Did that answer your question?\n\nOh, you wanted a way to completely resist Domination magic? That I'm afraid I do not know. The First Ones' language will only delay the inevitable.\n\nWhat I can tell you is that if you want to find more deliciously complex phrases of the First Ones' language, you should go to the Endless Sands and search the vaults.\n\nI wish I could go myself, but it has been overrun by those nasty Mawsworn.\n\nGood luck with the rest of your studies!", objectives = "Report to the Primus in the Geometric Cavern.", completion = "This Elder has given us an important answer to this puzzle. But now we must act on the information. Though, doing so will be difficult.\n\nFirst we must infuse the helm with those indecipherable phrases from the First Ones that are in the Endless Sands.\n\nBut that will not be enough on its own. We will need more. Let me prepare, while you acquire what we need. I will send word for you after." }
WordHunterWoW_QuestEN[64854] = { title = "Trappings of Success", description = "The wildlife of Zereth Mortis are attracted to the frenetic creation energy that flows throughout the land. When the wildlife finds something charged with that energy... they eat it!\n\nThe Mawsworn Cryptoseers have become aware of this and are attempting to find such wildlife to extract any remnants of that energy.\n\nEliminate the Cryptoseers, and use the Containment Trap to subdue and examine the wildlife for our research.", objectives = "Slay 5 Mawsworn Cryptoseers and examine the wildlife listed.", progress = "You have collected data before the Cryptoseers?", completion = "This information will help us continue to unravel the mysteries of Zereth Mortis." }
WordHunterWoW_QuestEN[64860] = { title = "Aetheric Lattice", description = "<Firim could make use of this item>", objectives = "Deliver the item to Firim.\n\nProvided item:", completion = "This is just what I needed! Take this in appreciation for your efforts!" }
WordHunterWoW_QuestEN[64861] = { title = "Kismetric Disc", description = "<Firim could make use of this item>", objectives = "Deliver the item to Firim.\n\nProvided item:", completion = "This is just what I needed! Take this in appreciation for your efforts!" }
WordHunterWoW_QuestEN[64863] = { title = "Arcane Guardians", description = "Those constructs patrolling the creche are not animated by the Earth-Warder's magic.\n\n<Dervishian narrows her eyes.>\n\nWe cannot allow there to be enemies in our midst.\n\nDestroy them to clear our path forward.", objectives = "Defeat 4 Guardians or Constructs.", progress = "Who would dare defy the Earth-Warder in this way?", completion = "Those constructs were animated with blue dragonflight magic. \n\nThe Earth-Warder would never have allowed this!" }
WordHunterWoW_QuestEN[64864] = { title = "Awaken, Dracthyr", description = "<Only flashes of memory remain as you shake off what feels like an endless sleep.\n\nThe dracthyr before you is unresponsive, frozen in place by some unknown magic. You sense that within you lies the power to break your ally free.\n\nThere may be others within the creche who are suspended in this stasis.\n\nIt is your duty to awaken them.>", objectives = "Awaken the other dracthyr.", completion = "<Azurathel listens to your report.>\n\nMy memories are as broken as yours, <name>. But we cannot dwell on that now.\n\nWe need to assess and make a plan." }
WordHunterWoW_QuestEN[64865] = { title = "Gear Up", description = "Hostiles have invaded, our people have been confined in magical stasis, and our creche seems to be collapsing.\n\nThis is why we train, {name}. When in doubt, fall back to what you know.\n\nFirst things first. Weapons, armor, supplies. Gather what you can find and get equipped while I marshal our forces.\n\nThen we will locate the Earth-Warder. Surely Neltharion can provide the answers we seek.", objectives = "Acquire weapons, armor, and supplies.", progress = "When memory fails, fall back on your training.", completion = "This gear is ancient, and the food has turned to dust.\n\nIt makes no sense... those rations should have lasted a lifetime.\n\nWell, we will make do with what we have." }
WordHunterWoW_QuestEN[64866] = { title = "Into the Cauldron", description = "Your skills are needed, evoker.\n\nThe creche is crumbling and we have few supplies. We must reach the passage out, but we have to get past this arcane barrier first.\n\nIn the chamber beyond, there are dracthyr in need of aid. Tend their wounds. Destroy any foe who stands in your way.\n\nThis may be the last time we walk these halls together, {name}. Make it count.", objectives = "Prepare to leave the creche.", completion = "You healed our people. Well done.\n\nNow to deal with that dragon." }
WordHunterWoW_QuestEN[64867] = { title = "Supplies from The Enlightened", description = "Ah, yes. How I've looked forward to this moment for quite some time!\n\nCome, visit me. Let us share this achievement together.\n\nI've prepared something special just for you.", objectives = "Speak with Vilo at Haven in Zereth Mortis.", completion = "Quite a hefty reward. Are you sure you can manage all on your own?" }
WordHunterWoW_QuestEN[64870] = { title = "Paragon of Enlightened Brokers", description = "My, my. You've been busy, haven't you?", objectives = "Speak with Vilo at Haven in Zereth Mortis.", completion = "Let's see if we can find a suitable reward for your efforts." }
WordHunterWoW_QuestEN[64871] = { title = "The Dragon at the Door", description = "That blue dragon will collapse the creche and trap us inside!\n\nHe claims to serve Malygos. That name is familiar, but... why would any dragon want to keep us prisoner?\n\nListen, {name}. We were trained to fight beside the dragons, not against them. But we have been left with no choice.\n\nTime to do what must be done, evoker.", objectives = "Defeat Lapisagos and escape the War Creche.", completion = "We will get that rubble cleared and make sure no <race> is left behind.\n\nBut first, we need to secure this area." }
WordHunterWoW_QuestEN[64872] = { title = "The Fire Within", description = "You are an evoker, {name}. The best of the best. An elite soldier who has mastered the skills of each of our weyrns.\n\nI expect a lot of you.\n\nYour memories may be broken, but the might of dragons courses through your veins. Harness it.\n\nOne of your most potent weapons is your breath attack. The fire within becomes more powerful the longer you inhale.\n\nThese insects swarming over our training grounds should make fine targets.", objectives = "Learn Fire Breath and practice empowered attacks.", progress = "A nice, deep breath clears the head.", completion = "Good. You remember your training.\n\nKeep your head low and your lungs full." }
WordHunterWoW_QuestEN[64873] = { title = "Stretch Your Wings", description = "I am heartened to see that so many escaped the War Creche. My own weyrn... was not as fortunate.\n\n<Emberthal stands in silence for a moment.>\n\nThere are other creches throughout the Reach, filled with dracthyr in peril. Strong wings will be needed to reach them.\n\nFocus. Remember your training. Get a feel for the wind again. You must regain your strength and fly to the other creches.\n\nThe time for rest is over.", objectives = "Practice casting Soar.", completion = "You are getting the hang of this a lot faster than I was!\n\nBut then, you finished your <class> training. I was hoping to specialize as a diplomat." }
WordHunterWoW_QuestEN[64875] = { title = "Something Wonderful", description = "{name}, I am so glad you are here! Firim sent me to find you.\n\nIt's the oracle, it... well... it's hard to describe. You should come see it for yourself. Hurry!", objectives = "Travel to Exile's Hollow to witness for yourself what is happening to Saezurah.", progress = "We must hurry, <name>. We do not know how long this will last.", completion = "We may be on the cusp of a wondrous revelation!" }
WordHunterWoW_QuestEN[64876] = { title = "Music of the Spheres", description = "It started gradually, the energy emanating from the oracle in increasing amounts, until the grand design you see before you took shape.\n\nThe terrible clamor ringing in our ears began shortly afterward.\n\nMy attempts to approach the fractals have been... unsuccessful. But they appear to resonate with Pocopoc.\n\nYou share a special bond with it; perhaps you shall have better luck than I.", objectives = "Examine the fractals that surround Saezurah's body.", completion = "A vision! The oracle communicates with us! You saw it too? Such magnificence! Such... a migraine left in its wake." }
WordHunterWoW_QuestEN[64877] = { title = "Navigation Playtest: Level Up (PART 2)", description = "Enjoy the end of Lowlands!", objectives = "Enjoy the end of Lowlands!" }
WordHunterWoW_QuestEN[64878] = { title = "What a Long Strange Trip", description = "<The voice from the vision speaks through Pocopoc, albeit distant and distorted.>\n\nI... am Saezurah. Oracle. This automa... speaks with my voice. Acts with my will. For now.\n\nThe pattern... is torn. Disrupted. Mending must be done.\n\nA great hunger swarms the sands. What it seeks must not be consumed.\n\nJourney with me. Follow my voice.", objectives = "Go with Pocopoc to make sense of your vision.", progress = "Pocopoc has not reached the destination yet.", completion = "Above the sands. Above us. The vessel awaits." }
WordHunterWoW_QuestEN[64879] = { title = "A Monumental Discovery", description = "Maw Walker--Pelagos stopped by earlier to give a report and said that the oracle's preparations were complete, and you were urgently needed. \n\nIf this is something that can help our efforts, I want you involved. Head to Exile's Hollow and see what they need.", objectives = "Meet Firim in Exile's Hollow.", completion = "Mortal, I have monumental news. Saezurah has indicated that preparations are complete. It is time to create a new Arbiter!" }
WordHunterWoW_QuestEN[64888] = { title = "Borrowed Power", description = "The land provides. The land thirsts. Invaders devour what we require.\n\nReclaim what has been consumed. Absorb what remains abundant.\n\nWings need wind to fly. We need power to ascend.", objectives = "Defeat volatile lured enemies or soak power from pools to reclaim Cosmic Energy to empower Pocopoc.", progress = "More power to Pocopoc.", completion = "Power thrums. A renewal of hope." }
WordHunterWoW_QuestEN[64889] = { title = "Match Made in Zereth Mortis", description = "The cyphers are the key. Each one, a step along the path. You must find them all.\n\nEnter the inner chamber. The Prime Locus Arrangement awaits.\n\nThe first step toward ascension. Toward the vessel.", objectives = "Study the Locus Arrangements and use the Locus Shift to reach the Ultimus Locus.", progress = "Need to gather the cyphers to reach the door where the vessel waits.", completion = "The last leg of the journey begins." }
WordHunterWoW_QuestEN[64935] = { title = "Between a Rock & a Rock", description = "<Piles of rock are scattered around the area. The devourers have done enough damage to obscure the cypher you seek.\n\nPerhaps one of the nearby servitors could be made to clear the rubble.>", objectives = "Smash the rubble barring access to the secundus locus arrangement.", progress = "Until we discover the cypher, we need to keep smashing rubble.", completion = "Our sojourn continues." }
WordHunterWoW_QuestEN[64936] = { title = "Searching High and Low", description = "Three locks upon the door, three keys hidden atop the zenith.\n\nFind the phrases. Speak the words. Secure the vessel.", objectives = "Gather the Ingress Phrases on the Ultimus Locus that are needed to claim the Vessel.", progress = "The vessel slumbers high above.", completion = "One journey ends. Another begins." }
WordHunterWoW_QuestEN[64937] = { title = "You Light Up My Life", description = "Great power entices great hunger. The insatiable devourers scale the cliffs in search of sustenance.\n\nSoon they will swarm the plateau. They seek to consume all they encounter. The vessel. Its power. Us.\n\nThis must not come to pass. Wield this automa. Silence their slavering howls.", objectives = "Use Pocopoc to defend the vessel against the devourers.", completion = "Sanctuary, for now. A greater task remains." }
WordHunterWoW_QuestEN[64941] = { title = "Chicken Soul", description = "<The Chicken Soul is perky and voracious. The shape of the chicken will be yours to call upon.>", objectives = "Bring the Chicken Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a chicken! You can cluck like one now, too!" }
WordHunterWoW_QuestEN[64942] = { title = "Call of the Primus", description = "Though we fought to stop the Jailer in the Sanctum of Domination, we failed. He enveloped Oribos in the Maw, struck down the Arbiter, and opened the way to Zereth Mortis. \n\nThe time has come to follow him. \n\nWithin the Arbiter's Chamber, we will forge our own path.\n\nHurry, Maw Walker. The fate of the Shadowlands, and all the realms beyond, is at stake.", objectives = "Speak with Tal-Inara in Oribos to travel to the Arbiter's Chamber.", completion = "There is but one final sigil needed to pursue Zovaal." }
WordHunterWoW_QuestEN[64944] = { title = "A Hasty Voyage", description = "The path to Zereth Mortis is open.\n\nWe must part ways here. The Eternal Ones are forbidden from returning to the place of our creation. Zovaal has defied the most sacred laws of the Progenitors.\n\nYou must undertake this journey alone.\n\nGo. Find a foothold in Zereth Mortis so that we can send the covenant forces through.\n\nThen we will pursue the Jailer and end his madness.", objectives = "Begin your journey to Zereth Mortis by mounting the anima wyrm.", completion = "This... certainly is not Oribos." }
WordHunterWoW_QuestEN[64945] = { title = "Strangers in a Strange Land", description = "Did we... did we reach Zereth Mortis? And are we walking on water?\n\nWhat a wondrous place! At least, from what I can tell through this fog.\n\nI think I can make out a structure in the distance. Perhaps we will find answers there.", objectives = "Accompany Pelagos and explore your surroundings.", completion = "I will not abide agents of the Jailer defiling this land!" }
WordHunterWoW_QuestEN[64947] = { title = "Give Me A Hand", description = "To drive the Jailer from Zereth Mortis, we must direct all our resources against the enemy.\n\nAn object of potential power lies in a nearby repository, but the chamber's defenses respond only to automa. I would never harm their kind, but I have encountered one that no longer functions.\n\nIf you extract its hand, we could use the inert appendage to gain access to the repository.\n\nI find such use of the First Ones' creations unsavory, but we cannot abide the presence of Mawsworn in this realm.", objectives = "Assist Firim.", completion = "Admittedly, I did not foresee this result." }
WordHunterWoW_QuestEN[64949] = { title = "For Research Purposes", description = "I have taken pains not to disturb the automa during my time in Zereth Mortis, and so far they have paid little attention to me.\n\nIt seems recent events have changed that.\n\nAgain, let me be clear that I have no wish to harm the creations of the First Ones. But if, in the course of your efforts, conflict with the automa becomes inevitable, we must ensure that some good can come of it.\n\nIf I can examine fragments of fallen automa, it may provide knowledge to use against the Mawsworn.\n\nGo carefully.", objectives = "Collect 12 Intact Automa Fragments from Alerted Automa within Genesis Vestibule", progress = "Did you find any useful fragments?", completion = "Though the loss of automa is unfortunate, these fragments could prove a boon to my research." }
WordHunterWoW_QuestEN[64950] = { title = "A Mutual Exchange", description = "It seems the other automa did not appreciate our appropriation of their colleague's hand. They have become hostile.\n\nUnfortunate, but we cannot allow this to impede our progress.\n\nThe automa's hand should activate a console within the Genesis Repository. I believe it holds an object of great potential.\n\nAfter you acquire it, I will guide you to a place that may provide a means to reach the allies you left behind.\n\nDo we have an accord?", objectives = "Use the Automa Hand to activate an Automa Console and obtain the Repository Treasure.", progress = "Did you acquire the object from the console?", completion = "<Firim snatches the core from your hands.>\n\nIntriguing. I have examined many automa cores, but this one glows with an energy unlike any I have seen before." }
WordHunterWoW_QuestEN[64951] = { title = "The Road to Haven", description = "I did not expect to encounter a living mortal and a kyrian this day, but your assistance has been valuable.\n\nBefore I begin my studies of this automa core, I will guide you to Haven, the settlement founded by my expedition upon our arrival.\n\nThough my colleagues saw fit to exile me for challenging their \"Enlightened\" dogma, I have no wish to see Haven wiped from existence by the Jailer.\n\nAid them and they may assist your efforts to return to your allies. We brokers are nothing if not transactional.", objectives = "Ride with Firim out of the Genesis Repository.", completion = "I can go no further.\n\nMy former colleagues and I have... philosophical differences." }
WordHunterWoW_QuestEN[64952] = { title = "Destroying the Destructors", description = "The Mawsworn possess terrible weapons that gather dark magic and hurl it against our gates.\n\nThe defensive barrier around Haven will not hold much longer. All that we are, all that we hold dear, will soon be erased from existence.\n\nIf you are who you claim to be, then prove it to us. Destroy the enemy's armaments and help defend our home.\n\nI pray to the First Ones that you succeed.", objectives = "Destroy 4 Maw Destructors.", completion = "You have bought us time, mortal. First Ones bless us all." }
WordHunterWoW_QuestEN[64953] = { title = "Defending Haven", description = "The Mawsworn are gathering in force outside our very gates. It is clear they mean to overrun our home!\n\nThe Enlightened wish only to honor the marvels of the First Ones in peace. Haven's defensive barrier was put in place to shield us from minor threats. We did not imagine the Jailer would send his forces against us.\n\nYou claim to be our ally, mortal? Then help us defend this sacred land.", objectives = "Defeat 13 Mawsworn in the Great Veldt.", progress = "Our pilgrims cannot continue like this.", completion = "You have proven your mettle, yet the enemy grows bolder." }
WordHunterWoW_QuestEN[64957] = { title = "This Old Waystone", description = "The Jailer has withdrawn his forces. I should be relieved, but I fear this means he has found a way into the Sepulcher.\n\n<Elder Ara trembles.>\n\nDespite Elder Kreth's doubts, you have proven to be an ally. Something we need more of.\n\nWhen our expedition arrived in Zereth Mortis, we discovered a dormant waystone. If you are indeed a Maw Walker, then the prophecies tell us that you will be able to activate it.\n\nIf your allies can save this sacred place, then the path to them must be opened.\n\nCome.", objectives = "Open the Waystone to Oribos.", completion = "Maw Walker! Thank the Light you and Pelagos are safe!" }
WordHunterWoW_QuestEN[64958] = { title = "The Forces Gather", description = "I am relieved that you survived the passage to Zereth Mortis. From what I've overheard of Pelagos's conversation with Kleia, it sounds like you had an incredible journey.\n\nThese Enlightened brokers could make valuable allies. Their knowledge of the automa and the land itself should help us against the Jailer.\n\nOur forces are gathered and ready to follow you to Zereth Mortis.\n\nThe final battle lies before us, {name}.", objectives = "Speak to Elder Kreth in Zereth Mortis.", completion = "You defended Haven, and now you bring allies to preserve this sacred land.\n\nBlessings of the First Ones be upon you, mortal." }
WordHunterWoW_QuestEN[64959] = { title = "Otter Soul", description = "<The Otter Soul is swift and boastful. The shape of the otter will be yours to call upon.>", objectives = "Bring the Otter Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, an otter! You can float like one now, too!" }
WordHunterWoW_QuestEN[64960] = { title = "Feed the Annelids", description = "", objectives = "" }
WordHunterWoW_QuestEN[64961] = { title = "Cat Soul", description = "<The Cat Soul is elegant and inquisitive. The shape of the cat will be yours to call upon.>", objectives = "Bring the Cat Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a cat! You can pounce like one now, too!" }
WordHunterWoW_QuestEN[64962] = { title = "As Foretold", description = "The spheres are in place. A melody builds. Go--bring forth the chorus of Scryers, that the cycle of rebirth may begin.", objectives = "Bring Firim and the Scryers to the center.", progress = "The song awaits its chorus.", completion = "The rustle of creation, whisper in the dark. We may begin." }
WordHunterWoW_QuestEN[64963] = { title = "A Defector's Request", description = "<Unrolling the scroll, you can make out that it's a coded arms requisition from the Maldraxxi of Death's End to their venthyr allies... all servants of the Jailer.\n\nSurely someone among the Death's Advance in Korthia will be able to help you fully break the code and learn exactly what they were planning.>", objectives = "Deliver the missive to Duchess Mynx in Keeper's Respite in Korthia.\n\nProvided item:", completion = "<A smile creeps across Duchess Mynx's face as she looks over the scroll you provided. A moment later, an echoing laugh bursts from her.>\n\nThe forces of the Jailer use such pathetic codes! This scroll of yours doesn't say where, but it seems there's a weapons cache ready to be claimed. A team of your allies should be able to investigate and retrieve it without too much trouble." }
WordHunterWoW_QuestEN[64964] = { title = "Choose Your Fighter", description = "The presence of the Jailer's forces at Provis Strata have been causing untold damage to the region. If left unchecked, we will lose all knowledge in the area.\n\nOne of our kin has prepared some automa to deal with the Mawsworn. Meet with them, and fight back against those who would disrespect Zereth Mortis in this manner.", objectives = "Pick an automa construct and use it against the Mawsworn.", progress = "Is the task complete?", completion = "Good work." }
WordHunterWoW_QuestEN[64969] = { title = "In the Weeds", description = "I understand now why Elder Nirav is filled with worry.\n\nMany of the pilgrims who have journeyed to the Catalyst Wards have not returned. This includes Feroz, who is most likely to have information we need to restore the remnants. \n\nPrepare yourself. The First Ones's newest creations are prevalent at the Catalyst. If something has gone wrong there, it could be tragically dangerous.", objectives = "Meet Elder Ara outside the Catalyst Wards.", completion = "Feroz explained what happened to the missing pilgrims.\n\nThey are trapped inside the Catalyst Wards!" }
WordHunterWoW_QuestEN[64970] = { title = "Timeworn Keystone: The Broken Isles", description = "I recently came into possession of a unique keystone. It may look old and worn, but I believe it still has a story to tell.\n\nTake it with you. Perhaps it will serve as a reminder of adventures long past. Adventures I hope you will tell me about, of course.", objectives = "Complete a Timeworn Keystone dungeon.", completion = "Your tales of adventure are most exciting, my friend! Please, allow me to offer a token of my gratitude." }
WordHunterWoW_QuestEN[64974] = { title = "Clean Up, Automa Aisle", description = "", objectives = "" }
WordHunterWoW_QuestEN[64977] = { title = "Step Into the Ring", description = "One of the remarkable things we have found about these lands is that they seem to be adaptive and changing, even as ancient as they are. Things are not stationary.\n\nIn the depths of the Nexus of Actualization there is a forge that appears made to test these various designs, and to learn. These creatures may one day be used to defend Zereth Mortis from threats, so you should test their effectiveness where possible.\n\nGo there, challenge what the forge creates and report back to me.", objectives = "Defeat Generated creations in the Nexus of Actualization.", completion = "What a remarkable device. Of course there is clearly some improvement to be made in what it creates. But perhaps it will learn from the lessons you have provided." }
WordHunterWoW_QuestEN[64984] = { title = "Bunny Soul", description = "<The Bunny Soul is clever and quick. The shape of the bunny will be yours to call upon.>", objectives = "Bring the Bunny Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a bunny! You can hop like one now, too!" }
WordHunterWoW_QuestEN[64985] = { title = "Rat Soul", description = "<The Rat Soul is curious and sociable. The shape of the rat will be yours to call upon.>", objectives = "Bring the Rat Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a rat! They're so clever!" }
WordHunterWoW_QuestEN[64988] = { title = "Snake Soul", description = "<The Snake Soul is patient and watchful. The shape of the snake will be yours to call upon.>", objectives = "Bring the Snake Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a snake! They always win staring contests!" }
WordHunterWoW_QuestEN[64989] = { title = "Porcupine Soul", description = "<The Porcupine Soul is cautious and shy. The shape of the porcupine will be yours to call upon.>", objectives = "Bring the Porcupine Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a porcupine! Some say they're prickly, but I think they're nice." }
WordHunterWoW_QuestEN[64990] = { title = "Cricket Soul", description = "<The Cricket Soul is a lucky one. The shape of the cricket will be yours to call upon.>", objectives = "Bring the Cricket Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a cricket! You can hop like one now, too!" }
WordHunterWoW_QuestEN[64992] = { title = "Prairie Dog Soul", description = "<The Prairie Dog Soul is ever alert. The shape of the prairie dog will be yours to call upon.>", objectives = "Bring the Prairie Dog Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a prairie dog! Nothing will get past you!" }
WordHunterWoW_QuestEN[64993] = { title = "Saurolisk Hatchling Soul", description = "<The Saurolisk Hatchling Soul is tenacious and fierce. The shape of the saurolisk hatchling will be yours to call upon.>", objectives = "Bring the Saurolisk Hatchling Soull to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a saurolisk hatchling! So cute, but so fierce!" }
WordHunterWoW_QuestEN[64994] = { title = "Frog Soul", description = "<The Frog Soul is a joyful one, filled with song. The shape of the frog will be yours to call upon.>", objectives = "Bring the Frog Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a frog! Their hearts are full of song!" }
WordHunterWoW_QuestEN[64995] = { title = "Saurid Soul", description = "<The Saurid Soul is a mischievous and playful one. The shape of the saurid will be yours to call upon.>", objectives = "Bring the Saurid Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a saurid! Lady Moonberry had a prank war with a big one of those, once. Hek hek hek!" }
