WordHunterWoW_QuestEN[65008] = { title = "Goat Soul", description = "<The Goat Soul is stoic and unwavering. The shape of the goat will be yours to call upon.>", objectives = "Bring the Goat Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the goat. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65009] = { title = "Ram Soul", description = "<The Ram Soul is brave and fierce. The shape of the ram will be yours to call upon.>", objectives = "Bring the Ram Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the ram. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65010] = { title = "Alpaca Soul", description = "<The Alpaca Soul is wary and alert. The shape of the alpaca will be yours to call upon.>", objectives = "Bring the Alpaca Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the alpaca. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65020] = { title = "Practical Applications", description = "Greetings, Maw Walker.\n\nI am pleased to announce that we have accumulated the relevant research necessary to set up a Field Anima Diverter.\n\nPlease find a suitable location for it in the Reliquary, preferably where it will not be impacted by interference from other anima-charged relics.", objectives = "Place the Field Anima Diverter in the Reliquary of Remembrance.", completion = "That is a fine spot for the Field Anima Diverter.\n\nPerhaps one of the greatest benefits of our research is a reduction of expended effort." }
WordHunterWoW_QuestEN[65021] = { title = "Eagle Soul", description = "<The Eagle Soul is brave and alert. The shape of the eagle will be yours to call upon.>", objectives = "Bring the Eagle Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the eagle. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65022] = { title = "Sporebat Soul", description = "<The Sporebat Soul is quick and alert. The shape of the sporebat will be yours to call upon.>", objectives = "Bring the Sporebat Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the sporebat. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65023] = { title = "Jormungar Soul", description = "<The Jormungar Soul is fierce and determined. The shape of the jormungar will be yours to call upon.>", objectives = "Bring the Jormungar Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the jormungar. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65024] = { title = "Cloud Serpent Soul", description = "<The Cloud Serpent Soul is energetic and loyal. The shape of the cloud serpent will be yours to call upon.>", objectives = "Bring the Cloud Serpent Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the cloud serpent. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65025] = { title = "Boar Soul", description = "<The Boar Soul is fierce and cunning. The shape of the boar will be yours to call upon.>", objectives = "Bring the Boar Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the boar. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65026] = { title = "Owl Soul", description = "<The Owl Soul is solemn and smart. The shape of the owl will be yours to call upon.>", objectives = "Bring the Owl Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the owl. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65031] = { title = "Battlegrounds", description = "Champions of the Horde and Alliance continue to fight across countless battlegrounds. The brokers of Cartel Zo are paying combatants in order to observe their tactics.\n\nWill you answer the call and join the fray?", objectives = "Speak with Tal-Inara.", completion = "The brokers of Cartel Zo will certainly be pleased by your choice." }
WordHunterWoW_QuestEN[65032] = { title = "Battleground Observers", description = "Zo'sorg and the other brokers of Cartel Zo can be found just down the hall.\n\nThey will certainly be eager to hear that large-scale battles are included in the Purpose.", objectives = "Speak with Strategist Zo'rak in Oribos.", completion = "Cartel Zo is a reliable partner. You have chosen well." }
WordHunterWoW_QuestEN[65033] = { title = "Observing Victory", description = "The threads of fate have called you to the realm of conflict, {name}.\n\nWill you rise to the challenge issued by your territorial rivals? Will you face them in combat and emerge victorious?\n\nIf you allow me to observe your victory, I will pay you your worth.", objectives = "Win any Battleground.", completion = "Victory is never assured. Return tomorrow for another observation." }
WordHunterWoW_QuestEN[65034] = { title = "Return to Oribos", description = "Return tomorrow for another observation.\n\nUntil then, Tal-Inara will be able to help direct your efforts in a productive manner.", objectives = "Speak to Tal-Inara in Oribos.", completion = "Cartel Zo speaks highly of your efforts. The Purpose is clear." }
WordHunterWoW_QuestEN[65035] = { title = "Return to Oribos", description = "You have been fantastic to work with, Maw Walker. You should bring this information back to whoever sent you here.\n\nMe? Oh, I'm staying here with my helpful box. \n\nFeel free to come back whenever you want. I may even have more tasks for you to do!", objectives = "Speak to Tal-Inara in Oribos.", completion = "You encountered a crazed broker and a... box? \n\nI am relieved you made it back in one piece, Maw Walker." }
WordHunterWoW_QuestEN[65036] = { title = "Train Like We Fight", description = "Jumping through hoops is helpful to get your bearings, but we train like we fight--relentlessly.\n\nGo ahead and try Soaring around the area until you feel you have mastered the technique. Of course you must be mindful of the local wildlife and keep an eye out for any potential threats. That is why we practice, after all.\n\nReport back to Emberthal when you feel you are ready. Good luck!", objectives = "Practice Soar.", progress = "The wind is gaining strength.", completion = "Time runs short. A storm approaches." }
WordHunterWoW_QuestEN[65045] = { title = "Stormsunder Crater", description = "Dervishian's report is troubling. An enemy force calling themselves the Primalists have invaded Stormsunder Crater, pinning the Ebon Scales down at the Siege Creche.\n\nThese intruders are summoning violent elementals and recruiting the vicious tarasek to their cause. \n\nAzurathel will need your help at the crater. By wing or by talon, save our people.\n\nOnce the Ebon Scales are safe, ask their commander to rendezvous with me. Be warned. Sarkareth can be... prickly.", objectives = "Meet Azurathel at Stormsunder Crater.", completion = "Well, <class>, I hope you are ready to get your talons dirty." }
WordHunterWoW_QuestEN[65046] = { title = "The Primalists", description = "My memories are still clouded from stasis, but I am certain we have encountered these Primalists before.\n\n<Dervishian grits her fangs.>\n\nIt is no use. Trying to remember feels like chasing fragments of a dream.\n\nPerhaps you can fare better. Look for any clues as to what--or who--motivates these invaders.", objectives = "Find clues about the Primalists' origins and intentions.", completion = "The Primalist speaks of unleashing a terrible storm.\n\nCould an even greater threat be locked away somewhere on the Reach?" }
WordHunterWoW_QuestEN[65049] = { title = "Tangle with the Tarasek", description = "The tarasek are unpredictable and wild. Like primordial drakonid, if you will.\n\nNeltharion considered them little more than fodder. Targets for our training. But they are cunning hunters, and deadly when encountered in packs.\n\nShould they gain elemental power from these Primalists, they will become even more dangerous.\n\nWe cannot let that happen, {name}. Thin their numbers.", objectives = "Slay 7 tarasek.", completion = "Do not mourn the loss of a few tarasek.\n\nWhere there is one, scores more lurk in the shadows." }
WordHunterWoW_QuestEN[65050] = { title = "Conjured Army", description = "These Primalists are summoning an army of elementals. We have to assume they mean to unleash them against our forces.\n\nWell, not on our watch.\n\nRain fire upon them, evoker! Burn those elementals from the Reach, and take out their conjurers before they summon more.", objectives = "Slay 12 Conjured elementals.", progress = "Where are they drawing all of this power from? And to what end?", completion = "Conjured elementals may not be the most satisfying foe, but it does feel good to stretch our wings again." }
WordHunterWoW_QuestEN[65052] = { title = "The Ebon Scales", description = "We got past the Primalist incursion. Now we must reach the creche.\n\nScalecommander Sarkareth is as tough as they come, and his weyrn holds the line. But a dragon has the Ebon Scales pinned down. \n\nTime for us to join the fight!\n\nTake point. Give the signal when we are in range of the dragon. Then we hit it with everything we have.\n\nWatch out for ambushes. I have a bad feeling about this.", objectives = "Reach Scalecommander Sarkareth.", completion = "You fight well, <class>, but we had this under control.\n\nThe Ebon Scales look after our own." }
WordHunterWoW_QuestEN[65053] = { title = "Giant Lungcap", description = "", objectives = "" }
WordHunterWoW_QuestEN[65054] = { title = "Training Dummies", description = "", objectives = "" }
WordHunterWoW_QuestEN[65055] = { title = "Protective Braziers", description = "", objectives = "" }
WordHunterWoW_QuestEN[65056] = { title = "Stop the Slip", description = "", objectives = "" }
WordHunterWoW_QuestEN[65057] = { title = "Rally to Emberthal", description = "Now that the fight is done, you ask me to report in to Emberthal. Does Azurathel expect me to follow her commands?\n\nI think not.\n\nThe Ebon Scales answer only to the Earth-Warder. And thus far, I have received no orders from Neltharion.\n\n<Sarkareth glowers.>\n\nStill, I am not blind to the threat these Primalists represent. I am certain I have fought their kind before, and yet...\n\nWe will rally to the grounds once my people have recovered. You are dismissed, evoker.", objectives = "Report to Emberthal.", completion = "The Primalists empowered their leader in some kind of ritual?\n\nTell me everything." }
WordHunterWoW_QuestEN[65060] = { title = "Caldera of the Menders", description = "Your vision from the arcane beacon showed that there are dracthyr trapped within their creches. We cannot afford to lose any more of our people.\n\n<Emberthal pauses, her brow furrowed.>\n\nThe Healing Wings are the finest medics in our ranks. Their creche lies within the Caldera of the Menders. Cindrethresh knows the way.\n\nLeave no one behind, evoker.", objectives = "Meet Cindrethresh in the Caldera of the Menders.", completion = "Look at all these wounded...\n\nThere are more Menders inside. We need to help them!" }
WordHunterWoW_QuestEN[65063] = { title = "Into the Hive", description = "Whatever toxin has infested this creche is potent enough to take down our best healers.\n\nThat does not bode well for either one of us, {name}.\n\nNo matter. Dracthyr are trapped inside. We are going in, regardless of risk.\n\nTake a deep breath and follow me!", objectives = "Follow Cindrethresh to find Viridia.", completion = "Good. You are awake.\n\n<Viridia coughs to clear her throat.>\n\nWe need an <class>'s skills right now." }
WordHunterWoW_QuestEN[65064] = { title = "Look Who I Found!", description = "Behold this magnificent creature!\n\nSiloh says we have no resources for another of my \"abnormal pets.\"\n\nBut we may be able to alter E'rnee so that I can keep him. Strange interactions occur between creatures and this environment. Perhaps we can make him smaller.\n\nI know a spot where we can conduct our research. There are flowers nearby called chromatic rosids that might trigger a reaction. Why don't you collect some on the way?", objectives = "Retrieve 6 Chromatic Rosids near Dimensional Falls.", progress = "We must find a way to keep E'rnee.", completion = "Perhaps we should do some experiments with other subjects before trying things out on E'rnee." }
WordHunterWoW_QuestEN[65065] = { title = "The Tuskarr", description = "Oh, excuse me but we did not know your kind was on this island. We are only newly arrived to these shores looking for a unclaimed land to call a home. We mean no harm and will move on if this land truly is forbidden.\n\nMy son To'no is quite the fan of dragonkin of all sorts and I am sure would have many questions for you. He is my little explorer. If you see him before I do know that you may be accosted by many questions.\n\nNow where did that little moo get to...?", objectives = "Find and meet To'no.", completion = "Oh! Dragonkin! You are skinnier than the others. Oh! And you have wings! \n\nUm... halp?" }
WordHunterWoW_QuestEN[65066] = { title = "Flora Aroma", description = "Perhaps we should not experiment on E'rnee without first knowing the effects.\n\nHang on to the rest of these rosids. We can run more tests. Some of the creatures here near the waterfall are more tame than others, and will be suitable for such experimentation.\n\nLet us discover whether different creatures have diverse responses to the rosid aroma.", objectives = "Experiment with Chromatic Rosids near Dimensional Falls.", progress = "Those rosids have such an odd aroma... Perhaps creatures will respond to it in unique ways.", completion = "These results seem... inconclusive." }
WordHunterWoW_QuestEN[65067] = { title = "Broker Beaker", description = "I was running some experiments of my own before you got here.\n\nThose tests... did not go too well. It turns out some environmental components can aggravate the creatures, turning even the most docile into predators.\n\nI dropped my component container and ran, and I cannot recall where I left it.\n\nThe beaker must be somewhere among the herd of carnivorous cervids. If these flowers do not work, we will need that container for our next round of tests.", objectives = "Retrieve the Component Beaker from Carnivorous Cervids near Dimensional Falls.", progress = "Be careful with those carnivorous cervids--they bite!", completion = "Ah. This will certainly be useful." }
WordHunterWoW_QuestEN[65068] = { title = "Cascades of Magnitude", description = "Many of the creatures here at Dimensional Falls are particularly affected by the environment. Hmm... let us experiment with the waterfalls themselves!\n\nWe have seen unique effects from various natural components here in Zereth Mortis. Why not the water as well?\n\nCollect some water, then sprinkle it on a creature in the Falls to see what happens.", objectives = "Experiment with waterfall water in Dimensional Falls.", progress = "These Falls must contain magic we cannot even comprehend.", completion = "That was unexpected." }
WordHunterWoW_QuestEN[65069] = { title = "Culling the Maelstrom", description = "Those little E'rnee duplicates were unfriendly.\n\nSome effect of the Falls created them. They are not stable. Did you see where they went? \n\nThey must be culled before they harm the rest of the wildlife. You take care of that while I collect another sample from the Falls.", objectives = "Kill 50 E'rnee Duplicates.", progress = "Have you found the duplicates?", completion = "Oh my... what happened to you?" }
WordHunterWoW_QuestEN[65070] = { title = "Can I Keep Him?", description = "Oh, no. I have created havoc in this sacred place.\n\nLook. E'rnee has bonded with you. It pains me, but you would be a better caretaker for him than I have been.\n\nOnce we resolve this, you should take him.\n\nNow we know, at least, that the Falls have the ability to change the size of creatures. Let us try it again.", objectives = "Throw Water on E'rnee.", progress = "If this does not work, we can always try again!", completion = "It worked! I cannot thank you enough for your help. And now, he is yours. Take good care of him.\n\nGoodbye, E'rnee." }
WordHunterWoW_QuestEN[65071] = { title = "Halp!", description = "I need halp!\n\nI am To'no and I was exploring cuz that is what I am good at but I did not realize my sister Ko followed me and I need you to halp me find her cuz she is in trouble so please halp please?\n\nShe went into this cave but she is not as good at hiding as I am and our parents are too far away to halp. \n\nCan you find her before the monsters do?", objectives = "Rescue Little Ko.", completion = "You found my little ones!" }
WordHunterWoW_QuestEN[65072] = { title = "Not Safe for Work", description = "Rana's discovery of Progenitor relics at the Ageless Shards has created quite a stir among the Enlightened. These relics predate our earlier discoveries, and through them we may gain a deeper understanding of the workings of Zereth Mortis.\n\nRana is collecting the relics, but I fear she is in danger. Agents of Cartel Xy have been spotted in the area, and will likely attempt to steal the relics.\n\nPlease travel to the Ageless Shards, and help Rana collect the relics.", objectives = "Assist Rana in her search and collect 8 Progenitor Relics.", progress = "Have you collected the Progenitor Relics?", completion = "Your help is always appreciated, <name>." }
WordHunterWoW_QuestEN[65073] = { title = "A Toxic Problem", description = "You recover quickly, {name}. Good.\n\nThose who escaped my creche are healing, but others remain trapped inside. Rush in to save them and I will just have to drag you out again.\n\nThere are beetle nests scattered around the caldera. Their toxin glands might provide a way to counter the effects of that poison.\n\nI am in no shape to collect them myself. I must rely upon your skills, evoker.", objectives = "Collect 6 Toxin Glands.", progress = "Time runs short.", completion = "Good. These are just what I needed.\n\nI will work on something to counter the toxin and get you back into the creche." }
WordHunterWoW_QuestEN[65074] = { title = "Easy Prey", description = "The wilds surrounding this creche are home to scythid. They are voracious insectoids, often territorial and aggressive. \n\nAll these wounded would be easy prey for those beasts. I do not want them attacking our Menders while they recover.\n\nCull their numbers while I look after Viridia.\n\nShe is.. very brave.", objectives = "Slay 4 scythid.", progress = "The menders do not need any more stress.", completion = "The scythid were always formidable, but it seems during our stasis they have grown even larger and more threatening." }
WordHunterWoW_QuestEN[65075] = { title = "The Healing Wings", description = "Evoker, you have my gratitude for aiding my weyrn in our most desperate hour.\n\nAfter we regain our strength, the Healing Wings will rendezvous with the rest of our forces.\n\nCindre tells me that Emberthal lost everyone from her weyrn. I fear I have no magic that can heal such a wound.\n\nShe may seem stoic, but Emberthal feels this loss deeply, {name}. Tell her I am on my way.", objectives = "Speak with Emberthal.", completion = "I am relieved that Viridia lives.\n\nIf what Dervishian says is true, we will have need of her talents in the battle to come." }
WordHunterWoW_QuestEN[65080] = { title = "Anima, Diverted", description = "Now, for the moment of truth.\n\nDeposit any anima on your person at the Field Anima Diverter behind me.\n\nWith any luck, you will not experience any side effects - loss of anima, loss of consciousness, loss of memory. That sort of thing.", objectives = "Deposit anima at the Field Anima Diverter in the Reliquary of Remembrance.", progress = "Were you able to deposit your anima at the Field Anima Diverter?", completion = "A resounding success!\n\nI trust the diverter will prove useful, now and in the future." }
WordHunterWoW_QuestEN[65081] = { title = "An Apple A Day", description = "", objectives = "" }
WordHunterWoW_QuestEN[65084] = { title = "The Froststone Vault", description = "Look there, across the Reach! Primalist forces are converging on Froststone Vault.\n\nThe storm they seek to unleash must be locked inside.\n\n<Emberthal winces, wrestling with her broken memories.>\n\nWe fought this enemy before, and won. Neltharion commanded that the vault be secured, but I... cannot remember why...\n\nThis is no time for contemplation. Rally with Sarkareth and the Ebon Scales at the vault. Ensure the enemy does not breach it!", objectives = "Rally to Froststone Vault.", completion = "Steady there, <class>. The Ebon Scales will put an end to this incursion." }
WordHunterWoW_QuestEN[65087] = { title = "The Prize Inside", description = "So the Primalists want what's inside this vault?\n\n<Sarkareth narrows his eyes.>\n\nLet them come.\n\nWe will show them what the dracthyr were born to do!", objectives = "Defend the vault.", progress = "We are not defending a creche. We are defending something far more dangerous. I can feel it.\n\nThe magic behind that barrier is fighting to get out. Stand your ground and do NOT let these Primalists pass.", completion = "We are overrun! They are about to breach the vault!\n\nWhere are those black dragons?!" }
WordHunterWoW_QuestEN[65089] = { title = "Frog'it", description = "", objectives = "" }
WordHunterWoW_QuestEN[65090] = { title = "Return More Lost Souls", description = "Souls still continue to pour into the Maw. Can you venture out again to save more?\n\nWe must thwart his plans.\n\nReturn to the Maw and rescue any more that you can.", objectives = "Rescue 20 Souls in the Maw.", completion = "Oh, you found so many more deserving souls!\n\nI will make sure these souls are well taken care of here in Ardenweald." }
WordHunterWoW_QuestEN[65096] = { title = "Your Death Or Mine", description = "We have obtained a wealth of information from relics discovered at the Ageless Shards. \n\nThe Mawsworn are aware of our discoveries, and are trying to stop us. They have placed traps around the area to block access to the relics. \n\nWe cannot allow the Jailer to cut off our access to those relics.\n\nPlease eliminate this Mawsworn threat, and recover as many relics as possible.", objectives = "Slay Punisher Makaris and collect 6 Sacred Relics.", progress = "Have you secured the relics at the Ageless Shards?", completion = "Blessed be your effort!" }
WordHunterWoW_QuestEN[65097] = { title = "Run!", description = "Storms are about to overwhelm us! We must evacuate!\n\nSave everyone you can. And find those black dragons!", objectives = "Retreat!", progress = "The... pain.", completion = "My thanks, <name>. \n\nYour aid is unexpected... but appreciated." }
WordHunterWoW_QuestEN[65098] = { title = "The Consequence of Courage", description = "Thank you for healing me, {name}. I hope that we are earning one another's trust.\n\n<Wrathion shudders.>\n\nThe Storm-Eater. I have never faced a dragon of such raw elemental power. If there are others like her...\n\nWait... where is Ebyssian? Did he survive? You must find him!", objectives = "Find Ebyssian.", completion = "I am relieved you made it out, <name>.\n\nBut I.. cannot help but feel lost." }
WordHunterWoW_QuestEN[65100] = { title = "Final Orders", description = "The storm unleashed by Raszageth is too powerful. We must evacuate the only home we have ever known.\n\nThere is no longer an Earth-Warder to command us. For the first time, we are free to make our own choices. To find our own fate.\n\nWherever you go in this new age, I hope you find worthy allies. Tell them our story.\n\nAs for me, I will stay here and look for survivors. Along the way, I may find answers about our past.\n\nMay fortune favor us all, {name}.", objectives = "Organize the evacuation of Forbidden Reach.", progress = "We are leaving! I never thought it would be like this but we will return again with greater preparation.", completion = "Wrathion speaks of a group called the Alliance. Noble folk who care for one another and defend this world.\n\nHe has offered to introduce us to their leaders in a place called Stormwind. Come, <name>." }
WordHunterWoW_QuestEN[65101] = { title = "An Iconic, Draconic Look", description = "You turned every head in Stormwind with your arrival, {name}. No doubt some citizens were more... amenable to your presence than others.\n\nIn order to better commune with other races, we dragons adopt a mortal visage, like the one you see before you. Not only does it put allies at ease, but it makes passing through doorways considerably less disruptive.\n\nClearly the essence of dragonkind flows through the dracthyr. I suspect you may share our ability to assume a visage.\n\nWalk with me.", objectives = "Assume your mortal visage.", progress = "Mortals can be so nervous around superior beings.", completion = "Your visage suits you well, <name>. It is unlike any I have seen before!\n\nPerhaps when we learn more of your origins, we will understand why the <race> visage differs from that of a dragon.\n\nBut now, we have an expedition to prepare for." }
WordHunterWoW_QuestEN[65102] = { title = "Fish Eyes", description = "", objectives = "" }
WordHunterWoW_QuestEN[65103] = { title = "Return More Lost Souls", description = "Souls still continue to pour into the Maw, we must stay the course and find more worthy souls.\n\nReturn to the Maw and save all that you can.", objectives = "Rescue 20 Souls from the Maw.", progress = "There is no fate worse than the Maw, did you find more?", completion = "Well done. I know we can spare even more from this truly cruel existence." }
WordHunterWoW_QuestEN[65104] = { title = "Return More Lost Souls", description = "Maw Walker, we must do more to cut off the Jailer's power and deny him any more souls. \n\nReturn to the Maw and rescue any more that you can.", objectives = "Rescue 20 Souls in the Maw.", progress = "There is no fate worse than the Maw, did you find more?", completion = "Excellent, Maw Walker. Our armies here will continue to grow stronger with each soul you return." }
WordHunterWoW_QuestEN[65105] = { title = "Return More Lost Souls", description = "Souls continue to pour into the Maw. \n\nI see no reason you cannot pull even more souls from the abyss.\n\nReturn to the Maw and find me even more worthy of redemption.", objectives = "Rescue 20 Souls in the Maw.", completion = "Another good collection of souls. Not too broken, not too drained, and not too innocent.\n\nI know just where to send these souls on their path to redemption." }
WordHunterWoW_QuestEN[65115] = { title = "Researching the Solution", description = "", objectives = "" }
WordHunterWoW_QuestEN[65117] = { title = "Bad Samples", description = "", objectives = "" }
WordHunterWoW_QuestEN[65118] = { title = "How to Glide with Your Dragon", description = "Let us start with the basics.\n\nIf you fly straight you will wear yourself out right now. Use gravity as an aid and aim slightly down to fly a long distance. The rings will give you the general angle that you should use for basic gliding.\n\nFirst, call upon your drake, or our Red Drake friend here can give you a lift.\n\nThen, fly through the rings and land at the target location.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", objectives = "Summon your skyriding mount, or mount the Red Drake. Then glide through the rings and land in the target area.", progress = "Well done, 0xcp.", completion = "Excellent work!" }
WordHunterWoW_QuestEN[65119] = { title = "Automa Ops", description = "", objectives = "" }
WordHunterWoW_QuestEN[65120] = { title = "How to Dive with Your Dragon", description = "Gliding will get you to where you want to go. But what if you want to get there faster?\n\nDiving after jumping from somewhere high will give you a speed boost.\n\nFly through the rings to the target location.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", objectives = "Dive then glide through the rings and land in the target area.", progress = "Well done, <name>.", completion = "See? That was much better.\n\nIf you start your flights with a dive you will get to where you want to go so much faster." }
WordHunterWoW_QuestEN[65121] = { title = "Friend of a Friend: Baroness Vashj", description = "", objectives = "<Baroness Vashj looks you over with great interest.>\n\nJust because we have a mutual friend does not mean that you and I will be friends...\n\nBut you can clearly handle yourself in a fight. Let's see if you continue to impress me." }
WordHunterWoW_QuestEN[65123] = { title = "Friend of a Friend: Lady Moonberry", description = "", objectives = "<Lady Moonberry grins as she hides something behind her back.>\n\nOh, I didn't see you there, <name>!\n\nDon't worry. Our mutual friend absolutely did NOT tell me all of your deepest, darkest secrets...  Nope. No way!" }
WordHunterWoW_QuestEN[65124] = { title = "Friend of a Friend: Mikanikos", description = "", objectives = "<Mikanikos studies you carefully.>\n\nOh yes, <name>. Our shared friend speaks highly of you. Very interesting. Very intriguing.\n\nExcited to learn more." }
WordHunterWoW_QuestEN[65126] = { title = "Friend of a Friend: The Countess", description = "", objectives = "<The Countess smiles courteously.>\n\nAh, the gossip was true this time! I've been waiting to meet you here since our mutual acquaintance first mentioned you.\n\nI am very intrigued to learn if the more extravagant stories I've heard about you are true... I certainly hope so." }
WordHunterWoW_QuestEN[65128] = { title = "Friend of a Friend: Alexandros Mograine", description = "", objectives = "<Alexandros Mograine salutes you.>\n\nWell met, <name>. Our mutual friend speaks very highly of you. I look forward to spending court together." }
WordHunterWoW_QuestEN[65129] = { title = "Friend of a Friend: Hunt-Captain Korayn", description = "", objectives = "<Hunt-Captain Korayn nods in approval.>\n\nOur mutual friend tells me you've been quite busy since we last met. They told some impressive stories of your hunts as well. I welcome the opportunity to hunt alongside you." }
WordHunterWoW_QuestEN[65130] = { title = "Friend of a Friend: Polemarch Adrestes", description = "", objectives = "<Polemarch Adrestes looks over some notes he brought with him.>\n\nOur mutual friend has given me several compelling reasons why you and I should get better acquainted.\n\nA friend of my friend is my friend indeed. Do not hesitate to ask anything of me if I may be of service." }
WordHunterWoW_QuestEN[65131] = { title = "Friend of a Friend: Rendle and Cudgelface", description = "", objectives = "<Rendle dusts off his shirt and tries to stand up tall.>\n\nGood to see you 'ere, <name>. A little birdie been telling you be the one I should be impressin' next.\n\nI'm makin' da rounds see. Bein' social butterfly and all 'at. So you wanna be friends with me and Cudgelface or what?" }
WordHunterWoW_QuestEN[65132] = { title = "Friend of a Friend: Choofa", description = "", objectives = "<Choofa's eyes get big as he sees you.>\n\n<name>! I've been waiting for you to get here! Our friend wouldn't shut up about how great you are... mostly because I kept forcing them to tell me stories about your adventures.\n\nBut now that you're here, you can tell me the stories yourself. We'll be best friends  in no time!" }
WordHunterWoW_QuestEN[65133] = { title = "How to Use Momentum with Your Dragon", description = "Now what if there is an obstacle in your way?\n\nAs long as you fly well, you can conserve your momentum and gain some height after a dive.\n\nWhen you dive this time you will find your flight path takes you below the landing area. By using your momentum you can regain lost height at the end of the course to still land in the target area.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", objectives = "Dive through the rings and land in the target area.", progress = "Well done, <name>.", completion = "Well done. The rest is now a matter of practice." }
WordHunterWoW_QuestEN[65134] = { title = "Friend of a Friend: Cryptkeeper Kassir", description = "", objectives = "<Cryptkeeper Kassir bows to you.>\n\nIt is an honor to meet you here, <name>. Temel delivered me an interesting letter from a shared acquaintance of ours.\n\nBased on their account, I must say the honor is doubled. I look forward to knowing you better." }
WordHunterWoW_QuestEN[65135] = { title = "Friend of a Friend: Droman Aliothe", description = "", objectives = "<Droman Aliothe smiles gently.>\n\nI was surprised when I read the details of this invitation. We apparently have a mutual friend, who I've grown quite fond of over time.\n\nI am pleased you are here. It is good to see another friendly face here, far from my hollow." }
WordHunterWoW_QuestEN[65136] = { title = "Friend of a Friend: Grandmaster Vole", description = "", objectives = "<Grandmaster Vole sizes you up with a quick glance.>\n\nNah, see, I told them you weren't THAT strong. I gotta find that buddy of ours and let 'em know I was right.\n\nDon't get me wrong, I'd bet you still pull your weight in a fight, but I gotta see more to really be impressed." }
WordHunterWoW_QuestEN[65137] = { title = "Friend of a Friend: Kleia and Pelagos", description = "", objectives = "<Kleia greets you warmly.>\n\nWell, this court keeps getting better.\n\nIt's good to see you, <name>. I've heard quite the tale of your adventures from our mutual friend. I am eager to learn more about you and what you value in your court." }
WordHunterWoW_QuestEN[65138] = { title = "Friend of a Friend: Plague Deviser Marileth", description = "", objectives = "<Plague Deviser Marileth offers you a slimy hug.>\n\nMy apprentice! What a wonderful surprise. Have you brought the results of our latest experiment with you?\n\nOh no, I suppose you haven't. I think I gave them to Kevin...\n\nOh well, I am just happy you're here. Another of my apprentices was talking about you just the other day." }
WordHunterWoW_QuestEN[65140] = { title = "Friend of a Friend: Sika", description = "", objectives = "<Sika brushes a bit of ash off of your shoulder.>\n\nNo offense meant. Ash falls from sky here. Very unpleasant on clothes. Sika help!\n\nSika's friend tell Sika stories of you. Good friend. Best friend! Maybe you become best friend too?" }
WordHunterWoW_QuestEN[65141] = { title = "Friend of a Friend: Stonehead", description = "", objectives = "<Stonehead sticks his chest out proudly.>\n\nMy best bud know you. My best bud is best bud!\n\nBut best bud tell me some can have more than one best bud?\n\nWould... you want be best bud too?" }
WordHunterWoW_QuestEN[65142] = { title = "Portal Play", description = "To aid in my studies, I have used a network of travel portals to install monitoring devices all over Zereth Mortis.\n\nMy devices have been quite successful at collecting large amounts of research data. It's time now to collect the data they have obtained.\n\nUse my portal network to locate my Prying Eyes and collect any data they have gathered. I'll give you a portal initiator as well, allowing you to re-enter the portal network, incase you find yourself lost!", objectives = "12 Prying Eye's research data collected.", progress = "Have you collected all the data?", completion = "This will do fine, but there is still so much more to understand. With my Prying Eyes still out there, we shall be able to collect some more data very soon." }
WordHunterWoW_QuestEN[65143] = { title = "Antros", description = "", objectives = "" }
WordHunterWoW_QuestEN[65145] = { title = "Relic Clues", description = "", objectives = "The research is going so well. \n\nPreliminary findings have given me clues on how to find more relics, let me share them with you." }
WordHunterWoW_QuestEN[65146] = { title = "Relic Hunter", description = "", objectives = "It seems some relics have a trace or unique identifier. \n\nHere are the details, it should allow you to locate even more relics when you find a source." }
WordHunterWoW_QuestEN[65147] = { title = "No Ordinary Steward", description = "Yes?", objectives = "There is greatness within you, Maw Walker. I can feel it!\n\nAnd the Forgelite Prime is rarely wrong.\n\nYou bear the wisdom of one who knows much. Yes, you must share it with me!\n\n...and I with you, of course." }
WordHunterWoW_QuestEN[65149] = { title = "Surveying Cyphers", description = "There are many consoles such as that one scattered throughout Zereth Mortis. \n\nThey have all been beyond my understanding, but perhaps that creature intends to reveal their meaning to us? \n\nFortunately, I know where there are more. I will mark them on your map, and accompany you... for research, of course.\n\nLet us see what this creature's purpose is.", objectives = "Find the Concordance consoles in Zereth Mortis.", completion = "You have gained a glimpse of knowledge unimaginable. Now, to make use of it." }
WordHunterWoW_QuestEN[65152] = { title = "A Hardened Bond", description = "Yes?", objectives = "" }
WordHunterWoW_QuestEN[65157] = { title = "A Hardened Bond", description = "yes?", objectives = "Our shared knowledge will benefit all of Maldraxxus." }
WordHunterWoW_QuestEN[65165] = { title = "Soul Support", description = "This is purely so you can see how much better Emeni is at everything.", objectives = "Though Emeni's body has yet to be rebuilt, she can still offer you advice and support in her soul form!" }
WordHunterWoW_QuestEN[65168] = { title = "My Wings Are Yours", description = "How can I serve?", objectives = "We have been through so much together, <name>. I am deeply grateful for all that you've done already.\n\nWe could do even more as soulbinds! What do you say?" }
WordHunterWoW_QuestEN[65169] = { title = "A Stalwart Ally", description = "", objectives = "Maw Walker, the time has come.\n\nAccept my bond and we shall shake the very foundations of Revendreth until it remembers where its roots truly lie." }
WordHunterWoW_QuestEN[65170] = { title = "Kindred Spirits", description = "", objectives = "My heart swells, knowing that our souls are bound for all eternity." }
WordHunterWoW_QuestEN[65177] = { title = "Fruit of the Bloom", description = "We never know when something new may emerge from the confluence of creation and energy.\n\nThe Catalyst Gardens have blossomed with a new crop of fruit. Their seeds may have special properties, and we wish to understand them.\n\nPlease gather what you can find, and make the gardens safer for the future.", objectives = "Gather Catamelon Seeds and slay Overgrowth in the Catalyst Gardens.", progress = "How can one understand what cannot be defined?", completion = "There is so much to learn from just these little seeds. What will they grow into? Will the vombata eat them?\n\nThank you for helping me to understand this place further." }
WordHunterWoW_QuestEN[65218] = { title = "Navigation Playtest: Level Up (PART 1)", description = "The start of the Azure Span.", objectives = "" }
WordHunterWoW_QuestEN[65219] = { title = "Jiro to Hero", description = "I have spoken to other jiro. Our orb can create a dampening field. It should close the rifts and stop new ones from forming.\n\nIt must be done where the Maw magic is strongest. Between the giant chains. The power released by the orb will draw devourers. You and I must defend the orb until the field is set.\n\nI will escort the others. Meet us at the rift when you are ready.", objectives = "Defend the jiro from devourers until they enact the dampening field.", completion = "Devourers have been repelled. For now. But they will return.\n\nOne day, we will remove them forever. I will stay to defend the jiro until then.\n\nThis could not have been done without you. You have my deepest gratitude." }
WordHunterWoW_QuestEN[65220] = { title = "Navigation Playtest: Level Up (PART 2)", description = "The finale of the Azure Span.", objectives = "The finale of the Azure Span." }
WordHunterWoW_QuestEN[65226] = { title = "Fleet-Footed and Fastidious", description = "When the Mawsworn came to Zereth Mortis, they brought mawrats with them!  \n\nA swarm of their mawrats overran my cave, making off with many of our research items!\n\nRana is assembling a team to help recover the items. Meet up with her and aid in the effort.", objectives = "Help Rana recover 6 Stolen Relics and slay 80 Thieving Mawrats.", progress = "Have you dealt with those mawrats?", completion = "A most excellent effort! I had feared these items lost for good." }
WordHunterWoW_QuestEN[65230] = { title = "Bot-any", description = "", objectives = "" }
WordHunterWoW_QuestEN[65231] = { title = "Plundered Knowledge", description = "", objectives = "" }
WordHunterWoW_QuestEN[65232] = { title = "Annelid-ilation", description = "", objectives = "" }
WordHunterWoW_QuestEN[65234] = { title = "Sweet On Them", description = "", objectives = "" }
WordHunterWoW_QuestEN[65237] = { title = "Oracle, Heal Thyself", description = "The vessel, snatched from peril. This automa, a steadfast servant. Its energy, the key to my restoration.\n\nPocopoc, it calls itself. A name that shall return to it.\n\nMy name will be mine again. Saezurah, among the last of the oracles. Guide to those who would save Zereth Mortis.\n\nBring Pocopoc. Its time as proxy has ended. The time of my awakening has arrived.", objectives = "Bring Pocopoc to Saezurah.", completion = "Dormant no longer. The pattern aligns. But more must be done." }
WordHunterWoW_QuestEN[65238] = { title = "Souls Entwined", description = "I must confess, at first I thought Pelagos was making a horrible sacrifice. But now I see--he was giving the Shadowlands all the hope and compassion he holds in his heart. We should go and see him.\n\nSpeak with Tal-Inara when you reach Oribos.\n\nI will meet you there, my friend.", objectives = "Speak with Tal-Inara in Oribos.", completion = "Pelagos is right. But if anyone can accomplish what is needed... I believe it is you, my friend." }
WordHunterWoW_QuestEN[65244] = { title = "Devourable", description = "", objectives = "" }
WordHunterWoW_QuestEN[65245] = { title = "Pop Goes the Devourer!", description = "Once... they had purpose. Made for balance. But now... shifted, altered. Disharmonious.\n\nThey rend the pattern. It cannot continue.\n\nElimination is the only recourse.", objectives = "Kill mutated devourers in the Resonant Peaks.", completion = "The design must be restored." }
WordHunterWoW_QuestEN[65249] = { title = "The Jailer's Defeat", description = "At long last, we have thwarted the Jailer's schemes. \n\nBoth the Forge of Afterlives and Azeroth's world-soul have been restored, and the Shadowlands can now begin to recover from the anima drought.\n\nI know it is in your nature to push ever forward. But this was a monumental victory, and it deserves a moment of reflection.", objectives = "Speak to Bolvar to relive the victory against the Jailer.", progress = "Have you witnessed the defeat of the Jailer?", completion = "A new era for the Shadowlands begins today." }
WordHunterWoW_QuestEN[65250] = { title = "Prisoner of Interest", description = "With the Jailer defeated, we must now turn our attention to healing the wounds he inflicted upon the Shadowlands. That process begins with Sylvanas Windrunner.\n\nThough she proved instrumental to our victory, the terrible atrocities she committed have been neither forgotten nor forgiven. She is to face the new Arbiter's judgment in Oribos.\n\nUther awaits you in the Ring of Fates. Together, you will escort Sylvanas to the Crucible.", objectives = "Speak to Uther in Oribos to escort Sylvanas to the Arbiter.", completion = "Word of Sylvanas's arrival has spread throughout the Shadowlands. Many wish to see her pay for her crimes." }
WordHunterWoW_QuestEN[65252] = { title = "Stomp It Now", description = "", objectives = "" }
WordHunterWoW_QuestEN[65255] = { title = "Forcing the Cycle", description = "The forces of Zovaal have been spreading their malign influence into the natural life within Provis Fauna. With the rate of their corruption, attempting to cleanse them one by one would be ill advised.\n\nInstead, we can just return their energies into the systems of Zereth Mortis to be used to create new fauna. Use this orb, let it absorb their energy as they die, and then cleanse it once it has been charged.", objectives = "Charge and cleanse the Progenitor orb.", progress = "Have you finished?", completion = "Their energy will serve the cycle." }
WordHunterWoW_QuestEN[65256] = { title = "Cluck, Cluck, Boom", description = "The endemic poultrids of Zereth Mortis have been influenced in an unseemly way by all these invaders.\n\nUse this device on the ones that have malfunctioned. Otherwise, they will do too much damage to the land.", objectives = "Use the Kinematic Micro-Life Recalibrator to \"recalibrate\" Malfunctioned Poultrids in the Great Veldt.", progress = "These mysterious ways must be understood.", completion = "Those poultrid do make quite a mess. Thank you for your assistance." }
WordHunterWoW_QuestEN[65259] = { title = "Heart of the Sepulcher", description = "Soon after we stepped forth into the realms of Death, a message left behind by the Primus gave warning that the Jailer must not be allowed to reach the Sepulcher.\n\nDespite all our efforts, he has done so.\n\nWithin the heart of that ancient place lie secrets the Jailer could use to dominate the entire cosmos. If he succeeds, everything we hold dear will be lost.\n\nGather your allies, {name}. Claim victory for the Shadowlands... and for Azeroth.", objectives = "Defeat the Jailer in the Sepulcher of the First Ones.", completion = "At long last, our campaign is at an end. Thanks to you, the Jailer has been defeated.\n\nYour efforts have saved us all, <name>." }
WordHunterWoW_QuestEN[65260] = { title = "A Long Walk", description = "The Arbiter awaits us. Though few are allowed within the Crucible, several who hail from Azeroth have been granted permission to bear witness as he passes judgment on Sylvanas.\n\nYet we are far from the only ones affected by all the carnage Sylvanas has wrought. Her actions have brought pain and suffering to a great many.\n\nScreaming back at the Banshee as she passes might be their only chance to speak their mind. Let them be heard.", objectives = "Speak to Uther in Oribos to escort Sylvanas to the Enclave, then speak to Tal-Inara to be brought to the Crucible.", completion = "Thank you for joining us, my friend. \n\nI felt it important that you be here to witness this moment." }
WordHunterWoW_QuestEN[65262] = { title = "Save the Vombata", description = "", objectives = "" }
WordHunterWoW_QuestEN[65263] = { title = "The Fate of Sylvanas", description = "The time has come.\n\nLet this bring the dark saga of Sylvanas Windrunner to a close and herald a new dawn for the Shadowlands.\n\nSpeak to me, and we will begin.", objectives = "Speak to Pelagos to witness the judgment of Sylvanas Windrunner.", completion = "How could I possibly pass judgment to Tyrande's satisfaction when she and her people were the ones most wronged by the Banshee Queen?" }
WordHunterWoW_QuestEN[65264] = { title = "Operation: Relocation", description = "Devourers have disrupted the avians nesting at Provis Esper.\n\nThis may be our last chance to examine them before they become tainted, like the others.\n\nCapture several of the avians at Provis Esper and return them to Pilgrim Arizh for relocation and study. Deal with any problems that get in your way.", objectives = "Deliver 8 wrangled Wild Proto Avians and slay 6 Soul-Parched Gorgers and 2 Reality Breachers in Provis Esper.", completion = "Well done, <name>. The avians will be moved to a safer location where we can observe them." }
WordHunterWoW_QuestEN[65265] = { title = "Buried Remnants", description = "Much has been lost to the invading forces, those that came with destruction in their hearts.\n\nWe cannot preserve this land as the First Ones intended if the Mawsworn are allowed to pulverize all remnants of their knowledge.\n\nSee what you can recover from the sands of Provis Strata.", objectives = "Recover Strange Artifacts from Provis Strata.", progress = "What was before, will be again.", completion = "Without the context in which these were first made, they may remain mysteries. But at least they are not trampled underfoot anymore." }
WordHunterWoW_QuestEN[65266] = { title = "Lost Research", description = "We have uncovered a promising source of Korthian research. Previous Archivists hid knowledge within repositories that were then placed within the rift.\n\nI fear that the repositories are no longer safe and that shades of that realm will consume them. It is imperative that we secure this research before it is lost forever.\n\nUse a Repaired Riftkey to enter the Korthia Rift. Recover the Korthian Repositories.", objectives = "Recover Korthian Repositories from the Korthia Rift for Archivist Roh-Suir.", progress = "The archive would be lost without you, Maw Walker.", completion = "The research within these repositories is invaluable. I may ask you to return to the rift again in the future." }
WordHunterWoW_QuestEN[65267] = { title = "Smash 'Em to Feathereens", description = "I was curious about these strange, winged creatures and attempted to introduce myself. I would have been eaten if not for Professor Chirpsnide and her large mechanical fowl!\n\nCould you help us deal with these \"Screechflight\"? The native bluefeather rocs are having a difficult time defending their nests from them.\n\nAlso, I'd hate for any more introductions to go the way mine did with them...", objectives = "Kill 8 Screechflight Witherers and 10 Screechflight Hexclaws.", progress = "The only thing I can thank these harpies for is giving me the chance to meet the professor!", completion = "Thank you, <name>!\n\nI've been assisting the good Professor while you've been gone. I'm afraid to say I've made things worse for her..." }
WordHunterWoW_QuestEN[65268] = { title = "Bzzzzt!", description = "The vespoids of the region use debris in the area to form the core of their nests. While this is normally something we'd allow them to naturally do, they've started taking some of the relics we were studying.\n\nI have a device that should hopefully allow for the removal of such relics from their hives without damaging the core structure. Use it to retrieve these relics.", objectives = "Use the enlightened broker device to remove the progenitor debris from vespoid nests.", completion = "That is enough for now, thank you." }
WordHunterWoW_QuestEN[65269] = { title = "Obvious Plant", description = "The situation in the Catalyst Gardens is troubling.\n\nBut most troubling of all is that we do not know more. If we had an understanding of the changing levels of energy emitted by the Creation Catalyst, we could make better decisions as to how to proceed.\n\nTake these sensors. Place them below the catalyst at the locations marked upon your map.", objectives = "Place the Progenitor Magic Sensors in the Catalyst Gardens.", progress = "Were you able to place the sensors?", completion = "Our brightest scholars will track the sensor data. First Ones willing, they will show us the way." }
WordHunterWoW_QuestEN[65271] = { title = "Forging Connections", description = "Firim described these Enlightened brokers unfavorably. Then again, he does seem a bit... eccentric.\n\nRegardless, if we are to restore contact with our comrades in Oribos and defeat the Jailer, we will need allies in Zereth Mortis.\n\nThe Mawsworn look to be gathering outside the gates of Haven. We must not let any more innocents fall prey to the Jailer's villainy.\n\nHopefully the Enlightened will welcome our aid. After you, my friend.", objectives = "Enter Haven and meet with the Enlightened.", progress = "You dare enter the sacred lands of the First Ones, outsider?", completion = "If you do not have the power to help us, then you must go." }
WordHunterWoW_QuestEN[65274] = { title = "Navigation Playtest: Level Up", description = "This is a single quest. It will guide you though the high points of the level up story for Thaldraszus", objectives = "This is a single quest. It will guide you though the high points of the level up story for Thaldraszus" }
WordHunterWoW_QuestEN[65279] = { title = "By Royal Decree", description = "Idiot gnoll not understand crown. Only understand violence. Beat them up or I eat you.", objectives = "Kill 8 Brackenhide Warriors and 4 Brackenhide Shamans in Creektooth Den.", progress = "GET WITH KILLING!", completion = "Good start... but have bigger plans." }
WordHunterWoW_QuestEN[65286] = { title = "Draconic Connections", description = "Ordinarily such a flight would take considerably longer. But when the bronze Aspect himself speeds you on your way, it allows one to make the journey in record... \n\n<ahem> ...time.\n\nOh, the soldiers with the pointy weapons? Not to worry. Merely a formality.\n\nI shall see about arranging an audience with the Lord Commander while you and Azurathel get your bearings.\n\nThankfully, I wield considerable influence in this city.", objectives = "Gain entrance to Stormwind.", completion = "Perhaps Wrathion's \"influence\" isn't as considerable as he thinks, if this is the welcome he receives." }
WordHunterWoW_QuestEN[65287] = { title = "Separating the Yolk", description = "I've deciphered the scroll and, surprise, it's bad news!\n\nThe Screechflight aren't just eating the bluefeathers for sustenance. Turns out they've found a spell or two that transfers the rocs' innate strength to themselves upon consumption. Especially the eggs!\n\nSave as many of those roc eggs as you can down the cliffs from here. It'll stall the harpies long enough to put my plan into motion.\n\nAnd watch out for rogue elementals. The Cursewives' spell work has stirred them up!", objectives = "Collect 20 Bluefeather Eggs.", progress = "Saving these eggs from the harpies is key to protecting these Bluefeathers from any further endangerment. As well as any future prey they plan on consuming next.", completion = "This is more than I imagined you'd be able to recover!\n\nMaybe you're not a bad sort after all. Not that I was thinking that or anything!" }
WordHunterWoW_QuestEN[65297] = { title = "Penance and Renewal", description = "When I became the new Arbiter, I vowed to myself that I would listen to those around me, to take their counsel into consideration before passing eternal judgment.\n\nI have an inkling of what Tyrande intends for Sylvanas. Her fury is tempered by wisdom, and I trust in the decision she has made.\n\nMeet her in the Ring of Transference and see her judgment come to pass.", objectives = "Speak to Tyrande at the Ring of Transference in Oribos.", completion = "Justice for Teldrassil. Peace for the kaldorei." }
WordHunterWoW_QuestEN[65302] = { title = "Keys to the Kingdom", description = "Need weapons for plan. Have good weapons, but locked up. Gnolls leave key in camp--protect weapon cache.\n\nGet pointiest sticks. They have most blood stains.", objectives = "Collect the key and use it to open the weapon cache.", progress = "You bring weapons yet or you want me eat you?", completion = "Always wanted power stick!\n\nMON-ARK PROVIDES!" }
WordHunterWoW_QuestEN[65304] = { title = "Frostwing's Fate", description = "", objectives = "" }
WordHunterWoW_QuestEN[65305] = { title = "The Way Forward", description = "I see you have a new friend, Maw Walker!\n\nWith Pocopoc at your side, I wonder what else you will discover about Zereth Mortis? The secrets we uncover here will be of great help against the Jailer. Perhaps they can teach us how to awaken this oracle.\n\nHighlord Bolvar will surely want to hear of them.\n\nPlease go to Haven and inform him. There is a transporter just outside the cave you may want to use. \n\nI will remain here and keep watch over the oracle.", objectives = "Return to Highlord Bolvar Fordragon in Haven.", completion = "You have returned, Maw Walker. What news do you have for me?" }
WordHunterWoW_QuestEN[65306] = { title = "Rot Rancher", description = "Decay gross, smelly, and painful. Have idea but need ooze. GET OOZE!", objectives = "Collect 20 Smelly Ooze from the decaying rot.", progress = "NEED MORE OOZE!", completion = "Squishy toe junk. Very nice." }
WordHunterWoW_QuestEN[65307] = { title = "Mercy First", description = "The toxicity in the creche nearly claimed us all. While the antidote is being prepared, I need you to seek out the wounded and heal them. \n\nYes, even the blue drakonid. The Healing Wings do not stand idly by while others suffer.", objectives = "Heal injured dracthyr and drakonid.", progress = "The toxins flooding the creche could not penetrate the stasis magic, but it engulfed us when we awakened.", completion = "Violence is not the only avenue to victory." }
WordHunterWoW_QuestEN[65313] = { title = "A Roc-ing Appetite", description = "Segallia seems like a good egg, good with gadgets, but she panics easily.\n\nFor example: When I sent her into the caves directly south of here, she was promptly run out of them by an unusually large harpy. Seems it was giving orders to the others as well.\n\nCould it be the matriarch of this brood? Perhaps a commander of some kind? Get in there and find out, {name}.\n\nAnd don't be afraid to ruffle a few feathers, if you know what I mean.", objectives = "Slay Hawthia Roc-Muncher.", completion = "My fine-tuned bird senses are telling me these Screechflight aren't just here for snacks...\n\nBut you did well, <name>! Let me decipher this scroll and we'll find out just what these harpies are after." }
WordHunterWoW_QuestEN[65324] = { title = "Patterns Within Patterns", description = "We stand at the origin of the Shadowlands. We must not allow this place to become its undoing.\n\nWork with our new allies, <name>. Their assistance will be the difference between our success and the unmaking of all things.", objectives = "Assist your allies in Zereth Mortis by completing World Quests, Daily Quests, looting treasures, and slaying rare creatures.", progress = "In this place, all fates are intertwined.", completion = "We move closer to our goal. Ever onward." }
WordHunterWoW_QuestEN[65325] = { title = "Motes of Knowledge", description = "The creatures of Untamed Verdure are ingesting everything in sight. They have consumed our Compilation Nodule, and the Composition Motes needed for compilation. We Jiro require these resources.\n\nThis area is too hazardous for unprotected Jiro operation.\n\nPlease help us reclaim our resources. Mai Obet will assist you.", objectives = "1 Compilation Nodule and 10 Composition Motes recovered.", progress = "Have you recovered our resources?", completion = "You have recovered our resources. Your assistance is appreciated." }
WordHunterWoW_QuestEN[65326] = { title = "Circle of Strife", description = "Automa need assistance to operate properly. We fulfill this purpose, but outsiders have caused too many interruptions. We cannot properly address them all. \n\nPlease assist Mai Obet in inspecting and reviewing the performance of the automa.", objectives = "Inspect 10 Automa Constructors in Provis Flora.", progress = "Do the automa meet expectations?", completion = "The automa are functioning properly. Thank you for your assistance." }
WordHunterWoW_QuestEN[65327] = { title = "Schematic Reassimilation: Ambystan Darter", description = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", objectives = "Present the schematic to an appropriate protoform forge.\n\nProvided item:", completion = "<The protoform forge chimes a melancholy song as it draws in the schematic.>" }
WordHunterWoW_QuestEN[65328] = { title = "Arbiter in the Making", description = "Maw Walker, I ... I do not know what to say. I did not expect this.\n\nShe speaks of preparations and a new Arbiter. We must tell our friends in Haven.", objectives = "Go to Haven and deliver the news that Saezurah seeks a new Arbiter.", progress = "Everyone will want to know that we are going to make a new Arbiter.", completion = "An Arbiter? I had not imagined we could set that to rights." }
WordHunterWoW_QuestEN[65329] = { title = "Safe Haven", description = "Let us return to Zereth Mortis. You should report back to Bolvar and tell him of what we have accomplished. We may have achieved this victory, but there is still much to be done.", objectives = "Report back to Bolvar in Haven.", completion = "A new Arbiter has been established? This is excellent news, <name>, and a massive step towards restoring balance to the Shadowlands. Your efforts here will not be forgotten. \n\nHowever, it is still only one step towards our goal. We must continue to strengthen our position in Zereth Mortis, and drive the Jailer's forces out. \n\nOur work continues--but with you on our side, victory is that much closer. Thank you." }
WordHunterWoW_QuestEN[65331] = { title = "Herbal Remedies", description = "Using the roots you collected, I have crafted a concoction that, in theory, will cause the plants to revert to their natural state.\n\nHurl vials of this remedy at the lashers of the Catalyst Gardens.\n\nIf it works, wonderful! If not, you will need to deal with them more directly, by killing them.", objectives = "Kill 30 Sentient Overgrowth and 6 Carnivorous Overgrowth.", completion = "A quasi-successful test run, but a success nonetheless." }
WordHunterWoW_QuestEN[65332] = { title = "Schematic Reassimilation: Fierce Scarabid", description = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", objectives = "Present the schematic to an appropriate protoform forge.\n\nProvided item:", completion = "<The protoform forge chimes a melancholy song as it draws in the schematic.>" }
WordHunterWoW_QuestEN[65333] = { title = "Schematic Reassimilation: Multichicken", description = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", objectives = "Present the schematic to an appropriate protoform forge.\n\nProvided item:", completion = "<The protoform forge chimes a melancholy song as it draws in the schematic.>" }
