WordHunterWoW_QuestEN[65362] = { title = "Not of the Body", description = "Enemies of Zereth Mortis wear the guise of productive automa. They do not complete any desired tasks.\n\nScan the automa to reveal enemy threats, then eliminate them.\n\nMai Obet shall assist.", objectives = "6 Dreadlord Infiltrators slain", completion = "You have exceeded expectations. Thank you for your assistance." }
WordHunterWoW_QuestEN[65363] = { title = "Dangerous State", description = "Enemies have attacked the jiro and severed them from the circle. The jiro are no longer stable. They are a danger to the order of things.\n\nThey must be removed.", objectives = "Leashkeeper Helzid and 12 Dominated Jiro slain", progress = "Have you removed the threat?", completion = "Order has been restored. Thank you for your assistance." }
WordHunterWoW_QuestEN[65364] = { title = "Super Jiro", description = "The outsiders have disrupted the tasks and purpose of the jiro. We cannot allow this to continue.\n\nWe will empower a larger jiro to help combat these threats. Jiro Prime will destroy the enemies that threaten Zereth Mortis.\n\nHelp direct Jiro Prime to resolve our crisis.", objectives = "Direct Jiro Prime to rescue 7 Distressed Jiro, while slaying 5 Mawbroken Automa and 100 Mawsworn forces.", progress = "Have the threats been eliminated?", completion = "Order has been restored. We thank you for your assistance." }
WordHunterWoW_QuestEN[65370] = { title = "Gut Check", description = "The crescendal is a powerful tool created by automa. They are given to jiro when work is hard or important. When the devourers attacked, crescendals were likely... eaten.\n\nCrescendals are strong. They do not easily damage. Check the stomachs of bigger devourers. Perhaps find one intact?", objectives = "Collect a Crescendal from an Insatiable Breaker or a Voracious Stalker at the Terrace of Formation.", progress = "We have very few crescendals. It is important to recover one.", completion = "<The jiro looks over the guts-spattered device.>\n\nNot ideal. But mostly intact... it will need cleaning." }
WordHunterWoW_QuestEN[65371] = { title = "A Nest of Our Own", description = "The scroll you found is a command that all bluefeather eggs are to be brought to the harpy chef, Fry-Aerie. Apparently, the Screechflight's matriarch won't eat anything that hasn't been properly prepared and seasoned.\n\nSo we'll bring her a special egg of our own. One that's EXPLOSIVELY delicious... and will explode when she eats it. Of course.\n\nHow will you deliver it? In disguise!\n\nSlay the creatures on the lower cliffs, collect up this list of parts, and I'll whip you up a full-feathered outfit.", objectives = "Collect 20 Screechflight Talons, 6 Screechflight Staves, and 3 Creekborne Cores.", progress = "Got everything I asked for yet?", completion = "Perfect! And a little gross. Just as I planned.\n\nTime to craft a disguise and take this matriarch out to roost!" }
WordHunterWoW_QuestEN[65373] = { title = "Plucking Parts", description = "Oh, no... I've made a huge mistake.\n\nHarleen entrusted me with the famed Feather-Plucker 3300, a phenomenal invention of her very own!\n\nI was planning to pluck roc feathers in the cave south of here for her research, but the harpies ambushed me and it broke into pieces as I was running out.\n\nPlease retrieve the parts! They're probably strewn about like shed scales on the cave floor.\n\nI can put it back together. Definitely. Well, probably.", objectives = "Retrieve the 4 Feather-Plucker 3300 parts.", progress = "I was so desperate to prove myself!", completion = "Oh, thank the flights!\n\nI've come to like the professor, and this could have spelled the end of our new friendship!" }
WordHunterWoW_QuestEN[65374] = { title = "It's Plucking Time", description = "Harleen told me she's making a disguise for you! How exciting! But she'll need some feathers from the roc hatchlings to complete the outfit.\n\nLuckily, I've just finished fixing up the Feather-Plucker 3300!\n\nThe Screechflight are capturing roc hatchlings on the lower cliffs to raise and breed for themselves. Use the Plucker to yank the hatchlings out of danger. It'll automatically pluck some of their feathers for you as well!\n\nTwo birds with one Plucker? I should say so!", objectives = "Pluck 6 Hatchling Feathers.", progress = "Professor Chirpsnide tells me that I've got a knack for gadgets! If I wasn't part of the Dracthyr military, do you think I could've worked in a Goblin city?", completion = "This is more than enough feathers! And all collected without the Feather-Plucker exploding... right?" }
WordHunterWoW_QuestEN[65375] = { title = "Schematic Reassimilation: Pale Regal Cervid", description = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>\n\n<The Enlightened of Pilgrim's Grace likely know where such a forge can be found.>", objectives = "Present the schematic to an appropriate protoform forge.\n\nProvided item:", completion = "Excellent. With this schematic and the right components, a new song can begin here to accompany you." }
