WordHunterWoW_QuestEN[65419] = { title = "Protoform Synthesis", description = "<Pocopoc jumps around anxiously. When you completed your research into the basics of Dealic, it got very excited and it is urging you to follow it somewhere else in this realm.>", objectives = "Escort Pocopoc to the Protoform Synthesis Forge.", progress = "<Pocopoc looks between you and the console excitedly.>", completion = "<Pocopoc points to some controls on this device, and you understand just enough Dealic to glimpse its purpose in bringing you here. With some materials found across Zereth Mortis and Pocopoc's help, you can trigger this machine to create fully realized beings based on specific schematics.>" }
WordHunterWoW_QuestEN[65420] = { title = "Judgment Call", description = "Oh no... No no no... What have I done?\n\nThe elders will never take me back. They shall cast me out as they did Firim.\n\nPlease, outsider, speak to Elder Amir in Pilgrim's Grace. Give him my thanks for sending you, and tell him all that has happened here. He will understand why I must never return.", objectives = "Speak to Elder Amir in Pilgrim's Grace.", completion = "Tahli is alive? And you preserved an automa archive with her help?! Oh, my. That is... a lot to take in.\n\nAnd, of course, her guilt has prevented her from returning home. Oh, Tahli." }
WordHunterWoW_QuestEN[65421] = { title = "Climb Every Mountain", description = "Hope ye are a quick study, {class}. 'Cause I got no time for a lesson! \n\nGrab a pack and find a path tae the top o' that peak.\n\nOnce yer up there, toss this parachute to our pal Yips. Poor kid got stuck on some vines when these air elementals crashed our plane!\n\nQuickly now, so we can get outta here!", objectives = "Grab the Climbing Gear, find a handhold, and climb up the cliff to rescue Pathfinder Yips!", progress = "Hurry on, now! Yips can't hold fer long!", completion = "Nice climbing! Yips owes ye a drink or two!\n\nOh, the elementals? Nah, don't worry 'bout 'em. This is OUR adventure!\n\n<Rocky resumes gleefully shooting bullets through the air elementals.>" }
WordHunterWoW_QuestEN[65422] = { title = "Treasure Hunting Ain't Easy", description = "I can see it yer eyes: Ye got the urge to climb to the top of this here mountain and find out what's on the top!\n\nUs climbers always recognize each other. We won't let any mountain make us feel small, right?\n\nWell, good fer ye I brought plenty of climbing gear. Grab a pack and find a path to the top!", objectives = "Grab the Rock Climbing Gear, then find a handhold and climb to the top of the mountain without losing your grip!I can see it yer eyes: Ye got the urge to climb to the top of this here mountain and find out what's on the top!\n\nUs climbers always recognize each other. We won't let any mountain make us feel small, right?\n\nWell, good fer ye I brought plenty of climbing gear. Grab a pack and find a path to the top!" }
WordHunterWoW_QuestEN[65424] = { title = "Whatever You Sayaad", description = "As my master, you should know - I'm fairly flexible when it comes to... matching preferences. \n\n<The demon gestures to themselves.>\n\nIf you're not a fan of this, then I could always just stick to a singular appearance that I have that will haunt your dreams. One of your mentors should be able to teach you how to adjust your summoning ritual.\n\nOf course, if you want to leave it up to me... Well, I can guarantee a good time either way.", objectives = "Speak with Kazak Darkscream in Orgrimmar about adjusting your Summon Succubus spell.", completion = "An interesting proposal... One I may need to try out myself.\n\nSpeak with me whenever you wish to adjust your summoning ritual. I believe I know what they were referring to." }
WordHunterWoW_QuestEN[65425] = { title = "Whatever You Sayaad", description = "As my master, you should know - I'm fairly flexible when it comes to... matching preferences. \n\n<The demon gestures to themselves.>\n\nIf you're not a fan of this, then I could always just stick to a singular appearance that I have that will haunt your dreams. One of your mentors should be able to teach you how to adjust your summoning ritual.\n\nOf course, if you want to leave it up to me... Well, I can guarantee a good time either way.", objectives = "Speak with Evelyn Thorn in Stormwind about adjusting your Summon Succubus spell.", completion = "What a curious concept. I had no idea that Succubi were capable of such a thing.\n\nSpeak with me whenever you wish to adjust your summoning ritual. I believe I know what they were referring to." }
WordHunterWoW_QuestEN[65426] = { title = "The Lost Component", description = "Maw Walker! Look.\n\nWe have been studying this automa component for some time. Its cyphers are similar to those of the components near and within the Protoform Repository.\n\nKodah's last effort should not be in vain. Please return this component to the repository that our friend restored.", objectives = "Pick up the Protoform Catalyst and return it to the Protoform Repository.", progress = "The mortal seeks protoform synthesis.", completion = "Greetings, Architect." }
WordHunterWoW_QuestEN[65427] = { title = "A New Architect", description = "The architects prototype designs to fulfill the purposes of the First Ones. \n\nThis archive contained many such designs.\n\nA number of design entries are lost or corrupted due to the Maw invasion. \n\nAn untouched design lattice and tools are detected nearby. The mortal will retrieve them to begin the synthesis process.", objectives = "Collect 1 Cervid Lattice and 3 Protoform Tools and bring them to the Servitor Interface in the Protoform Repository.", progress = "Have the necessary materials been located?", completion = "Success. \n\nThe Protoform Repository is now restored." }
WordHunterWoW_QuestEN[65431] = { title = "Further Research: Aealic", description = "Maw Walker, you have made some wondrous discoveries, but there are still secrets to uncover.\n\nYou have taken the first step, in unlocking the console and I believe that you are ready to take another.\n\nPlease go investigate the console and see what new piece of the pattern unfolds itself to you.", objectives = "Investigate the Cypher Console in Exile's Hollow further.", progress = "Go see what secrets await you!", completion = "New knowledge! The First Ones truly did leave such marvelous insights." }
WordHunterWoW_QuestEN[65432] = { title = "Further Research: Dealic", description = "<The console hums with a mysterious energy.>", objectives = "Further investigate the Cypher Console in Exile's Hollow.", progress = "<Further investigation may be required.>", completion = "<A strange energy surrounds the console.>" }
WordHunterWoW_QuestEN[65433] = { title = "Further Research: Trebalim", description = "<The console hums with a mysterious energy.>", objectives = "Further investigate the Cypher Console in Exile's Hollow.", progress = "<Further investigation may be required.>", completion = "<A strange energy surrounds the console.>" }
WordHunterWoW_QuestEN[65435] = { title = "The Dragon Isles Await", description = "Heroes of the Horde, I bring news. The Dragon Isles are awakening!\n\nThe Isles went dormant in the wake of the Sundering. But now, at long last, they have called my kin and me  home.\n\nWhile the Isles hold many wonders, it is also a perilous land. We will require the aid of our mortal allies to reclaim our legacy.\n\nI am about to present the Aspects' invitation to the Horde Council in Orgrimmar. Meet me there and we shall see what they have to say.", objectives = "Meet Ebyssian in Orgrimmar.", completion = "I am grateful you have answered the call. Your courage will be welcome on the journey ahead." }
WordHunterWoW_QuestEN[65436] = { title = "The Dragon Isles Await", description = "Wondrous news, my friend! The Dragon Isles are awakening!\n\nMy people left our lands dormant in the wake of the Sundering. But now, at long last, we feel the call to home.\n\nWhile the Isles hold many wonders, there are perils as well. We will require the aid of our mortal allies in order to reclaim our legacy.\n\nMeet me in Stormwind. I must present the Aspects' invitation to the Alliance.", objectives = "Meet Wrathion in Stormwind.", completion = "The Aspects' invitation extends to you as well, friend." }
WordHunterWoW_QuestEN[65437] = { title = "Aspectral Invitation", description = "Your arrival is well timed, {name}.\n\nI have just met with the Horde Council, and they have accepted the Aspects' invitation to the Dragon Isles.\n\nThe same invitation extends to you, as well.\n\nYou may also notice some unfamiliar faces here in Orgrimmar. The dracthyr are new arrivals you will learn about on the journey ahead.\n\nLet us speak more.", objectives = "Speak with Ebyssian.", completion = "I am honored that you will journey to the homeland of dragonkind.\n\nOne of your allies is eager to assist you in preparing for what lies ahead." }
WordHunterWoW_QuestEN[65438] = { title = "Awesome Quest Start", description = "The start of the Azure Span.", objectives = "" }
WordHunterWoW_QuestEN[65439] = { title = "Whispers on the Winds", description = "Hello, {name}. It's been a while, and I wish we had more time to catch up.\n\nBut you see, I've just had a rather enlightening... no, make that foreboding... yes, a foreboding conversation with an old friend.\n\nSometimes a revelation can be both, after all.\n\nI really must tell you of what I've learned.", objectives = "Speak with Archmage Khadgar outside Orgrimmar.", progress = "Our journey begins with you.", completion = "Unsettling news indeed, but you had to know of the peril we face." }
WordHunterWoW_QuestEN[65443] = { title = "Expeditionary Coordination", description = "Pleasure to meet you, I am Naleidea Rivergleam.\n\nThe invitation to visit the Dragon Isles is quite an exciting prospect. Don't you agree?\n\nThe Reliquary has combined forces with our expeditionary counterparts to help coordinate our efforts. As a member of the Dragonscale Expedition, it is my honor to welcome you.\n\nThough first we must gather a few more members for our journey. Shall we begin?", objectives = "Recruit explorers, artisans, and scholars throughout Orgrimmar for the expedition to the Dragon Isles.", progress = "Have you spoken with the others yet?", completion = "I believe this expedition shall be a great success." }
WordHunterWoW_QuestEN[65444] = { title = "To the Dragon Isles!", description = "Our preliminary expedition has made landfall in the Dragon Isles.\n\nThanks to the efforts of those brave Dragonscale Expedition members, we've established a protected landing site in the Dragon Isles and made contact with the dragonflight's embassy.\n\nAre you prepared to accompany us on our next voyage to the Dragon Isles?", objectives = "Ride the Defiant Dragonscale to the Dragon Isles from the zeppelin tower outside Orgrimmar.", completion = "Welcome to the Dragon Isles!" }
WordHunterWoW_QuestEN[65445] = { title = "Necessary Resourcing", description = "Devourers are consuming neomotes.\n\nWe need neomotes for necessary creation work. Without them, we are unable to complete our work.\n\nEliminate the devourers and retrieve the neomotes.", objectives = "Obtain 30 Neomote Residue and 3 Solidified Neomotes from Devourers in Zereth Mortis.", progress = "Have you collected the neomotes?", completion = "You have completed the task. Thank you for your assistance." }
WordHunterWoW_QuestEN[65448] = { title = "A Return to Grace", description = "<With the temple restored and its defenses back online, the Wellspring should be safe from the devourers. Conservator Olem will want to know what you've done here.>", objectives = "Speak to Conservator Olem and give him the good news.", progress = "You return--and as I expected, you were successful.", completion = "As I thought--your arrival was by the design of the First Ones. I look forward to the legacy you forge in this land of our creators." }
WordHunterWoW_QuestEN[65451] = { title = "Practice Materials", description = "These proto-drakes are unlike any I've seen before on Azeroth.\n\nTheir scales appear to be naturally flame-resistant, stronger than steel, and don't lose flexibility in the process. Incredible. \n\nMy artisans--all of them--are clamoring to get their hands on some of those scales to work with.\n\nStart with the whelps. The smaller scales should be more pliable until we've mastered our techniques with them.", objectives = "Collect 20 Primal Proto-Whelp Scales.", progress = "Have you got the scales yet? The alchemists are getting antsy, and that always makes me nervous.", completion = "<Boss Magor carefully studies the scales.>\n\nOur artisans will put these to good use. Thank you." }
WordHunterWoW_QuestEN[65452] = { title = "Explorers in Peril", description = "Don't mistake the expedition's scholarly pursuits as timidness, {name}.\n\nWe are not recluses studying books in far-off towers.\n\nWe are adventurers, hunting down knowledge first-hand in every corner of Azeroth!\n\nThat passion for adventure often leads us onto the path of perils and hazards, and a few expedition members have bitten off a little more than they could chew...", objectives = "Rescue 3 Dragonscale Expedition members in the Wild Coast.", progress = "Are the expedition members safe?", completion = "The dragons are not here to meet us as Ebyssian said they would be..." }
WordHunterWoW_QuestEN[65453] = { title = "Primal Pests", description = "<Cindrethresh glances suspiciously at the proto-dragons lurking on the ridge behind her.>\n\nI'd swear that those proto-dragons edge closer to camp every time I turn my back...\n\nThose are not the dragons Ebyssian invited us here to meet.\n\nProto-dragons are ruthless predators who cannot be reasoned with. We must be ruthless in return.\n\nCull their numbers to keep their ambitions in check, or this expedition will be over before it begins.", objectives = "Kill 8 Primal Proto-drakes on the Wild Coast.", progress = "Always keep an eye on the skies.", completion = "That may dissuade them from attacking the expedition camps for a time.\n\nIt's eat or be eaten in the Dragon Isles, <name>. You'd do well to remember that." }
WordHunterWoW_QuestEN[65456] = { title = "Long Lost Firim", description = "I was gathering data here when your portal opened. The disruption activated these gate-locking mechanisms. \n\nIt is only fair for you to gather the gate keys, yes? We shall speak while you search.", objectives = "Help Firim open the gate into Zereth Mortis.", progress = "And now, onward.", completion = "You are stronger and more patient than you look." }
WordHunterWoW_QuestEN[65460] = { title = "Your First Cantaric Protolock", description = "Maw Walker, it appears that Pocopoc has learned the Cachial skill. This grants you access to the Caches of Creation. You will find several types of these caches all throughout Zereth Mortis.\n\nIn order to aid me with my research, you will need to be able to decode various cyphers such as the Cantaric Protolock. \n\nNow, let me show you what you need to do to assist me.", objectives = "Complete the Cantaric Protolock.", progress = "Good, now take your expanded knowledge out into the field.", completion = "Well done, Maw Walker.\n\nI am sure that with enough energy and effort your companion will be able to help you overcome these challenges, if they become a struggle for you." }
WordHunterWoW_QuestEN[65461] = { title = "Your First Mezzonic Protolock", description = "In order to aid me in my research, you will need to decode various Progenitor cyphers like the Mezzonic Protolock.  Now, I will show you what you need to do.", objectives = "Complete the Mezzonic Protolock.", progress = "Use this knowledge to collect more data from the field.", completion = "Use this knowledge and collect more data from the field, Maw Walker.\n\nThere is still one more Cache of Creation that I must instruct you on." }
WordHunterWoW_QuestEN[65463] = { title = "The Wellspring of the First Ones", description = "A mortal, here? How unusual! Welcome to Pilgrim's Grace. Would that you had arrived under better circumstances. Pilgrims usually travel here to visit the sacred Wellspring of the First Ones. \n\nUnfortunately, the wellspring has gone dry. I do not understand it. The creations of the First Ones should be infallible! \n\nThis situation is as unusual as your arrival--perhaps you can lend your aid? Travel to the wellspring and speak to Conservator Olem.", objectives = "Speak to Conservator Olem about the Wellspring's problem.", completion = "A mortal, here? The designs of the First Ones are mysterious." }
WordHunterWoW_QuestEN[65466] = { title = "Your First Fugueal Protolock", description = "In order to aid my research you will need to decode various Progenitor cyphers like the Fugueal Protolock. This is a most difficult cypher, I will show you what you need to do.", objectives = "Complete the Fugueal Protolock.", progress = "Use this knowledge and collect more data from the field.", completion = "Well done, Maw Walker. That was truly an impressive effort.\n\nRemember, that if you do struggle with these protolocks, your companion can help you overcome them if they have enough energy.\n\nNow take your expanded knowledge out into the field." }
WordHunterWoW_QuestEN[65467] = { title = "Turkey Soul", description = "<The Turkey Soul is bold and fierce. The shape of the turkey will be yours to call upon.>", objectives = "Bring the Turkey Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a turkey! You can gobble like one now, too!" }
WordHunterWoW_QuestEN[65475] = { title = "Rolling in the Screech", description = "<You pull a scrap of parchment from the gooey, blood-soaked satchel of the Roc-Muncher. All you can make out is imagery of harpies devouring large eggs.\n\nYou're positive the thick, unintelligible scratch marks will make plenty of sense to your favorite senior ornithologist, Harleen Chirpsnide.>", objectives = "Bring the Screechflight Scroll to Harleen Chirpsnide in the Bluefeather Cliffs.", progress = "Back from the caves already?", completion = "Ho, now! That's certainly no dinner menu you're holding!\n\nOr maybe it is..." }
WordHunterWoW_QuestEN[65486] = { title = "Picture Perfect", description = "Sorry if ya be waitin' long. Sometimes I get lost in de telescope.\n\nDo ya ever find da world be easier understood from a distance? No interference, just nature goin' about its business without us...\n\n<Akunda the Cataloger sighs.>\n\nI see Coralie gave ya a camera. Good.\n\nTake a ride down the river with Fren, and take photographs of some wildlife in dey natural habitats for me to study.", objectives = "Ride the Cataloger's Raft with Fren and take pictures of local wildlife.", progress = "Fren will row the raft for ya. Don't worry, she's da very best!", completion = "<Akunda flips through the photographs quickly, intently analyzing each one.>\n\nRe-mark-a-ble! Surprisin' too. I've much to learn from these; so many new specimens to document!\n\nThank you, <name>!" }
WordHunterWoW_QuestEN[65490] = { title = "Explosive Excrement", description = "The harpies are a nice surprise and all, but I came to these mountains for one reason and one reason only: EXCREMENT!\n\nSpecifically, the excrement of bluefeather rocs that's then been eaten and digested by bugs. Scarab stomach juices enhance the explosive nitrogen content by tenfold! At least!\n\nHere, take this Chirpsnide Auto-Excre-Collector. Stomp on the scarabs crawling around the cave floor, and use the Collector to reap the rewards.\n\nBring it back full and we can start the real fun: EXPLOSIONS!!", objectives = "Fill Professor Chirpsnide's Auto-Excre-Collector.", completion = "Oh, yes! Quality stuff!!\n\nHave you thought about doing this work professionally, <name>?" }
WordHunterWoW_QuestEN[65504] = { title = "Dragonhawk Soul", description = "<The Dragonhawk Soul is nimble and resilient. The shape of the dragonhawk will be yours to call upon.>", objectives = "Bring the Dragonhawk Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the dragonhawk. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65505] = { title = "Scorpid Soul", description = "<The Scorpid Soul is fierce and voracious. The shape of the scorpid will be yours to call upon.>", objectives = "Bring the Scorpid Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the scorpid. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65506] = { title = "Ray Soul", description = "<The Ray Soul is clever and swift. The shape of the ray will be yours to call upon.>", objectives = "Bring the Ray Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the ray. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65507] = { title = "Elekk Soul", description = "<The Elekk Soul is clever and mighty. The shape of the elekk will be yours to call upon.>", objectives = "Bring the Elekk Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the elekk. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65508] = { title = "Tallstrider Soul", description = "<The Tallstrider Soul is agile and curious. The shape of the tallstrider will be yours to call upon.>", objectives = "Bring the Tallstrider Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the tallstrider. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65509] = { title = "Bat Soul", description = "<The Bat Soul is cunning and swift. The shape of the bat will be yours to call upon.>", objectives = "Bring the Bat Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the bat. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65510] = { title = "Brutosaur Soul", description = "<The Brutosaur Soul is loyal and valiant. The shape of the brutosaur will be yours to call upon.>", objectives = "Bring the Brutosaur Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the brutosaur. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65512] = { title = "Silithid Soul", description = "<The Silithid Soul is brutal and quick. The shape of the silithid will be yours to call upon.>", objectives = "Bring the Silithid Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the silithid. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65513] = { title = "Gromit Soul", description = "<The Gromit Soul is exuberant and inquisitive. The shape of the gromit will be yours to call upon.>", objectives = "Bring the Gromit Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a gromit! They pounce about with such joy!" }
WordHunterWoW_QuestEN[65514] = { title = "Armadillo Soul", description = "<The Armadillo Soul is cautious and resilient. The shape of the armadillo will be yours to call upon.>", objectives = "Bring the Armadillo Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, an armadillo! They're so well-protected!" }
WordHunterWoW_QuestEN[65515] = { title = "Pig Soul", description = "<The Pig Soul is curious and tenacious. The shape of the pig will be yours to call upon.>", objectives = "Bring the Pig Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a pig! Now you can oink like one too!" }
WordHunterWoW_QuestEN[65516] = { title = "Sheep Soul", description = "<The Sheep Soul is calm and stalwart. The shape of the sheep will be yours to call upon.>", objectives = "Bring the Sheep Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a sheep! They're so cute and cuddly!" }
WordHunterWoW_QuestEN[65517] = { title = "Penguin Soul", description = "<The Penguin Soul is playful and sociable. The shape of the penguin will be yours to call upon.>", objectives = "Bring the Penguin Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a penguin! Now you can slide like one too!" }
WordHunterWoW_QuestEN[65518] = { title = "Bee Soul", description = "<The Bee Soul is protective and spry. The shape of the bee will be yours to call upon.>", objectives = "Bring the Bee Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a bee! Now you can buzz like one too!" }
WordHunterWoW_QuestEN[65519] = { title = "Snail Soul", description = "<The Snail Soul is cautious and patient. The shape of the snail will be yours to call upon.>", objectives = "Bring the Snail Soul to Choofa in the Heart of the Forest.\n\nProvided item:", completion = "Ooh, a snail! Now you can crawl like one too!" }
WordHunterWoW_QuestEN[65563] = { title = "Delivery for Kasea", description = "Hope ye don't mind, but I used some of your materials to craft something Kasea has been asking me for.\n\nWould you mind bringin' it over to her?", objectives = "Deliver the Bladed Helmet to Kasea Angerforge.", completion = "Thurgaden finally made it, did he? And sent it with just the right person!" }
WordHunterWoW_QuestEN[65564] = { title = "Good Fiery Boy", description = "I train hounds of all types, 'long as they're fiery. I've trained up Grimhowl here since he was a wee pup, but a life in Shadowforge City isn't what he's meant ta live!\n\nGrimhowl needs that special someone to bond with, someone who'll take him 'round all of Azeroth. Perhaps that could be you?\n\nTake some time to get to know him. I think Grimhowl will warm up to ye real quick!", objectives = "Bond with Grimhowl.", progress = "If ye bond with this beastie, you'll have a loyal companion for life!", completion = "They like ye, they really like ye! Treat this pup with love and they will be your adventuring partner for years to come." }
WordHunterWoW_QuestEN[65594] = { title = "Making a Mountain Out of a Gnoll Hill", description = "Stupid decay thinks it in charge, but me in charge. We kill it now. Me turned ooze into friends.", objectives = "Destroy 3 Decay Totems.", progress = "IT'S SO BOUNCY!", completion = "You live this long? Good meat." }
WordHunterWoW_QuestEN[65595] = { title = "One Bad Apple", description = "Rot starve gnolls.\n\nRot hurt friends.\n\nWe kill rot now. Is what Mon-Arks do.", objectives = "Kill the Root of Decay.", completion = "Me lead gnolls to better hunt now. You... not so bad. Gnolls hungry though, and you still meat.\n\nLeave. Me no chase." }
WordHunterWoW_QuestEN[65598] = { title = "Adore Elune", description = "A temple to Elune!\n\nOh, I cannot give up an opportunity to visit my dear queen's sister in one of her holy abodes! Why, she's practically an aunt to us fae!\n\nNow that the two are on better terms, it is a fine time to visit and see how they do things here!", objectives = "" }
WordHunterWoW_QuestEN[65606] = { title = "Renowned with the Maruuk", description = "Your deeds to further the interests of the clan have not gone unnoticed. \n\nReturn to Maruukai, I have prepared some supplies to further assist you in your work with us.", objectives = "Speak with Agari at Maruukai.", completion = "You honor us with your deeds, I will tell the elders of your work. Take these supplies, may they aid you in the hunt!" }
WordHunterWoW_QuestEN[65608] = { title = "Muck-Covered Map", description = "<The fragile parchment feels as though it may fall apart at any time. There must be someone who can help understand what information it holds.>", objectives = "" }
WordHunterWoW_QuestEN[65613] = { title = "An Iconic, Draconic Look", description = "I am sure your arrival in Orgrimmar drew the attention of its citizens. No doubt some were more comfortable in your presence than others.\n\nWhen I was a young dragon, I took on the mortal visage you now see. It allowed me to live among the tauren of Highmountain as an ally.\n\nThough your path differs from mine, the essence of dragonkind flows through you as well, {name}. Perhaps that will allow you to assume a visage of your own.\n\nLet us walk together.", objectives = "Adopt a Visage Form.", progress = "Tap into your draconic heritage.", completion = "You have a noble visage indeed, <name>. Most distinctive.\n\nI do not know why your visage is unique from that of a dragon. Perhaps when we learn more of your past, the answer will present itself.\n\nBut for now, we must prepare for the journey ahead." }
WordHunterWoW_QuestEN[65615] = { title = "Arcane Intrusion", description = "That beacon ahead--I am certain it was not there before we were imprisoned.\n\nSpellcraft is not my forte, but I know arcane magic when I see it. The same magic used by the blue dragon in the creche.\n\nHe said a name... Malygos. It sounds so familiar, but the Earth-Warder's teachings feel distant. Fragmented.\n\nIf this Malygos put us into stasis, perhaps the arcane beacon was placed on his orders.\n\nInvestigate the area and report back. Ensure the beacon cannot be used to call in enemy reinforcements.", objectives = "Investigate the beacon.", progress = "There is powerful magic in the air. But it is ancient, fading.", completion = "<Azurathel listens intently as you tell him what you witnessed.>\n\nSo there were beacons placed outside the other creches as well.\n\nOur allies are in peril. We must reach them!" }
WordHunterWoW_QuestEN[65625] = { title = "The Jailer's Gauntlet", description = "Maw Walker! I have been looking for you. \n\nWord is there is a new gathering of the Jailer's forces in Torghast. I'm not sure what they are doing, but it can't be good.\n\nPerhaps you should put an end to their plans?", objectives = "Enter the new portal in the Torghast Lobby." }
WordHunterWoW_QuestEN[65640] = { title = "Cervid Soul", description = "<The Cervid Soul is noble and wise. The shape of the cervid will be yours to call upon.>", objectives = "Bring the Cervid Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", completion = "Ah, the cervid. This shape is now yours to call upon." }
WordHunterWoW_QuestEN[65642] = { title = "Fletch Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[65649] = { title = "A New Deal", description = "Ah, Maw Walker! Opportunities abound now that you have found a way into Zereth Mortis. \n\nLet us discuss further business, yes?\n\nWe have an interest in observing the potential this new pathway has provided. I trust you will procure what we require. Do not let anyone get in your way.\n\nIf this is not agreeable, I am certain I can find someone else to solve both of our problems.", objectives = "Collect 150 Protoplasmic Thread in Zereth Mortis, while in War Mode.", progress = "I trust you are not returning empty-handed, yes?", completion = "Good! You have done well.\n\nHere, a token of our appreciation. Your contributions were well observed." }
WordHunterWoW_QuestEN[65652] = { title = "Summons from the Matriarch", description = "Greetings, {name}.\n\nLet us not mince words--you are urgently needed in Silvermoon. \n\nWe're experiencing a resurgence of Scourge in Quel'Thalas. With nothing to hold the Scourge in check, we'll soon be overrun. We must hold the line!\n\nMeet me in the Hall of Blood, and we will get you a full briefing.", objectives = "Meet Lady Liadrin in Silvermoon.", completion = "Good, you made it.\n\nLet us begin." }
WordHunterWoW_QuestEN[65653] = { title = "Victory for the Sin'dorei", description = "The power of the ranseur has been spent, but we are victorious! With Vorath defeated, perhaps the Scourge will be more easily dealt with--thanks to you.\n\nMeet me back in the Hall of Blood. Silvermoon is grateful for your bravery.", objectives = "Return to Lady Liadrin in Silvermoon City.", completion = "This is not the end of the Scourge, but it is gratifying to drive the threat from our lands with such tenacity.\n\nSilvermoon is grateful for you this day." }
WordHunterWoW_QuestEN[65655] = { title = "Eyes of the Wolf", description = "An alarming rumor has reached me, thanks to our spies.\n\nThe Forsaken are mustering in Tirisfal Glades. For what purpose, I do not know. Notably, Calia Menethil has gone there as well.\n\nWe must know more of what they are up to, now that the accursed Banshee Queen no longer unites them.\n\nGo, don a disguise and see what you can discover. Observe everything. And if there is opportunity to gain their trust and learn more, do as they ask.\n\nI eagerly await your report.", objectives = "Meet Calia Menethil in Brill, Tirisfal Glades.", completion = "<Calia studies you closely for a moment, a smile on her lips.>\n\nYou will fit right in. And do not fear, I will not reveal you to the others here.\n\nBut please understand, many of the Forsaken were once citizens of Lordaeron. They are trying to do something extraordinary here, and I promise, if you play along and help them, it will be worth the effort.\n\nIt will make for a better Azeroth." }
WordHunterWoW_QuestEN[65656] = { title = "Call to Lordaeron", description = "With the Shadowlands healing, it is time to turn our attention to matters close to home again, on Azeroth.\n\nThe Forsaken are mustering in the ruins of the kingdom of Lordaeron. They seek to reclaim as much as they can of the Tirisfal Glades, to finally put the destruction left by the Fourth War behind them.\n\nAnd I intend to assist them in any way I can.\n\nI also know that for the Horde, I have much to prove. Come, join me in Brill and we can help the Forsaken together.", objectives = "Meet Calia Menethil in Brill, Tirisfal Glades.", progress = "We all bear the weight of our history.", completion = "I was always fond of Brill.\n\nMuch remains to be done, but it is heartening to see the progress made in rebuilding here." }
WordHunterWoW_QuestEN[65657] = { title = "Assemble the Forsaken", description = "It's heartening to see progress has been made in rebuilding Brill, but this is only a first step. The ruins of the capital remain inaccessible because of the blight.\n\nAnd here is where I hope you will aid the cause.\n\nRestoring as much of the land as possible will require a gathering of minds all working toward a singular purpose.\n\nA number of influential figures have risen to prominence among the Forsaken. Please help bring them together so we can meet and discuss the path forward.", objectives = "Assemble Dark Ranger Velonara, Lillian Voss, and Master Apothecary Faranell.", progress = "Everyone is working hard to get back on their feet. Might not be the feet they started out with, but they work.", completion = "Looks like we're ready to get started.\n\nI don't think there have been this many Forsaken in one place since... well, Darkshore.\n\nBut we are in our own lands now, and it's time we take care of our own." }
WordHunterWoW_QuestEN[65658] = { title = "This Land is Ours", description = "The plague unleashed during the war has tainted the land and disturbed the dead. That is to say, more so than they already were.\n\nWe have worked hard to rebuild, but our people cannot complete their efforts while under threat.\n\nMy first duty is to ensure the safety of the Forsaken. I will meet with the others as Calia requests, but first you must help me eradicate some of these Blighted.", objectives = "Slay Blighted Soldiers in Tirisfal Glades.", progress = "We need the pressure off of Brill so we can continue to rebuild.", completion = "That should give our guards some breathing room. Metaphorically speaking, of course.\n\nThank you for the help, <name>." }
WordHunterWoW_QuestEN[65659] = { title = "The Blight Congress", description = "We, the Forsaken, have been through a lot since the destruction of Lordaeron. But we're determined to keep our home.\n\nWhy should we give up what we've fought so hard to carve out for ourselves?\n\nCalia is still a relative newcomer in some ways, but obviously she's known to our people. How could she not be, as the sister of Arthas himself?\n\nI hope we can move forward, and that she can really help. Her voice could be a powerful one, if she is really truly committed to the people.", objectives = "Listen to the Forsaken.", completion = "I expected that my presence might cause friction. But I'm grateful to Lilian for her mediation, and for giving me the chance to show that I am committed to helping the Forsaken people.\n\nBut now, I must prove it." }
WordHunterWoW_QuestEN[65660] = { title = "Walk of Faith", description = "I promised that I would help, and I shall. We need that pure sample of the plague afflicting Lordaeron, but we cannot put anyone else at risk.\n\nCome with me. I will call forth a shield of Holy Light to safeguard us deep into the blighted area so that we can collect that sample.\n\nThis spell will require my full focus. I'll trust you to protect us from anything that might try to stop us.\n\nAre you with me?", objectives = "Protect Calia inside her shield and collect the pure plague sample.", progress = "I guess I should have faith.", completion = "That's something you don't see every day." }
WordHunterWoW_QuestEN[65661] = { title = "Consulting Our Allies", description = "I hope Calia is right about these lords of Maldraxxus. That they know how to deal with this sort of powerful plague.\n\nWe've only got one plague eater left, too, but Faranell says he can replicate more of them as long as they're strong enough to survive.\n\nLet's get to the Shadowlands.", objectives = "Speak to Margrave Sin'dane in Maldraxxus.", completion = "You carry a rather nasty example of the unchecked and unfettered ambition of a plague-maker.\n\nI trust the creator of this monstrosity has already been purged. What would you ask of the houses of Maldraxxus?" }
WordHunterWoW_QuestEN[65662] = { title = "House of Plagues", description = "The one with the knowledge you seek is a survivor of the House of Plagues. You already know him.\n\nPlague Deviser Marileth may not be the most lucid of conversationalists, but he will know what to do with your plague.\n\nFind him near the ruins of that fallen house. But be wary! Many things lurking there could end your existence without a hint of concern.", objectives = "Meet Plague Deviser Marileth in the House of Plagues.", completion = "Hello, my favorite apprentice! \n\nSay, you look a tad wan. Are you certain you're getting enough sleep?" }
WordHunterWoW_QuestEN[65663] = { title = "Feed the Eater", description = "The House of Plagues has suffered calamity, much like Lordaeron. I hope that our work and effort here will reverse some of that destruction.\n\nBut first, we must reach farther into the House of Plagues so we can strengthen the capabilities of Faranell's plague eater.\n\nAny slime or creature you slay will surely help it gain fortitude.", objectives = "Slay Slimes and Plaguerocs in the House of Plagues.", progress = "We all have something we can contribute.", completion = "The Plague Eater is looking so much stronger already. I think Master Apothecary Faranell would be pleased." }
WordHunterWoW_QuestEN[65664] = { title = "Essence of Plague", description = "Your little friend there looks hungry! Not to worry, I know just what to feed it. Soon it will grow big and strong and be able to eat all the plague it can.\n\nThere are various concoctions nearby that will give it bolstering properties. And every color is a different flavor!\n\nI will take the plague sample you brought me deeper into the House of Plagues, to see what else we can learn. Meet me there, and let your plague eater dine in style!", objectives = "Absorb different Concoctions in the House of Plagues.", progress = "Every color is a different flavor!", completion = "Did you see that? What a fearsome plague sample you brought me!\n\nIt hit me in the head and quite nearly killed your friends, apprentice. Marvelous!" }
WordHunterWoW_QuestEN[65665] = { title = "Embodiment", description = "What a nasty little plague you've brought me, apprentice. Must've been concocted by a true sadist.\n\nTo study the sample, I gave it form. But the ungrateful thing turned on me and attacked, completely unprovoked! \n\nIt's shuffled a bit further on into the House. I hate to say it, but I believe this one must be put down before it is allowed to grow any stronger... or larger.\n\nLook on the bright side. If your plague eater manages to survive, it'll be attuned to your particularly terrible form of blight.", objectives = "Slay the Lordaeron Blight.", progress = "Have you disposed of that manifestation?", completion = "Despite all the trouble that sample gave us, I think I actually have a little bit of hope now." }
WordHunterWoW_QuestEN[65666] = { title = "Return to Brill", description = "We've strengthened our plague eater, and now it looks ready to take on a much, much bigger meal.\n\nLet's get it back to Faranell. He said he can replicate its properties and disperse plague eaters all across the ruins.\n\nThen maybe, just maybe, we can set foot in our home again.\n\nHere, take my hearthstone. It'll bring you back to Brill.", objectives = "Return to Master Apothecary Faranell outside of the Ruins of Lordaeron.", progress = "What have you brought me?", completion = "Wonderful! Not only did you manage not to lose my plague eater, you brought it back stronger than ever!\n\nNow, witness the genius and rapidity of my machines. There will be more than enough plague eaters to spread across the surface of the Undercity." }
WordHunterWoW_QuestEN[65667] = { title = "The Remedy of Lordaeron", description = "The time has come. By the Light, I pray our plan works.\n\nMaster Apothecary Faranell's wagons have reproduced the plague eater many times over, and the bats are ready to deploy them.\n\nIf you see a place where our forces could spread even more of the remedy, you can signal them with a flare.\n\nTake to the skies, and let's put an end to this blight. For Lordaeron, and for the Forsaken.", objectives = "Mount a Shadowbat and deploy Plague Eaters in the Ruins of Lordaeron.", completion = "We did it. By working together, we've cleared the surface level of the deadly plague cloud.\n\nIt will take more time to clean up the lower reaches of the Undercity, but it's a fine start." }
WordHunterWoW_QuestEN[65668] = { title = "The Desolate Council", description = "By combining our knowledge and expertise, we've restored the surface of the Undercity to the Forsaken.\n\nIt was only possible by setting aside our distrust and acting for the good of our people. Now it's time to make this council official.\n\nWe are no longer the same undead that followed and served Sylvanas Windrunner. From here on, we lead ourselves, with the same spirit of independence and pride we've had since we reclaimed our free will.\n\nIt's time for a new future, with new leadership.", objectives = "Witness the formation of the new Desolate Council.", progress = "Hope, and fresh air, have been restored.", completion = "I am greatly honored that they have accepted me as part of the new leadership of the Forsaken. \n\nI swear that I will do my best to protect and preserve the people, no matter where they come from, or what form of undeath has created them." }
WordHunterWoW_QuestEN[65669] = { title = "Report to Greymane", description = "Thank you for all of your assistance, leading to this historic moment.\n\nI believe there may be others who are interested in what happened here. Please, carry this letter, and my well wishes, when you return to them.", objectives = "Deliver Calia's letter to Genn Greymane in Oribos.", progress = "What happened with the Forsaken?", completion = "They did WHAT?\n\nAnd Calia has proposed a discussion on the return of Gilneas?\n\nYour ability astounds me, <name>. Well done." }
WordHunterWoW_QuestEN[65674] = { title = "What Is This Thing?", description = "<The ambiguous essence in your hands looks as if it could serve a variety of purposes. In fact, it almost seems to radiate possibility.>\n\n<Perhaps Firim may have some answers about this.>", objectives = "Bring the Unformed Essence to Firim in Exile's Hollow.\n\nProvided item:", completion = "Oh, now this is a most interesting find indeed, mortal.\n\nI have encountered such material in my research before. In theory, it can alter the fate of various objects--unlocking their potential, as it were. Curious, no?\n\nI will keep this essence as I have need of it. In exchange, I will share with you the knowledge on how to use similar materials in your own creations." }
WordHunterWoW_QuestEN[65680] = { title = "Schematic Reassimilation: Heartbond Lupine", description = "<This schematic contains the pattern of a new protoform construct. Present it to an appropriate protoform forge and it may instantiate one of these creatures for you.>", objectives = "Present the schematic to an appropriate protoform forge.\n\nProvided item:", completion = "Excellent. With this schematic and the right components, a new song can begin here to accompany you." }
WordHunterWoW_QuestEN[65686] = { title = "To the Azure Span", description = "Greetings, {name}! \n\nPakina and I are here on behalf of the Kirin Tor looking for aid. \n\nThe Kirin Tor are working to safeguard the wild arcane magic located all throughout the Azure Span.\n\nKalecgos, the Aspect of the blue dragonflight and one of our leaders, needs aid in reclaiming the Azure Oathstone there as well.\n\nIf you're willing to help, keep traveling along the road to find Glania of the Blessed Ones.\n\nShe can direct you to where you can help the most.", objectives = "Meet with Glania of the Blessed Ones within the Azure Span.", completion = "Excellent, an adventurer. I can fill you in on the details before I have to learn to... fish." }
WordHunterWoW_QuestEN[65687] = { title = "Punching Up", description = "Some of the other disciples are... very mean.\n\n<Ingot rubs a fresh wound on his snout.>\n\nIt used to not be like that, but when Cygenoth came, he said \"We should value strength above all else\". Now everybody fights all the time.\n\nI try to fight back, but their hides are too thick... and I'm too small.\n\nBut not you! You must fight bullies all the time. Maybe you can help?", objectives = "Slay 12 Worldbreaker Dragonkin.", progress = "The Worldbreakers aren't all bullies. Promise!", completion = "Those snagglescaled clods won't be hurting anyone else! The Earth-Warder thanks you! \n\nOh. And me. I thank you too." }
WordHunterWoW_QuestEN[65688] = { title = "Meeting Kalecgos", description = "I fear we will have to split our attention. The Primalist threat to the east must be handled.\n\nI must ask you travel to the Azure Archives in my stead to aid Kalecgos in reclaiming the Azure Oathstone.\n\nYou'll need to pick up a few supplies to help you with whatever is happening there.\n\nSpeak with our portal quartermaster, they ought to have something that can aid you along the way. \n\nGood luck, {name}. Kalecgos will appreciate the aid.", objectives = "Get the Bag of Helpful Goods, then meet Kalecgos at the base of the Azure Archives.", progress = "I'm relieved to have any help. I know Khadgar and the others must be quite busy with the Primalists.", completion = "Khadgar is wise to redirect his efforts towards the Primalists.\n\nBut now... we've got a lot of work to do here." }
WordHunterWoW_QuestEN[65689] = { title = "The Many Images of Kalecgos", description = "Good to formally meet you, {name}. My name is Kalecgos, Archmage of the Kirin Tor and Aspect of the blue dragonflight.\n\nI'm having difficulty repairing the Azure Archives to reclaim the Azure Oathstone. I could use an extra pair of physical hands.\n\nI'm currently up in the archives themselves. I was able to reactivate the pylon outside, which should allow you to traverse up here.", objectives = "Use the Crystal Pylon to reach the Azure Archives.", progress = "Glad to see you've made it.", completion = "Let's get to work. It's imperative to reclaim the Azure Oathstone." }
WordHunterWoW_QuestEN[65690] = { title = "A Cultist's Misgivings", description = "Another outsider arrived yesterday. She called herself an \"emissary\" for the red dragonflight and asked for an audience with our leader, the Voice of Neltharion. \n\nBut the Voice got terribly mad. He said that the Earth-Warder was testing us, and that we had to execute her!\n\nI know we're not supposed to trust outsiders, but we don't have to kill them! Please, help me save her.", objectives = "Locate Ayasanth in Smoldering Perch.", completion = "This hatchling asked for your help?\n\n<Ayasanth exhales with relief.>\n\nPerhaps we can save the Worldbreakers after all." }
WordHunterWoW_QuestEN[65691] = { title = "The Shadow of His Wings", description = "The Voice of Neltharion resides below, spreading lies amongst his followers. \n\nHe appears to be dragonspawn like me. but his Draconic is clumsy--fit for the unscaled. \n\nI suspect duplicity: an illusion, perhaps. If we can subdue him, I'm certain the truth will out.", objectives = "Confront Cygenoth, Voice of Neltharion.", completion = "We quenched the last embers of the Twilight's Hammer today. But the Worldbreakers are another matter--these scaleborn will find new explanations for their misfortune, new myths, and new leaders. \n\nMy kin and I will watch over them. Should another Voice rise, we will intervene.\n\nYou've done a good thing this day." }
WordHunterWoW_QuestEN[65700] = { title = "Core Control", description = "Your timing is most excellent.\n\nIt appears one of my traps captured a rather curious creature moments ago. I dare not investigate, but you... you can do this for me.\n\nTake Pocopoc along with you. Perhaps there are secrets yet to be discovered.", objectives = "Examine the curious creature outside of Exile's Hollow.", progress = "Find something of interest?", completion = "Pocopoc is most intriguing, yes? I do wonder the extent of its capabilities." }
WordHunterWoW_QuestEN[65701] = { title = "Preservation, Augmentation, or Devastation", description = "If what these dragons say is true, then a great battle is upon us. We need you focused and strong, evoker.\n\nTime to choose your battle specialization. Will you preserve your allies, or devastate your enemies? \n\nTo hone your combat skills to their sharpest, choose Devastation.\n\nTo maximize your healing potential, take the path of Preservation.\n\nTo enhance your wingmates, embrace Augmentation.\n\nEach specialization should serve you well. And remember, you can change or adapt it later.", objectives = "Choose a specialization.", completion = "Excellent choice.\n\nRemember, you can reconsider your specialization and adjust abilities as needed--so long as you are not in the heat of battle." }
WordHunterWoW_QuestEN[65702] = { title = "Driven Mad", description = "The Azure Archives was once a place where the blue dragons would gather to discuss magic.\n\nNow I am the only one of my kind here.\n\nThis place controls the ley lines beneath the Azure Span, but it and its servants have gone out of control.\n\nI believe if we bring order to this place that I can then reclaim the Azure Oathstone.\n\nThe various constructs and elements are brimming with unstable arcane energy that needs to be redirected.\n\nDestroy them and collect what you can.", objectives = "Recover 40 Unstable Arcane Energies.", progress = "The archives are in a perpetual state of recreation for most of its guardians. We need to fix its flow.", completion = "Excellent work. The creations here are already being soothed with just this amount of unstable arcana removed." }
WordHunterWoW_QuestEN[65703] = { title = "Shadowlands (60) E", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[65704] = { title = "Shadowlands (60) E", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[65705] = { title = "Shadowlands (60) E", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[65709] = { title = "Arcane Pruning", description = "We cannot activate the oathstone in the Azure Archives until we fix the issue with the out of control ley energy here.\n\nTwo out of the three draconic runes that are meant to control it are being choked by unstable arcana.\n\nI apologize that this falls to you, given Khadgar's responsibilities and the lack of my brethren appearing.\n\nThere should be a ley scepter within that bag of helpful goods you have.\n\nUse it to help repair the runes nearby.", objectives = "Look through the Bag of Helpful Goods for the Ley Scepter, then use it to repair 2 platforms.", progress = "The ley scepter should allow you to properly align and configure the runes nearby.", completion = "Excellent work. It seems these runes are able to transport us to the top of the archives.\n\nI believe that may be where our last problem resides..." }
WordHunterWoW_QuestEN[65711] = { title = "Stealing Its Thunder", description = "It's you! Thank Ohn'ahra. I was pretending to be hurt to fool the next brute who dared come in here. Ugh--the hoof lickers put some binding spell on me. I'll figure it out.\n\nThey've got Lizi in the cave. Please save her. I'll figure out how to free myself.\n\nDo what you have to do.", objectives = "Kill the Storm Extractors and rescue Lizi the Thunderspine in Kaighan Camp.", progress = "Anyone whose laid a hoof on Lizi will pay!", completion = "<Radiya is unusually quiet and trembling slightly as she looks upon the tortured beast.>" }
WordHunterWoW_QuestEN[65717] = { title = "Leading Motives", description = "<A small object catches your eye. It glitters with Progenitor magic--ancient, yet... strangely more refined.>\n\n<Soft vibrations and tones are woven into the device in a repeating refrain that almost seems to be trying to... speak?>\n\n<Firim would be very interested in this.>", objectives = "Bring the Almanac's Echo to Firim in Exile's Hollow.\n\nProvided item:", completion = "By the First Ones... once again, you bring me the extraordinary. You say you found this when you defeated the Jailer? How curious.\n\nIt almost seems as if it's trying to... to communicate somehow. The implications alone are--ah! Forgive me for getting carried away. This will require more than simple research, I'm afraid. \n\nPlease, take this in return. It was one of my first discoveries--I suspect you have more to gain from its mobility than I do. \n\nThank you, my friend." }
WordHunterWoW_QuestEN[65725] = { title = "The Burrowed Bufonid", description = "The large bufonid beneath the mud remains still.\n\nThere must be something it fancies. Have you some meats we can use to lure it out?", objectives = "The large bufonid beneath the mud remains still.\n\nThere must be something it fancies. Have you some meats we can use to lure it out?", progress = "The large bufonid beneath the mud remains still.\n\nThere must be something it fancies. Have you some meats we can use to lure it out?", completion = "Thank you, <name>. Let us see if this does the trick." }
WordHunterWoW_QuestEN[65726] = { title = "The Burrowed Bufonid", description = "If meat and honey could not lure this creature from the waters, let us try another approach. \n\nBring me some Shrouded Cloth. I will craft a net from it that may be more effective.", objectives = "If meat and honey could not lure this creature from the waters, let us try another approach. \n\nBring me some Shrouded Cloth. I will craft a net from it that may be more effective.", progress = "If meat and honey could not lure this creature from the waters, let us try another approach. \n\nBring me some Shrouded Cloth. I will craft a net from it that may be more effective.", completion = "Thank you, <name>. Let us try this for Bud's sake, if not our own curiosity." }
WordHunterWoW_QuestEN[65727] = { title = "The Burrowed Bufonid", description = "Have you stopped to watch the bufonids?\n\nA lovely one lurks underwater. Still, patient, unmoving. Wise Bud takes after him. They are much alike. I sense Bud desires to see this large bufonid up close. \n\nPerhaps the creature can be lured out with some honey from the vespoids here in Zereth Mortis. Would you please gather some?", objectives = "Collect 15 Vespoid Honey from Vespoid around Zereth Mortis.", progress = "Have you found that honey?", completion = "Thank you, <name>. Now, let us see if this will entice that bufonid to emerge." }
WordHunterWoW_QuestEN[65728] = { title = "The Burrowed Bufonid", description = "Since a trap did not work, let us try again to find a lure that interests this austere bufonid. \n\nPerhaps it desires some fish? Please bring us some.", objectives = "Since a trap did not work, let us try again to find a lure that interests this austere bufonid. \n\nPerhaps it desires some fish? Please bring us some.", progress = "Since a trap did not work, let us try again to find a lure that interests this austere bufonid. \n\nPerhaps it desires some fish? Please bring us some.", completion = "Thank you, <name>. Let us hope this works." }
WordHunterWoW_QuestEN[65729] = { title = "The Burrowed Bufonid", description = "I am running out of ideas. What else might entice our shy friend?\n\nLet us try more flesh from the creatures of Zereth Mortis. Something must grab its attention!", objectives = "I am running out of ideas. What else might entice our shy friend?\n\nLet us try more flesh from the creatures of Zereth Mortis. Something must grab its attention!", progress = "I am running out of ideas. What else might entice our shy friend?\n\nLet us try more flesh from the creatures of Zereth Mortis. Something must grab its attention!", completion = "Thank you, <name>. Let us see if this produces results." }
WordHunterWoW_QuestEN[65730] = { title = "The Burrowed Bufonid", description = "What else could we possibly try to persuade this bufonid to emerge?\n\nMaybe the jiro know the trick. I hear there is one with fruit pastries to offer. Bring us one, if you please.", objectives = "What else could we possibly try to persuade this bufonid to emerge?\n\nMaybe the jiro know the trick. I hear there is one with fruit pastries to offer. Bring us one, if you please.", progress = "What else could we possibly try to persuade this bufonid to emerge?\n\nMaybe the jiro know the trick. I hear there is one with fruit pastries to offer. Bring us one, if you please.", completion = "Thank you, <name>. Maybe our bufonid friend just has more refined taste." }
WordHunterWoW_QuestEN[65731] = { title = "The Burrowed Bufonid", description = "Hmmmmm...\n\nMy friend, I am nearly out of ideas. We have exhausted most of Zereth Mortis' supply of tempting flavors. \n\nI have spent hours pondering the things I find enticing. Only one thing outside of Zereth Mortis brushes my memory: \n\nSweet organic melons. \n\nMy dear friend once sold them just inside the great Tazavesh marketplace. Is it possible they are still there? You will need to gain access to the city, if you have not already.", objectives = "Hmmmmm...\n\nMy friend, I am nearly out of ideas. We have exhausted most of Zereth Mortis' supply of tempting flavors. \n\nI have spent hours pondering the things I find enticing. Only one thing outside of Zereth Mortis brushes my memory: \n\nSweet organic melons. \n\nMy dear friend once sold them just inside the great Tazavesh marketplace. Is it possible they are still there? You will need to gain access to the city, if you have not already.", progress = "Hmmmmm...\n\nMy friend, I am nearly out of ideas. We have exhausted most of Zereth Mortis' supply of tempting flavors. \n\nI have spent hours pondering the things I find enticing. Only one thing outside of Zereth Mortis brushes my memory: \n\nSweet organic melons. \n\nMy dear friend once sold them just inside the great Tazavesh marketplace. Is it possible they are still there? You will need to gain access to the city, if you have not already.", completion = "Thank you, <name>. This is a piece of a past long lost and forgotten...\n\nBut it is not for me. Let us see if this at last will attract our hidden bufonid friend." }
WordHunterWoW_QuestEN[65732] = { title = "The Patient Bufonid", description = "Look, another magnificent creature of Zereth Mortis! By the glint in its eye, I would say it was playing along the whole time.\n\nPatience delights. Bud is pleased. \n\nExcellent work, Maw Walker.", objectives = "Thank you, <name>. The creature seems quite friendly, and I believe it has taken a liking to you! I am certain you will take excellent care of it." }
WordHunterWoW_QuestEN[65735] = { title = "WANTED: Custos", description = "A once-stable automa is showing signs of unusual dysfunction, attacking Enlightened along the road outside of Pilgrim's Grace. \n\nIt is essential that the roads remain safe for our pilgrims.\n\nRafiq has designated the elimination of this threat to be of the highest priority.", objectives = "Eliminate Custos.", completion = "I do not understand why it was behaving in that manner, but we will be safer now that it is gone. This reward shall start you on the way towards some of my finer equipment." }
WordHunterWoW_QuestEN[65748] = { title = "You Supply the Effort", description = "The gear I provide is made available by the blessings of the First Ones and the... efforts of many other travelers.\n\nEach of us needs to provide for those that will follow later.\n\nCollect what provisions you come across in your exploration of Zereth Mortis. Keep a sharp eye out--they may be hidden in mysterious places. Return them here to me. I will in turn provide them to future travelers.", objectives = "Locate 10 Enlightened Provisions from chests, nests, relics and other containers about Zereth Mortis.", progress = "What have you found for me?", completion = "Well met, traveler! What have you found there? Ah, this will help many other travelers in need. You have my thanks--and theirs as well." }
WordHunterWoW_QuestEN[65749] = { title = "The Necessity Of Equipment", description = "I have been sharing research for some time with an associate of mine, Rafiq.  It is only through our shared efforts that he has been able to acquire useful items.\n\nDeliver my latest research notes to Rafiq and see if you can earn favor with him. In time, he should be able to aid you with better equipment.", objectives = "Collect Firim's Research Notes and deliver them to Rafiq.", progress = "What is this you have brought me?", completion = "You have my thanks <name>, and a gift for your future efforts." }
WordHunterWoW_QuestEN[65750] = { title = "Eight-Legged Menace", description = "{class}!\n\nI require your aid if you're willing...\n\nThis joint expedition was intended to study the unique arachnids inhabiting the area, but, as you can see, our plan has gone awry. \n\nWhat we originally assumed was an evolutionary adaptation is instead a Primalist perversion of the natural order!\n\nI take my responsibilities as a conservationist seriously, but the time for studying live specimens has passed. We can't let their perversion spread. We can study their corpses instead. \n\nWill you help us?", objectives = "Kill 10 Shiverweb Creepers or Shiverweb Crawlers and 3 Primalist Tenders in Shiverweb Vale.", progress = "Is it done?", completion = "An unfortunate necessity. We could not allow them to spread.\n\nI think we've learned all we can from them." }
WordHunterWoW_QuestEN[65751] = { title = "Platform Adjustments", description = "It seems the last of the arcane disruption is up here. \n\nI'll continue adjusting the ley energies. Use some of the arcana you recovered to dispel the disruptions here.", objectives = "Dispel 3 Unstable Arcane Energies at the top of the Azure Archives.", progress = "Do you need anything?", completion = "Fine work! I can feel the ley lines beneath this place beginning to heal. We're almost done." }
WordHunterWoW_QuestEN[65752] = { title = "Arcane Annoyances", description = "A large number of mana wyrms are absorbing the wild arcane magic coming out from the archives.\n\nThe rate that they're doing it is causing the ley lines to be thrown off balance... which is preventing the Azure Oathstone from being reclaimed.\n\nI will use some of the unstable arcana you collected to form a hook of sorts.\n\nUse it to slay several of the wyrms. The brief delay will be enough for me to adjust the energies below.", objectives = "Slay 6 Feasting Wyrms.", progress = "These wyrms will learn to feast somewhere else.", completion = "The Kirin Tor will ensure these archives are properly cared for when this is finished. Thank you for your aid." }
WordHunterWoW_QuestEN[65758] = { title = "Grungir the Explorer", description = "{name}! My Explorers' League counterpart, Grungir Ironspout, wasn't among those you rescued. He had fought his way free originally, but once he saw how few of us made it out, he turned around and headed right back in! Alone!\n\nThe oaf is as brave as he is impulsive and does not deserve whatever fate has befallen him.\n\nPlease... find him.", objectives = "Find Grungir Ironspout.", completion = "Good tae see another face with the right number o' eyes!" }
WordHunterWoW_QuestEN[65760] = { title = "Reporting for Duty", description = "I've only read of the djaradin in books.\n\nAncient rivals to the dragons, powerful giants with mastery over earth and lava... dedicated wholly to hunting dragons to extinction.\n\n<Sendrax furrows her brow at the distant volcano.>\n\nMy instructor said that they hadn't been seen since the dragons left as they slumbered deep in the earth.\n\nIf they've awoken, every whelpling on the isles is in danger!\n\nWe should hurry to Commander Lethanak at the Dragonheart Outpost.", objectives = "Meet commander Lethanak at the Dragonheart Outpost.", progress = "Our ancient enemies have risen from their slumber... and wasted no time.", completion = "I will take what reinforcements I can get.\n\nWe must act swiftly." }
WordHunterWoW_QuestEN[65761] = { title = "More Adventure Than Expected", description = "<Godoloto's stare is beady and accusatory. She huffs.>\n\n<Perhaps the ohuna can help you find and rescue Radiya.>", objectives = "Work with Godoloto to find and rescue Radiya.", completion = "<name>!" }
WordHunterWoW_QuestEN[65762] = { title = "Sepulcher of the First Ones - Heavy is the Crown", description = "Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king.\n\nFour fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.", objectives = "Collect 4 Sword Fragments from Anduin within the Sepulcher of the First Ones on Mythic Difficulty.", progress = "Four Sword Fragments should allow us to access his chamber.", completion = "This should help us travel directly to Anduin." }
WordHunterWoW_QuestEN[65763] = { title = "Sepulcher of the First Ones - Heavy is the Crown", description = "Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king.\n\nFour fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.", objectives = "Collect 4 Sword Fragments from Anduin within the Sepulcher of the First Ones on Heroic Difficulty.", progress = "Four Sword Fragments should allow us to access his chamber.", completion = "This should help us travel directly to Anduin." }
WordHunterWoW_QuestEN[65764] = { title = "Sepulcher of the First Ones - Heavy is the Crown", description = "Anduin's blade is a powerful conduit for The Jailer. If we claim fragments of this weapon, I'll be able to open a pathway directly to the boy king.\n\nFour fragments should be enough. With these, we can break the Jailer's hold on Anduin for good.", objectives = "Collect 4 Sword Fragments from Anduin within the Sepulcher of the First Ones on Normal Difficulty.", progress = "Four Sword Fragments should allow us to access his chamber.", completion = "This should help us travel directly to Anduin." }
WordHunterWoW_QuestEN[65768] = { title = "Our Forward Scouts", description = "The Jailer's forces control much of Zereth Mortis, but there are other dangers out there as well.\n\nI have dispatched scouts to survey the surrounding area and pinpoint any potential threats.\n\nSpeak with each scout. They should have a report of their surveys. Gather this information and then return to me.", objectives = "Speak with the forward scouts in Zereth Mortis.", progress = "What have you discovered?", completion = "This information will help us plan our next move. Thank you, Maw Walker." }
WordHunterWoW_QuestEN[65769] = { title = "Icy Webs", description = "Many of my friends and colleagues were captured when the arachnids and their Primalist masters attacked. \n\nI saw them being bound in frozen webbing and dragged away to a fate I dare not consider. \n\nPlease free any of them that you can!", objectives = "Free 6 Cocooned Survivors in Shiverweb Vale.", completion = "Thank you, <name>. I feared I would never see any of them again." }
WordHunterWoW_QuestEN[65770] = { title = "A Promise Is A Promise", description = "The animals are comfortable around you. That's a good indicator of your spirit.\n\nActually... can you keep a secret? I want to introduce you to my friend. Nobody else knows about her.\n\nYou have to promise me first that you'll keep this between us. My Ohn would exile me from the plains if she found out.", objectives = "Promise Initiate Radiya to keep her secret.", completion = "<Togotseng's ohuna glares at you.>" }
WordHunterWoW_QuestEN[65771] = { title = "Favor of the First Ones", description = "The attack from the Jailer's forces is a sign! In the past, there was one among us who sought the forbidden knowledge of the First Ones. For that, we must have earned their ire and lost the protections we once had.\n\nWe must atone for the trespasses of our kin.\n\nTake this incense. Go out into the veldt and burn it as offerings to the First Ones. I hope they will offer us forgiveness.", objectives = "Burn Enlightened Incense around the Great Veldt.", completion = "May the First Ones accept these offerings as penitence for past transgressions. \n\nThank you, Maw Walker." }
WordHunterWoW_QuestEN[65772] = { title = "Necessary Harvest", description = "Between the Mawsworn attacks and your presence here, our supplies are dwindling. It pains me to say it, but the most immediate solution for replenishing our resources is the local wildlife. \n\nIt is unfortunate that it has come to this, but it is what must be done. Cull some of the local wildlife, and help us replenish our supplies.", objectives = "Collect 15 Latent Protein from raptora, cervids, and lupines in The Great Veldt and surrounding area.", progress = "Have you brought us the necessary supplies?", completion = "Thank you. Your efforts are greatly appreciated." }
WordHunterWoW_QuestEN[65773] = { title = "Solo Mission", description = "Seems it is time you prove yourself alone.\n\nThere's a chance for continual conflict, but this has to be undertaken by yourself. Sometimes you have to fight along side enemies to understand their tactics, this seems like a chance.\n\nGood luck.", objectives = "Complete 5 rounds of Solo Shuffle.", completion = "Excellent. You fight so fiercely to claim a piece of ground. The Observer will find that intriguing." }
WordHunterWoW_QuestEN[65774] = { title = "The Catalyst Awakens", description = "Adventurer, can you feel it? High above the Catalyst Gardens, the Creation Catalyst hums with new power. \n\nThis power will change the world itself. You must harness it at once.", objectives = "Travel to the Catalyst Gardens and use the Creation Catalyst.", progress = "The very fabric of creation shudders.", completion = "The power of creation itself is in your hands." }
WordHunterWoW_QuestEN[65775] = { title = "Soloing Strategy", description = "You survived that battle test.\n\nI still think improvements can be found during these bouts. Try again.\n\nReturn when you are finished.", objectives = "Complete 15 rounds of Solo Shuffle.", completion = "Excellent. You fight so fiercely to claim a piece of ground. The Observer will find that intriguing." }
WordHunterWoW_QuestEN[65777] = { title = "Mudcaked Necklace", description = "<The ancient markings on the necklace are quite difficult to read, but the materials appear to be made of animal hide and carved bone fragments.\n\nPerhaps a knowledgeable hunter may glean insight into this object's value.>", objectives = "Locate someone knowledgeable in plainshunting and handcrafted artifacts.\n\nProvided item:" }
WordHunterWoW_QuestEN[65778] = { title = "Screechflight Potluck", description = "Are you ready to put those acting chops of yours to good use, {name}?\n\nWhat? You don't have any chops? Then it's a good thing I've made you an im-PECK-able Screechflight disguise out of all the materials you just gathered!\n\nSegallia and I still need time to finish building the final \"egg\" that will take out the matriarch, but I've made a smaller, prototype version for you to try out on the chef.\n\nAnd don't worry! You'll be 12% safer from these explosions under all the feathers!", objectives = "Wear your disguise and use the Prototype \"Egg\" on the Matriarch's Personal Chef.", progress = "Old Monte Gazlowe once invited me over and cooked dinner to impress me. To be honest, it smelled a lot like whatever is coming from that cave over there.", completion = "You did great and looked pretty good in that outfit to boot!\n\nFinally ready to cut this terrifying threat off at its beak?" }
WordHunterWoW_QuestEN[65779] = { title = "Into the Plains", description = "The green dragonflight has returned to their gardens in the nearby plains. Queen Alexstrasza wishes for you to make contact with Merithra of the Dream.\n\nThe centaur of those plains are fierce hunters. To reach the Emerald Gardens, you will need to establish diplomacy with them first.\n\nBe respectful, but show no weakness.", objectives = "Meet the Shikaar scout in the Ohn'ahran Plains.", progress = "<Tomul eyes you up and down with reserved curiosity.>\n\nState your business in the plains.", completion = "You serve as an envoy of the dragons, then. Times are changing." }
WordHunterWoW_QuestEN[65780] = { title = "Proving Oneself", description = "A gift from dragons may impress some centaur, but Clan Shikaar must see how well you hunt.\n\nOne of our hunting parties just brought down a proto-dragon infused with the power of flame. Prove your worth by aiding in the kill.", objectives = "Slay the Blazing Proto-Dragon.", progress = "You look like you can handle yourself, but looks can be deceiving.", completion = "You are a more formidable fighter than I assumed." }
WordHunterWoW_QuestEN[65782] = { title = "Under Lock and Key", description = "When we heard rumors of a Deathwing cult, Majordomo Selistra ordered me to bring these erstwhile scaleborn back into the fold. We'd hoped it was a simple misunderstanding.\n\nClearly, we were wrong.\n\nTheir leader must be dealt with--but first I need out of this cage. Find the key and bring it to me.", objectives = "Acquire the Worldbreaker Cell Key and free Ayasanth.", progress = "I must admit: this cage has gotten rather tiresome.", completion = "I may have suffered imprisonment--but the Worldbreakers barely spit an ember next to the Twilight's Hammer. I should be grateful for that at least." }
WordHunterWoW_QuestEN[65783] = { title = "Welcome at Our Fire", description = "You have fought alongside our hunters and earned a place at our fire.\n\nOur khan is at our hunting post in the swamp, readying our upcoming caravan. I will notify her of your arrival and purpose.\n\nSurely you can find your way on your own.", objectives = "Meet with Scout Tomul at Timberstep Outpost.", completion = "You outsiders seem to have a habit of meddling in the affairs of others." }
WordHunterWoW_QuestEN[65784] = { title = "The Otter Side", description = "To the northeast, there are a system of otter burrows along the bank. Some of the otters there are blessed by the river to grow to magnificent sizes.\n\nI will not have you hunting these blessings out of respect. Instead you will bring them back here, alive, so that we may treat them with the reverence they deserve.", objectives = "Bring 3 Gargantuan River Otters back to Clan Aylaag.", progress = "Remember, they must be returned alive.", completion = "Fine creatures. We will make use of everything they have to offer." }
WordHunterWoW_QuestEN[65788] = { title = "A Walk with Ghosts", description = "Reclaiming these ruins means a lot to the Forsaken. Especially since the war ended, our people have needed something to hold onto, to give us purpose in the wake of everything that's happened to us.\n\nI saw Calia walk toward the throne room. That place holds many memories for her. Many ghosts. \n\nWe should check on her.", objectives = "Speak to Calia in the throne room of Lordaeron.", completion = "Thank you, <name>. You have helped so much. \n\nFrom here, I believe the Forsaken will rebuild and solidify their identity. Not just as former denizens of Lordaeron, but as their own people. A people I am proud to be one of." }
WordHunterWoW_QuestEN[65789] = { title = "Where Rivers Sleep", description = "The Mirewood contains key reagents often used to converse with the ancestors. Unfortunately, the Mudfin tribe swarms the area, making it difficult for us to forage the area.\n\nIf you could gather some of the blooms within the marsh, along with some of the Mudfin's own resources, I would appreciate it.", objectives = "Collect reagents from Mirewood Fen.", progress = "Have you found everything?", completion = "I thank you. These will be put to good use." }
WordHunterWoW_QuestEN[65791] = { title = "Life-Binder on Duty", description = "Soon the Life Pools will be full once again.\n\nThank you for your part in this, {name}, it means more than I can ever hope to express.\n\nGo, find the Life-Binder by the oathstone. Tell her that we are ready for the eggs.", objectives = "Meet Alexstrasza by the Ruby Oathstone.", completion = "The future of all the flights is now secure." }
WordHunterWoW_QuestEN[65792] = { title = "Teeth for a Tooth", description = "Toliqui has been claiming that just the other day she killed a rockfang without any assistance. Given our connected souls, I don't want to call her as a liar. So instead... \n\nI want to prove to her, and everyone else, that I'm the better half of our soul! The nearest rockfang quest is to the northeast - meet me there!", objectives = "Slay 10 rockfangs with Toluijin.", progress = "I cannot let Toliqui continue to leave me in her shadow.", completion = "The clan will be talking about this for weeks!" }
WordHunterWoW_QuestEN[65793] = { title = "Black Wagon Flight", description = "With the oathstone empowered once more, we must now transport the future of our kind to the Life Pools. It is the right of every true dragonflight to have their eggs nurtured by its waters.\n\nUnfortunately, our enemies will be watching the skies, now that we have revealed ourselves. We will make the final leg of the journey on foot to avoid their scrutiny.\n\nMeet me near the Obsidian Bulwark, {class}. As the Life-Binder's champion, you are welcome to join me in this.", objectives = "Escort the eggs to the Life Pools.", completion = "You have served admirably, <race>." }
WordHunterWoW_QuestEN[65794] = { title = "A Charge of Care", description = "You have my thanks, {class}, and my condolences for having to deal with those two for as long as you did.\n\nThe red dragonflight is charged with the preservation and nurturing of all dragons, even those we may tire of at times.\n\nWith the return of the Black Dragonflight's eggs, dragonkind is united as it has not been in thousands of years. I believe this is what will restore our ruby oathstone.\n\nSpeak with me when you are ready to bring the eggs to the Obsidian Lifepool.", objectives = "Witness the Black Dragon Eggs rejoin the Life Pools.", completion = "The Life Pools are filled once more, in no small part thanks to you.\n\nWith our purpose fulfilled, our oathstone shines once more as a symbol of our calling." }
WordHunterWoW_QuestEN[65795] = { title = "Next Steppes", description = "The green dragonflight requires your aid now, hero. My sister's daughter and her flight have entered the Emerald Dream in an attempt to empower their own oathstone, but we have heard nothing since their slumber began.\n\nSeek out the centaur that rule over the Ohn'ahran Plains. You may well need their connection to the land and its spirits if you are to rouse the greens.\n\nThey are a proud and territorial people who do not suffer insult lightly. Speak with our ambassador and he will prepare you.", objectives = "Meet Ambassador Taurasza in the Rubyscale Outpost.", completion = "We have much to discuss, you and I." }
WordHunterWoW_QuestEN[65796] = { title = "The Best Defense...", description = "Our next path is through Nokhud territory. Historically, we have been at a tentative peace with their clan, but times have changed. \n\nIf we do not act first, we leave ourselves open while we're vulnerable. My scouts have reported that one of their war leaders has been spotted near Dragonsmeet. Take the fight to her directly - do not let her gather the forces to assault us on the move.", objectives = "Slay Sirena the Fangbreaker.", progress = "I cannot afford any mistakes. There are too many lives counting on me.", completion = "Thank you, this will give me some peace of mind as we prepare for our journey." }
WordHunterWoW_QuestEN[65798] = { title = "An Opportunistic Approach", description = "The Shikaar have formed an offensive line against the Nokhud to the north. While I do not like stooping to scavenging, it is unfortunately a necessary evil for our supplies. Brave the battlefield and return with weapons, and I will reward your efforts.\n\nIf you could focus said efforts on the Nokhud side of the line, perhaps the ancestors will judge me less harshly.", objectives = "Retrieve weapons and slay Nokhud forces at the Nokhud Approach.", progress = "Weapons will be the most useful thing - I apologize for asking this of you.", completion = "Ancestors forgive me. If I were stronger, we would not need to resort to such a questionable method for resources." }
WordHunterWoW_QuestEN[65801] = { title = "Making Introductions", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nIt has been countless generations since an outsider like you reached our lands. With Primalists treading on our lands and peddling forbidden magics, my people are understandably wary.\n\nIf you are to travel with us, you must make yourself known. Introduce yourself to the members of my clan.", objectives = "Introduce yourself to members of Clan Shikaar.", progress = "Good. The Khan is putting you to work.", completion = "The rest of our attending clan has already traveled to Maruukai to prepare our site. The caravan from this outpost will be the last to arrive." }
WordHunterWoW_QuestEN[65802] = { title = "Supplies for the Journey", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nWhile you travel with us, you must pull your weight. Unruly gorlocs have been raiding our medical supplies recently, and we must restock. Gather the orange blooms around the outpost so we can create more poultices.\n\nThere are supplies around the outpost that need to be brought to the caravan as well. I would like you to gather them while you are out.\n\nOnce you have everything, bring it to Tomul.", objectives = "Collect 5 Camp Provisions from around Timberstep Outpost and 4 Feralbloom Pods from the nearby woods.", progress = "Don't bother me until you have the caravan provisions.", completion = "<Scout Tomul looks over the gathered provisions.>\n\nEverything seems to be in order." }
WordHunterWoW_QuestEN[65803] = { title = "Toward the City", description = "The Khural is a time of discussion amongst clans. Stories are shared. While there are many centaur clans across the plains, we are all Maruuk.\n\nThe caravan is ready to go. As Maruukai is some distance away, we will make stops.\n\nWhen you are ready to leave, find me at the caravan. Don't keep us waiting.", objectives = "Travel alongside the Shikaar caravan to Wanderer's Steppe.", completion = "Take a breath, two-foot." }
WordHunterWoW_QuestEN[65804] = { title = "For Food and Rivalry", description = "Maruuk travel from all across the plains to attend the Khural, and the gathering lasts many days.\n\nFeeding that many centaur is no simple feat. Clan Shikaar's hunters provide meat for all of the shared meals. It is our tradition to hunt on our way to Maruukai. \n\nYou must pull your weight as well.", objectives = "Collect 30 Fresh Game Meat from wildlife in Wanderer's Steppe.", progress = "Our youngest hunters are passionate and determined. Be sure they don't show you up.", completion = "You hunt as strangely as you fight. I hope Aru and Belika observed your technique." }
WordHunterWoW_QuestEN[65805] = { title = "Connection to Ohn'ahra", description = "The wind is restless here, {name}. Ohn'ahra is reaching out. I must answer her call.\n\nI need reagents for my ritual: reeds from the riverbanks, feathers from the tails of mallards, and the heart of a salamanther. Gather these materials from the river so that I may heed her voice.", objectives = "Collect 4 River Reeds, 8 Fowl Tailfeathers, and a Salamanther Heart from the river banks.", progress = "Ohn'ahra's song is fleeting. We must work quickly.", completion = "Excellent. I will use these materials to interpret her song." }
WordHunterWoW_QuestEN[65806] = { title = "Maruukai", description = "<Okir vocalizes as Sansok Khan signs.>\n\nMaruukai rests beside a mountain near this grove. Our journey is almost over.\n\nThe Khural is a time of truce amongst the Maruuk, but Ohn Seshteng's omen is troubling. We must stay on our guard.", objectives = "Travel into Maruukai.", completion = "Welcome to Maruukai." }
WordHunterWoW_QuestEN[65832] = { title = "Dwarven Antifreeze", description = "I'm in a wee bit of a pickle, laddie. The Primalist frost lickers stuck me in this overgrown ice cube and the only reason I'm nae frozen solid yet is me secret stash o' the good stuff. \n\nSadly, me less secret stashes got nicked when tae thieving scum jumped me. I'm runnin' low!\n\nWould ye do a dwarf a kindness and fetch me flasks afore me blood turns tae ice?\n\nOh, and laddie, if ye do haftae pull one out o' some spider's unmentionables, dinnae tell me. I'd rather nae know.", objectives = "Find 6 Flasks of Dwarven Antifreeze.", progress = "I can feel ma wee piggies freezin'!", completion = "Thank Magni! This'll keep me blood from freezin' long enough for the ice tae melt." }
WordHunterWoW_QuestEN[65833] = { title = "Primalist Tampering", description = "The Primalists are infusin' spiders with elemental ice and are fixin' to use 'em as shock troops tae overrun the dragons' defenses in the Span. We cannae let that happen.\n\nThe three frosty lookin' ones are in charge. Take 'em out and bring me the runestones they're using tae focus the primal magic and we can see about cuttin' off the flow.", objectives = "Retrieve the three Frostcallers' Runestones.", progress = "Did ye get all three?", completion = "Serves 'em right.\n\nThank ye, <name>." }
WordHunterWoW_QuestEN[65834] = { title = "Kill the Queen", description = "Here we go! A lil' formal education, a lil' educated guessin', a touch o' re-chiselin' runes, and we got ourselves a magic un-infuser! Defuser? Out-fuser?\n\nWhatever! It'll do somethin' unpleasant tae the queen, o' that I'm pretty sure. And she's got tae go if we're aimin' tae stop the threat. Squashin' the lil' ones will only slow 'em down. Ye got tae cut 'em off at the source.", objectives = "Slay the Shiverweb Queen.", progress = "She's in the cave over yonder.  Giant spider. Cannae miss 'er.", completion = "Aye, that should throw a wrench intae their plan.\n\nNow... just tae push... a... lil'... harder..." }
WordHunterWoW_QuestEN[65836] = { title = "Show of Storm", description = "<Watu stands up easily, as if his injury was gone.>\n\nI--I--I stuck the shard into myself. Nothing hurts anymore. I feel good. Great. Immense.\n\nOlekk still isn't back. Something must have gone awry. He should have never gone without me!", objectives = "Regroup with Watu in the Sagecrest Pines.", completion = "No!" }
WordHunterWoW_QuestEN[65837] = { title = "Trouble In The Pines", description = "There's been a primalist attack in the Shikaar Highlands.\n\nIf you have information or think you can help, head over to Pinewood Post and look for Olekk. Tell him I sent you. <Tirren chuckles.> I sure hope the dusty hoofer remembers me.\n\nKeep to the roads, {name}. The plains are not as peaceful since all this change arrived.", objectives = "Speak to Sentinel Olekk at Pinewood Post in the Ohn'ahran Plains.", completion = "Tirren? He's still hoofing around, is he?\n\nThank you for coming. We can use all the help we can get." }
WordHunterWoW_QuestEN[65838] = { title = "Breaching the Brackenhide", description = "If the gnolls here have discovered decay magic, the ley line and even the land itself are in grave danger. \n\nMy mirror images are spread too thin to withstand elemental disruption of this scale. Please enter the forest and investigate the decay. \n\nI'll work with our new tuskarr friends to find a place I can maintain my image. Then, I will meet you deeper in the forest.\n\nWe must put a stop to this!", objectives = "Investigate Brackenhide Outskirts.", progress = "Can you sense the disruption of magic all around us?", completion = "You may want to cover your mouth. You don't want to breathe in the decay." }
WordHunterWoW_QuestEN[65840] = { title = "Same as the Old Boss", description = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing.\n\nHowever, Deathwing has not returned, and still there is no Twilight.\n\nIt is time for a new leader. You can help bring about the change.", objectives = "Eliminate Doventhal the Chosen.", progress = "Are we ready for a new leader?", completion = "You have done well. Now there is ample room for a new leader to rise and bring the Worldbreakers to a better future." }
WordHunterWoW_QuestEN[65841] = { title = "Stop the Spread", description = "", objectives = "" }
WordHunterWoW_QuestEN[65842] = { title = "Disarming Behavior", description = "I have little love for the Worldbeaker dragonkin. They follow a misplaced belief that Deathwing himself will return one day, and they will not help us with the Obsidian Throne.\n\nWeaponmaster Vordak, who once swore loyalty to the Black Prince, has stolen many weapons crafted here in the Citadel and given them to the Worldbreakers. I will not allow such theft. Or such betrayal.\n\nGo to Smoldering Peak and recover the weapons... by force if necessary.", objectives = "Eliminate Weaponmaster Vordak and collect 15 Worldbreaker Weapons.", progress = "Have you acquired the weapons?", completion = "Well done. These weapons are back where they belong.\n\nI'm sure this won't be the last conflict we have with the Worldbreakers, either. Anyone crazy enough to think that Deathwing will return isn't going to be reasoned with." }
WordHunterWoW_QuestEN[65844] = { title = "Cut Out the Rot", description = "This decay must have rotted these gnolls' brains as well as their bodies! \n\nDestructive as they are, gnolls are native to this land--just like us.\n\nBut we already saw them spreading decay to the Big Tree Tribe. At this rate, they'll consume the Span and destroy themselves. \n\nWe can't let this happen. It's a shame... but put an end to them.", objectives = "Kill 5 Rotting Treants and 10 Brackenhide Rotflingers.", progress = "Er, please, do tell... Did you see any interesting effects of the decay on any gnolls you observed? The effect on their social structure must be enormous...\n\nAh, we should stay on task.", completion = "Gnolls can be fascinating creatures! They're not evil, only wild. And very dumb. \n\nKilling them is a shame, but the decay helps no one. And we can't let them hurt our family." }
WordHunterWoW_QuestEN[65845] = { title = "Echoes of the Fallen", description = "There are tuskarr here! My friends, my people--my family. They left for a hunt not a week ago.\n\nAlready they're too decayed to recover. \n\nTheir spirits are here still. They linger in rage and regret. Kaqiata, Lutokk, Tuyuki...\n\nPlease, {name}, take this totem and place it near their remains. It'll contact their spirits... and help them find peace.", objectives = "Place Brena's Totem near 5 tuskarr corpses to contact their spirits.", progress = "Some of my fallen kin were able to take Karkut's hand into the next world. Others weren't. I feel their presence like a weight.\n\nLutokk was going to wed in the next moon. \n\nTuyuki wanted to sail to Northrend to reconnect with our distant kin. \n\nPopoak was a great hunter, and Hanu's cousin. His kills made for the best soups.\n\nNomurok was so young. This was his first hunt.\n\nKaqiata was little Rowie's only blood family left. Now who'll teach him to fish?", completion = "So they all chose to lend their power to my totem? \n\n<Brena squeezes her eyes shut in sorrow.> \n\nThank you, my friends. We will use the strength of your spirits well. The gnolls will not reach Iskaara." }
WordHunterWoW_QuestEN[65846] = { title = "Ley Litter", description = "The ley line is here--I can feel it! \n\nBut first, we must stop the gnolls. That ancient will be their greatest weapon.\n\nThere are some ley crystals the gnolls have gathered. Thankfully, they don't seem to understand the power that the crystals hold. \n\nBring me as many as you can. They'll empower my mirror image and help me summon something useful from the Archives to take that monster down!", objectives = "Collect 7 Ley Crystals from Brackenhide Outskirts.", progress = "I'm sorry I can't be of more help in this form. I can feel the decay sapping my image's strength. \n\nI hope once we reach the ley cavern, Gleamcove as the tuskarr call it, I'll be able to teleport here fully.", completion = "What were they doing with these? Using them as back scratchers?!\n\n<Kalecgos pinches the bridge of his nose.>\n\n...I suppose we should be grateful they didn't figure out their true potential." }
WordHunterWoW_QuestEN[65847] = { title = "Realignment", description = "Now for this ley line. It looks like my fears were correct -- the decay has spread into the line itself.\n\nWe'll need to purge the decay and speed along the healing process, but I can't channel enough energy with my mirror image alone. \n\nFocus yourself on this ley crystal here. My connection with you will help me teleport here physically. Then, I will be strong enough.", objectives = "Focus on the Ley Crystal, then destroy 3 Decay Infections.", progress = "While the decay here is lessened, it's still thick enough to cause trouble teleporting safely.", completion = "We did it. Great work, <name>. Breathe the fresh air again!\n\nWith this ley line restored, and Khadgar finishing up on the one in the tower, the Oathstone should be ready to claim. I must return to the Azure Archives shortly." }
WordHunterWoW_QuestEN[65848] = { title = "Tome-ward Bound", description = "We must stop that tree! With these ley crystals, I can finally help.\n\nSpeak with me when you are ready. I'll open a portal into the Azure Archives and try to bring out something useful. \n\nStand back, it may be rather unstable.", objectives = "Speak with Kalecgos to open the portal, then use what he summons to take out the Brackenhide Putrifiers and then destroy the Twisted Ancient.", progress = "This should be interesting!", completion = "You did well, hero, thank you. \n\nThat tree was probably not their only pool of decay, but it was the riskiest one for the tuskarr and this ley line. With it gone, this area may be able to recover. It will take time, but it will heal. \n\nI'm glad we were able to give the spirits of those tuskarr some peace." }
WordHunterWoW_QuestEN[65849] = { title = "To Iskaara", description = "Thank you, {name}, for all your help. My family is safe because of you.\n\nNow, we can finally return to Iskaara and see old Ponoliak taken back to the sea. He was my mentor, and a fine chieftain. \n\nPlease, you must join us! A celebration of the Cycle of the Sea is something all can share in.", objectives = "Meet Brena in Iskaara.", completion = "I'm so glad you have come to join us. \n\nI must ask you to be patient, however. There is still much to be prepared for the ceremony." }
WordHunterWoW_QuestEN[65850] = { title = "The Cycle of the Sea", description = "Thank you, {name}. I have learned what I need for now from our new friends. \n\nThe funeral ceremony for their former chieftain is about to start. Given how kind and hospitable the Iskaarans have been to us, it seems only right that we join them before departing back to the Archives. \n\nSpeak with Brena and let her know we are ready when they are.", objectives = "Speak with Brena to witness the funeral ceremony.", progress = "It is good to slow down, now and then. And interesting to see the tuskarr's traditions. \n\nIt has been long since the blue dragonflight has had traditions such as these.", completion = "<Kalecgos looks distant.>" }
WordHunterWoW_QuestEN[65852] = { title = "Straight to the Top", description = "There appears to be something sapping the arcane energies at the apex of the tower. \n\nNow that you've stabilized the energies down here, you should be able to \"ride\" the arcane magics in the area.\n\nLook in that bag of yours for something called an arcane stepping stone, and use it to meet me at the top.", objectives = "Look through the Bag of Helpful Goods for the Arcane Stepping Stone, then use at an arcane focus point to reach the top of the Azure Archives.", progress = "It's a long way down from here. Be careful.", completion = "It's a bit worse up here than I had anticipated!" }
WordHunterWoW_QuestEN[65854] = { title = "Reclaiming the Oathstone", description = "Fine work, friend. It seems we've managed to repair the leylines within the Azure Archives.\n\nBack when the blue dragonflight was united, I would tell my brothers and sisters to never doubt the strength of mortals.\n\nMeet me at the oathstone to the south of here. I will reclaim it, and then be on my way to Thaldraszus.", objectives = "Witness Kalecgos reclaim the Azure Oathstone.", completion = "It is good to be back... or reactivated, as it were. \n\nThere is much to do, and I am glad to give whatever aid I can." }
WordHunterWoW_QuestEN[65855] = { title = "Aiding Azure Span", description = "The oathstone's energy cannot be reclaimed until the ley lines within the Azure Span are repaired.\n\nSome ley lines may only be reachable by those of Kalecgos's skills... but you may still be of aid.\n\nIf they still yet survive, seek out the tuskarr. They lived here in my times and have a deep knowledge of the land.\n\nSpeak with one of our arcane aids to return to your allies.", objectives = "Return to Noriko the All-Remembering in Camp Antonidas.", progress = "What can I do for you?", completion = "The tuskarr? There are a number of tuskarr merchants and travellers who pass through here." }
WordHunterWoW_QuestEN[65863] = { title = "Transitioning Spawns Demo", description = "", objectives = "" }
WordHunterWoW_QuestEN[65864] = { title = "Catch the Caravan", description = "You should catch up with Brena. Her caravan passed through no more than a few hours ago.\n\nThey were collecting our late chieftain's most prized possessions for a funeral to honor him.\n\nGiven that the caravan was heavily burdened, she can't be far ahead.", objectives = "Catch up with Brena near the Big Tree Hills.", progress = "I've got you, Hanu.", completion = "The gnolls were ruthless in their assault.\n\nThey hit us hard and fast and took everything that wasn't nailed down." }
WordHunterWoW_QuestEN[65865] = { title = "They've Got Us Pinned Down!", description = "These gnoll sharpshooters are ruthless... and surprisingly accurate.\n\nWe cannot even consider heading into the Big Tree Hills while they have their weapons trained on us.\n\nThin our their ranks and show them that we will not be used for target practice!", objectives = "Kill Gnoll Sharpshooters." }
WordHunterWoW_QuestEN[65866] = { title = "Snap the Traps", description = "The hills ahead are littered with insidious bladejaw traps.\n\nWith a keen eye, you should be able to locate them. Very carefully spring the traps using this old tuskarr trick: a long stick. Note that while stepping on them is another way to set the traps off, I wouldn't recommend it.\n\nOnce enough have been removed, find Hanu. Elder Poa and I will catch up when we can.", objectives = "Spring 5 Bladejaw Traps.", completion = "Well done. It will be safer for Brena to make her way here." }
WordHunterWoW_QuestEN[65867] = { title = "Howling in the Big Tree Hills", description = "The gnolls that attacked our caravan were led by three lieutenants.\n\nDurgun was flanked by a dozen hyenas.\n\nKerwal cackled maniacally each time we tried to pursue him and fell for one of his steel-jawed traps.\n\nBakra taunted us, mercilessly.\n\nTo have a hope in recovering what was stolen, they must be slain.", objectives = "Slay Durgun, Kerwal, and Bakra.", progress = "<Hanu stares at you intently.>", completion = "Good, you did what I could not. \n\nBut there is another gnoll leading the Shadepaw... more terrifying than the three you encountered." }
WordHunterWoW_QuestEN[65868] = { title = "Those Aren't for Chewing", description = "I found one of Ponoliak's funerary offerings, mishandled and then discarded by these Shadepaw gnolls... It has bite marks all over it!\n\nThis offering, and others like it, are needed for the memorial ceremony for the recently deceased Iskaara chieftain.\n\nIt's a travesty that something so sacred should be employed as a chew toy. Please keep an eye out for more offerings.", objectives = "Recover 8 Funerary Offerings.", progress = "<Hanu leans forward and gazes into your pack hopefully.>", completion = "<Hanu's nose crinkles.>\n\nUgh... slathered in slobber.\n\nThey will have to suffice for the chieftain's memorial." }
WordHunterWoW_QuestEN[65869] = { title = "Another Ambush", description = "A tragedy. And potentially the first of many more.\n\nFind out what Akiun knows, then examine anyone who fell in the attack. \n\nI have my hunches about what happened here. Let's see if the clues support my theory.\n\nMeanwhile, I'll try to reassure my rattled friends.", objectives = "Speak to Akiun and examine 4 nearby corpses.", progress = "We must pinpoint the source of this gnoll aggression, before they can do any more damage.", completion = "This is truly a tragedy... but at least we can follow the clues.\n\nWe are getting closer to the source of this rot." }
WordHunterWoW_QuestEN[65870] = { title = "Supplies!", description = "There was no sign of our stolen hunting supplies in the Big Tree Hills. They must be in that cave.\n\nKeep an eye out for the supply containers, and be prepared for anything.\n\nI would not trust the gnolls to leave the goods unprotected.", objectives = "Recover the caches of hunting supplies.", progress = "I'd hate for Iskaara to go hungry...", completion = "<Elder Poa looks approvingly at the supplies you've recovered.>\n\nThe Iskaara tuskarr will hunt again." }
WordHunterWoW_QuestEN[65871] = { title = "Gnoll Way Out", description = "I've tracked the captured tuskarr, including my husband Norukk, to this cave. \n\nNorukk doesn't always look out for his own hide, so that responsibility falls to me. But I'm not too proud to ask for help.\n\nPlease rescue them!", objectives = "Rescue Norukk and 3 other captive tuskarr.", progress = "We can't leave our brothers and sisters behind!", completion = "<Hanu wrinkles her cheeks and shoots a tusky grin at Norukk.>\n\nI'm beyond relieved that Norukk made it out alive. We will mourn those we lost once we return to Iskaara." }
WordHunterWoW_QuestEN[65872] = { title = "Ill Gnolls with Ill Intent", description = "I'm catching a strange scent on the wind. Something here isn't right...\n\nHanu described the gnolls in this cave as strange... and sickly. We should learn more about what is causing this.\n\nDon't let your guard down. Despite their sickly appearance, expect them to be just as devious and dangerous.", objectives = "Kill 16 Shadepaw gnolls in Kargpaw's Den.", completion = "We have never seen rot take on a form like this.\n\nThis is troubling." }
WordHunterWoW_QuestEN[65873] = { title = "Leader of the Shadepaw Pack", description = "Kargpaw is the true leader of the gnolls in this part of the forest. We've had... unpleasant encounters with him in the past.\n\nThis time was different. He carried a strange totem that seemed to twist his very essence.\n\nKargpaw must be stopped and this totem recovered. I fear the gnolls are meddling in something darker than we can imagine.", objectives = "Kill Kargpaw and recover his totem.", progress = "Did you recover Kargpaw's totem?", completion = "<Brena recoils in disgust as she accepts the totem.>\n\nKargpaw was always violent, but he was also a coward. He and his band never attacked us if we traveled in large numbers.\n\nSomething has changed... and this totem is behind it." }
WordHunterWoW_QuestEN[65874] = { title = "A Rotten Revelation", description = "Hmm...\n\n<Brel peers intently at the strange totem, turning it over in her thick hands.>\n\nWe've got to put our whiskers together and determine what this means.", objectives = "Speak with Hanu, Elder Poa, and Norukk." }
WordHunterWoW_QuestEN[65875] = { title = "A Dragon's Day Off", description = "A lifetime spent in Outland... always fighting. So little time to relax!\n\nSometimes a dragon just needs a day off by the sea with a cold, cold drink in their claws.\n\nHey, maybe you can help me relax! Do me a favor and see if you can find a few of these drinks to refresh our supply here.", objectives = "Locate the various drinks for Vazallia.", progress = "Have fetched my beverages yet? No? That's too bad.", completion = "Yes! Time to kick back and relax!" }
WordHunterWoW_QuestEN[65877] = { title = "Food for the Road", description = "", objectives = "" }
WordHunterWoW_QuestEN[65878] = { title = "Heightened Senses", description = "", objectives = "" }
WordHunterWoW_QuestEN[65879] = { title = "Path of the Plainshunter", description = "", objectives = "" }
WordHunterWoW_QuestEN[65880] = { title = "Path of the Hunter", description = "", objectives = "" }
WordHunterWoW_QuestEN[65881] = { title = "The Great Hunt Begins", description = "Slay the great beast!", objectives = "" }
WordHunterWoW_QuestEN[65882] = { title = "Ways of Old", description = "The mystic awaits.", objectives = "" }
WordHunterWoW_QuestEN[65883] = { title = "Essence of Awakening", description = "The Awakened maintain the truest of sights here within the plains, but the journey is only temporary.\n\nSearch too long and one may be lost forever.", objectives = "" }
WordHunterWoW_QuestEN[65886] = { title = "To Rhonin's Shield", description = "Raszageth and the Primalists are launching an all out assault on Vakthros. We cannot let her succeed!\n\nKhadgar and I will go ahead to handle the situation there from the sky.\n\nIn the meantime, make your way to the Rhonin's Shield, one of the last Kirin Tor camps in the area.\n\nYou may be able to get there faster by riding that drake of yours from the top of the archives.\n\nSee that the Kirin Tor there are all right, then make your way to Vakthros.\n\nWe'll be counting on your help from the ground.", objectives = "Meet with Drok Scrollstabber in the Tower Outlook.", completion = "I saw Kalecgos and Khadgar go towards the mountains a moment ago. We're holding our own against the Primalists here, but we can always use more help!" }
WordHunterWoW_QuestEN[65887] = { title = "To the Mountain", description = "It's a sight to behold up there, Khadgar and Kalecgos fighting the Primalists in the sky!\n\nThey've summoned several mirror images of themselves to help you through the monstrous hole the Primalists have created.\n\nOne pair is at the base of the mountains right now. \n\nIf things start to look bad... well I'll get the word out to the rest of us in the Azure Span.", objectives = "Meet Khadgar and Kalecgos's mirror images at the base of Vakthros Range.", completion = "This is worse than I could have expected. There's no time to lose." }
WordHunterWoW_QuestEN[65890] = { title = "The Nelthazan Ruins", description = "The Dragonscale Expedition requires your assistance.\n\nA skyscribe was sent to the ruins to gather information. They should be uninhabited, but I can hear his shouting from over here.\n\nHe must be in dire circumstances for it to be audible at this distance.\n\nOn this expedition, we take care of our own. Even the insufferable ones. Seek him out and protect him from whatever danger he has found.", objectives = "Meet Skyscribe Adenedal at the Nelthazan Ruins.", completion = "Well of course I am shouting! The book will not listen. What else am I to do?" }
WordHunterWoW_QuestEN[65891] = { title = "Tools of the Tirade", description = "Good. I was just thinking that I am in need of an adventurer like you. Strong. Sturdy. Willing to work for a trivial sum.\n\nIt is as if I willed you into existence. Well done, me. These ruins seem to have brought the attention of others. We cannot rely on them to excavate it properly. They will taint the samples!\n\nTake this. Deploy it around artifacts of interest around the ruins. It is enchanted to perform any necessary duty.", objectives = "Deploy the enchanted tools to 5 piles of rubble.", progress = "I think I shall write a bit of poetry. Or, rather, instruct the book to write it for me.", completion = "We will gather everything in time." }
WordHunterWoW_QuestEN[65892] = { title = "The Sundered Asunder", description = "", objectives = "" }
WordHunterWoW_QuestEN[65893] = { title = "The Relic Inquiry", description = "The Sundered Flame are here. Would you trust anyone claiming to be sundered with precious artifacts?\n\nI did not think so. Regardless, we need to know what they are here for if we are to proceed. Gather what you can recover from them and report back to me with your findings.\n\nThere are more pieces to this puzzle than what we will find in the ground.", objectives = "Gather 60 Nelthazan Artifact Fragments.", progress = "These ruins are ruined enough.", completion = "They are still looking for something? Then why did you bring me this garbage?\n\nWe have to find it before they do!" }
WordHunterWoW_QuestEN[65895] = { title = "Competing Company", description = "Bah! We will learn nothing from the slaughter of laborers.\n\nSeek out their leaders. One of them will know what we need.\n\nOh, and {name}. Listen to them before you kill them this time. You may learn something useful.", objectives = "Gather information about the Sundered Flame.", progress = "What have you learned?", completion = "I have seen a sickness like this once before in my life. I had hoped to never see it again." }
WordHunterWoW_QuestEN[65896] = { title = "Let the Healing Begin", description = "Do you think you would be able to step into this city without me noticing? No!\n\nI was right about your kind before and I'll be damned before I let dragons destroy my home again.\n\nThis once was a park filled with joy and peace. Then your progenitor, Deathwing, came. Oh yes, I know all about him. \n\nSee for yourself the legacy of destruction that was left behind. The pain that walks these streets still.", objectives = "Help the people of Stormwind heal.", completion = "You have given me the most wonderful gift today. You have shown me that my city is ready to heal. That our legacies are still in our control.\n\nGo forth with honor, friend." }
WordHunterWoW_QuestEN[65898] = { title = "Proto Problems", description = "I hold no love for the Sundered Flame, but even I cannot stand idle while they rip themselves apart like this. It is all too familiar.\n\nWhatever this Locus is, it is safer in our hands than in their clutches. Follow the trail of bodies and I suspect we will find it.\n\nDo be careful, {name}. I worry we will find that the nest is not quite as abandoned as it appears.", objectives = "Acquire the Locus and defeat the protodrake that protects it.", progress = "I am glad you made it out safely. Do you have the Locus?", completion = "Thank you, <name>.\n\nYou have been most helpful." }
WordHunterWoW_QuestEN[65899] = { title = "Find Theramus", description = "{race}! Are you here to visit the beautiful Lilac Ramble? I'm so sorry about its current state. I promise it's not usually this untended!\n\nTheramus, the garden's keeper, was supposed to meet us today and tackle the issues together. He's been struggling with the upkeep lately, so Felina and I are helping out. But we can't do it all.\n\nWould you help us look around for him? Maybe he did forget.", objectives = "Search the nearby caves and find Theramus.", completion = "You found him! It looks like he's really down in the dumps today." }
WordHunterWoW_QuestEN[65900] = { title = "Suspiciously Spiced Steak", description = "My sister's idea is charming, but Theramus needs a real pick-me-up.\n\nThat would be a generous serving of sourbloom. We can make it into a paste to slather onto his favorite food: turtle meat!\n\nWill you help me collect the ingredients?", objectives = "Collect 2 Perfectly Tender Turtle Meat, 6 Reptilian Eggshells, and 15 Sourbloom.", progress = "Do you know why sourbloom grow under the coastal trees?\n\nThe tree roots trap an abundance of nutrients from the waves, which then feed the sourbloom. This gives them incredible nutritious value.", completion = "The meat to sourbloom ratio is just right." }
WordHunterWoW_QuestEN[65901] = { title = "Sneaking Out", description = "I'm grounded indefinitely! Doesn't my Ohn know I'm turning sixteen next spring? I should be able to leave when I want to.\n\nYou look like you could help me out. I do have an escape plan: by channeling these totems, I'll concentrate the air and create quite a stir. But I can't go around placing them, because I'm under maximum wind watch. Even Togo won't help me.\n\nBut with your help... Please! I promise I'll show you something cool.", objectives = "Place the air totems in Ohn'iri Springs and then inform Radiya.", progress = "If you rat me out, I'll haunt you with the windiest ghost--FOREVER! Don't do it!", completion = "Whew, thank you! Freedom!" }
WordHunterWoW_QuestEN[65902] = { title = "Food or Floof", description = "Look at this juicy and delectable herbed turtle meat! I speak objectively, of course. I'm a vegetarian.\n\nGo on! He probably hasn't had a meal all day.", objectives = "Bring the Herbed Turtle Meat and Glade Hoppers to Theramus.", progress = "Go, before the meat gets old!", completion = "Oh dear. We heard his outburst. Are you okay?" }
WordHunterWoW_QuestEN[65903] = { title = "Can't Beat Fluffy", description = "Poor Theramus. I have an idea to cheer him up!\n\nTake this net to catch some of the native hoppers, which are docile but quick. They've made quite a home by the coast.\n\nWe'll bring them to Theramus. He'll literally be overrun with fluffy goodness!", objectives = "Catch 12 Glade Hoppers.", progress = "They are impossibly soft! I could spend all day petting them.", completion = "So! Many! Hoppers! Let's pet them all!" }
WordHunterWoW_QuestEN[65904] = { title = "Enough Is Enough", description = "Grumpy or not, Theramus has a job to do. While he hides inside, he can't see the consequences of his absence.\n\nLet's go together. We'll show him the evidence.", objectives = "Bring the evidence of Lilac Ramble's damage to Theramus.", progress = "This would convince anyone that the grove needs help, now!", completion = "...I think it worked? He left the cave!" }
WordHunterWoW_QuestEN[65905] = { title = "More Than Weeds", description = "Perhaps it's best we give Theramus some space. \n\nBut we can't be idle. The grove is destroying itself at a rapid rate! Please help us out.", objectives = "Clear out overgrowth and monsters in Lilac Ramble.", completion = "Thank you, <race>." }
WordHunterWoW_QuestEN[65906] = { title = "A Disgruntled Initiate", description = "I received an interesting letter from Ohn'iri Springs.\n\nAs for the letter's contents, it details, quote, horrid imprisonment, controlling mentors, and extreme boredom. It is formally signed by Initiate Radiya. There's also a sketch of an eagle... kicking a centaur named Meluun off a cliff.\n\nWell. I suppose this is a call for help, if you are so inclined to see for yourself. To be frank, I think Radiya is probably okay. She sends me such letters often.", objectives = "Speak to Initiate Radiya at Ohn'iri Springs in the Ohn'ahran Plains.", completion = "Who are you? Ordven sent you? He actually reads my letters?!\n\n<Radiya snorts with surprise and pleasure.> Thank Ohn'ara!" }
WordHunterWoW_QuestEN[65907] = { title = "Favorite Fruit", description = "Mystic training is so boring. I'm watching water be wet half of my days. My brothers are already out in the wild hunting drakes and primalists, and making a difference in the world.\n\nAnyway, I promised I'd show you something cool! Did you know mudstompers love bushfruit? It grows nearby, among the geysers. Go pick some and we can feed them together.", objectives = "Forage Wild Bushfruit from the Ohn'ir Geysers and feed them to 6 Lounging Mudstompers.", progress = "I used to really like bushfruit until I had too much one day.\n\nMy whole body was shivering, like a bad cold, and my breath was minty for days after.", completion = "Seems like they like you! Or just the fruit. That's okay too. <Radiya winks.>" }
WordHunterWoW_QuestEN[65911] = { title = "Azure Alignment", description = "The bonds of this community... the friendship and family they share. \n\nI... never had that. The blue dragonflight never had that. And maybe that's because we haven't had a chance to. \n\nNow is the time. I must gather my kind. \n\nMeet me at the Azure Archives. There is much to be done.", objectives = "Return to Kalecgos in the Azure Archives.", completion = "I never expected to learn so much from the tuskarr. I think I'll visit when I can, and maintain those bonds of friendship." }
WordHunterWoW_QuestEN[65913] = { title = "Wotcher, Watcher?", description = "Thank the Titans! {class}, we need your help!\n\nPrimalists attacked only moments ago. My sisters and I were able to defend, but at a severe loss...\n\nThere will be time to mourn after my watcher is safe! A group of Primalists broke away while we were fighting and I swear if they hurt our Watcher--\n\nYou must help her before it's too late!", objectives = "Rescue Watcher Mara from the Primalists in Tyrhold Reservoir.", completion = "Thank you, <race>. Were it not for your aid, I would have surely perished." }
WordHunterWoW_QuestEN[65914] = { title = "Mammoths Matter", description = "Our tribe has proudly nurtured the On'tuq mammoth herd for generations. Now they're... gone. \n\nTheir souls will linger in rage, after such a massacre. We must honor their lives by making good use of their remains.\n\nThere's too many for us to gather alone. Please, gather what materials you can from the youngsters and matriarchs, then meet me in the Kauriq Gleamlet.", objectives = "Collect On'tuq Hide Scraps and On'tuq Tusks from fallen On'tuq Mammoths near the Kauriq Gleamlet.", progress = "My children had already picked out calves to foster into companions. How will I tell them?", completion = "With these remains, I think we can make something truly special... something that will put the souls of the mammoths at ease." }
WordHunterWoW_QuestEN[65916] = { title = "We Don't Negotiate with Primalists", description = "The Primalists thought they were able to overcome the might of Tyr. They were wrong. \n\nMy refti were able to track down the Primalists to a cave not far from here. As I thought, they have the missing keystones. \n\nChampion, if we are to restore the reservoir, we must get those keystones back.\n\nFurthermore, their leader must be slain so that they won't attempt a second assault.", objectives = "Slay Primalist Leader Ko'jo and retrieve the Missing Keystones in Tyrhold Reservoir.", progress = "Surely once we get the keystones back, Zuttiki will not look so... Dismal.", completion = "Thank you, <name>. Our final task of restoring the wards awaits." }
WordHunterWoW_QuestEN[65918] = { title = "Preventative Maintenance", description = "The Primal Elementals are reproducing unchecked. Ordinarily, my sisters and I would take care of them, but we're in no condition to fight them. We've had so many of our soldiers eliminated. \n\nBesides, we few that remain have other matters we must look into.\n \n<Zuttiki winces in pain.>\n\nThat's where you come in, {name}. Could you take care of the elementals?", objectives = "Kill 8 Unleashed Elementals in Tyrhold Reservoir.", progress = "Mara, my sisters? This wasn't supposed to happen.", completion = "Thank you, <name>. That should hold them at bay for now." }
WordHunterWoW_QuestEN[65920] = { title = "For the Ward!", description = "We can finally restore the wards. We have suffered great losses, but our work must be completed.\n\n{name}, we need your help once more. Bring each keystone to its rightful place in order to make the wards whole again. \n\nOnce that is done, come back, so we can activate the console and restore order in the reservoir.", objectives = "Use the Missing Keystones to repair the reservoir wards, then activate the console.", progress = "Once all three wards are repaired, return here to activate the ward console.", completion = "Excellent work, <name>. The wards have been restored, and Tyrhold Reservoir is once again protected. Thank you for all you have done. Thaldraszus owes you a great debt." }
WordHunterWoW_QuestEN[65921] = { title = "Refti Retribution", description = "I cannot get it out of my head, {name}. So many of my sisters massacred! Lives tossed away... Their sacrifices will not go unanswered!\n\nMy soldiers have tracked down the Primalists, and they say some of our sisters are still alive.\n\nWe must rescue them, and ensure every Primalist knows my anger!", objectives = "Kill Primalists and rescue refti in Tyrhold Reservoir.", progress = "I knew this day could always come, I just hoped that it would not.", completion = "I will always feel pain for those we lost, but I am thankful for the ones we rescued." }
WordHunterWoW_QuestEN[65925] = { title = "Culling the Cullers", description = "These wyrms don't belong here. I don't know what's driven them from their underground lairs, but there's no way to help them, now.\n\nWe can't allow them to destroy the native life here.\n\nSlay the wyrms, {name}. Keep their parts, if you must, and find me in the Gleamlet when you're done.", objectives = "Slay Ice Slitherers and Ice Borers near the Kauriq Gleamlet.", completion = "It's a pity to wipe out any natural life... even troublesome ones." }
WordHunterWoW_QuestEN[65926] = { title = "Tackling the Falls", description = "Have you heard the tale of the Gleamfisher? She built a boat strong enough to pass down waterfalls! \n\nElder Nava loves to tell the story.\n\nI think the noble spirits of the On'tuq mammoths would be honored if we used their remains to craft such a boat again.\n\nMy brother says no. But if we succeed, we can help bring fish to our struggling sister tribes.\n\nYou've proven your skill and passion! Together, I'm sure we can build something great.", objectives = "Help Ruriq build The Fallstrider.", completion = "Ruriq is as stubborn as ever." }
WordHunterWoW_QuestEN[65928] = { title = "Wayward Winds", description = "Bah! Work together, she says? \n\nBut... if the Gleamfisher believes there is a chance we can help the other tribes... we must try. \n\nFor the wind spirit Kraunot to acknowledge us, we will first have to tend to his element. The nearby wind elementals have been agitated ever since the land began to awaken.\n\nWhile I inspect this boat you two made, you go and fight to dismantle them, then bring me their restless motes. That should bring some calm back to the area.", objectives = "Collect 10 Restless Wind Motes from Restless Winds near the Kauriq Gleamlet.", progress = "Don't worry, these wind elementals being here simply means they are riled up. By destroying them, we will restore some peace to the winds here.", completion = "I will tend to these motes, so they dissipate harmlessly. Kraunot will be pleased." }
WordHunterWoW_QuestEN[65929] = { title = "Ice Breakers", description = "I knew the ancestor would approve!\n\nI don't know much about spirits -- Kauj is the shaman. But we will need to appease the great Spirits of Air and Water before they will appear to us. \n\nAnyone could see water elementals up the mountain slowly freezing. It is not a natural freeze. Cold has been coming down the mountains more than usual, lately. Left be, our entire river could ice over.\n\nRelease them from their icy prisons!", objectives = "Break Freezing Waters from ice near the Kauriq Gleamlet.", progress = "We welcome the natural shift of the earth, but this encroaching ice... it threatens our entire home.", completion = "Excellent. Otu'rorq, the local River Spirit, will be pleased to know his river will continue to flow, for now." }
WordHunterWoW_QuestEN[65930] = { title = "A Wrestle of Wind and Water", description = "Now we should be able to face the Spirits.\n\nDid Ruriq fail to mention it? By our tribe's traditions, we must face the Spirits in combat before asking a boon of them. The strength of their blessing is dependent on how well you impress them. \n\nPerhaps that is why the Gleamfisher insisted we all work together.\n\nIf you take on Kraunot, the Spirit of Air, Ruriq and I will tackle Otu'rorq, the Spirit of Water.\n\nThey dwell in the cave behind the nearby waterfall. We will meet you there, adventurer.", objectives = "Face Kraunot, the Spirit of Air, near the Kauriq Gleamlet.", progress = "We must impress those spirits if Ruriq's vision is to come to life.", completion = "With how much older he is, Kauj has always been almost... more a father than a brother. \n\nI thought getting older and starting my own family would make me feel less like I needed him. \n\nI was wrong. Even before my wife passed, I was wrong." }
WordHunterWoW_QuestEN[65935] = { title = "Catching Up to Chromie", description = "You have helped us regain our hold on the sands, but I can sense something greater happening up on the temple platforms. Let us take to the skies and regroup with Ambassador Chronormu there.\n\nAs always, time is of the essence.", objectives = "Meet with Chromie on the Temporal Conflux platforms.", completion = "About time! Eternus might look frozen in that bubble, but she's struggling with all her might to get free." }
WordHunterWoW_QuestEN[65937] = { title = "Proof of Negligence", description = "We can't give up. He must understand what's happening out here! If he won't leave the cave, we'll show him directly.\n\nAnything will do, I'm sure. There's so much going wrong, from the corrupted flora to the antagonized wildlife!", objectives = "Find and then show evidence of the Lilac Ramble's damage to Theramus.", progress = "It's terrible to see the grove, and Theramus, in such a state.", completion = "You've returned!" }
WordHunterWoW_QuestEN[65938] = { title = "The Once and Future Team", description = "All right! Let's pop that stasis bubble around the temple doors and release our Wardens! Are you ready for a huge tug-of-war match with time itself?\n\nYank at the door's bubble like you did with the crystals earlier. But be careful, all the time energy released is sure to collect and attack you. I'm not sure what will be there, but at least you'll have the freed Wardens on your side no matter what happens.\n\nGood luck, {name}!", objectives = "Use your Timewalker Staff to pop the temple door's stasis bubble.", progress = "We really should've foreseen this when we built our security system all that time ago...", completion = "That's the second largest time elemental I've ever seen! I knew I should have packed my S.E.L.F.I.E Camera today.\n\nOh well! I'll just stop by this moment again on my next day off." }
WordHunterWoW_QuestEN[65939] = { title = "The Courage of One's Convictions", description = "The next battle will no doubt be fierce, but our courage and determination will overcome their greater numbers.\n\nI am counting on your exceptional skills to help lead the troops to victory.\n\nWe shall begin the assault when you are ready.", objectives = "Gain control of the Obsidian Citadel.", progress = "Have we secured the Citadel.", completion = "Excellent, <name>! The djaradin forces are on the run! We control the upper courtyard of the citadel. However, the vaults below may take much longer to secure." }
WordHunterWoW_QuestEN[65940] = { title = "By Broken Road", description = "I hope you don't mind getting your feet wet. The next leg of our journey will take us across two rivers.\n\nOhn Seshteng would like to share a story with you about our blessed watcher, Ohn'ahra. I happily leave you under her watch.", objectives = "Travel with the Shikaar caravan to the river crossing.", completion = "I sense something on the wind." }
WordHunterWoW_QuestEN[65943] = { title = "Primal Offensive", description = "Khadgar and I are doing our best to hold off the Primalists in the sky, but we can't push further towards the tower.\n\nWe need you to weaken their ground forces so we can get closer to Raszageth and stop her before it's too late.\n\nMake your way through the Primalists ahead. If I can maintain my concentration, there'll be another mirror image waiting.", objectives = "Defeat 15 Primalists within Vakthros.", completion = "Good work, some of their forces are diverting from above." }
WordHunterWoW_QuestEN[65944] = { title = "Lava Burst", description = "The Primalists have torn apart the mountain to send their forces streaming to Vakthros!\n\nI spied some lava orbs in the initial corridor that they're using to spread more of their elemental chaos.\n\nDestroy them to help slow their advance. I'll do what I can from up here to help Kalecgos.", objectives = "Destroy 3 Lava Orbs.", completion = "That should slow them down a bit. It seems I'm getting a bit rusty compared to the fight with the Burning Legion..." }
WordHunterWoW_QuestEN[65947] = { title = "Time-Locked Timewalkers", description = "I'm so glad you're here! I need you to stabilize the situation here on the platforms while Dante and Zera help me hold our infinite dragon friend in place.\n\nThe temple's security measures locked Eternus in a stasis bubble when she tried to take control of our Oathstone. Unfortunately, the other Timewalkers were also caught in those security measures.\n\nYour Timewalker staff should free them, no problem. Just make sure to deal with any angry timelings that pop up!", objectives = "Free 8 Timewalkers from Time Bubbles.", progress = "We can't have our Temple visitors rest inside of stasis bubbles when they get here.\n\nOh, wait! Maybe that's exactly what we should do! I'll write it down for later, <name>.", completion = "It worked? I'm not surprised... not entirely, at least!" }
WordHunterWoW_QuestEN[65948] = { title = "Cracks in Time", description = "When the temple locked down, the Wardens got sealed up with the temple doors. We need to pop that stasis bubble to get them out! Unfortunately, that'll need a fully empowered Timewalker staff...\n\nI know! You can drain the crystals here on the platforms! That should power up your staff enough.\n\nThey have their own stasis fields, so just yank them out and absorb their energy with your staff.\n\nAnd don't feel bad if they shatter--the power is still there, even if it's in pieces!", objectives = "Use the East and West crystals to further empower your Timewalker Staff.", completion = "Excellent work!\n\nYou should be cooking with more than enough time juice to release the Wardens now!" }
WordHunterWoW_QuestEN[65949] = { title = "The Sole Mender", description = "When we join Ohn'ahra in the wind, we leave these medallions behind.\n\nAlthough I helped craft this medallion, I am not its rightful owner.\n\nIt should be returned to Roscha. It is the last memory of her betrothed.\n\nTake it to her so she may mourn and be at peace.", objectives = "Return the Medallion to Farrier Roscha.\n\nProvided item:", completion = "Is this... ah. It is. My beloved is in the sky, then, running with Ohn'ahra. I will join her... in time.\n\nThank you, <name>. \n\nI will remember what you have done for Clan Shikaar. And for me." }
WordHunterWoW_QuestEN[65950] = { title = "Thieving Gorlocs", description = "Is Farrier Roscha invited to the caravan? No! But who must provide shoes for the caravan? Farrier Roscha. And from whom do the Mudfins steal? Of course, Farrier Roscha. Pah.\n\nI would send Khasar, but who knows where he has wandered this time? \n\nFind my supplies. Teach those thieving creatures not to steal from Farrier Roscha.\n\nGo!", objectives = "Return the stolen supplies from the Mudfin Village.", progress = "There are too many gorlocs around us. We're not safe here.", completion = "Roscha sent you? She must be furious.\n\nShe has been through so much already. I could not return without securing all that was lost." }
WordHunterWoW_QuestEN[65951] = { title = "Sole Supplier", description = "Poor Roscha! She has toiled endlessly to prepare for the caravan, only for her supplies to be stolen by nasty gorlocs. \n\nShe has lost so much already. I am doing my best to assist her. \n\nKhasar likely went after her supplies alone, telling no one. It is his way. But he has been gone too long. Many dogs are missing as well. \n\nWould you please check on Khasar and the dogs, {name}?", objectives = "Search the woods for Khasar.", completion = "Thank you, <name>. Let's get to work." }
WordHunterWoW_QuestEN[65952] = { title = "A Chief of Legends", description = "The gorlocs of this swamp were once simple creatures. Pests, perhaps, but never raiders, thieves, or dog-eaters.\n\nIt is their chief, Grrlgllmesh, who has led them away from their nature.\n\nPut an end to him, and the gorlocs will threaten us no more.", objectives = "Kill Chief Grrlgllmesh.", progress = "Chief Grrlgllmesh is a scourge to these lands.", completion = "With their chieftain slain, the gorlocs will no longer bother us. \n\nI am astounded by how strong they became under Chief Grrlgllmesh. \n\nI have never seen such primitive creatures rise up against a mighty civilization like ours before. Are we not so different? So much further evolved? I suppose not..." }
WordHunterWoW_QuestEN[65953] = { title = "The Ora-cull", description = "Of all the madness in this gorloc village, I have discovered none so troubling as the gorloc shamans.\n\nThey are particularly vicious and play recklessly with storm magic with no regard for the consequences. \n\nThis must be put to an end. Slay them, and bring me their totems. Our mystics will be interested in them.", objectives = "Collect 4 totems from gorloc shamans.", progress = "The gorloc shamans have gone too far.", completion = "<Khasar frowns at the totems.>\n\nThese totems are for storm magic. Storm magic is sacrilege to the gift of winds given by Ohn'ahra herself.\n\nI will deliver these to the mystics." }
WordHunterWoW_QuestEN[65954] = { title = "Release the Hounds", description = "I have heard the familiar howls and barks of bakar that are missing from camp.\n\nOur beloved dogs are trapped in cages, waiting to be ripped apart by those... those things.\n\nWe have a duty to our companions. Free them and witness the true might of a Shikaar bakar!", objectives = "Free the Shikaar Bakar.", progress = "The gorlocs of this village will learn to fear our bakar.", completion = "Magnificent beasts, aren't they?\n\nEvery bakar holds a special place in Clan Shikaar. They are our fellow hunters, guards, and our most cherished friends." }
WordHunterWoW_QuestEN[65955] = { title = "A Centaur's Best Friend", description = "It isn't safe for us to remain in the open, {name}.\n\nThe gorlocs forced my hunting companion, Baba, into a cave to the east.\n\nSet me free, then we shall rescue Baba. I will meet you in the cave when the path is clear.", objectives = "Free Khasar and meet him in the cave.", progress = "Together, Baba and I are one hunting unit greater than all the rest.", completion = "Thank you, <name>. We are safe in here and can speak freely. \n\nI will protect Baba from any gorlocs that dare venture in while he rests." }
WordHunterWoW_QuestEN[65956] = { title = "Talon Strike", description = "With your help, my Blacktalon assassins will cut down the djaradin defending the outer perimeter. Mark any targets with a small stun bomb, and they will come to your aid.\n\nProceed quickly and eliminate anything that may hinder our advance.", objectives = "Djaradin defenses disrupted.", progress = "Have you eliminated their defenses?", completion = "Our advance is pushing them back! All that remains is to breach the gates." }
WordHunterWoW_QuestEN[65957] = { title = "No Time for Heroes", description = "From what we have observed, djaradin society is built on strength. The strongest serve as examples for others to fight all the harder. \n\nAmong the forces below are three examples of the mightiest djaradin... and your targets.\n\nYou, {name}, will personally eliminate them. This should deal a devastating blow to their morale.", objectives = "Slay Modak the Flamespit, Piercer Gigra, and Olphis the Molten.", progress = "Have you defeated your targets?", completion = "You've proven yourself the true hero of the day, <name>." }
WordHunterWoW_QuestEN[65958] = { title = "Primal Power", description = "I'm afraid it's becoming harder to maintain my mirror images. The Primalists are focusing their efforts to tearing me out from the sky.\n\nNot to worry... I have a plan.\n\nI need you to take the orb you recovered and gather elemental magic from slain Primalists. \n\nWe'll need that elemental power up ahead to divert their forces away from me.", objectives = "Use the Elemental Focus to drain elemental energy out of slain Primalists and elementals.", progress = "We must act quickly.", completion = "That orb is brimming with power! That will be perfect for what's next." }
WordHunterWoW_QuestEN[65962] = { title = "The Never-Final Countdown", description = "I never thought I'd save our temple by dismantling the very security we set up to protect it, but here we are!\n\nWith the time elementals purged, our Timewalkers free, and our Wardens at the ready, it's finally time to let this last stasis bubble down and deal with Eternus.\n\nLet me know when you're ready. I know with you by my side nothing can go wrong.", objectives = "Speak to Chromie when ready.", completion = "Eternus and Chromie have fallen through space and time. We must retrieve them at all costs!" }
WordHunterWoW_QuestEN[65977] = { title = "Kirin Tor Recovery", description = "When the Primalists attacked our expedition, I feared many of our mages were lost to us.\n\nIt seems they were taken by the Primalists and are being tortured as we speak!\n\nPlease, you must rescue the mages left here. They may not be able to help in this fight, but we cannot leave them behind!", objectives = "Rescue 6 Dying Mages.", progress = "We must aid those mages.", completion = "You have my thanks. We cannot forsake anyone in this fight." }
WordHunterWoW_QuestEN[65989] = { title = "Invader Djaradin", description = "We may not have the power to take back our outpost, but we do not have to surrender without a fight.\n\nShow them we still have teeth.", objectives = "Kill 6 djaradin at the Dragonheart Outpost.", progress = "The djaradin had not been seen for generations. We were... unprepared.", completion = "Wonderful." }
WordHunterWoW_QuestEN[65990] = { title = "Deliver Whelps From Evil", description = "They descended upon us before we could even respond. My guards held as long as they could as we evacuated the young and helpless, but I fear that there are more within the outpost.\n\nCross that bridge and search for survivors.", objectives = "Save 4 Whimpering Whelplings from Dragonheart Outpost.", progress = "We will take back the town as soon as we can muster the forces... but for now, the lives of our people must be our priority.", completion = "We cannot rest yet, but I breathe easier knowing we have rescued them. Thank you." }
WordHunterWoW_QuestEN[65991] = { title = "Time for a Reckoning", description = "Cadet Sendrax has informed me of our majordomo's plans. Thank the Life-Binder that we have their help. Their interference gives us the reprieve we need to get our wounded back to the Life Pools to be treated.\n\nI wish I could reinforce Selistra but I must keep my guards near the wounded. Go to the enemy stronghold to meet them. \n\nIf there were another way of handling the djaradin, I would ask it. But, as it were...\n\nYou must do what you must.", objectives = "Meet Wrathion and Majordomo Selistra at Scalecracker Keep.", completion = "It does my heart well to hear such good news from Dragonheart Outpost during such a terrible time. The refugees will be safe at the Life Pools.\n\nEven the djaradin would not raise arms against the might of Queen Alexstrasza herself." }
WordHunterWoW_QuestEN[65992] = { title = "Blacktalon Intel", description = "While Selistra and I attracted their eyes above, shadows crept in through their defenses.\n\nMy agents, the Blacktalon, are keeping an eye and an ear throughout the keep. Meet them and let them know you're on our side. They'll give you some valuable information on our enemies.", objectives = "Speak to Wrathion's spies hidden around Scalecracker Keep.", progress = "I've put my life in their hands. You can trust them.", completion = "That is troubling, to say the least. Yet another reason to fight them." }
WordHunterWoW_QuestEN[65993] = { title = "Killjoy", description = "Ah, yes.\n\nI saw the leader of these giants headed back from the raid shortly after I arrived. She's celebrating their victory somewhere within the camp. \n\nIt would be a shame if someone interrupted her revelries, don't you think?", objectives = "Kill Meatgrinder Sotok at Scalecracker Keep.", completion = "The djaradin seem to have no shortage of bodies to throw in our way... but perhaps this blow shall give them pause. Well done, friend." }
WordHunterWoW_QuestEN[65994] = { title = "Djaradin Djustice", description = "", objectives = "" }
WordHunterWoW_QuestEN[65995] = { title = "The Obsidian Citadel", description = "<At a glance, this seems to be internal communications between djaradin camps.\n\nThe words 'Obsidian Citadel' leap out at you.\n\nPerhaps Wrathion would be interested in seeing this.>", objectives = "Give the Qalashi Plans to Wrathion.\n\nProvided item:", completion = "A treat! I love seeing into the minds of my enemies. Helps me strike fast, strike true.\n\nLet's see...\n\nThe Obsidian Citadel?\n\nNo.\n\nNo!" }
WordHunterWoW_QuestEN[65996] = { title = "Veteran Reinforcements", description = "Commander Lethanak was insightful, as always. We will need the help of our most veteran guards to stop their threat. Rallying them was the perfect task for a young cadet like Sendrax, but she may need support.\n\nSendrax's path will take her towards the west, which may have been overwhelmed by this rising threat. They will need aid as well. Take this concoction and give them your support.", objectives = "Help the injured guards and find Sendrax.", progress = "We are all in this together, <name>. The safety of the isles is at stake.", completion = "Sendrax stopped by and rushed through. That one is a whirlwind.\n\nI like her." }
WordHunterWoW_QuestEN[65997] = { title = "Chasing Sendrax", description = "Cadet Sendrax came through here not long ago.\n\nShe relayed Commander Lethanak's orders for all drakonid to rally back at the Life Pools. Our whole defensive regiment set off in that direction not long after.\n\nBut our scouts were out on patrol in the old ruins, so she headed in there to rally them too.", objectives = "Find Sendrax in the Life-Binder Conservatory ruins.", progress = "Keep low, <name>.", completion = "I haven't read anything in the archives about the Primalists stealing dragon eggs before.\n\nThis is bad. Very bad." }
WordHunterWoW_QuestEN[65998] = { title = "Future of the Flights", description = "There is no higher charge given to a drakonid upon their graduation than to defend every single dragon egg with their lives.\n\nIt's why we train. Why we exist.\n\nI can no longer hide and observe, {name}. By stealing and infusing these eggs, the Primalists threaten the entire future of the dragonflights!\n\nWe are vastly outnumbered, but will you stand by my side? Will you fight to save the dragonflights?", objectives = "Rescue the Ruby Dragon Eggs.", progress = "Such cruelty and selfishness... I cannot even fathom.", completion = "<Sendrax is clearly shaken by what she had to do.>\n\nDeath was the only mercy left to those poor whelplings..." }
WordHunterWoW_QuestEN[65999] = { title = "Red in Tooth and Claw", description = "Commander Lethanak warned us recruits that he had received reports of the Storm-Eater, Raszageth, escaping her prison. It seems her servants have followed in her wake, threatening all we hold dear.\n\nThey move quickly. These ruins were reported to be abandoned during the last patrol.\n\nWe must stop the Primalists here.\n\nFor the Life-Binder, and for all of the dragonflights!", objectives = "Kill 15 Primalist invaders.", progress = "The dragonflights will prevail against the Primalists.", completion = "<Sendrax pats out a lingering flame on her armor.>\n\nWe've done what we could. What was needed." }
WordHunterWoW_QuestEN[66000] = { title = "Library of Alexstrasza", description = "<The pages on this book are charred.\n\nThe Primalists seem to be burning the ancient tomes found here, putting the dragonflights' very history in peril. It's as if the Primalists want to erase the dragonflights from history.\n\nSave what you can.>", objectives = "Save 4 works of cultural significance.", progress = "I smell burning parchment on the wind...", completion = "Our history will survive." }
WordHunterWoW_QuestEN[66001] = { title = "A Last Hope", description = "A whole brood of whelplings, lost...\n\n<Sendrax straightens her back and sticks her chin up.>\n\nThere is one more location we have not checked yet. The large ritual site where that proto-dragon dropped off the eggs.\n\nLet us charge their cruel defenses together, {name}, and save what we can.", objectives = "Rescue the last Infused Dragon Egg.", completion = "Is that...?" }
WordHunterWoW_QuestEN[66003] = { title = "Rings To Bind Them", description = "The djaradin here have become bold, binding flame elementals and letting them rampage through the area. The wildlife has fled, and the elementals are dangerously close to our camps.\n\nLuckily, I have been able to construct a small bastion of stone to stand against this fiery tide the djaradin have unleashed... and we will not fall!\n\nGather the magical rings that bind these flame elementals. We shall use them to bolster our defenses against the flame elementals.", objectives = "Gather 12 Molten Binding Rings.", progress = "Have you gathered all the rings I asked for?", completion = "Perfect! The residual energies of these rings can be turned against their creators to summon a construct under our control!" }
WordHunterWoW_QuestEN[66004] = { title = "Galgresh", description = "", objectives = "" }
WordHunterWoW_QuestEN[66005] = { title = "Medallion of a Fallen Friend", description = "<This chewed up hunk of metal was once a beautiful ornament of great importance to a Shikaar centaur. \n\nKhasar may know more about the owner.>", objectives = "Return the Medallion of a Fallen Friend to Khasar.\n\nProvided item:", completion = "This medallion is all that remains of a dear friend of mine who ventured too far into the swamp this past season. I thought it lost to the elements.\n\nI cut this leather from her first mammoth hunt. We were children, then." }
WordHunterWoW_QuestEN[66006] = { title = "Return to Roscha", description = "Baba is rested, and Roscha's supplies are recovered. We can return without upsetting her further. \n\nTake some boxes when you go. I will send warriors for the rest.", objectives = "Return the supplies to Farrier Roscha.", progress = "What took you so long?", completion = "You have the supplies? Good.\n\nLeave them by the forge.\n\n<Roscha looks around and frowns.>" }
WordHunterWoW_QuestEN[66007] = { title = "Free Air", description = "The Primalists are using these massive orbs here to hold off Kalecgos. \n\nAt this rate, Kalecgos will be too injured to continue the fight. If he falls, I won't be able to fend off Raszageth.\n\nThe empowered gem you hold should allow you to disguise yourself as an elemental to sneak ahead.\n\nUse the gem to destroy the orbs. That should give Kalecgos room to unleash his power.\n\nI will focus my attention on shielding the tower from Raszageth.", objectives = "Destroy 4 Lava Beacons.", completion = "Thank you, <name>. Now it's time to show the Primalists the true might of the Aspect of the blue dragonflight!" }
WordHunterWoW_QuestEN[66009] = { title = "In Defense of Vakthros", description = "It's time, {name}. The Primalist forces in the air are dwindling now that you've handled things on the ground.\n\nRaszageth is calling in one of her lieutenants to reinforce the Primalist forces, thanks to your efforts.\n\nI need you to handle this monster while I push forward to fight Raszageth and help Khadgar.\n\nLook for my magic during your fight. I will do what I can to aid you.\n\nIt is time for Raszageth to face the fury of the Aspect of magic!", objectives = "Defeat Korthrox the Destroyer.", completion = "Good to see you adventurer. Time is of the essence!" }
WordHunterWoW_QuestEN[66011] = { title = "In Memory of Ysera", description = "Oh, no! Now I think I understand. Theramus...he misses Ysera, and she can't come back.\n\nCome! I suspect I know where he went. We won't bother him further, but it'll be good to tell him that we're sorry, and that we'll give him the space he wants.\n\nWe are here for each other, within the nature all around us.", objectives = "Find Theramus again.", progress = "We appreciate you sticking around, <race>. You've been a great help.", completion = "<Theramus looks quietly upon the newly restored shrine.>" }
WordHunterWoW_QuestEN[66012] = { title = "The Sealed Door", description = "Our scouts have been combing the Dragon Isles for anything of interest. They've returned much of note, but one discovery stands out amongst the rest--a door.\n\nA door forged by the titans, and sealed against the world. No one has yet managed to find their way through to the artifacts that surely lie within.\n\nBut then, no mystery has endured under the discerning gaze of the Reliquary.\n\nWith the help of the Explorers' League, this challenge will be simple, I am certain.", objectives = "Travel to the Sealed Door in Thaldraszus and speak to Naleidea.", completion = "I trust the journey was trivial for one of your capabilities." }
WordHunterWoW_QuestEN[66013] = { title = "Investigate the Door", description = "Here we are. If we're going to get past this door, we need to understand who locked it, and how.\n\nTake a look around and see if you can find anything that might give us the answers we seek.", objectives = "Search the area for clues.", progress = "What an intriguing discovery. What do you imagine is on the other side?", completion = "We'll need more to go on than this." }
WordHunterWoW_QuestEN[66015] = { title = "The Blue Dragon Oathstone", description = "The Azure Span has stabilized for now and more blue dragons have arrived... just in time.\n\nIt's time to return to the Azure Archives and reclaim the oathstone.\n\nI would request your presence there, {name}. You've been a great boon throughout this ordeal.", objectives = "Accompany Kalecgos to claim the Blue Dragon Oathstone.", progress = "I'm quite relieved you all prevented the complete annihilation of the Azure Span.\n\nShall we continue?", completion = "The Oathstone is empowered once more. There is much to do... but the Azure Span is at least returning to what it once was." }
WordHunterWoW_QuestEN[66016] = { title = "Clan Teerai", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nClan Teerai is the clan of our Khanam Matra, our direct connection to the Maruuk ancestors. They are the holders of our traditions, and our storytellers.\n\nTo understand the Maruuk, you must understand Clan Teerai. One of the Khanam Matra's daughters, Qariin Dotur, is preparing a meal for our ancestors. Aid her. She will teach you about our people.", objectives = "Report to Qariin Dotur.", completion = "Welcome, outsider." }
WordHunterWoW_QuestEN[66017] = { title = "Clan Ohn'ir", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nThe mystics of our lands, like Ohn Seshteng, belong to Clan Ohn'ir. The clan is not made up of families, but rather of centaur from across the plains with an innate connection to Ohn'ahra. They spend their lives building that connection and honing their skills. Eventually, they receive assignments to advise different clans and protect our lands.\n\nOhn Seshteng went to speak with her khan about the omen she received. Join her to learn about the Ohn'ir.", objectives = "Meet Ohn Seshteng at the mystic pools.", completion = "It is good to be back with my clan." }
WordHunterWoW_QuestEN[66018] = { title = "Clan Nokhud", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nClan Nokhud is the newest to rise to power. Their late khan, Jhakan, raised a mighty army to seize territory from their predecessors. Such is the way of our people.\n\nWhile Jhakan had earned his respect, his son has not. Balakar killed his father and took control of the clan. They have grown ever more insular since. But to know the Maruuk, you must know them.", objectives = "Accompany Tomul to Guard Bahir.", completion = "I have the great unpleasantness of introducing you to Bahir, one of Balakar Khan's thugs." }
WordHunterWoW_QuestEN[66019] = { title = "Honoring Our Ancestors", description = "Our ancestors walk beside us upon the winds of Ohn'ahra, guiding and protecting us. All Maruuk, dead and living, gather under truce at the Khural. \n\nThe scent of this meal calls the ancestors to our fire. When they arrive, the Khural begins.", objectives = "Help Qariin Dotur cook a meal for the ancestors.", progress = "The Maruuk have returned to this spot for generations upon generations. We walk alongside our ancestors.", completion = "Our ancestors risked much for our future. It is right to invite them to gather alongside us." }
WordHunterWoW_QuestEN[66020] = { title = "Omens and Incense", description = "I shared with Tigari Khan the omen we received before entering Maruukai. She expressed her concern, as the wind felt cold to her as well.\n\nWe cultivate certain flowers here, blooms that can be ground and burned to elicit a trancelike effect. They are used to deepen our connection to an omen. \n\nI request that you collect some so that we may make an incense to burn. With my khan's help, perhaps we can learn more of Ohn'ahra's plight.", objectives = "Collect 5 Sweetsuckle Blooms, grind them into Sweetsuckle Incense, then aid Ohn Seshteng in the ritual.", progress = "Tigari Khan is most well-versed in reading omens. With her aid, we can learn more about this omen.", completion = "A betrayal threatens Ohn'ahra herself. We must stand tall, <name>. Now is a time for allies." }
WordHunterWoW_QuestEN[66021] = { title = "Unwelcome Outsider", description = "Hah! Look at you. Weak. Just like those puny hunters that brought you here.\n\nYou want to know the Nokhud? We speak through battle. \n\nOur battle ritual is called \"the tabarr\". We train. We spar. And it hardens us. Now there is no weakness in our clan.\n\nEnough talk. Go spar.", objectives = "Defeat 6 Nokhud centaur.", completion = "The Nokhud prefer brute strength and power over all else.\n\nWe do not see eye to eye on many things." }
WordHunterWoW_QuestEN[66022] = { title = "The Khanam Matra", description = "I cannot linger in centaur lands; I must return to the gardens as soon as I am able.\n\nThe Khanam Matra has agreed to hear our plea for aid. She awaits my arrival at the top of the krutal, the central building of Maruukai.\n\nThough I must speak with her on my own at first, you are more than welcome to join us.", objectives = "Report to Khansguard Akato to join Gemisath's audience with the Khanam Matra.", progress = "The Khanam Matra is waiting for you.", completion = "That traitorous fool.\n\n<Akato spits on the ground.>" }
WordHunterWoW_QuestEN[66023] = { title = "Trucebreakers", description = "Balakar disgraces his clan. He leads them into the storm, blinded by his lust for power.\n\nTheir betrayal reveals their fragility. Cut them down.", objectives = "Kill 10 Nokhud forces.", progress = "To attack the Khanam Matra... it is a rejection of our ways.", completion = "The path they have chosen is now stained with blood.\n\nScout Tomul tried to warn us this might happen. She may have further suspicions." }
WordHunterWoW_QuestEN[66024] = { title = "Covering Their Tails", description = "The Nokhud drool over war stories of our kind's ancient past. In truth they are weak, playacting children. And with one strike of lightning, they have severed their connection to Ohn'ahra.\n\nWell! If they will walk the path of corruption to seek war, then we will indulge them.\n\nOf course, Bahir was left in command to cover his escape. Her blood will soon stain the ground.", objectives = "Slay Guard Bahir.", progress = "<Sarest surveys the battlefield, eyes narrowed.>", completion = "Balakar was an easy target for Koroleth's corrupting influence.\n\nThe storm has arrived." }
WordHunterWoW_QuestEN[66025] = { title = "The Nokhud Threat", description = "Clan Nokhud's army is taking Maruukai. \n\nLet us discuss our next moves in the khan chambers. We must keep the Maruuk safe.", objectives = "Discuss next steps.", completion = "The very lifeblood of the Maruuk is in danger." }
WordHunterWoW_QuestEN[66026] = { title = "Urgent Action Required", description = "The source of these attacks must be the Brackenhide.\n\nWe've fought with the Brackenhide gnolls for generations, but until now they've been nothing more than a nuisance.\n\nWe have no choice but to take urgent action against the gnolls. Their foul decay will destroy the Azure Span, including whatever you're searching for.\n\nMeet us outside Brackenhide. We will need all the help we can get.", objectives = "Meet Brena at Brackenhide.", completion = "Just standing here, I can feel the dread of this forest wash over me. Something is deeply wrong here. \n\nI'm beginning to regret sending our best fighter back to Iskaara." }
WordHunterWoW_QuestEN[66027] = { title = "Calling the Blue Dragons", description = "I can no longer be afraid of reuniting the blue dragons, {name}. It is better for us to be a family... than a fragment of our former selves.\n\nEven if I cannot reclaim the oathstone, I can still use its power to send a message to all of the blue dragons. \n\nIt is time they received word... from their Aspect.", objectives = "View Kalecgos call back the blue dragonflight.", progress = "Stand back, <name>.", completion = "We need to move, <name>." }
WordHunterWoW_QuestEN[66028] = { title = "To the Future!", description = "I have tracked Chronormu and Eternus to a potential future. I know not what you will find there, only that it is dark and chaotic.\n\nSoridormi has taken some of our timewalkers ahead to that future in order to hold our connection to that time stable. Her considerable power will be needed to keep the portal open, so she must rely on your talents.\n\nSoridormi will be able to direct you further once you meet her there.\n\nHurry, {name}. Find Chronormu.", objectives = "Travel to the Primalist Future.", completion = "We need to find Chromie and Eternus before more damage can be done to this time." }
WordHunterWoW_QuestEN[66029] = { title = "Temporal Tuning", description = "Chronormu and Eternus are falling though time, but I sense them stop every so often. These brief moments are our opportunity to find them.\n\n<Nozdormu conjures a small chrono crystal.>\n\nI have imbued this crystal with power as well as my own temporal resonance. They have gone to a... troubling possible future. Find them and use it. Hopefully you can fix their position in time before they slip away again.", objectives = "Use Chrono Crystal on Eternus and Chromie in the Primalist Future to stop them from falling through time.", completion = "The process was not finished but I can more accurately track Chronormu now." }
WordHunterWoW_QuestEN[66030] = { title = "Resistance Isn't Futile", description = "The temporal ripples have caused trouble for the people here. Enemies appear where they were not, or are far stronger than they should be. These changes are small, but they are disastrous.\n\nI ask you to help the resistance fighters here. Heal their wounds so that they may fight once more. Set their timeline back on its correct course, as if it had never interacted with our own. It is not much, but it is what we can do for them.", objectives = "Heal resistance fighters in the Primalist Future.", progress = "Have you assisted the resistance?", completion = "These brave fighters will be able to bolster their forces once more." }
WordHunterWoW_QuestEN[66031] = { title = "Making Time", description = "I guess I shouldn't be surprised to find myself here.\n\nThis is not the Azeroth I wanted, but it's the one I have. We're fighting to preserve what's left and take the world back, but your arrival has caused some trouble. \n\nWe use the essence of those elementals out there to fuel our protections and keep ourselves safe. See that shield? That's the only thing keeping us from discovery and annihilation and you drained our resources. Bring back some of that essence and we may survive another day.", objectives = "Collect Elemental Essence for the survivor's camp.", progress = "Have you collected what we need?", completion = "You've given us some breathing room." }
WordHunterWoW_QuestEN[66032] = { title = "Return to the Present", description = "This timeline is dark and chaotic. The disruption here has been severe. I shall remain in this timeline a moment more to help sort out what remaining ripples may appear. \n\nReturn to Nozdormu. He will want to know of our success, even if it was less complete than we would like.", objectives = "Return to Nozdormu in the Present.", completion = "Your journey did not accomplish our goals, but it was a success nonetheless." }
WordHunterWoW_QuestEN[66033] = { title = "To the... Past?", description = "It is regrettable that we could not stabilize Chronormu, but there is another potential location where we may be able to catch her and bring an end to her fall through time. \n\n<Nozdormu frowns.>\n\nThe glimpses of this timeline past are... strange. Even among some of the visions I have witnessed in my life.\n\nBe on your guard, {name}. I am uncertain what you will face, but it is powerful and... oddly familiar.", objectives = "Take the portal and meet with Andantenormu in Azmerloth.", completion = "Whatever I expected... This is not it." }
WordHunterWoW_QuestEN[66035] = { title = "Murloc Motes", description = "An alternate timeline born from murlocs??!\n\nForgive my selfishness, but would you obtain a few stray motes of temporal energy while you locate Ambassador Chronomu? \n\nJust walk into them and your staff should do the rest. I will examine the data later. When we are not in the middle of venturing through rips in Azeroth's varied realities.", objectives = "Drain 12 Temporal Motes.", progress = "I have no doubt we shall succeed against the Infinite this day, and studying this foreign energy will be our reward!", completion = "Astounding work! \n\nNow, what do you imagine the murlocs of this Murloc World are? I shudder to think..." }
WordHunterWoW_QuestEN[66036] = { title = "Mugurlglrlgl!", description = "Mrglgulglrrlglgul! Grurguglullgurl!\n\nGruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl.\n\nMgrgulllglll gurl gugll.\n\n<You aren't certain what's being said, but there are lots of stabbing motions. It seems like this murloc wants you to kill something.>", objectives = "Murglgulglrrlglgul!", progress = "Murglgulglrrlglgul!", completion = "Frrg thrg Allrghnnge!\n\n<The murlocs appear to be pleased.>" }
WordHunterWoW_QuestEN[66037] = { title = "Back to Reality", description = "We were able to increase Ambassador Chronormu's connection to our time. I am certain when we find her again, we will be able to finish the ritual.\n\nFor now, let us return to our present and a world with... significantly fewer murlocs.", objectives = "Return to Nozdormu in the Present.", completion = "Thank you for helping to uphold the timelines... odd as they may sometimes be." }
WordHunterWoW_QuestEN[66038] = { title = "Race Through Time!", description = "{name}, we must act quickly to catch up to Ambassador Chronormu, and I mean that quite literally.\n\nZera and I will do what we can to speed our progress, but it is imperative we avoid entangling with this time period as much as possible. To do so will slow us down and we may not be able to catch the Ambassador before she is lost to even Nozdormu's magic.\n\nWe haven't a moment to lose!\n\n(Accepting this quest will begin a timer)", objectives = "Race through time, following Chromie and Eternus's Path.", completion = "By the Aspects... This is the Black Empire!" }
WordHunterWoW_QuestEN[66039] = { title = "Chromie Time", description = "This... This is the Black Empire. We have traveled very far into the past, indeed.\n\nLook! I see Ambassador Chronormu and Eternus! We need to hurry and complete the ritual. \n\nEven my curiosity is not enough to wish to see where they might travel to next.", objectives = "Find Chromie and Complete the Temporal Stabilization Ritual.", completion = "That feels much better!\n\nOh, don't worry about Eternus. We've come to a bit of a truce for the moment." }
WordHunterWoW_QuestEN[66040] = { title = "Back to the Future", description = "We're not going to fall through time anymore but we're far in the past. Waaaaay far in the past. \"The Titans Haven't Visited Azeroth Yet\" far in the past. Getting home is going to be... tricky.\n\nBut we dragons can do it! \n\nWe're going to need you to keep those Black Empire minions off our backs though. It shouldn't take too long! \n\nI think.\n\nProbably.\n\nDon't worry about it! Just keep those creepy monsters away and we'll handle the rest! Easy!", objectives = "Defend your allies against the Black Empire until the temporal portal is created.", progress = "This has been an... unexpected turn of events.", completion = "Time is stable once more." }
WordHunterWoW_QuestEN[66042] = { title = "Patterns Within Patterns", description = "We stand at the origin of the Shadowlands. We must not allow this place to become its undoing.\n\nWork with our new allies, {name}. Their assistance will be the difference between our success and the unmaking of all things.", objectives = "Assist your allies in Zereth Mortis by completing World Quests, Daily Quests, looting treasures, and slaying rare creatures.", progress = "In this place, all fates are intertwined.", completion = "We move closer to our goal. Ever onward." }
WordHunterWoW_QuestEN[66044] = { title = "Taking the Walls", description = "Sabellian and the other dragons are holding back the djaradin for now. We must act quickly to secure the high towers and ensure our victory.\n\nYou and I shall clear the siege arbalests that threaten us from above.\n\nLet me know when you are ready.", objectives = "Eliminate the three Siege Arbalests and Champion Choruk.", progress = "Are the Arbalests and Champion Choruk defeated?", completion = "Well done, <name>. Sabellian and his forces will hold off the djaradin, while I activate the Oathstone to restore power." }
WordHunterWoW_QuestEN[66048] = { title = "Best Plans and Intentions", description = "Attacking the djaradin controlling the Obsidian Citadel will be no easy task. Even with Wrathion and his Blacktalon forces, this will be a fierce battle. Wrathion may be confident, but... I am not so certain.\n\nPerhaps we can speak to those helping to plan the strategy, and see if we can find any room for improvement.", objectives = "Review the plans with the various members of Wrathion's forces.", progress = "Can you improve our odds of success?", completion = "I see. I shall consider your evaluation carefully, of course." }
WordHunterWoW_QuestEN[66049] = { title = "Obsidian Oathstone", description = "When Neltharion became the Earth-Warder, he swore an oath to protect this world, {name}. To safeguard the deep places of the earth and, with his flight, to serve as Azeroth's defenders. The Obsidian Oathstone represents that promise. \n\nWe must activate the stone and let the Dragon Isles know that the black dragonflight has returned!\n\nFollow me, {name}.", objectives = "Locate the Obsidian Oathstone.", progress = "Have you seen the Oathstone?", completion = "This is a setback, but with your help, I am sure we can repair the Oathstone. Work with Bazentus... make it so." }
WordHunterWoW_QuestEN[66055] = { title = "A Shattered Past", description = "The Oathstone is damaged! There are pieces missing.\n\nDo what you can to recover the fragments... maybe there is a way to fix the stone!", objectives = "Recover 12 Oathstone Fragments.", progress = "Have you found the missing fragments of the Oathstone?", completion = "This looks like all the pieces. I believe we can repair this!" }
WordHunterWoW_QuestEN[66056] = { title = "Forging a New Future", description = "The forge of the Earth-Warder is the most powerful of all the dragon forges in existence. Our ancestors used it to create the strongest weapons and armor to defend Azeroth.\n\nWithin the hearth of that forge is the power necessary to reform the shattered fragments of the Oathstone.\n\nLet us go and prepare the forge for the work to be done.", objectives = "Prepare the Earth-Warder's forge.", progress = "Have you finished the work we require?", completion = "Very good. Now with the arrival of our Prince, we can begin." }
WordHunterWoW_QuestEN[66057] = { title = "Restoring the Faith", description = "The shattered fragments have been reformed. We are ready to repair the Oathstone.\n\nGo now and help Wrathion complete the repairs.", objectives = "Repair the Obsidian Oathstone.", completion = "This complicates matters, but I will not be denied what is rightfully mine!" }
WordHunterWoW_QuestEN[66070] = { title = "Brightblade's Bones", description = "", objectives = "" }
WordHunterWoW_QuestEN[66071] = { title = "Flying Rocs", description = "The name is Professor Harleen Chirpsnide, infamous ornithologist extraordinaire! I came here to study the mythical bluefeather rocs of the Dragon Isles, but I suppose we've got bigger fowl to fry.\n\nI bet these harpies flew in from Kalimdor when the Isles opened up. They're highly invasive and feasting like a pack of ogres at the Bilgewater Casino buffet.\n\nLet's give the native rocs here a fighting chance. Take this medical kit and use it to get the injured ones back on their feet.", objectives = "Assist 8 Injured Bluefeather Rocs.", progress = "Don't worry about using up my supplies. I'm good pals with the clerks at the Expedition's reimbursement office.", completion = "A full-feathered job, <name>!\n\nI would have helped you with the healing and the slaying, but I'm more of an 'ideas goblin' these days." }
WordHunterWoW_QuestEN[66074] = { title = "Primal Scythid Queen", description = "", objectives = "" }
WordHunterWoW_QuestEN[66076] = { title = "Creature Name", description = "", objectives = "" }
WordHunterWoW_QuestEN[66078] = { title = "Sharp Practice", description = "For years I have fostered the Blacktalon, teaching and encouraging them to pursue the same heights you have reached.\n\nThey may not have achieved the same lofty goals as yourself, but they are accomplished in their own right. They've made me proud.\n\nEach would be honored if you test their skills. I think you will see some of yourself in them.", objectives = "Test the skills of 8 Blacktalon Assassins and Avengers.", progress = "Have you tested them and found them worthy?", completion = "I believe the Blacktalon are prepared for anything." }
WordHunterWoW_QuestEN[66079] = { title = "Wrathion Awaits", description = "These eggs represent a new generation of dragonkind. They must be protected and fostered. Yet... my heart aches, and I worry for Wrathion. I fear his stubborn determination will lead to folly. \n\nYou have been a trusted friend over the years, {name}. Perhaps you can go in my place, and help him. \n\nSeek him out at the Obsidian Bulwark. And please, watch over him. There are so few of his flight left.", objectives = "Meet with Wrathion at the Obsidian Bulwark.", completion = "Ah, champion--your arrival is most fortuitous. With you here now, my plan will certainly succeed." }
WordHunterWoW_QuestEN[66080] = { title = "Temporal Difficulties", description = "Hello, {class}. You're right on time!\n\nSome trouble up at the temple is causing the timeways to destabilize and spill out into the valley. Not only that, but a bunch of Timewalkers are missing!\n\nWe've asked for extra help, but one of the new recruits hasn't arrived yet.\n\nCan you look for her? Be careful though, time's in a massive state of flux around the valley. There's no knowing what dangers are around!", objectives = "Find the missing recruit in the Flowing Forest in Thaldraszus.", completion = "I knew somebody would come around... eventually!" }
WordHunterWoW_QuestEN[66081] = { title = "Time is Running Out", description = "With the bronze temple under attack temporal energy is seeping out everywhere.\n\nThe Timewalkers placed collectors all through this forest trying to gather all the errant magic. Anything collected can also be used as extra power! Which is a good thing, this crisis is draining all our resources.\n\nI was supposed to retrieve the collectors, but I still need a moment to catch my breath.\n\nCould you get them for me?", objectives = "Collect 8 Temporal Collectors in the Flowing Forest of Thaldraszus.", progress = "Were you able to find them all?", completion = "Thank you, <name>. \n\nNow the forest can try to recover, and the Timewalkers have extra some extra energy." }
WordHunterWoW_QuestEN[66082] = { title = "Time in a Bottle", description = "Great! The Timewalker staff intact! But, it is definitely drained.\n\nI know! You can recharge it using the temporal energy coalescing around the wildlife here. Unfortunately, that means defeating affected creatures in the forest. The energies were making them dangerous and unstable, and we would have had to cull the population after anyhow... \n\nSometimes you have to sacrifice for the greater good. Could you help? I still need a minute.", objectives = "Collect time energy from slain time-charged wildlife within the Flowing Forest of Thaldraszus.", completion = "This staff has been through a lot, but it should be fully functional again.\n\nThank you, <class>." }
WordHunterWoW_QuestEN[66083] = { title = "Feels Like the First Time", description = "Shepherding the timeways is a dangerous duty.\n\nThough you are not a Timewalker, Ambassador Chronormu believes you will be of great help. But to ensure your safety we must properly train you.\n\nUnfortunately, all our instructors are still missing. I will do my best to help. Let us see how we both do. I know the Ambassador Chronormu is counting on the both of us.", objectives = "Speak with Andantenormu and participate in Timewalker training.", completion = "That was quite unexpected! As you can see, there are many dangers that come with wielding time energy.\n\nI do wish there was time to examine the effects of your little hiccup, but there are more important matters." }
WordHunterWoW_QuestEN[66084] = { title = "Times Like These", description = "Despite that small hiccup during training, I believe you are prepared enough to aid us here.\n\nThe distortions in the valley are allowing different time periods to cross over into ours. We are unsure why these timelines connect which is quite alarming. We need more information.\n\nPlease, see if you can find anything about the creatures pouring in from different timelines. I am sure their passage will have left some sort of residue. By studying it we can hopefully find a way to get ahead of this crisis.", objectives = "Collect 100 Temporal Residue from time-lost enemies in the Shifting Sands.", progress = "While it is unfortunate this is all happening, I am eager to discover new chronologies to study.", completion = "With these samples, we will have a better understanding of how and why these timelines are intersecting with ours.\n\nThank you for your assistance." }
WordHunterWoW_QuestEN[66085] = { title = "If We Could Turn Back Time", description = "A proper Timewalker never leaves a crisis half-resolved. Why wait and study when we have the tools we need already?\n\nSince you have my original staff, I found a spare for me to use. I am sure no one will miss it. This is my plan: we team up on those rifts together and save the day! All the days, really. Sorry, I still get confused about the time stuff. \n\nWhat do you say? The task should be simple enough, right?", objectives = "Close the Time Rifts in the Shifting Sands with Siaszerathel.", completion = "We did it! Right?\n\nOkay maybe there was a wrinkle or two--nothing Dante needs to know about. Also, an unexpected visitor..\n\nStill, overall I would say that went pretty well." }
WordHunterWoW_QuestEN[66087] = { title = "Closing Time", description = "These incursions push the durability of this timeline to the point of breaking. If only we had our full contingent of Timewalkers!\n\nThough you are a novice with the staff, I am told that you have managed to help us out greatly. With an extra push, I believe you may further aid our cause.\n\nNormally, I would put you through a full training but the times are... unorthodox. Take this scroll of advanced knowledge and use it to push back the invaders! Be swift though, the effects are only temporary.", objectives = "Assist the Timewalkers by slaying time-lost enemies, buffing bronze allies, returning lost artifacts, and closing time rifts in the Shifting Sands.", progress = "Every incursion threatens to weaken this timeline.", completion = "A Timewalker's staff is crucial to shepherding time. Sometimes a gentle prod is all that is needed. Other times, firmer action is required. This should be enough to mitigate the instability in this area for now. \n\nWhile there is still more work to be done, your companions are eager to assist up at the temple. I will ensure the area down here is supported while you all go ahead.\n\nGood luck." }
WordHunterWoW_QuestEN[66090] = { title = "Path of the Dark Rangers", description = "", objectives = "Accept the Dark Ranger regalia.", completion = "<Velonara peers at you knowingly.>\n\nIt was a fair disguise, but I saw at once that you were not who you claimed to be. \n\nRegardless, you risked your life to aid us. I will not forget that.\n\nThere are those among the kaldorei raised by Sylvanas' val'kyr who wish to return to their own. If Tyrande would have them back, they are free to go. The rest will be welcome in the ranks of the dark rangers. \n\nIn recognition for your service to us, I offer this gift." }
WordHunterWoW_QuestEN[66091] = { title = "Path of the Dark Rangers", description = "", objectives = "For years, we dark rangers worked as agents of the Banshee Queen. Now, under the leadership of the new Forsaken council, we serve a greater cause: shaping our people's future.\n\nWe cannot be certain what lies ahead. But I vow that the dark rangers will do everything in our power to defend this kingdom.\n\nYour aid was crucial in helping us cleanse the ruins of Lordaeron. Take this, with our thanks." }
WordHunterWoW_QuestEN[66094] = { title = "The Ruins of Szar Skeleth", description = "According to the watcher's logs, the stone of Insight can be found in a draconic tower on a river in the center of the Ohn'ahran Plains. That should be Szar Skeleth. Be careful. We can be sure the Sundered Flame won't let us just walk in and take it.\n\nOnce you get there, rendezvous with Toddy. Then we can retrieve the stone.", objectives = "Meet up with Toddy near Szar Skeleth in the Ohn'ahran Plains.", completion = "Ye made it. I've quite the mission for ye, <name>." }
WordHunterWoW_QuestEN[66100] = { title = "Supplying in Weight", description = "I really screwed up this time. I only stepped away from the campsite for a moment, but I barely returned in time to see the tarasek snatching up everything I had not bolted down.\n\nThose supplies were expensive, and I can't exactly ask for help getting more! My sister Nori thinks I'm inept enough as it is.\n\nIf you are sure you want to head through the valley, would you mind keeping an eye out for any stray bags of supplies?", objectives = "Collect 6 bags of Waywatcher Supplies.", progress = "<Alvi glances in your direction, clearly panicked. The missing supplies seem to be the last thing on her mind at the moment.>", completion = "Thank you, <name>, but we have bigger things to worry about now." }
WordHunterWoW_QuestEN[66101] = { title = "From Such Great Heights", description = "Toddy and Naleidea have requested a survey report of the surrounding area immediately.\n\nLuckily, I have acquired an enchanted telescope and surveyor's disc that will help us scout out nearby areas from the safety of the clouds.\n\nUnluckily, I am deathly afraid of heights and cannot bring myself to set foot on the contraption.\n\nYou are not afraid of heights, are you?", objectives = "Use the Surveyor's Disc to bounce into the sky and scout the area.", progress = "Good luck up there. I much prefer the ground under my feet.", completion = "<Aster breathes a sigh of relief.>\n\nI thought for certain you would plummet to your death from up there. Thanks again for taking the risk so that I was not required to." }
WordHunterWoW_QuestEN[66103] = { title = "Eager to Please", description = "We need more troops to defend the Obsidian Citadel. Now that we've got a foothold, it's important to make sure we've got fresh eyes and bodies for the effort.\n\nWe have additional reserve troops at the Obsidian Bulwark that could reinforce us.\n\nThey are well trained, but they'd benefit from a combat test with someone as skilled and experienced as you. So we know they're ready.", objectives = "Test the skills of 10 Blacktalon Assassins and Avengers at the Obsidian Bulwark.", completion = "Thank you, <name>. These troops are better prepared than ever, thanks to you. And this effort will take a lot of preparation and muscle." }
WordHunterWoW_QuestEN[66104] = { title = "Forensic Ecology", description = "I'm at my wits end, {name}. Tharu and I have made our way through nearly all the corpses only to stumble at the end because we cannot agree on a methodology. If only he would just listen to me!\n\n<Ecologist Iskha sighs.>\n\nThe stress of the situation is getting to us both. I don't even have a firm hypothesis yet.\n\nYou look like you have a strong stomach. Will you take over on these last two gorlocs? You can borrow my scalpel.", objectives = "Dissect the gorloc corpses.", progress = "Don't worry, you'll get used to the smell after a while.", completion = "It's the gorlocs fighting that's been harming the wetlands so?\n\n<Ecologist Iskha looks ashamed.>\n\nI think I understand now..." }
WordHunterWoW_QuestEN[66105] = { title = "A Scalpel of a Solution", description = "I believe we are gathering enough data safely from here but... \n\nTharu is an exceptional ecologist and prefers we take action. Still, the ecosystem is fragile, and we may damage it if we are not careful. I do however agree we don't have much time. \n\nIt might be worth indulging him. A little.\n\nCulling the rampaging elementals ought to buy us time without impeding our research. Be sure to cull them in equal numbers--we don't want to throw things further out of balance.", objectives = "Kill 5 Rampaging Water and 5 Rampaging Wind.", progress = "Is it done? Can I finally get Tharu off my back about this?", completion = "Did that seem to affect anything? No?\n\n<Ecologist Iskha sighs.>\n\nWell, at least we're nearly finished with our research." }
WordHunterWoW_QuestEN[66106] = { title = "Don't Be So Shellfish", description = "I was a fool to doubt Iskha when he insisted there was more to this. He wouldn't be my mate if he wasn't always two steps ahead of me.\n\nWe can make it up to him--by taking action, of course. If it's shells that are causing all this elemental chaos, why don't you go into their camp and take those shells right out of their slimy hands?\n\nBring back piles of the wind and water shells, enough for Iskha to research to his heart's content.", objectives = "Collect 15 Water-Infused Shells and 15 Wind-Infused Shells from Soggymaw and Windyfin Gorlocs.", progress = "That ought to show them.", completion = "Iskha and I will take these back to the life pools--somewhere where they can't cause any more trouble.\n\nYou've done good work here today, <name>." }
WordHunterWoW_QuestEN[66107] = { title = "Wildlife Rescue", description = "It doesn't take an ecologist to see that the wetlands are in real trouble.\n\nBut Iskha's got us stuck here examining dead creatures when we ought to be stopping them from dying in the first place! The red dragonflight is about preserving life--not dissecting it!\n\nI love Iskha, and he's good at what he does, but if we wait until he's done puttering, there won't be any wetlands left to save. \n\nI'll manage his overthinking. You get out there, get your boots muddy, and rescue some wildlife.", objectives = "Rescue the wildlife of the Restless Wetlands.", completion = "There! The wetlands are fixed! Meanwhile, Iskha is still doing his taxidermy... I mean research!\n\nWait, what do you mean the elementals keep coming?" }
WordHunterWoW_QuestEN[66108] = { title = "A Sledgehammer of a Solution", description = "While I'm glad Tharu now sees my point of view, I'm also grateful he had you rescue wildlife while I was dawdling.\n\nThe situation is much more dire than anticipated; he was right to take action. With what we've learned, I fear this elemental bombardment won't stop until we've dealt with the gorlocs.\n\nIf I were Tharu and thinking actionably, I would go straight for their leaders. Without anyone to rally around, the fighting should dissipate and no longer threaten the wetlands.", objectives = "Slay Sogglmoggl, King of the Soggymaw and Whirglgurgl, King of the Windyfin.", progress = "This should buy us some room to breathe while we clean up this mess.", completion = "That ought to leave them scrambling--at least for a while.\n\nThank you for all your help, <name>." }
WordHunterWoW_QuestEN[66110] = { title = "Give Peace a Chance", description = "Aka'Magosh, {name}.\n\nThis expedition is under the protection of both the Horde and the Alliance. Our instructions are clear: give aid to any members of the Dragonscale Expedition regardless of their other allegiances.\n\nThe Alliance's representatives, Captain Garrick and her son Henry, stand guard on the other side of camp.\n\nI fought with Captain Garrick against the scourge. She is honorable and will serve the Expedition well.\n\nGo offer her your assistance. Show her that the Horde honors its agreements.", objectives = "Introduce yourself to the Alliance representatives.", completion = "<Captain Garrick salutes your approach.>\n\nWarlord Breka proves her honor once again by sending you to me." }
WordHunterWoW_QuestEN[66111] = { title = "Encroaching Elementals", description = "The crafters, artisans, and explorers of the Dragonscale Expedition are ill-suited to the vigors of battle.\n\nBut not you and I, {name}.\n\nHere in the Dragon Isles, let us use that strength to protect those who can't protect themselves.\n\nClear out the elementals encroaching from the north, so the expedition can focus on their noble pursuits.", objectives = "Kill 15 primal elementals in Wingrest Embassy.", completion = "For the Dragonscale Expedition!\n\n<Captain Garrick salutes you.>" }
WordHunterWoW_QuestEN[66112] = { title = "Always Be Crafting", description = "Have ye ever seen such powerful elementals?!\n\n<Grun cheers.>\n\nI hear the guards grumblin' 'bout havin' to fight 'em all the time, but they're missin' the big picture... Bigger elementals means bigger craftin' components!\n\nWhile you're out there clearin' the elementals for our safety or whate'er it is ye be doin', be sure to pick up pieces of the biggest ones ye can find. I want tae try makin' somethin' out of 'em!", objectives = "Collect a Primal Molten Core.", progress = "I'm gonna build a grand helmet first... No, a hammer... No, a BIG hammer!", completion = "<Grun's eyes open wide as you hand him the primal cores.>\n\nIncredible! This is the best day of me life!" }
WordHunterWoW_QuestEN[66113] = { title = "An Inconspicuous Conveyance", description = "[DNT] Our foes watch the skies. I will risk no harm to the future of my flight, so we must travel by less traditional mean.\n\nI ordered a more... down to earth means of transport be acquired, but it seems to have suffered some damage during the exchange. You are undoubtedly more familiar with such things than I, {race}, so your assistance in repairing the wagon would be most appreciated.", objectives = "Repair the Borrowed Wagon." }
WordHunterWoW_QuestEN[66114] = { title = "For the Benefit of the Queen", description = "We safeguard our precious eggs to protect the future of all dragonflights. The Primalists do not simply threaten pain or anguish with their actions. \n\nThey threaten us with extinction.\n\nI must inform our queen at once.", objectives = "Ride with Majordomo Selistra to the Ruby Lifeshrine.", completion = "This is dire... but our flight has suffered many tragedies over the years. We shall endure." }
WordHunterWoW_QuestEN[66115] = { title = "The Mandate of the Red", description = "Our calling is care and compassion. We aid the other flights not only for their own sake, but for the sake of dragonkind as a whole.\n\nPerhaps speaking with the dragonspawn here at the Ruby Lifeshrine will help you understand us further.", objectives = "Talk to the tenders at the Ruby Lifeshrine.", progress = "The red dragonflight preserves the future of us all.", completion = "I hope you have grown to appreciate what we do." }
WordHunterWoW_QuestEN[66116] = { title = "The Primary Threat", description = "There are far too many vulnerable eggs to secure. If the enemy breaks through, all is lost!\n\nI am sure our guards are mustering on the field to push them back. Speak to Commander Lethanak, and he will use your strength where it will be most helpful.", objectives = "Find Commander Lethanak at the Flashfrost Assault.", progress = "I need all the help I can get.", completion = "I will use every weapon in my arsenal to stop these foes." }
WordHunterWoW_QuestEN[66117] = { title = "Clear the Battlefield", description = "", objectives = "" }
WordHunterWoW_QuestEN[66118] = { title = "Basalt Assault", description = "Raszageth and her Primalists have summoned towering earth elementals to break our walls. They must be stopped!", objectives = "Destroy 4 Enraged Cliffs in the Flashfrost Assault.", progress = "They will do anything they can to destroy our walls!", completion = "The Lifeshrine stands strong." }
WordHunterWoW_QuestEN[66119] = { title = "Ruby Life Pools: Primalist Invasion", description = "The Primalists have torn their way into our home. We were not prepared for such an intense attack... several got through.\n\nOne of our drakonid ventured in to follow them, but he has not reported his findings. I fear the worst.\n\nI will stand guard. No more shall breach our walls while we draw breath, but you must stop those who made it inside.\n\nGo!", objectives = "Enter the Ruby Life Pools and stop the Primalist attack.\n\nYou can enter the Ruby Life Pools solo by queuing for it in Follower Dungeons.", progress = "They will destroy our future if we cannot stop them.", completion = "Our home will bear the wounds of this assault for years, but we are strong. We will endure... and the eggs we saved will bring about a bright future for us all.\n\nThank you." }
WordHunterWoW_QuestEN[66121] = { title = "Egg Evac", description = "The Primalists have stolen our eggs for their perverse rituals! They must be stopped.\n\nHelp us recover our eggs before it is too late. Mark each egg as you find them, {name}. I will ensure they are safely extracted from the area.", objectives = "Rescue 4 eggs from the Flashfrost Enclave.", completion = "Nearly done." }
WordHunterWoW_QuestEN[66122] = { title = "Proto-Fight", description = "These proto-dragons detest us. They believe we are a twisted version of dragonkind that is manipulated and chained by the Titans. They do not understand.\n\nWhich is why they feel safe even as they throw their forces at our walls. \n\nThey are mistaken.\n\nTake this spear, {name}. Kill our enemies.", objectives = "Defeat 3 proto-dragons in the Flashfrost Enclave.", progress = "They intend to harm our dragons. They deserve no mercy.", completion = "They may have been our kin, and perhaps we could have approached them as our brethren... but their cruelty leaves no mercy in my heart." }
WordHunterWoW_QuestEN[66123] = { title = "Cut Off the Head", description = "Jadzigeth, one of Raszageth's foul lieutenants, proudly leads the Primalists here.\n\nLet us show them all what happens to those who stand against us.", objectives = "Defeat Jadzigeth in the Frostflash Enclave.", progress = "There is no other path.", completion = "Our queen!" }
WordHunterWoW_QuestEN[66124] = { title = "Exeunt, Triumphant", description = "From what I saw, the queen fell back to the Wild Hatchery. It is an outpost to keep watch over the proto-drakes in the area... I only hope that its defenses are enough.\n\nWe must head there at once!", objectives = "Escape the Frostflash Enclave with Majordomo Selistra.", progress = "My queen...", completion = "I could not rest until the eggs were safe... this is a relief.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[66126] = { title = "Unlocking Our Past", description = "Bring me an assembled Key", objectives = "Collect 1 Assembled Key", progress = "A restored Obsidian Key could allow us to unlock aspects of this forge that we have only dreamed about!", completion = "A wise choice. All these squabbles over the throne will not solidify our defenses. We must craft weapons and gear to fend off the djaradin." }
WordHunterWoW_QuestEN[66128] = { title = "Next Steps", description = "These stones are an incredible discovery, even if their intended use is never realized.\n\nBut before we try them out, we have a process to adhere to. They must be examined and cataloged, and reports sent and received to both the Reliquary and Explorers' League headquarters.\n\nLet's meet back at basecamp. We can go over what's next.", objectives = "Meet with Toddy and Naleidea in the Explorer's tent at the Dragonscale Basecamp in the Waking Shores.", progress = "Oh ye wouldn't believe the plans I have to get into that facility!", completion = "Don't ye worry. Show a little patience, and we'll get to the bottom a' this yet." }
WordHunterWoW_QuestEN[66129] = { title = "Unlocking Our Past", description = "Bring me an assembled Key", objectives = "Collect 1 Assembled Key", progress = "We must have the lost Obsidian Keys. The power they unlock is necessary to drive back the unbelievers.", completion = "This contribution shall ensure your place among Deathwing's chosen few. Together we shall sweep across the world and announce the Hour of Twilight!" }
WordHunterWoW_QuestEN[66130] = { title = "Unlocking Our Past", description = "Bring me an assembled Key", objectives = "Collect 1 Assembled Key", progress = "Find me more restored Obsidian keys, and we shall unlock the full potential of the Obsidian Citadel.", completion = "Good work, champion. This key will allow us to access more of the Citadel's lost secrets." }
WordHunterWoW_QuestEN[66131] = { title = "Unlocking Our Past", description = "Bring me an assembled Key", objectives = "Collect 1 Assembled Key", progress = "Bring me additional restored keys, and we shall continue our work here.", completion = "Thank you, <name>. Your support in this matter shall bolster my claim to the throne." }
WordHunterWoW_QuestEN[66133] = { title = "Keys of Loyalty", description = "", objectives = "Collect 1 Greater Obsidian Key." }
WordHunterWoW_QuestEN[66134] = { title = "Azeroth Pest Control", description = "You there! Hatchling!\n\nLend me a hand, won't you? These podlings are ripping up all my plants!\n\nAll kinds of elementals have invaded the gardens, and they seem to be... affecting the wildlife. It's like their energy has driven these podlings mad! More mad than usual!\n\nI've got my hands full with just these three. Please! Before they rip up all my flower beds.", objectives = "Kill 8 Agitated Seedlings in the Gardens.", progress = "I'm too old to be fighting podlings!", completion = "Thank the Titans you showed up! Otherwise I don't know if I'd ever get these pests to leave.\n\nSo what do you say to helping an old Drakonid out with the rest of the gardens?" }
WordHunterWoW_QuestEN[66135] = { title = "The Gardener's Apprentice", description = "Basilton! Lord Basilton, where are you?\n\nMy executive assistant and apprentice, Lord Basilton, has gone missing! He loves to explore, but he's even worse at defending himself than I am. I'm a gardener, not a warrior!\n\nCould you please go find that layabout? I need him here so I can think. He's usually in the shed, digging through piles of junk.\n\nBe careful though. He can be a bit prickly at first.", objectives = "Search for Lord Basilton in the Garden Shed by cleaning up Piles of Junk.", progress = "At my age, an executive assistant is a necessity.", completion = "Ah, there he is! My lovely assistant. Who's a good boy? A good, spiky boy? Basilton! Who's the spikiest? That's right! You are!\n\nAhem. Thank you, <name>." }
WordHunterWoW_QuestEN[66136] = { title = "Elemental Extract", description = "A huge fire elemental destroyed the pond a few days ago. I think it's behind all this ruckus, but it's too big to fight. We need to weaken it somehow.\n\nBut don't count Old Gryrmpech out just yet, I have a plan!\n\nWater elementals decided to make themselves at home in the Blue flight's gazebo. If you can collect enough essence from them, we might be able to use their magic against them.\n\nFight fire with fire, right? Well, fight fire with water, I guess.\n\nAnyway, you should probably get going.", objectives = "Collect 5 Watery Essence in the Gardens.", progress = "In all my years, I've never seen so many elementals in one place. So why did it have to be my gardens?", completion = "Excellent! This is just what we need to snuff out those fire elementals once and for all." }
WordHunterWoW_QuestEN[66137] = { title = "Lashing Out", description = "I'm sure the podlings aren't the only wildlife acting like hooligans.\n\nAlexstrasza's tree has always been a thorn in my side. Her life magic draws all sorts of plants and animals to it, good and bad. And guess who has to take care of the bad ones? Old Gryrmpech, that's who!\n\nAspects above, I'm getting too old for this.\n\nThe stewards aren't trained in combat, so it is up to you to take care of the Life-Binder's weed problem.", objectives = "Kill 10 Invasive Deathblossoms and Lasher Weedlings in the Gardens.", completion = "The elemental problem is more dire than I thought, if you killed that many. Alexstrasza will be happy, at least." }
WordHunterWoW_QuestEN[66138] = { title = "Like Sands Through the Hourglass", description = "Like the rest of the gardens, Nozdormu's hourglass has had to weather the elemental unrest. Turbulent wind elementals came through and scattered the magical sand contained within.\n\nWithout this sand, Nozdormu's influence here is greatly diminished.\n\nAs a steward-in-training, I have been tasked with overseeing the hourglass at all times. If you would collect the sand in my stead, I would be eternally grateful.", objectives = "Collect 8 Piles of Windswept Time Sand in the Gardens.", progress = "I can rest easy knowing Nozdormu has already foreseen your success.", completion = "Excellent work.  Nozdormu informed me yesterday that he wishes to express his gratitude." }
WordHunterWoW_QuestEN[66139] = { title = "Flame at Last", description = "Alright, youngling, I've placed all the water elemental essences in this jar for you.\n\nIf you just toss it at the big one, it should work. I mean, when has water not worked against fire? It's foolproof.\n\nThe heat, uh, isn't good for my joints, so I'll just stay here. I trust you can handle it.\n \nGood luck, young one!", objectives = "Use the Concentrated Essence of Water to defeat the Blazing Inferno in the Gardens.", progress = "You remind me of myself, when I was your age. Nothing could stand in the way of Gryrmpech!", completion = "Incredible! I wasn't sure it was going to work, but I'm glad it did." }
WordHunterWoW_QuestEN[66141] = { title = "Broken Traditions, Broken Bodies", description = "My fellow furbolg are no longer themselves. They have done... bad things. Now, they have become worse things.\n\nFurbolg has never fought furbolg!\n\nMy brother and I escaped them. I came here looking for help. He remains by our clan's den.\n\nHelp us before our clan is lost!", objectives = "Meet Garz and Narn on the way to Rustpine Den.", completion = "My brother spoke the truth.\n\nIt is even worse than when I left." }
WordHunterWoW_QuestEN[66147] = { title = "Crystals in the Water", description = "We might not look it this moment, but we are professionals. The Expedition entrusted us with finding a clutch of rare crystals in the area--a geological survey if you will.\n\nI'm still collecting myself after the gorloc attack. Would you be a dear and go look for these crystals? Bring samples back if you can.", objectives = "Collect 4 Crystal Samples in Gorloc Shore.", progress = "Fieldwork is exhausting.", completion = "Excellent work! I'll get this to LOU-C and see what her little contraption can make of it." }
WordHunterWoW_QuestEN[66148] = { title = "Former Furbolg Family", description = "Primalists came. They offered us new strength: the command of the elements.\n\nI did not think Stoneheart would accept their gifts. Our clan did not need power. He thought nothing of the cost.\n\nHis terrible decision cannot be unmade. The magic has corrupted my clan--like disease rots a root.\n\nMy heart breaks, but culling the corrupted is the only way.", objectives = "Kill 15 Rustpine furbolg and elementals, then meet Narn further in Rustpine Den.", progress = "It must be done.", completion = "I am sorry you met the Rustpine clan now. This is not my people." }
WordHunterWoW_QuestEN[66149] = { title = "Elemental Influence", description = "Narn says not all the Rustpines followed Stoneheart or the Primalists.\n\nSome resisters are held against their will. Totems spewing rock and mud restrain them... to force them to obey. \n\nShatter the totems. Set them free!", objectives = "Destroy 3 Primalist Earthbind Totems, then meet Narn further in Rustpine Den.", progress = "My friends do not deserve this fate.", completion = "I will never forgive the Primalists for making our clan suffer." }
WordHunterWoW_QuestEN[66150] = { title = "Rescuing Radza", description = "Radza Thunderclaw is our Spiritkeeper. She holds true our traditions and history.\n\nPrimalist beliefs go against everything our clan holds true. I knew she would defy Stoneheart! \n\nStoneheart will do anything to bring her to heel. No one is chieftain without Radza's blessing!\n\nNarn says Khargall Fivefangs, the Chieftain's guard, is trying to break her. If Radza dies, our clan dies with her.\n\nGo aid her, {name}, and be ready. He will not let her go without a fight.", objectives = "Rescue Radza Thunderclaw.", completion = "So many of my clan have fallen in battle with their brothers and sisters... all for the promise of power.\n\n<Radza utters a guttural growl which fades into a long, mournful whisper.>" }
WordHunterWoW_QuestEN[66151] = { title = "His Stone Heart", description = "We howl with grief for our chieftain, yet he lives.\n\nWhat remains of Stoneheart is in the cave ahead. Many tried to reason with him. \n\nHe killed them--and almost killed Narn.\n\nHe is a monster! This is the goal of the primalists. They would turn us into stone and flame to serve them.\n\nThere is no Rustpine left in him. He must be destroyed before others meet the same fate.", objectives = "Kill Stoneheart.", progress = "Our chieftain wanted power to protect the clan... but it took everything from us.", completion = "My chieftain, I am sorry.\n\nThere was nothing else that could be done." }
WordHunterWoW_QuestEN[66152] = { title = "Nowhere to Go", description = "We cannot stay here.\n\nI do not know what to do... where to go next...\n\nWe will return to your Camp Nowhere. The tuskarr should know what happened at Rustpine.\n\nIf we tell our story and keep it, maybe it will not happen again...", objectives = "Meet Garz at Camp Nowhere.", completion = "Our clan has been clawed to shreds.\n\nI hope another will accept us." }
WordHunterWoW_QuestEN[66154] = { title = "Salivatory Samples", description = "<The gaunt undead pinches the bridge of his nose and sighs heavily.>\n\nThis is going to reflect very poorly on my record. Somehow in a single day we've managed to stir up the local gorlocs, lose half of our equipment, and are now down a dwarf. \n\nIn this situation, protocol dictates that we be as efficient as possible. Go thin out some of our toothy antagonists and bring me their saliva for further testing while you're at it.\n\nOnly the good stuff, mind you.", objectives = "Collect 12 Saliva Samples in Gorloc Shore.", progress = "Have you secured the samples?", completion = "Well, what do you know? Someone around here actually accomplished something. What's that old saying? Two for you, one for me?\n\n<Rowe takes a small sip from the beaker.>\n\nAh, that's the stuff." }
WordHunterWoW_QuestEN[66155] = { title = "Ruriq's River Rapids Ride", description = "I did not expect my brother's approval... but it is welcome, all the same. \n\nThe time has come! Let's see if our hard work has paid off!\n\nJoin me in The Fallstrider, {name}, and we shall take off down the river, catching fish for Iskaara as we go!", objectives = "Ride the Fallstrider down the river.", progress = "With all of our hard work together, I'm certain our trip will be successful.", completion = "Phew, what a ride! It's a miracle the boat is in one piece!\n\nThank you very much, <name>. Let us meet again for another ride!" }
WordHunterWoW_QuestEN[66156] = { title = "Renowned with the Dragonscale Expedition", description = "Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer!\n\nReturn to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.", objectives = "Speak with Cataloger Jakes at the Dragonscale Basecamp.", completion = "Your deeds bring renown to all explorers. Take these supplies to aid you!" }
WordHunterWoW_QuestEN[66159] = { title = "A Message Most Dire", description = "Kalecgos would not speak of what happened in the Azure Span till you arrived.\n\nWhatever he has to share gives me a terrible sense of foreboding, {name}.", objectives = "Speak with Alexstrasza at the Seat of the Aspects within Valdrakken.", completion = "Raszageth! She is attempting to find them... This is profoundly disturbing news.\n\nWe do not know where her Primalists will be next. Our city must be protected from her chaos." }
WordHunterWoW_QuestEN[66163] = { title = "Nowhere to Hide", description = "Welcome to Valdrakken, {race}. \nThe climate in the city has been a bit warm of late, and I do not mean the weather.\n\nThe Primalists are skulking about, fomenting dissent among the citizens of our city.\n\nOur foes are crafty. They have been disguising themselves as citizens of our city to hide from the Scalesworn. They know how to avoid my guards but will not suspect an outsider.\n\nTake this Dragon's Eye gem, it should help you see through their disguises.\n\nGo reveal and kill these infiltrators!", objectives = "Kill 6 Primalist Infiltrators within Valdrakken.", progress = "Have you taken care of our infiltrator problem?", completion = "Good. Let this serve as a notice that the Primalists will never be welcome in Valdrakken!" }
WordHunterWoW_QuestEN[66164] = { title = "Fishy Fingers", description = "Now that Mordigan's off licking rocks, we can get to the crux of the problem...\n\nThose perfidious fishmen have pilfered my parts!\n\nWe weren't in this dinky little village for more than an hour and WHAM! Gorloc were swarming all over us! Rowe was yelling, Aelnara was screaming, and I'm flailing around with my wrench like a madgnome! \n\nSee if you can't salvage the situation and get some of my parts back!", objectives = "Recover 5 Stolen Parts in Gorloc Shore.", progress = "This is sub-optimal.", completion = "You're back! I'll start getting the Geoscanner 289-07 reconfigured and as functional as circumstances allow. These seaside conditions are admittedly less than ideal." }
WordHunterWoW_QuestEN[66166] = { title = "Eyes and Ears", description = "The Primalists have been spewing their propaganda among the citizens of Valdrakken. \n\nOur enemies are too wily to say anything in the presence of my Scalesworn, but perhaps you might be able to get close enough to eavesdrop on their conversations.\n\nI have marked locations on your map for further investigation.\n\nYou may want to visit the Transmogrifier to see about changing your look to avoid any suspicion.\n\nTake this enchanted stone, as long as you have it on hand we will be able to communicate.", objectives = "Locate Clues within Valdrakken, and visit the Transmogrifier to learn how to change your appearance.", progress = "Well, find anything useful?", completion = "So, the Primalists are up to something in the south and soldiers have not been arriving from South Hold Garrison... This does not sound good <name>. That does not sound good at all." }
WordHunterWoW_QuestEN[66167] = { title = "Southern Exposure", description = "Based on your discoveries I suspect the Primalists are attacking Commander Eranog's Garrison at South Hold. But, my Scalesworn cannot leave the city as that would be exactly what the Primalists are hoping for.\n\nI need your help again, {name}. \n\nTravel to South Hold, see what kind of forces we are facing, and if possible make contact with the garrison guardians there.", objectives = "Travel to South Hold Gate in search of making contact with the garrison guardians.", completion = "You have my thanks, and my apologies, stranger. In the heat of battle it is difficult to distinguish a friend from a foe, and there are plenty of foes around." }
WordHunterWoW_QuestEN[66169] = { title = "Vengeance, Served Hot", description = "The Primalists caught us completely unawares.\n\n<Velomir spits in disgust.>\n\nMy fellow guardians were ripped apart by these monsters. I would have joined them in death if you had not shown up when you did.\n\nOff in the distance I can still hear the sounds of battle. Perhaps others still live, maybe even Commander Eranog.\n\nLend me your aid. I need you to cause a distraction so I can sneak to a position closer in.\n\nKilling a few of these so called \"Magmasworn\" would be perfect.", objectives = "Kill 12 Magmasworn Primalists within South Hold Gate.", progress = "Do you have a bodycount for me, <name>?", completion = "Great work, <class>. Those monsters deserve every bit of pain you gave them twice over!" }
WordHunterWoW_QuestEN[66170] = { title = "Silent Vigil", description = "<Dori'thur hovers silently, peering at you with keen, expectant eyes.\n\nPerhaps the noble owl wishes you to see something of import.>", objectives = "Witness Dori'thur's vision.", progress = "<Dori'thur ponders your actions.>", completion = "<Dori'thur blinks knowingly.>" }
WordHunterWoW_QuestEN[66173] = { title = "Hall of Samples", description = "Did you hear what that console said?\n\nThere's a hall full of samples. Ancient titan machinery? Specimens from other worlds? Only Tyr knows what's in there!\n\nLet's change that.", objectives = "Explore the Hall of Samples.", progress = "Do ye wonder what else the titans captured as \"samples?\"", completion = "If ye decide to retire from adventuring, I'm sure ye could find work as a dragon wrangler." }
WordHunterWoW_QuestEN[66174] = { title = "Hall of the Aspects", description = "The Hall of the Aspects, eh? Why would Tyr seal something like this away? Was he hidin' something?\n\nThe implications are staggering--hopefully we'll find some answers in there.", objectives = "Explore the Hall of the Aspects.", progress = "Let's pop through that transporter before Naleidea gets cold feet!", completion = "I don't care what Naleidea says, I knew ye were the right choice from the beginning." }
WordHunterWoW_QuestEN[66175] = { title = "Field Experiment", description = "Thanks to you, our geological survey is now operating at nearly 96% efficiency! \n\n<LOU-C furrows her eyebrows.>\n\nThose are rookie numbers.\n\nHelp me run the samples you collected through my Geoscanner 289-07. It should give us a baseline as to what exactly is going on at the plateau.", objectives = "Help LOU-C run her tests in Whaler's Nook.", progress = "For science!", completion = "They say to expect the unexpected, but wow... this is unprecedented!" }
WordHunterWoW_QuestEN[66176] = { title = "Elemental Experimentation", description = "Go conduct experiments on the water elementals harassing the gorlocs!", objectives = "Conduct 6 elemental experiments in Gorloc Shore." }
WordHunterWoW_QuestEN[66177] = { title = "No Dwarf Left Behind", description = "The salt levels here are off the charts! We need to find Mordigan and get him out of there. He must be dangerously dehydrated by now. \n\nHe's only been gone a couple hours. See if you can't determine which path the grumpy old dwarf took!", objectives = "Follow Mordigan Ironjaw's path through Gorloc Shore.", completion = "You've been busy. So have I." }
WordHunterWoW_QuestEN[66178] = { title = "A Day in the Groves", description = "Rymek was sent here by the blue flight to learn about and protect our gardens. \n\nI am glad for their support. We are few in number, and our losses have been great. The blue dragonflight commands powerful magic, so we can learn a great deal from each other.\n\nCome. Let us demonstrate the green dragonflight's important role here in the Dragon Isles.", objectives = "Meet Merithra and Rymek at the Leafy Repose in the Emerald Gardens.", completion = "It is so peaceful here.\n\nThis is Somnikus's favorite place to rest, but... he has been morose since his son was killed in the centaur attacks. \n\nBut we shall focus on the present. Let us show Rymek our purpose here in the groves." }
WordHunterWoW_QuestEN[66179] = { title = "Seeds for the Future", description = "The Primalists' attack left its mark on the Emerald Gardens. I wish to see it grow and flower once again.\n\nIn this part of the garden, we have an overabundance of lashers. Their seeds can be used by the Sisters of the Garden to cultivate vegetation in those damaged glades.\n\nThin out the lashers to collect their seeds, and then give those seeds to the Sisters. They sometimes struggle to inflict harm on any creature, even when it is in the best interest of the gardens overall.", objectives = "Collect seeds from various Lashers and give them to Sisters of the Garden.", progress = "Have you collected the seeds?", completion = "Thank you. Do not fear, the lashers always grow back at a remarkable rate. Their numbers will rebound quickly." }
WordHunterWoW_QuestEN[66180] = { title = "Wake the Ancients", description = "There are many ways to keep the gardens safe, and we have allies to help us.\n\nA few Ancients rest dormant in these glades. They are giant trees sworn to defend the forest and the creatures within. \n\nUse this fragment of my breath to wake them.", objectives = "Use Merithra's Borrowed Breath to wake Ancient Guardians in the Emerald Gardens.", completion = "One of the ancients was slain? By frost?\n\nThis does not bode well. We must be alert. The Primalists could be preparing another assault on the garden." }
WordHunterWoW_QuestEN[66181] = { title = "A Frenzied Defender", description = "I have noticed that these gardens have rather diverse defenses, from the dragons to the drakonid and ancients... and even the wildlife!\n\nBut there is one defender that seems to have become rather too zealous in its protectiveness. It even tried to swoop at me when I arrived!\n\nAnd since we know something has been killing within these groves, it cannot hurt to be too cautious.\n\nUnfortunately, this creature must be slain before it can do more damage.", objectives = "Slay the Frenzied Grovetalon.", progress = "Have you found and put down that overzealous bird?", completion = "The gardens are more peaceful already, are they not?\n\nYou are quite capable, <race>." }
WordHunterWoW_QuestEN[66182] = { title = "Gerithus's Research", description = "The green dragonflight has many duties, not solely in the tending of the garden. We also defend the Emerald Dream, and some extend their attention even further.\n\nMy son Gerithus, for example, has always had interest in all kinds of magic.\n\nYou and Rymek should seek him out, to see what he is working on and help where you can.", objectives = "Meet Gerithus deeper in the Emerald Gardens.", completion = "Welcome! I appreciate that my mother has been interested in my research. Even if it's a little far-fetched.\n\nThough I'm sure Rymek, as an emissary of the blue flight, will have a much greater understanding of magic than I do. I hope that we can make some real progress.\n\nLet's begin!" }
WordHunterWoW_QuestEN[66183] = { title = "Emerald Tears", description = "We may've only recently returned to the Emerald Gardens, relatively speaking, but we carry our long-lasting feelings with us.\n\nMany of us are still reeling from the death of Ysera, my grandmother. Including myself. I wish I had gotten to spend more time with her and to learn more from her. What amazing things she's seen in her life!\n\nIn places like the Emerald Gardens, when we shed tears, they can crystalize and carry great power within them. I have an idea for how this galvanized grief could help us.", objectives = "Collect 8 Emerald Tears.", progress = "Have you collected some of the Emerald Tears in the garden?", completion = "These are beautiful examples, <name>. Now let's see what we can do!" }
WordHunterWoW_QuestEN[66184] = { title = "Anchors to Life", description = "Based on my research, I believe there's a way to reestablish Ysera's ties to the Emerald Dream, so we can bring her closer to Azeroth.\n\nWhen Ysera died, the Winter Queen used her own power to restore her in Ardenweald. For now, she's bound there, but I think if we can just get Ysera over into the Emerald Dream, we can use these anchors to keep her there.\n\nBut I'm getting ahead of everything.\n\nFirst, we have to infuse these anchors with the power of those Emerald Tears.", objectives = "Empower the Inert Anchors with the Emerald Tears.", progress = "There is so much potential within ourselves.", completion = "That's it! I can feel the power in the anchors.\n\nNow, of course, there's just the one tiny problem of how to get Ysera to cross from the realms of death into the realms of life. One thing at a time.\n\nFor now, I'll get these anchors to the Shady Sanctuary for safekeeping.\n\nMy mother is here. She must have more that she wants you and Rymek to see." }
WordHunterWoW_QuestEN[66185] = { title = "Across the Weald", description = "It is time. I know I said that I was fine, but ever since Solethus' death, it's like I've been missing something essential.\n\nI am alive, and he is not. That feels... wrong.\n\nBut there might be a way I can set things right. Ysera is the only one who can help us get control of Ancient Bough again. I think I can help bring her back.\n\nIt's getting harder and harder to cross over. We need to make this count.\n\nTyrande and Malfurion will meet us there.", objectives = "Meet Somnikus at the Grove of Awakening in Ardenweald.", completion = "Greetings. Somnikus has told me of the grave threat in the Emerald Gardens. He has told me of his own part in it.\n\nBut I'm afraid the solution will not be as simple as he hopes." }
WordHunterWoW_QuestEN[66186] = { title = "The Price", description = "I am eager to return to the Emerald Dream and defend the gardens from the Incarnates and their followers. But I cannot leave Ardenweald yet, not with my bond to the Winter Queen.\n\nI dare not ask anyone to do this, unless they accept the consequences. As I did.\n\nBut there is one who could take my place.", objectives = "Witness the decision.", completion = "It is settled. I will remain in Ardenweald.\n\nI remain to protect the Dream and all the hope that grows within it. It must be me." }
WordHunterWoW_QuestEN[66187] = { title = "Mad Mordigan & The Crystal King", description = "I've scouted the perimeter. If Mordigan's anywhere, he's inside this cave.\n\n<Muffled curses and insults echo out from the cave entrance.>\n\nHe's definitely inside this cave.\n\nLOU-C said these crystals have dangerous dehydrating properties. See if you can't separate him from his... geological finds. And try not to hurt him too much.\n\nHe's fairly respected in his field.", objectives = "Decrystallize Mordigan Ironjaw in Gorloc Shore.", completion = "An inelegant solution, but I appreciate your quick thinking and... resourcefulness." }
WordHunterWoW_QuestEN[66188] = { title = "Storm's Rest", description = "Let us go into the Grove of Awakening. The Winter Queen is the only one who can transfer this bond from Ysera to me. I have faith that she will agree. She aided Ysera in a time of desperate need, and now Ysera can help us in turn.\n\nIf the Winter Queen agrees, I expect that I will not be able to remain awake for long. The weight of the bond will be heavy to bear.\n\nIn time, I hope that I may wake again and gaze upon the fully grown might of the new tree.", objectives = "Activate the Globes of Rebirth in the Grove of Awakening.", progress = "I long to see the twisting green expanse of the Dream once again.", completion = "It has been done. Malfurion will sleep here in my stead. And Tyrande will watch over her people as she has capably done for millennia before.\n\nNow, we must ready ourselves. When I cross over into the Emerald Dream, there will be a brief window when you can join me.\n\nAre you ready?" }
WordHunterWoW_QuestEN[66189] = { title = "Step Into the Life", description = "We mustn't delay. I can feel the energies of rebirth surging in me. I am ready to cross back into the Emerald Dream. \n\nFrom the realms of Death into Life.\n\nFollow me through the gate of Awakening, and we will race across the Dreamway to Ancient Bough. I expect there will be some resistance within, so be on your guard.", objectives = "Fight your way across the Emerald Dreamway with Ysera and enter Ancient Bough.", completion = "It is worse than I feared. I can destroy the ice that surrounds the grove, but there are too many enemies upon us. And we need to find a way to bring down the barrier that keeps the others out.\n\nWe must work quickly and vanquish these foes, so Merithra and the others can reinforce us." }
WordHunterWoW_QuestEN[66190] = { title = "So Close", description = "I must take a moment to thank you, {name}, for all your help. \n\nTruly, I never thought I would have a chance to admire the Dream within Ancient Bough! Not as a humble emissary! How very kind.\n\nLord Somnikus has graciously invited me to set foot inside the grove and see the portal. I would be honored if you would join me.\n\nI will remember this moment for the rest of my life. Share it with me.", objectives = "Enter the Dream portal grove with Rymek.", completion = "I... can't believe...\n\nThis cannot be...\n\nI failed. I trusted Rymek and his dragonkin, and they betrayed us all." }
WordHunterWoW_QuestEN[66191] = { title = "And Yet So Far", description = "I cannot slip into the Dream here as I once did. With the bough defenses activated, we are essentially blocked from the grove.\n\nBut I'm afraid it only gets worse, {name}.\n\nI believe Rymek did not merely trick us to gain access to the Dream. I suspect he is looking for something within it... something precious and powerful that I swore to protect. \n\nNot even Gerithus or Somnikus knew of its existence, but now, my hand is forced. You must know the truth.", objectives = "Speak to Merithra.", completion = "Our situation is dire. Rymek has left us few options.\n\nHe has forced our hand. Now we must make great sacrifices.\n\nThough we may not be able to enter the grove from this side, there is a way in... from beyond the realms of life." }
WordHunterWoW_QuestEN[66195] = { title = "Flaming for Gold", description = "Our scouts noticed that there were artifacts frozen in the falls and rivers of the Winterpelt Hollow.\n\n I have just the thing, the Ice Panning Focuser Mark 15, or I.P.F. for short. I think we have all of the bugs worked out so take it and use it to defrost the likely frozen relics. \n\nOnce you have 10, bring them back and I will put our researchers to work identifying them.", objectives = "" }
WordHunterWoW_QuestEN[66196] = { title = "A Quack For Help", description = "<This duckling flails around frantically inside the bubble, quacking in fright.>\n\n<Maybe the ecologists would know how to help it?>", objectives = "Bring the Bubbled Duckling back to the Ecologists' Camp.", progress = "<Tharu coos at the bubbled duckling.>\n\nShh, don't cry, little one.\n\nUs big strong ecologists will keep you safe! And <name> too of course.", completion = "We'll look after Waddles. Let us know if you find any other lost ducklings out there." }
WordHunterWoW_QuestEN[66197] = { title = "Filet Frenzy", description = "The sockeye salmon are running, there are great numbers rushing up the rivers of the Azure Span.\n\nHave you ever tasted fresh salmon? <Marl holds his hand to his lips and gives the classic chef's kiss>\n\nPlease explorer gather or fish up 12 Sockeye Salmon and we will have a great menu of salmon for the week.\n\nOh, I should mention that the bears of the span 'really' like salmon as well, so be careful, but they might just help you with the fishing. <The chef winks at you.>", objectives = "" }
WordHunterWoW_QuestEN[66199] = { title = "Wood Beats Cold", description = "So, what is with this crazy white stuff? It could get cold in Vol'dun but we never had to worry about frozen fire wood. \n\nWe are going to freeze if we cannot find some dry firewood. And what would you know we walked right through a forest on the way here with dry wood all over the ground... why not setup a camp there? \n\nWell no one listens to me, they just want me to get it figured out. \n\nSo I need you to gather 20 Pieces of Firewood from the west of the Azure Span.", objectives = "" }
WordHunterWoW_QuestEN[66201] = { title = "Hooves of War", description = "Balakar will marshal his forces for war. I will do the same, but we are outnumbered.\n\nThe dragons have asked for our aid, and we can use their help to even the odds. To answer their call for an alliance, I must blow the Horn of Drusahl, but I need Ohn'ahra's blessing. Will you help me?\n\nGo to Teerakai and deliver my declaration of war to my lieutenant, Jebotai. He will marshal my forces and direct you to the mystics who can find Ohn'ahra.", objectives = "Deliver the Khanam Matra's message to Khansguard Jebotai at Teerakai.", progress = "What do you want, outsider?", completion = "<Jebotai reads the message. His face grows more and more concerned.>" }
WordHunterWoW_QuestEN[66203] = { title = "Wash Over Them", description = "", objectives = "" }
WordHunterWoW_QuestEN[66206] = { title = "Nozdormu, I've Come to Bargain", description = "", objectives = "" }
WordHunterWoW_QuestEN[66210] = { title = "Gather the Family", description = "Your friend Kalecgos wishes to speak of ley lines, but preparations must be made for the funeral. \n\nWhile I meet with him, could you gather the final offerings from around Iskaara and place them in the funeral boat alongside dear old Ponoliak? \n\nI hope you take a moment to enjoy the town, as well! My people will welcome you warmly, especially after your help in Brackenhide.", objectives = "Collect 4 Funeral Offerings from around Iskaara, then place them in the funeral boat.", progress = "Did you get yourself a bowl of soup?", completion = "Your friend is very inquisitive! Does he ever take a moment to relax?" }
WordHunterWoW_QuestEN[66211] = { title = "Brackenhide Hollow: To the Source", description = "We cannot thank you enough for your aid pushing back the Brackenhide gnolls. \n\nBut they continue to gather, using their foul decay magic from some source deep within Brackenhide Hollow. Worse, we have not heard from the tuskarr in that area for weeks, now.\n\nI fear something terrible is happening there. We must protect our home. Please, gather your forces, find our people, and see what you can do about the decay!", objectives = "Enter Brackenhide Hollow and confront Decatriarch Wratheye.\n\nYou can access Brackenhide Hollow solo by queuing for it in Follower Dungeons.", progress = "We must save our people, and stop the spread of decay!", completion = "Iskaara would be lost without you." }
WordHunterWoW_QuestEN[66212] = { title = "Fishing: Aileron Seamoth", description = "Doesn't ANYBODY know how to fish PROPERLY anymore?\n\n<Lukoturukk wiggles his nose angrily.>\n\nYou, with the face, go get me some fish. GOOD fish. And no grungles!", objectives = "Fish up 5 Aileron Seamoths from the ocean around the Dragon Isles.", progress = "Well, what've you caught, then? \n\nIt better not be any skinny little ancheevies.", completion = "Hmmph.\n\nHmmmmmph.\n\n...you're alright." }
WordHunterWoW_QuestEN[66213] = { title = "The Weave of a Tale", description = "My dearest wife, Poa, is an excellent storyteller. \n\nBut it's been thirty years, and she tells the same ones over and over again! Please, {class}, talk to Poa and give her a new story to tell.\n\nWhat's that? Tell her a story about your adventures? Don't be ridiculous -- I don't want to hear about that! The greatest stories are always about fish. Tell a story about fish, even if you have to make one up!", objectives = "Tell Elder Poa a fishy tale.", progress = "I'm waiting...", completion = "Thank goodness, a new story. \n\nLet's hear it!" }
WordHunterWoW_QuestEN[66214] = { title = "Snow Scout", description = "The Azure Span is the next plan for an Expedition, we need you to verify the site is secure and will suit our needs. \n\nVenture out to the location marked your map, deal with any issues that come up, and report back to me.", objectives = "" }
WordHunterWoW_QuestEN[66215] = { title = "Cold Weather Insulation", description = "Our next expedition is to the eastern edge of the Azure Span, <Weynar shivers>, dang that happens every time I even think of that place. Now I won't actually be going myself but it is my job to outfit the expedition and so that means cold weather gear. \n\nAnd we have two blubbery creatures nearby and up the slope that can accommodate our needs, Riverbeats and Hornswog. \n\nSo budding explorer, fetch me 30 Pounds of Blubbery Flesh and I will have an enchantment prepared to keep it in the coat stuffing.", objectives = "" }
WordHunterWoW_QuestEN[66217] = { title = "WANTED: Krojek the Shoreprowler", description = "We've been watching the great shark we know as Krojek for many years now, waiting for the best time to hunt him down. \n\nHis hunting ground has meandered closer and closer to the shore. That means the time is now. Gather your hunting party and take him out!", objectives = "Kill Krojek the Shoreprowler.", completion = "It is the cycle of the sea life out here. Some we leave to continue the line. Some we cull, some we eat. All in balance." }
WordHunterWoW_QuestEN[66218] = { title = "Scampering Scamps", description = "Hello again.\n\nCould you do me and Norukk a favor? Our kids, Neelo and Nau, left to play. They know they should be back by now. \n\nI am occupied, so please find them. I doubt they are in danger; my kids know how to take care of themselves.", objectives = "Find Neelo and Nau.", progress = "Neelo and Nau can fend for themselves. But they know they are supposed to be home helping by now.", completion = "Ta says all gnolls are dangerous and mean. But this is just a baby! \n\nMa says I always have to take care of Nau, and she's a baby, too." }
WordHunterWoW_QuestEN[66221] = { title = "Moving On", description = "With the Bronze Oathstone restored, Alexstrasza can proceed with her plan.\n\nTravel to Valdrakken, {name}. She will want to hear of your success.", objectives = "Speak with Alexstrasza at the Seat of the Aspects in Valdrakken.", progress = "I thank you, <name>.", completion = "<name>, please accept our most sincere gratitude for all you have done for us. I will let you know when the time comes to accompany me on this next step." }
WordHunterWoW_QuestEN[66222] = { title = "The Calm Before the Storm", description = "The Nokhud are powerful and have many allies. It will take all we have to withstand them.\n\n{name}, you have the Khanam Matra's trust. Her orders were to rally our friends and prepare our people. \n\nI need your help. Seek Hojin to mobilize the remaining khansguard. Alert Scout Khenyug to possible Nokhud incursions. Inform Agura to expect wounded, and tell Gensai to prepare our provisions.\n\nAs for the mystics, I believe they left recently. I will see if any remain in Teerakai.", objectives = "Communicate Jebotai's orders to the townsfolk of Teerakai.", progress = "It is rare for us to meet outsiders. It is even more rare to have them helping us, as you are. Thank you.", completion = "I did not wish to cause a panic, but the people must be ready. Clan Nokhud is not known for mercy." }
WordHunterWoW_QuestEN[66223] = { title = "Can We Keep It?", description = "He's only trying to eat us because he's so hungry! \n\nFish! Nobody can turn down some tasty, ice cold, raw fish!\n\nFrigidfish are the best, ever. You can fish them up all over the ocean! But if you can't fish one yourself, Jinkutuk in Iskaara will definitely sell you some. \n\nBring me so many he won't be hungry any more!", objectives = "Bring Neelo 7 Frigidfish from either a vendor in Iskaara or fishing in any Dragon Isles ocean water.", progress = "So many fishes! I want to eat them all!\n\n... But no. They're for Scaps. This is important.", completion = "Scaps is gonna love these and then we're gonna be the bestest of friends!" }
WordHunterWoW_QuestEN[66224] = { title = "Mystic Mystery", description = "I'm sorry, I've failed to commune with Ohn'ahra. You will need someone else to fulfill the Khanam Matra's request.\n\nSeveral days ago, my fellow mystics were called to Ridgewater Retreat on an urgent request from Tigari Khan. They should still be there.\n\nMeet me outside of town. The least I can do is show you the way.", objectives = "Meet up with Boku and travel to Ridgewater Retreat.", progress = "<name>, you're alright! Thank Ohn'ahra.\n\nOh! These are my totems.", completion = "I barely escaped that ambush with my life. I'm afraid my fellow mystics weren't so lucky...." }
WordHunterWoW_QuestEN[66225] = { title = "Toting Totems", description = "Boku asked why I sent a message calling all mystics to Ridgewater Retreat.\n\nI sent no such message. Balakar purposefully drew my mystics into a trap to cripple Clan Ohn'ir.\n\nBut there may be a second reason. The Nokhud are gathering mystic totems, as many as they can find. These totems are blessed by Ohn'ahra.\n\nThe Nokhud motives in this are unclear, but we cannot allow them to take Ohn'ahra's gifts. Recover as many totems as you can.", objectives = "Gather 8 Bundles of Totems from the Nokhud at Ridgewater Retreat.", progress = "The totems are infused with Ohn'ahra's wind magic.\n\nYet the Nokhud have abandoned her teachings. What are they up to?", completion = "So many totems. So many fallen mystics." }
WordHunterWoW_QuestEN[66226] = { title = "Emotional Support Companions", description = "Please don't hurt me... \n\nWhat? You're here to help? You must save the animals!\n\nThe Nokhud attacked without warning. We all fled for our lives! I barely escaped death by diving into the lake.\n\nThe animals! We left them behind. Please, I beg you, rescue the creatures. Who knows what cruelty the Nokhud have in store for them.", objectives = "Rescue the innocent creatures from the Nokhud at Ridgewater Retreat.", progress = "As initiates, we practice our healing arts by rehabilitating wounded creatures. \n\nFour creatures were under our care. However many you can rescue will be a relief.", completion = "You saved them! They're a bit worse for wear, but they're alive and will recover.\n\nThank you stranger. Please take this, as a token of our everlasting gratitude." }
WordHunterWoW_QuestEN[66227] = { title = "Some Good Fishing", description = "Another pair of hands! I could use some help catching enough fish to bring home for a meal.\n\nThese Kirin Tor seem concerned about something called magical anomalies in the area, whatever that means.\n\nYou're all welcome to stay here as long as you pitch in and help out.\n\nGrab a fishing pole and start fishing. Many hands make light work!", objectives = "Catch 3 blue-tailed minnows within Khuri's Fishing Spot.", progress = "Let me know if you need a few tips.", completion = "Ah, that will do nicely! Thank you, adventurer." }
WordHunterWoW_QuestEN[66228] = { title = "Camp Antonidas", description = "The Kirin Tor have our main camp set up to the south of here: Camp Antonidas.\n\nI believe Noriko and Khadgar are there now gathering adventurers to aid Kalecgos in reclaiming the Azure Oathstone.\n\nIf you wish to help in our endeavours, go there.", objectives = "Meet Noriko the All-Remembering in Camp Antonidas.", completion = "Ah, <name>. Good to see you...\n\nHold on... do you feel that?" }
WordHunterWoW_QuestEN[66230] = { title = "A Sketchy Request", description = "The tarasek took everything they could get their claws on, including my scouting ledger.\n\nThese overgrown lizards hoard trinkets and trophies by the dozens. I am sure that they stashed my ledger away somewhere. Could you keep an eye out for it as you work your way through the pass?\n\nOh, and {name}? If you do manage to find it, please do not look inside. The contents are sort of... personal.", objectives = "Retrieve Alvi's \"Ledger\" and return it to Waywatcher Alvi.", progress = "Did you find anything else, <name>?", completion = "Ah... You really did find it.\n\nIn truth, it's more of a sketchbook than a ledger. For as long as I can remember, I've been more interested in doodling than scouting...\n\n<Alvi looses a long, low sigh.>\n\nMaybe if I had actually done my job properly, then Nori wouldn't have gotten hurt.\n\nI have to fix this... but I don't know if I can do it alone." }
WordHunterWoW_QuestEN[66232] = { title = "Afront 'Till A Salt", description = "We don't mind accommodating you and your friends in our little place--not that anyone asked-- but would you be a good neighbor and nab me some crystal flakes if you're going up to the springs? We use 'em to preserve all kinds of things. It's a crucial part of keeping food around here.\n\nThe larger gorlocs are absolutely covered in the stuff. Maybe get some flakes off them?", objectives = "Gather 120 Crystal Flakes in Gorloc Shore.", progress = "Now that you mention it, I'm actually pretty hungry.", completion = "This is will go a long way in helping us in these parts. We just might let your friends stick around..." }
WordHunterWoW_QuestEN[66236] = { title = "Catching Wind", description = "The Nokhud are collecting totems. The Primalists are capturing ohuna. And Ohn'ahra is silent.\n\nWhatever the Nokhud plans are, we must foil them. You and Boku must travel to Windsong Rise. Our enemies are likely there already.\n\nSearch for Ohn'ahra there. If her children are in danger, she will undoubtedly go to them, and we must help. The Windmother is powerful, but I fear what these Primalists are capable of.", objectives = "Meet Boku at Windsong Rise.", completion = "Balakar and these Primalists have trampled on our most sacred beliefs." }
WordHunterWoW_QuestEN[66237] = { title = "Spiritual Allies", description = "Our arrival will not have gone unnoticed.\n\nAllow me to speak with them before we enter. I have something of a history with the council.\n\nThere will be time for introductions after.", objectives = "Speak with the authorities.", completion = "A warmer welcome than I feared." }
WordHunterWoW_QuestEN[66239] = { title = "Spreading Decay", description = "<Brena turns Kargpaw's totem over and over in her thick hands.>\n\nKargpaw is a pawn. He isn't the source of this rot. We must find it, before the decay spreads further.\n\nThe closest tuskarr presence from here is a trading outpost, just across the bridge on the way to Iskaara.\n\nWe should check in with them... and quickly.", objectives = "Meet Brena at the trading outpost.", completion = "As I feared, they were attacked as well." }
WordHunterWoW_QuestEN[66241] = { title = "Thaldraszus Rally", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66242] = { title = "Weather Control", description = "This unnatural storm is heavy with magic. By the looks of it, the Nokhud are learning to manipulate the sacred essence of Windsong Rise to create storm elementals. Some have had more success than others...\n\n<Boku gestures to the unfortunate Nokhud initiate nearby still smoking from lightning burns.>\n\n{name}, we can't allow them to continue.", objectives = "Kill 8 Stormbound Essences and 6 Stormcaller Initiates.", progress = "The Nokhud will regret abandoning Ohn'ahra for the Primalists!", completion = "I don't want to spill blood, but the Nokhud must be stopped." }
WordHunterWoW_QuestEN[66243] = { title = "A Gift of Hope", description = "Greetings, Maw Walker.\n\nI bear a summons from the Winter Queen. She requests your presence in Ardenweald to witness a ceremony involving others from your world.\n\nShandris Feathermoon will be among them. You can find her in the Grove of Awakening.", objectives = "Meet Shandris Feathermoon in the Grove of Awakening.", progress = "The Winter Queen awaits us, <name>.", completion = "The Winter Queen's gift... what we just witnessed...\n\n<Shandris's eyes glisten with tears of hope.>\n\nWe must ask Ysera to help us keep this precious seed safe." }
WordHunterWoW_QuestEN[66244] = { title = "To Valdrakken", description = "Thanks to you, we narrowly avoided a complete catastrophe.\n\nHowever, we should convene with the other Aspects and share word of what happened here.\n\nPlease meet me at the Seat of the Aspects within Valdrakken. I'm sure the others will have insight into what Raszageth and her Primalists are attempting.\n\nThere is a crossing into Thaldraszus north and a bit east of here. The flight is scenic, but do not take too long getting there.", objectives = "Travel to Valdrakken and meet with Alexstrasza the Life-Binder.", completion = "Welcome to Valdrakken, <name>. Kalecgos says there is news about the Azure Span." }
WordHunterWoW_QuestEN[66245] = { title = "Remember the Fallen", description = "So many of my comrades have fallen.\n\nPlease... Collect their identifying signets so that their names may not be forgotten.", objectives = "Collect 8 South Hold Garrison Signets.", progress = "How goes your task, hero? Did you find any signets?", completion = "Their memories will be honored." }
WordHunterWoW_QuestEN[66246] = { title = "The Fog of Battle", description = "The Primalist attack came suddenly and with no warning. My unit attempted to find our leader, Commander Eranog, but before we could get to the other side of the garrison we were cut off.\n\nIn the battle my unit leader, Sergeant Tagrik, held off three Primalists by himself as Kaora, Mikor, and myself battled at his side.\n\nTheir screams are the last thing I remember before I fell. \n\nPlease, {race}, if you see any signs of my unit let me know what happened to them.", objectives = "Search for the members of Guardian Velomir's unit in the South Hold Gate.", progress = "Have you found what happened to my unit? I fear the worst, but I have hope that they survived.", completion = "This... pains me to hear... but I understand. Thank you, <class>." }
WordHunterWoW_QuestEN[66247] = { title = "Slightly Used Weapons", description = "This spear appears to be in good shape, given the condition of its former owner.\n\nGuardian Velomir mentioned to keep an eye out for useful materials, perhaps a few more of these spears can be obtained from the Magmasworn.", objectives = "Gather 6 Magmasworn Spears.", progress = "Find anything worthwhile out there?", completion = "Good find, <name>! These should be useful." }
WordHunterWoW_QuestEN[66248] = { title = "Tying Things Together", description = "This coil of heavy rope seems to be in good condition. \n\nGuardian Velomir said to keep an eye out for useful materials, perhaps if you can find a few more coils he might find them useful.", objectives = "Gather 5 Coils of Heavy Rope.", progress = "What is it, friend? Did you find something?", completion = "What is this? Rope? There is no time to make a net!\n\nWait... I have an idea. There are some old weapons that we could use with these... \n\nGood eye, <name>! These are perfect!" }
WordHunterWoW_QuestEN[66249] = { title = "Clear the Sky", description = "You did well to gather those spears and rope. With them, we can ensure those haughty Primalists will no longer rule the skies!\n\nThere is a platform up the stairway with several Siege Scorpions. If you use the rope to string their bows and use the spears as ammunition, you should be able to strike the Magmasworn's dragons in the air!\n\nOnce cleared, the path up the spire will be safe and we can continue our search for Commander Eranog.", objectives = "Control a Siege Scorpion and then use it to clear the skies of Magmasworn Trueborn.", completion = "Well done, <name>! That should take some heat off us. \n\nKeep your weapon in hand though, we are not done yet." }
WordHunterWoW_QuestEN[66250] = { title = "Where's The Chief?", description = "This is the only part of the fortress we haven't yet searched, {name}. If Commander Eranog is anywhere, it has to be here.\n\n<Velomir glances towards the nearby doorway.>\n\nLet us see what we can find out.", objectives = "Accompany Guardian Velomir and inspect the Lookout Tower within South Hold Gate.", completion = "Damn it all! The commander was behind this? I cannot believe he would betray us like this." }
WordHunterWoW_QuestEN[66251] = { title = "Fire Fighter", description = "Commander Eranog has betrayed us and left this beast in charge.\n\nYou have done so much for me already, but I can not handle that monster in my current state.\n\nPlease, do this one last thing for me and help ensure that South Hold Gate does not fall to these Primalists.\n\nWe must kill their leader!\n\nHelp me, {name}.", objectives = "Kill Magmatalon.", completion = "With their leader dead these Primalists should be easy for reinforcements from Valdrakken to clear out." }
WordHunterWoW_QuestEN[66252] = { title = "Reporting In", description = "The Primalists threat has been diminished, {name}. Forces from Valdrakken will be headed in soon, and can clean up any remnants. \n\nYou should head back to the city and inform Captain Drine of what has happened. She will be interested to know what occurred here with Commander Eranog.\n\nThank you again, {name}, for everything.", objectives = "Return to Valdrakken and report to Captain Drine.", completion = "Eranog joined the Primalists? Flame and Scale, this is a terrible development!\n\nHowever, you were able to prevent them from taking South Hold Gate.\n\nThat is no small feat. I appreciate your service to Valdrakken, <name>. It will not be forgotten." }
WordHunterWoW_QuestEN[66253] = { title = "Stolen Shipments", description = "Tha shipments from Shiri and Zen'kala keep comin' in, we can barely keep up! But one of my workers thinks I won't notice if he shaves a little off the top. \n\nThe goblins here have been workin' on a little device to help make a mess of this thief: an exploding pie.\n\nLook for Kanyaku and throw one straight at him. I'm sure he's makin' mischief somewhere.", objectives = "Throw the explosive pie at the thief and retrieve 1 Shipment.", progress = "Throw an explosive pie at the thief to get the shipment.", completion = "Great work mon." }
WordHunterWoW_QuestEN[66254] = { title = "Pessimistic Mystic", description = "War? Dragons? You need me to contact Ohn'ahra?\n\nI can't. I can't hear Ohn'ahra at all. I'm just an initiate, and it seems like Ohn'ahra has withdrawn her blessings from me. Maybe I'm not good enough...\n\n<Boku starts digging through a satchel.>\n\nWhen my mentor assigned me to this clan, she gifted me with these totems. She said they would empower me if ever I doubted myself.\n\nWill you help me place them? I will try to call upon Ohn'ahra one more time.", objectives = "Place the Empowerment Totems around Boku.", completion = "Still nothing. Not even a sigh from Ohn'ahra." }
WordHunterWoW_QuestEN[66256] = { title = "Eagle-itarian", description = "We've discovered why the Nokhud want mystic totems. They can be used to capture the Children of Ohn'ahra. Though the Nokhud have stolen the totems, the Primalists are the ones behind this blasphemy.\n\nThe Children of Ohn'ahra are sacred ohuna, blessed by the Windmother herself. Please, {name}, free any ohuna you see! And if you come across any Primalists...\n\n<Boku trails off, but his expression is one of grim determination.>", objectives = "Free 6 Children of Ohn'ahra and eliminate 6 Primalists at Windsong Rise.", progress = "The Children of Ohn'ahra bear the spirits of the honored dead to the beyond.", completion = "After all Ohn'ahra has done for us, we must do all we can to help her children. Thank you, <name>." }
WordHunterWoW_QuestEN[66257] = { title = "Fowl Sorcery", description = "It is said that Ohn'ahra infused the spear of our ancestor, Maruuk, with her power. Balakar Khan must have told the Primalists about that legend.\n\nThey have stolen the magic from Ohn'ahra's children, polluted it with storm sorcery, and infused it into ballista bolts. Why would the Nokhud need such weapons?\n\nWe shouldn't wait to find out. These storm bolts are being loaded into wagons for transport. Take my totems and place one atop each wagon you come across. My wind magic will smash them to pieces.", objectives = "Use Boku's Wind Totem to destroy the Nokhud wagons.", progress = "You might want to run after placing a totem.", completion = "I'm sure there's more out there, but we destroyed what we could. Hopefully, this will at least slow them down." }
WordHunterWoW_QuestEN[66258] = { title = "Oh No, Ohn'ahra!", description = "That Primalist is restraining Ohn'ahra, but just barely. She doesn't seem to notice us.\n\nTigari Khan would say, \"Even the slightest breeze can topple a teetering stone.\" If I can disrupt her spell, even just a little, Ohn'ahra might be able to break free.\n\nKeep the guards distracted. I have an idea.", objectives = "Defeat enemies as Boku tries to free Ohn'ahra.", completion = "We took quite a tumble. We're lucky to be alive." }
WordHunterWoW_QuestEN[66259] = { title = "A Storm of Ill Tidings", description = "{name}, we need to tell the Khanam Matra everything that's happened, including the capture of Ohn'ahra.\n\nYou must go to Maruukai as quickly as you can. You'll have to go alone. I was hurt in the fall, and I'd just slow you down.\n\nDon't worry about me. I'll catch up later. Go!", objectives = "Deliver your report to the Khanam Matra in Maruukai.", progress = "Well? Speak.", completion = "This is dire news, <name>, but we cannot lose focus. We are bruised but not beaten." }
WordHunterWoW_QuestEN[66261] = { title = "A Minor Setback", description = "Ah, adventurer! Just the sort of well-armed individual I was hoping to encounter.\n\nI'm here in this literal backwater on very important Kirin Tor business, you see, and whilst I was beginning to set up my camp, I was chased off by filthy, mangy gnolls.\n\nIn fact, a rather concerning number of gnolls have gathered nearby, enough that I believe they pose a threat to the wider Span.\n\nFear not though, for I have a plan! Meet me in the lake just over there, and I'll explain everything.", objectives = "Reach Detry.", completion = "Now, to work!" }
WordHunterWoW_QuestEN[66262] = { title = "Waste Water Cleanup", description = "First things first--I need my base of operations back! But the elementals running amok around here have made it very difficult to gain even a toehold.\n\nAnd of course it is those wretched gnolls' fault.\n\nThe gnolls have dumped so much refuse, offal, and Light knows what else into the lake that the local elementals have started to go berserk.\n\nBe a dear and clean up a few of the more revolting messes before things come to a head. And, more importantly, before they stain my robes permanently!", objectives = "Clean 6 Rotting Piles from the lake.", progress = "Ugh, the smell is horrific.", completion = "I can taste the difference already!" }
